INSERT INTO `contest_submission` VALUES (1,1,2,1,'import java.util.Scanner;\r\n\r\npublic class Main {\r\n    public static void main(String[] args) {\r\n        Scanner scanner = new Scanner(System.in);\r\n        int n = scanner.nextInt();\r\n        scanner.close();\r\n        \r\n        // 处理边界情况\r\n        if (n <= 1) {\r\n            System.out.println(1);\r\n            return;\r\n        }\r\n        \r\n        long prev1 = 1; // f(1) 或 f(0)，根据定义\r\n        long prev2 = 1; // f(0)\r\n        long current = 0;\r\n        \r\n        for (int i = 2; i <= n; i++) {\r\n            current = prev1 + prev2;\r\n            prev2 = prev1;\r\n            prev1 = current;\r\n        }\r\n        \r\n        System.out.println(current);\r\n    }\r\n}','JAVA','ACCEPTED',349,0,'通过','2026-06-15 13:53:11',NULL,NULL),(2,2,2,1,'import java.util.Scanner;\r\n\r\npublic class Main {\r\n    public static void main(String[] args) {\r\n        Scanner sc = new Scanner(System.in);\r\n        int n = sc.nextInt();\r\n        sc.close();\r\n        System.out.println(climbStairs(n));\r\n    }\r\n\r\n    public static long climbStairs(int n) {\r\n        if (n <= 2) return n;\r\n        long first = 1;  // 对应 n=1\r\n        long second = 2; // 对应 n=2\r\n        for (int i = 3; i <= n; i++) {\r\n            long third = first + second;\r\n            first = second;\r\n            second = third;\r\n        }\r\n        return second;\r\n    }\r\n}','JAVA','ACCEPTED',305,0,'通过','2026-06-16 22:35:16',NULL,NULL),(3,2,2,3,'import java.util.Scanner;\r\n\r\npublic class Main {\r\n    public static void main(String[] args) {\r\n        Scanner sc = new Scanner(System.in);\r\n\r\n        // 第一行：容量（第一个数），第二个数（物品数量，实际由后续列表长度决定，忽略）\r\n        int capacity = sc.nextInt();\r\n        int n = sc.nextInt(); // 忽略，实际物品数由后续行决定\r\n        sc.nextLine(); // 消耗换行符\r\n\r\n        // 第二行：物品重量列表（空格分隔）\r\n        String[] weightParts = sc.nextLine().trim().split(\"\\\\s+\");\r\n        // 第三行：物品价值列表（空格分隔）\r\n        String[] valueParts = sc.nextLine().trim().split(\"\\\\s+\");\r\n\r\n        // 取较短的作为有效物品数\r\n        int m = Math.min(weightParts.length, valueParts.length);\r\n        int[] weights = new int[m];\r\n        int[] values = new int[m];\r\n        for (int i = 0; i < m; i++) {\r\n            weights[i] = Integer.parseInt(weightParts[i]);\r\n            values[i] = Integer.parseInt(valueParts[i]);\r\n        }\r\n\r\n        // 0-1 背包动态规划（一维数组，逆序更新）\r\n        int[] dp = new int[capacity + 1];\r\n        for (int i = 0; i < m; i++) {\r\n            for (int j = capacity; j >= weights[i]; j--) {\r\n                dp[j] = Math.max(dp[j], dp[j - weights[i]] + values[i]);\r\n            }\r\n        }\r\n\r\n        System.out.println(dp[capacity]);\r\n        sc.close();\r\n    }\r\n}','JAVA','ACCEPTED',216,0,'通过','2026-06-16 22:35:46',NULL,NULL),(4,3,2,6,'import java.util.Scanner;\r\n\r\npublic class Main {\r\n    // 二分查找：返回 target 在有序数组 nums 中的索引，若不存在返回 -1\r\n    public static int binarySearch(int[] nums, int target) {\r\n        int left = 0, right = nums.length - 1;\r\n        while (left <= right) {\r\n            int mid = left + (right - left) / 2; // 防止溢出\r\n            if (nums[mid] == target) {\r\n                return mid;\r\n            } else if (nums[mid] < target) {\r\n                left = mid + 1;\r\n            } else {\r\n                right = mid - 1;\r\n            }\r\n        }\r\n        return -1;\r\n    }\r\n\r\n    public static void main(String[] args) {\r\n        Scanner sc = new Scanner(System.in);\r\n        \r\n        // 读取数组长度\r\n        int n = sc.nextInt();\r\n        int[] nums = new int[n];\r\n        // 读取数组元素\r\n        for (int i = 0; i < n; i++) {\r\n            nums[i] = sc.nextInt();\r\n        }\r\n        // 读取目标值\r\n        int target = sc.nextInt();\r\n        \r\n        // 调用二分查找并输出结果\r\n        int result = binarySearch(nums, target);\r\n        System.out.println(result);\r\n    }\r\n}','JAVA','WRONG_ANSWER',268,0,'答案错误','2026-06-18 11:31:04',NULL,NULL);
/*!40000 ALTER TABLE `contest_submission` ENABLE KEYS */;
UNLOCK TABLES;

