  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_problem_company` (`problem_id`,`company_id`),
  KEY `idx_company_id` (`company_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4966 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='题目-企业关联表';
