DROP TABLE IF EXISTS `problem_similar`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `problem_similar` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `problem_id` bigint NOT NULL COMMENT '题目',
  `similar_problem_id` bigint NOT NULL COMMENT '相似题目',
  `reason` varchar(120) DEFAULT NULL COMMENT '为什么说它像',
  `sort_order` int DEFAULT '0' COMMENT '展示顺序',
