--
-- Table structure for table `problem_solution`
--

DROP TABLE IF EXISTS `problem_solution`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `problem_solution` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `problem_id` bigint NOT NULL COMMENT '题目ID',
  `language` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '语言：JAVA/CPP/C/PYTHON/JAVASCRIPT/SQL/TEXT',
  `code` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '已验证的完整代码（或讲解 / SQL）',
  `note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '算法哥写之前的一句话',
  `verified` tinyint NOT NULL DEFAULT '0' COMMENT '是否已提交验证通过',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_problem_lang` (`problem_id`,`language`)
) ENGINE=InnoDB AUTO_INCREMENT=695 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='题目-已验证参考答案（多语言）';
/*!40101 SET character_set_client = @saved_cs_client */;

