INSERT INTO `problem_solution` VALUES (1,3,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        int W = sc.nextInt();\n        int[] values = new int[n];\n        int[] weights = new int[n];\n        for (int i = 0; i < n; i++) {\n            values[i] = sc.nextInt();\n        }\n        for (int i = 0; i < n; i++) {\n            weights[i] = sc.nextInt();\n        }\n        int[] dp = new int[W + 1];\n        for (int i = 0; i < n; i++) {\n            for (int j = W; j >= weights[i]; j--) {\n                dp[j] = Math.max(dp[j], dp[j - weights[i]] + values[i]);\n            }\n        }\n        System.out.println(dp[W]);\n    }\n}',NULL,1,'2026-09-27 13:04:30','2026-09-28 15:16:03'),(2,2,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        String text1 = scanner.nextLine();\n        String text2 = scanner.nextLine();\n        int m = text1.length();\n        int n = text2.length();\n        int[][] dp = new int[m + 1][n + 1];\n        for (int i = 1; i <= m; i++) {\n            for (int j = 1; j <= n; j++) {\n                if (text1.charAt(i - 1) == text2.charAt(j - 1)) {\n                    dp[i][j] = dp[i - 1][j - 1] + 1;\n                } else {\n                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n        System.out.println(dp[m][n]);\n    }\n}',NULL,1,'2026-09-27 13:04:30','2026-09-28 15:16:03'),(3,1,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        if (n <= 2) {\n            System.out.println(n);\n            return;\n        }\n        int a = 1, b = 2;\n        for (int i = 3; i <= n; i++) {\n            int c = a + b;\n            a = b;\n            b = c;\n        }\n        System.out.println(b);\n    }\n}',NULL,1,'2026-09-27 13:04:30','2026-09-28 15:16:03'),(4,4,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        int[] tails = new int[n];\n        int size = 0;\n        for (int x : nums) {\n            int l = 0, r = size;\n            while (l < r) {\n                int mid = l + (r - l) / 2;\n                if (tails[mid] < x) {\n                    l = mid + 1;\n                } else {\n                    r = mid;\n                }\n            }\n            tails[l] = x;\n            if (l == size) {\n                size++;\n            }\n        }\n\n        System.out.println(size);\n    }\n}',NULL,1,'2026-09-27 13:04:30','2026-09-28 15:16:03'),(5,3,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, W;\n    cin >> n >> W;\n    vector<int> values(n), weights(n);\n    for (int i = 0; i < n; i++) {\n        cin >> values[i];\n    }\n    for (int i = 0; i < n; i++) {\n        cin >> weights[i];\n    }\n    vector<int> dp(W + 1, 0);\n    for (int i = 0; i < n; i++) {\n        for (int j = W; j >= weights[i]; j--) {\n            dp[j] = max(dp[j], dp[j - weights[i]] + values[i]);\n        }\n    }\n    cout << dp[W] << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:04:32','2026-09-28 15:16:03'),(6,1,'CPP','#include <iostream>\nusing namespace std;\n\nint climbStairs(int n) {\n    if (n <= 2) {\n        return n;\n    }\n    int a = 1;\n    int b = 2;\n    for (int i = 3; i <= n; i++) {\n        int c = a + b;\n        a = b;\n        b = c;\n    }\n    return b;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    cout << climbStairs(n) << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:04:32','2026-09-28 15:16:03'),(7,2,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nint main() {\n    std::string text1, text2;\n    std::getline(std::cin, text1);\n    std::getline(std::cin, text2);\n    int m = text1.length();\n    int n = text2.length();\n    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));\n    for (int i = 1; i <= m; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (text1[i - 1] == text2[j - 1]) {\n                dp[i][j] = dp[i - 1][j - 1] + 1;\n            } else {\n                dp[i][j] = std::max(dp[i - 1][j], dp[i][j - 1]);\n            }\n        }\n    }\n    std::cout << dp[m][n] << std::endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:04:33','2026-09-28 15:16:03'),(8,4,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    vector<int> tails(n);\n    int len = 0;\n\n    for (int x : nums) {\n        int left = 0, right = len;\n        while (left < right) {\n            int mid = left + (right - left) / 2;\n            if (tails[mid] < x) {\n                left = mid + 1;\n            } else {\n                right = mid;\n            }\n        }\n        tails[left] = x;\n        if (left == len) {\n            len++;\n        }\n    }\n\n    cout << len << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:04:33','2026-09-28 15:16:03'),(9,3,'C','#include <stdio.h>\n\nint main() {\n    int n, W;\n    scanf(\"%d %d\", &n, &W);\n    int values[n], weights[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &values[i]);\n    }\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &weights[i]);\n    }\n    int dp[W + 1];\n    for (int i = 0; i <= W; i++) {\n        dp[i] = 0;\n    }\n    for (int i = 0; i < n; i++) {\n        for (int j = W; j >= weights[i]; j--) {\n            int candidate = dp[j - weights[i]] + values[i];\n            if (candidate > dp[j]) {\n                dp[j] = candidate;\n            }\n        }\n    }\n    printf(\"%d\\n\", dp[W]);\n    return 0;\n}',NULL,1,'2026-09-27 13:04:34','2026-09-28 15:16:03'),(10,1,'C','#include <stdio.h>\n\nint climbStairs(int n) {\n    if (n <= 2) {\n        return n;\n    }\n    int a = 1;\n    int b = 2;\n    for (int i = 3; i <= n; i++) {\n        int c = a + b;\n        a = b;\n        b = c;\n    }\n    return b;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    printf(\"%d\\n\", climbStairs(n));\n    return 0;\n}',NULL,1,'2026-09-27 13:04:34','2026-09-28 15:16:03'),(11,4,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int tails[n];\n    int len = 0;\n\n    for (int i = 0; i < n; i++) {\n        int x = nums[i];\n        int left = 0, right = len;\n        while (left < right) {\n            int mid = left + (right - left) / 2;\n            if (tails[mid] < x) {\n                left = mid + 1;\n            } else {\n                right = mid;\n            }\n        }\n        tails[left] = x;\n        if (left == len) {\n            len++;\n        }\n    }\n\n    printf(\"%d\\n\", len);\n    return 0;\n}',NULL,1,'2026-09-27 13:04:35','2026-09-28 15:16:03'),(12,3,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    n = int(data[0])\n    W = int(data[1])\n    values = list(map(int, data[2:2+n]))\n    weights = list(map(int, data[2+n:2+2*n]))\n    dp = [0] * (W + 1)\n    for i in range(n):\n        for j in range(W, weights[i] - 1, -1):\n            dp[j] = max(dp[j], dp[j - weights[i]] + values[i])\n    print(dp[W])\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:04:35','2026-09-28 15:16:03'),(13,1,'PYTHON','n = int(input())\nif n <= 2:\n    print(n)\nelse:\n    a, b = 1, 2\n    for i in range(3, n + 1):\n        a, b = b, a + b\n    print(b)',NULL,1,'2026-09-27 13:04:36','2026-09-28 15:16:03'),(14,4,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1+n]))\n\n    tails = [0] * n\n    length = 0\n\n    for x in nums:\n        left, right = 0, length\n        while left < right:\n            mid = left + (right - left) // 2\n            if tails[mid] < x:\n                left = mid + 1\n            else:\n                right = mid\n        tails[left] = x\n        if left == length:\n            length += 1\n\n    print(length)\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:04:36','2026-09-28 15:16:03'),(15,3,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const first = lines[0].split(/\\s+/).map(Number);\n    const n = first[0];\n    const W = first[1];\n    const values = lines[1].split(/\\s+/).map(Number);\n    const weights = lines[2].split(/\\s+/).map(Number);\n\n    const dp = new Array(W + 1).fill(0);\n    for (let i = 0; i < n; i++) {\n        for (let j = W; j >= weights[i]; j--) {\n            dp[j] = Math.max(dp[j], dp[j - weights[i]] + values[i]);\n        }\n    }\n    console.log(dp[W]);\n});',NULL,1,'2026-09-27 13:04:37','2026-09-28 15:16:03'),(16,1,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim(), 10);\n    console.log(climbStairs(n));\n    rl.close();\n});\n\nfunction climbStairs(n) {\n    if (n <= 2) {\n        return n;\n    }\n    let a = 1;\n    let b = 2;\n    for (let i = 3; i <= n; i++) {\n        const c = a + b;\n        a = b;\n        b = c;\n    }\n    return b;\n}',NULL,1,'2026-09-27 13:04:37','2026-09-28 15:16:03'),(17,4,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n\n    const tails = new Array(n);\n    let len = 0;\n\n    for (const x of nums) {\n        let left = 0, right = len;\n        while (left < right) {\n            const mid = left + Math.floor((right - left) / 2);\n            if (tails[mid] < x) {\n                left = mid + 1;\n            } else {\n                right = mid;\n            }\n        }\n        tails[left] = x;\n        if (left === len) {\n            len++;\n        }\n    }\n\n    console.log(len);\n});',NULL,1,'2026-09-27 13:04:38','2026-09-28 15:16:03'),(18,5,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] prices = new int[n];\n        for (int i = 0; i < n; i++) {\n            prices[i] = sc.nextInt();\n        }\n        int minPrice = Integer.MAX_VALUE;\n        int maxProfit = 0;\n        for (int price : prices) {\n            if (price < minPrice) {\n                minPrice = price;\n            } else if (price - minPrice > maxProfit) {\n                maxProfit = price - minPrice;\n            }\n        }\n        System.out.println(maxProfit);\n    }\n}',NULL,1,'2026-09-27 13:04:39','2026-09-28 15:16:03'),(19,6,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int target = sc.nextInt();\n\n        int left = 0, right = n - 1;\n        int ans = -1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] == target) {\n                ans = mid;\n                break;\n            } else if (nums[mid] < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        System.out.println(ans);\n    }\n}',NULL,1,'2026-09-27 13:04:39','2026-09-28 15:16:03'),(20,7,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int target = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int left = 0, right = n - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] == target) {\n                System.out.println(mid);\n                return;\n            } else if (nums[mid] < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        System.out.println(left);\n    }\n}',NULL,1,'2026-09-27 13:04:39','2026-09-28 15:16:03'),(21,5,'CPP','#include <iostream>\n#include <vector>\n#include <climits>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> prices(n);\n    for (int i = 0; i < n; i++) {\n        cin >> prices[i];\n    }\n    int minPrice = INT_MAX;\n    int maxProfit = 0;\n    for (int price : prices) {\n        if (price < minPrice) {\n            minPrice = price;\n        } else if (price - minPrice > maxProfit) {\n            maxProfit = price - minPrice;\n        }\n    }\n    cout << maxProfit << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:04:41','2026-09-28 15:16:03'),(22,6,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int target;\n    cin >> target;\n\n    int left = 0, right = n - 1;\n    int result = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            result = mid;\n            break;\n        } else if (nums[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n\n    cout << result << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:04:41','2026-09-28 15:16:03'),(23,7,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n, target;\n    cin >> n >> target;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int left = 0, right = n - 1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            cout << mid << endl;\n            return 0;\n        } else if (nums[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    cout << left << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:04:41','2026-09-28 15:16:03'),(24,5,'C','#include <stdio.h>\n#include <limits.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int prices[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &prices[i]);\n    }\n    int minPrice = INT_MAX;\n    int maxProfit = 0;\n    for (int i = 0; i < n; i++) {\n        int price = prices[i];\n        if (price < minPrice) {\n            minPrice = price;\n        } else if (price - minPrice > maxProfit) {\n            maxProfit = price - minPrice;\n        }\n    }\n    printf(\"%d\\n\", maxProfit);\n    return 0;\n}',NULL,1,'2026-09-27 13:04:43','2026-09-28 15:16:03'),(25,6,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int target;\n    scanf(\"%d\", &target);\n\n    int left = 0, right = n - 1;\n    int result = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            result = mid;\n            break;\n        } else if (nums[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n\n    printf(\"%d\\n\", result);\n    free(nums);\n    return 0;\n}',NULL,1,'2026-09-27 13:04:43','2026-09-28 15:16:03'),(26,7,'C','#include <stdio.h>\n\nint main() {\n    int n, target;\n    scanf(\"%d %d\", &n, &target);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int left = 0, right = n - 1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            printf(\"%d\\n\", mid);\n            return 0;\n        } else if (nums[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    printf(\"%d\\n\", left);\n    return 0;\n}',NULL,1,'2026-09-27 13:04:43','2026-09-28 15:16:03'),(27,5,'PYTHON','n = int(input())\nprices = list(map(int, input().split()))\nmin_price = float(\'inf\')\nmax_profit = 0\nfor price in prices:\n    if price < min_price:\n        min_price = price\n    elif price - min_price > max_profit:\n        max_profit = price - min_price\nprint(max_profit)',NULL,1,'2026-09-27 13:04:44','2026-09-28 15:16:03'),(28,6,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\ntarget = int(input())\n\nleft, right = 0, n - 1\nresult = -1\nwhile left <= right:\n    mid = left + (right - left) // 2\n    if nums[mid] == target:\n        result = mid\n        break\n    elif nums[mid] < target:\n        left = mid + 1\n    else:\n        right = mid - 1\n\nprint(result)',NULL,1,'2026-09-27 13:04:44','2026-09-28 15:16:03'),(29,7,'PYTHON','n, target = map(int, input().split())\nnums = list(map(int, input().split()))\n\nleft, right = 0, n - 1\nwhile left <= right:\n    mid = left + (right - left) // 2\n    if nums[mid] == target:\n        print(mid)\n        break\n    elif nums[mid] < target:\n        left = mid + 1\n    else:\n        right = mid - 1\nelse:\n    print(left)',NULL,1,'2026-09-27 13:04:45','2026-09-28 15:16:03'),(30,5,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const prices = lines[1].split(\' \').map(Number);\n    let minPrice = Infinity;\n    let maxProfit = 0;\n    for (let price of prices) {\n        if (price < minPrice) {\n            minPrice = price;\n        } else if (price - minPrice > maxProfit) {\n            maxProfit = price - minPrice;\n        }\n    }\n    console.log(maxProfit);\n});',NULL,1,'2026-09-27 13:04:45','2026-09-28 15:16:03'),(31,6,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    const target = parseInt(lines[2]);\n\n    let left = 0, right = n - 1;\n    let result = -1;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] === target) {\n            result = mid;\n            break;\n        } else if (nums[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n\n    console.log(result);\n});',NULL,1,'2026-09-27 13:04:46','2026-09-28 15:16:03'),(32,7,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const [n, target] = lines[0].split(\' \').map(Number);\n        const nums = lines[1].split(\' \').map(Number);\n        let left = 0, right = n - 1;\n        while (left <= right) {\n            const mid = left + Math.floor((right - left) / 2);\n            if (nums[mid] === target) {\n                console.log(mid);\n                rl.close();\n                return;\n            } else if (nums[mid] < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        console.log(left);\n        rl.close();\n    }\n});',NULL,1,'2026-09-27 13:04:46','2026-09-28 15:16:03'),(33,48,'SQL','DELETE p1 FROM Person p1\nJOIN Person p2 ON p1.email = p2.email AND p1.id > p2.id;',NULL,1,'2026-09-27 13:04:47','2026-09-28 15:16:03'),(34,46,'SQL','SELECT email FROM Person GROUP BY email HAVING COUNT(*) > 1;',NULL,1,'2026-09-27 13:04:47','2026-09-28 15:16:03'),(35,49,'SQL','SELECT w1.id\nFROM Weather w1\nJOIN Weather w2\n  ON DATEDIFF(w1.recordDate, w2.recordDate) = 1\nWHERE w1.temperature > w2.temperature;',NULL,1,'2026-09-27 13:04:47','2026-09-28 15:16:03'),(36,8,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int target = sc.nextInt();\n\n        int left = findFirst(nums, target);\n        int right = findLast(nums, target);\n\n        System.out.println(\"[\" + left + \",\" + right + \"]\");\n    }\n\n    private static int findFirst(int[] nums, int target) {\n        int left = 0, right = nums.length - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] >= target) {\n                right = mid - 1;\n            } else {\n                left = mid + 1;\n            }\n        }\n        if (left < nums.length && nums[left] == target) {\n            return left;\n        }\n        return -1;\n    }\n\n    private static int findLast(int[] nums, int target) {\n        int left = 0, right = nums.length - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] <= target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        if (right >= 0 && nums[right] == target) {\n            return right;\n        }\n        return -1;\n    }\n}',NULL,1,'2026-09-27 13:04:47','2026-09-28 15:16:03'),(37,47,'SQL','SELECT (SELECT DISTINCT salary FROM Employee ORDER BY salary DESC LIMIT 1 OFFSET 1) AS SecondHighestSalary;',NULL,1,'2026-09-27 13:04:48','2026-09-28 15:16:03'),(38,10,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int x = sc.nextInt();\n        System.out.println(mySqrt(x));\n    }\n\n    public static int mySqrt(int x) {\n        if (x == 0) return 0;\n        int left = 1, right = x, ans = 0;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (mid <= x / mid) {\n                ans = mid;\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        return ans;\n    }\n}',NULL,1,'2026-09-27 13:04:48','2026-09-28 15:16:03'),(39,9,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int target = sc.nextInt();\n        System.out.println(search(nums, target));\n    }\n\n    public static int search(int[] nums, int target) {\n        int left = 0, right = nums.length - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] == target) {\n                return mid;\n            }\n            if (nums[left] <= nums[mid]) {\n                if (target >= nums[left] && target < nums[mid]) {\n                    right = mid - 1;\n                } else {\n                    left = mid + 1;\n                }\n            } else {\n                if (target > nums[mid] && target <= nums[right]) {\n                    left = mid + 1;\n                } else {\n                    right = mid - 1;\n                }\n            }\n        }\n        return -1;\n    }\n}',NULL,1,'2026-09-27 13:04:48','2026-09-28 15:16:03'),(40,50,'SQL','SELECT d.Name AS Department, e.Name AS Employee, e.Salary\nFROM Employee e\nJOIN Department d ON e.DepartmentId = d.Id\nWHERE (e.DepartmentId, e.Salary) IN (\n    SELECT DepartmentId, MAX(Salary)\n    FROM Employee\n    GROUP BY DepartmentId\n);',NULL,1,'2026-09-27 13:04:49','2026-09-28 15:16:03'),(41,52,'TEXT','1. **安全性**：HTTP明文传输，易被窃听篡改；HTTPS在HTTP下加入TLS/SSL加密，保证机密性、完整性。\n\n2. **端口**：HTTP默认80，HTTPS默认443。\n\n3. **证书**：HTTPS需CA颁发证书验证服务器身份，防中间人攻击；HTTP无身份验证。\n\n4. **性能**：HTTPS因加解密和握手，延迟略高、消耗更多CPU，但现代优化后差距很小。\n\n5. **URL**：HTTPS以https://开头，HTTP为http://。\n\n核心：HTTPS = HTTP + TLS，解决明文传输的安全问题。',NULL,1,'2026-09-27 13:04:49','2026-09-28 15:16:03'),(42,51,'TEXT','1. **连接**：TCP面向连接，需三次握手；UDP无连接，直接发送。\n2. **可靠性**：TCP可靠，有确认、重传、排序、去重；UDP不可靠，不保证送达和顺序。\n3. **传输方式**：TCP面向字节流；UDP面向数据报，保留报文边界。\n4. **速度与开销**：TCP头部20字节起，开销大、速度慢；UDP头部仅8字节，开销小、速度快。\n5. **拥塞与流量控制**：TCP有拥塞控制和流量控制；UDP无。\n6. **通信模式**：TCP仅一对一；UDP支持一对一、一对多、多对多（广播、组播）。\n7. **适用场景**：TCP用于文件传输、网页等要求可靠的场景；UDP用于直播、游戏、DNS等重实时低延迟场景。',NULL,1,'2026-09-27 13:04:49','2026-09-28 15:16:03'),(43,53,'TEXT','HTTP 常见请求方法：\n\n- **GET**：获取资源，参数在 URL，幂等、可缓存，不改变服务端状态。\n- **POST**：提交数据、创建资源，参数在请求体，非幂等，不可缓存。\n- **PUT**：全量更新资源，幂等，客户端提供完整资源。\n- **PATCH**：局部更新资源，非幂等。\n- **DELETE**：删除资源，幂等。\n- **HEAD**：同 GET 但只返回响应头，用于探测。\n- **OPTIONS**：查询支持的方法，用于 CORS 预检。\n\n核心区分：**幂等性**（GET/PUT/DELETE 幂等，POST 非幂等）与**安全性**（GET/HEAD 安全，不修改资源）。',NULL,1,'2026-09-27 13:04:49','2026-09-28 15:16:03'),(44,8,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint findFirst(const vector<int>& nums, int target) {\n    int left = 0, right = nums.size() - 1;\n    int ans = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] >= target) {\n            if (nums[mid] == target) ans = mid;\n            right = mid - 1;\n        } else {\n            left = mid + 1;\n        }\n    }\n    return ans;\n}\n\nint findLast(const vector<int>& nums, int target) {\n    int left = 0, right = nums.size() - 1;\n    int ans = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] <= target) {\n            if (nums[mid] == target) ans = mid;\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return ans;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int target;\n    cin >> target;\n\n    int left = findFirst(nums, target);\n    int right = findLast(nums, target);\n\n    cout << \"[\" << left << \",\" << right << \"]\" << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:04:50','2026-09-28 15:16:03'),(45,10,'CPP','#include <iostream>\nusing namespace std;\n\nint mySqrt(int x) {\n    if (x == 0) return 0;\n    int left = 1, right = x;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (mid <= x / mid) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return right;\n}\n\nint main() {\n    int x;\n    cin >> x;\n    cout << mySqrt(x) << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:04:50','2026-09-28 15:16:03'),(46,54,'TEXT','**核心区别：**\n\n1. **存储位置**：Cookie 存在客户端浏览器；Session 存在服务端（Session ID 通常借 Cookie 传给客户端）。\n2. **安全性**：Cookie 明文可见、可篡改，安全性低；Session 存服务端，相对安全。\n3. **容量**：Cookie 单个约 4KB 且数量受限；Session 受服务器内存限制，容量更大。\n4. **性能**：Cookie 随每次请求发送，增加带宽；Session 存服务端，但高并发下占内存、需考虑共享。\n5. **生命周期**：Cookie 可设过期时间长期保存；Session 随会话结束或超时失效。\n\n**使用场景**：Cookie 用于记住登录状态、偏好设置等非敏感轻量数据；Session 用于存用户身份、权限等敏感信息。',NULL,1,'2026-09-27 13:04:50','2026-09-28 15:16:03'),(47,9,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint search(vector<int>& nums, int target) {\n    int left = 0, right = nums.size() - 1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            return mid;\n        }\n        if (nums[left] <= nums[mid]) {\n            if (target >= nums[left] && target < nums[mid]) {\n                right = mid - 1;\n            } else {\n                left = mid + 1;\n            }\n        } else {\n            if (target > nums[mid] && target <= nums[right]) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n    }\n    return -1;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int target;\n    cin >> target;\n    cout << search(nums, target) << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:04:50','2026-09-28 15:16:03'),(48,57,'TEXT','死锁产生的四个必要条件：\n\n1. **互斥**：资源一次只能被一个进程占用。\n2. **占有并等待**：进程已持有至少一个资源，同时又在等待其他被占用的资源。\n3. **不可剥夺**：资源只能由持有它的进程主动释放，不能被强行抢占。\n4. **循环等待**：存在一个进程与资源的环形等待链，每个进程都在等待下一个进程持有的资源。\n\n四个条件同时满足才可能死锁，破坏其中任一条件即可预防死锁。',NULL,1,'2026-09-27 13:04:51','2026-09-28 15:16:03'),(49,56,'TEXT','1. **定义**：进程是资源分配的基本单位；线程是CPU调度的基本单位。\n2. **资源**：进程有独立地址空间和资源；线程共享所属进程的资源（内存、文件等），仅独享栈和寄存器。\n3. **开销**：进程创建、切换、销毁开销大；线程轻量，切换开销小。\n4. **通信**：进程间通信需借助IPC（管道、共享内存等）；线程可直接读写共享内存，但需同步。\n5. **独立性**：进程相互隔离，一个崩溃不影响其他；线程共享进程，一个线程崩溃可能导致整个进程退出。\n6. **关系**：一个进程可含多个线程，线程依附于进程存在。',NULL,1,'2026-09-27 13:04:51','2026-09-28 15:16:03'),(50,55,'TEXT','**跨域问题**：浏览器同源策略限制，协议、域名、端口任一不同即为跨域，导致 AJAX 请求被拦截（请求可能发出，但响应被阻止）。\n\n**常见解决方法**：\n1. **CORS**：服务端设置 `Access-Control-Allow-Origin` 等响应头，最主流。\n2. **Nginx 反向代理**：同源访问代理服务器，由服务器转发，规避浏览器限制。\n3. **JSONP**：利用 script 标签，仅支持 GET，已少用。\n4. **开发环境代理**：如 webpack/vite devServer proxy。\n5. **postMessage / document.domain**：用于窗口间通信或子域场景。\n\n**核心**：跨域是浏览器行为，服务端之间无跨域；CORS 需处理预检请求（OPTIONS）。',NULL,1,'2026-09-27 13:04:51','2026-09-28 15:16:03'),(51,10,'C','#include <stdio.h>\n\nint mySqrt(int x) {\n    if (x == 0) return 0;\n    int left = 1, right = x;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (mid <= x / mid) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return right;\n}\n\nint main() {\n    int x;\n    scanf(\"%d\", &x);\n    printf(\"%d\\n\", mySqrt(x));\n    return 0;\n}',NULL,1,'2026-09-27 13:04:51','2026-09-28 15:16:03'),(52,2,'PYTHON','text1 = input()\ntext2 = input()\nm = len(text1)\nn = len(text2)\ndp = [[0] * (n + 1) for _ in range(m + 1)]\nfor i in range(1, m + 1):\n    for j in range(1, n + 1):\n        if text1[i - 1] == text2[j - 1]:\n            dp[i][j] = dp[i - 1][j - 1] + 1\n        else:\n            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])\nprint(dp[m][n])',NULL,1,'2026-09-27 13:04:52','2026-09-28 15:16:03'),(53,58,'TEXT','常见进程调度算法：\n\n- **FCFS（先来先服务）**：按到达顺序执行，非抢占。实现简单，但长作业先到会导致短作业等待，平均等待时间长（护航效应）。\n- **SJF（短作业优先）**：选运行时间最短的进程，分抢占/非抢占。平均等待时间最优，但需预知运行时间，长作业可能饥饿。\n- **RR（时间片轮转）**：按到达顺序轮流执行固定时间片，抢占式。响应快、公平，适合分时系统；时间片过大退化为FCFS，过小则切换开销大。\n- **优先级调度**：按优先级选进程，分抢占/非抢占，低优先级可能饥饿，可用老化解决。\n- **多级反馈队列**：多队列不同优先级+时间片，兼顾响应与吞吐，综合性强。',NULL,1,'2026-09-27 13:04:52','2026-09-28 15:16:03'),(54,8,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint findFirst(int nums[], int n, int target) {\n    int left = 0, right = n - 1;\n    int ans = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] >= target) {\n            if (nums[mid] == target) ans = mid;\n            right = mid - 1;\n        } else {\n            left = mid + 1;\n        }\n    }\n    return ans;\n}\n\nint findLast(int nums[], int n, int target) {\n    int left = 0, right = n - 1;\n    int ans = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] <= target) {\n            if (nums[mid] == target) ans = mid;\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return ans;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int target;\n    scanf(\"%d\", &target);\n\n    int left = findFirst(nums, n, target);\n    int right = findLast(nums, n, target);\n\n    printf(\"[%d,%d]\\n\", left, right);\n\n    free(nums);\n    return 0;\n}',NULL,1,'2026-09-27 13:04:52','2026-09-28 15:16:03'),(55,9,'C','#include <stdio.h>\n\nint search(int nums[], int n, int target) {\n    int left = 0, right = n - 1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            return mid;\n        }\n        if (nums[left] <= nums[mid]) {\n            if (target >= nums[left] && target < nums[mid]) {\n                right = mid - 1;\n            } else {\n                left = mid + 1;\n            }\n        } else {\n            if (target > nums[mid] && target <= nums[right]) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n    }\n    return -1;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int target;\n    scanf(\"%d\", &target);\n    printf(\"%d\\n\", search(nums, n, target));\n    return 0;\n}',NULL,1,'2026-09-27 13:04:52','2026-09-28 15:16:03'),(56,59,'TEXT','常见页面置换算法：\n\n- **OPT（最佳置换）**：淘汰未来最长时间不被访问的页面。缺页率最低，但需预知未来，仅作理论基准。\n- **FIFO（先进先出）**：淘汰最早进入内存的页面。实现简单，但可能淘汰常用页，且存在 Belady 异常（增加物理块反而缺页增多）。\n- **LRU（最近最久未使用）**：淘汰最长时间未被访问的页面。基于局部性原理，性能接近 OPT，但需记录访问历史，开销较大。\n- **Clock（时钟）**：LRU 的近似，用循环队列加访问位，访问位置 1，淘汰时扫描置 0，兼顾性能与开销。\n\n考点：各算法淘汰依据、优缺点、Belady 异常及 LRU 与 OPT 的区别。',NULL,1,'2026-09-27 13:04:52','2026-09-28 15:16:03'),(57,10,'PYTHON','import sys\n\ndef mySqrt(x):\n    if x == 0:\n        return 0\n    left, right = 1, x\n    while left <= right:\n        mid = left + (right - left) // 2\n        if mid <= x // mid:\n            left = mid + 1\n        else:\n            right = mid - 1\n    return right\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    x = int(data[0])\n    print(mySqrt(x))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:04:53','2026-09-28 15:16:03'),(58,61,'TEXT','**概念**：保证一个类仅有一个实例，并提供全局访问点。\n\n**实现要点**：\n1. 私有构造器，禁止外部 new。\n2. 静态私有实例变量。\n3. 提供静态公有获取方法。\n\n**常见方式**：\n- 饿汉式：类加载即创建，线程安全但可能浪费。\n- 懒汉式：延迟创建，需加锁或用双重检查锁保证线程安全。\n- 静态内部类：延迟加载且线程安全，推荐。\n- 枚举：最简洁，天然防反射和反序列化破坏。\n\n**使用场景**：全局配置、连接池、线程池、日志对象、缓存等需唯一实例且频繁访问的资源。',NULL,1,'2026-09-27 13:04:53','2026-09-28 15:16:03'),(59,60,'TEXT','银行家算法是操作系统的**死锁避免**算法。\n\n- **原理**：进程运行前先声明最大资源需求。系统分配资源前，先试探性分配，再执行**安全性检查**：判断是否存在一个安全序列，使所有进程能依次获得所需资源并完成。若存在则真正分配，否则拒绝，让进程等待。\n- **核心数据结构**：可利用资源、最大需求、已分配、需求矩阵。\n- **作用**：在资源分配前预判是否会导致系统进入不安全状态，从而**避免死锁**，而非事后检测或解除。\n- **局限**：需预知最大需求、进程数固定、资源单一时效率低，实际中较少直接使用。',NULL,1,'2026-09-27 13:04:53','2026-09-28 15:16:03'),(60,62,'TEXT','工厂模式是创建型设计模式，用工厂封装对象创建过程，使调用方与具体类解耦。\n\n分类：\n1. 简单工厂：一个工厂类按参数创建不同产品，不属于GOF23，违反开闭原则。\n2. 工厂方法：定义创建接口，由子类决定实例化哪个类，符合开闭原则。\n3. 抽象工厂：创建一系列相关产品族，适合多产品线组合。\n\n使用场景：对象创建逻辑复杂或需隐藏具体实现；产品类型可能扩展；需统一管理一族产品。',NULL,1,'2026-09-27 13:04:54','2026-09-28 15:16:03'),(61,8,'PYTHON','import sys\n\ndef find_first(nums, target):\n    left, right = 0, len(nums) - 1\n    ans = -1\n    while left <= right:\n        mid = left + (right - left) // 2\n        if nums[mid] >= target:\n            if nums[mid] == target:\n                ans = mid\n            right = mid - 1\n        else:\n            left = mid + 1\n    return ans\n\ndef find_last(nums, target):\n    left, right = 0, len(nums) - 1\n    ans = -1\n    while left <= right:\n        mid = left + (right - left) // 2\n        if nums[mid] <= target:\n            if nums[mid] == target:\n                ans = mid\n            left = mid + 1\n        else:\n            right = mid - 1\n    return ans\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    target = int(data[1 + n])\n    left = find_first(nums, target)\n    right = find_last(nums, target)\n    print(f\"[{left},{right}]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:04:54','2026-09-28 15:16:03'),(62,2,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 2) {\n        const text1 = lines[0];\n        const text2 = lines[1];\n        const m = text1.length;\n        const n = text2.length;\n        const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));\n        for (let i = 1; i <= m; i++) {\n            for (let j = 1; j <= n; j++) {\n                if (text1[i - 1] === text2[j - 1]) {\n                    dp[i][j] = dp[i - 1][j - 1] + 1;\n                } else {\n                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n        console.log(dp[m][n]);\n        rl.close();\n    }\n});',NULL,1,'2026-09-27 13:04:54','2026-09-28 15:16:03'),(63,9,'PYTHON','import sys\n\ndef search(nums, target):\n    left, right = 0, len(nums) - 1\n    while left <= right:\n        mid = left + (right - left) // 2\n        if nums[mid] == target:\n            return mid\n        if nums[left] <= nums[mid]:\n            if nums[left] <= target < nums[mid]:\n                right = mid - 1\n            else:\n                left = mid + 1\n        else:\n            if nums[mid] < target <= nums[right]:\n                left = mid + 1\n            else:\n                right = mid - 1\n    return -1\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    target = int(data[1 + n])\n    print(search(nums, target))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:04:54','2026-09-28 15:16:03'),(64,10,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const x = parseInt(line.trim(), 10);\n    console.log(mySqrt(x));\n    rl.close();\n});\n\nfunction mySqrt(x) {\n    if (x === 0) return 0;\n    let left = 1, right = x;\n    while (left <= right) {\n        let mid = left + Math.floor((right - left) / 2);\n        if (mid <= Math.floor(x / mid)) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return right;\n}',NULL,1,'2026-09-27 13:04:54','2026-09-28 15:16:03'),(65,63,'TEXT','**概念**：观察者模式定义一对多依赖关系，当被观察者（Subject）状态改变时，自动通知所有观察者（Observer）更新。\n\n**核心角色**：\n- Subject：维护观察者列表，提供注册/注销/通知接口。\n- Observer：定义更新接口，接收通知。\n\n**使用场景**：\n- 事件驱动系统：GUI 事件监听、按钮点击回调。\n- 消息订阅：发布-订阅、MQ、Redis 订阅。\n- 数据联动：MVC 中 Model 变化通知 View 刷新。\n- 跨模块解耦：状态变更需通知多个不相关模块。\n\n**优点**：解耦、支持广播、符合开闭原则。\n**缺点**：通知顺序不可控、观察者过多影响性能、可能循环依赖。',NULL,1,'2026-09-27 13:04:54','2026-09-28 15:16:03'),(66,64,'TEXT','**概念**：策略模式定义一系列算法，将每个算法封装成独立类并可相互替换，使算法的变化独立于使用它的客户端。\n\n**核心角色**：抽象策略（接口）、具体策略（实现类）、上下文（持有策略并调用）。\n\n**使用场景**：\n1. 同一问题有多种算法，需运行时动态切换（如排序、支付方式、促销计算）。\n2. 用多分支 if-else/switch 判断不同行为，且分支会持续扩展。\n3. 需要隔离算法实现细节，避免客户端依赖具体算法。\n\n**优点**：符合开闭原则，消除条件分支，算法可复用、易扩展。\n**缺点**：策略类增多，客户端需了解各策略差异。',NULL,1,'2026-09-27 13:04:55','2026-09-28 15:16:03'),(67,65,'TEXT','MVC是一种分层架构模式，将应用分为三层：\n\n- **Model（模型）**：封装数据和业务逻辑，负责数据的存取与状态管理，不依赖View和Controller。\n- **View（视图）**：负责数据展示和用户界面渲染，只呈现Model的数据，不处理业务逻辑。\n- **Controller（控制器）**：接收用户输入，调用Model处理业务，再选择合适的View返回结果，起协调调度作用。\n\n核心思想是**关注点分离**：三者职责单一、解耦，便于维护、复用和测试。',NULL,1,'2026-09-27 13:04:55','2026-09-28 15:16:03'),(68,66,'TEXT','面向对象三大特性：\n\n1. **封装**：将数据和操作数据的方法绑定在一起，隐藏内部实现细节，仅对外暴露必要接口。目的是降低耦合、提高安全性和可维护性。\n\n2. **继承**：子类复用父类的属性和方法，并可扩展或重写。目的是代码复用、建立类之间的层次关系。分为单继承和多继承。\n\n3. **多态**：同一接口在不同对象上有不同表现。分为编译时多态（重载）和运行时多态（重写，依赖继承与父类引用指向子类对象）。目的是提高扩展性和灵活性。\n\n三者关系：封装是基础，继承是手段，多态是目的。',NULL,1,'2026-09-27 13:04:55','2026-09-28 15:16:03'),(69,9,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    const target = parseInt(lines[2]);\n    console.log(search(nums, target));\n});\n\nfunction search(nums, target) {\n    let left = 0, right = nums.length - 1;\n    while (left <= right) {\n        let mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] === target) {\n            return mid;\n        }\n        if (nums[left] <= nums[mid]) {\n            if (target >= nums[left] && target < nums[mid]) {\n                right = mid - 1;\n            } else {\n                left = mid + 1;\n            }\n        } else {\n            if (target > nums[mid] && target <= nums[right]) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n    }\n    return -1;\n}',NULL,1,'2026-09-27 13:04:56','2026-09-28 15:16:03'),(70,67,'TEXT','1. **定义**：抽象类用 abstract class 声明，可含抽象方法和具体方法；接口用 interface 声明，方法默认 public abstract（Java 8 后可有 default、static 方法）。\n\n2. **继承**：类只能单继承抽象类，但可实现多个接口。\n\n3. **成员变量**：抽象类可有普通变量、常量；接口变量默认 public static final 常量。\n\n4. **构造器**：抽象类有构造器；接口没有。\n\n5. **访问修饰符**：抽象类方法可用各种修饰符；接口方法默认 public。\n\n6. **设计语义**：抽象类表示“is-a”，用于代码复用；接口表示“can-do”，用于定义行为契约、解耦。\n\n7. **使用场景**：共性逻辑用抽象类，扩展能力用接口。',NULL,1,'2026-09-27 13:04:56','2026-09-28 15:16:03'),(71,8,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    const target = parseInt(lines[2]);\n\n    const left = findFirst(nums, target);\n    const right = findLast(nums, target);\n\n    console.log(`[${left},${right}]`);\n});\n\nfunction findFirst(nums, target) {\n    let left = 0, right = nums.length - 1;\n    let ans = -1;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] >= target) {\n            if (nums[mid] === target) ans = mid;\n            right = mid - 1;\n        } else {\n            left = mid + 1;\n        }\n    }\n    return ans;\n}\n\nfunction findLast(nums, target) {\n    let left = 0, right = nums.length - 1;\n    let ans = -1;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] <= target) {\n            if (nums[mid] === target) ans = mid;\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return ans;\n}',NULL,1,'2026-09-27 13:04:56','2026-09-28 15:16:03'),(72,12,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int maxReach = 0;\n        boolean canReach = true;\n        for (int i = 0; i < n; i++) {\n            if (i > maxReach) {\n                canReach = false;\n                break;\n            }\n            maxReach = Math.max(maxReach, i + nums[i]);\n            if (maxReach >= n - 1) {\n                break;\n            }\n        }\n        System.out.println(canReach && maxReach >= n - 1);\n    }\n}',NULL,1,'2026-09-27 13:04:56','2026-09-28 15:16:03'),(73,68,'TEXT','**重载（Overload）**：同一类中，方法名相同、参数列表不同（个数、类型、顺序），与返回值无关，编译期确定，是编译时多态。\n\n**重写（Override）**：子类重新实现父类方法，方法名、参数列表、返回值（协变除外）必须相同，访问权限不能更严，不能重写 private/static/final 方法，运行期确定，是运行时多态。\n\n**核心区别**：\n1. 范围：重载同类内，重写发生在父子类间。\n2. 签名：重载参数必须不同，重写参数必须相同。\n3. 时机：重载编译期绑定，重写运行期绑定。\n4. 目的：重载扩展同类方法形式，重写改变父类行为。',NULL,1,'2026-09-27 13:04:56','2026-09-28 15:16:03'),(74,69,'TEXT','1. **指代对象**：this 指向当前对象自身；super 指向当前对象的父类部分（父类实例）。\n2. **访问成员**：this 访问本类成员（属性、方法），可区分同名参数与成员变量；super 访问父类成员，用于调用被子类重写的方法或父类属性。\n3. **调用构造器**：this() 调用本类其他构造器；super() 调用父类构造器。二者都必须放在构造器首行，且不能同时出现。\n4. **使用场景**：this 用于区分变量、链式调用、返回当前对象；super 用于子类访问父类被覆盖的成员、初始化父类。\n5. **本质**：this 是当前对象引用；super 不是引用，只是访问父类成员的语法关键字。',NULL,1,'2026-09-27 13:04:56','2026-09-28 15:16:03'),(75,11,'JAVA','import java.util.Arrays;\nimport java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int gn = sc.nextInt();\n        int sn = sc.nextInt();\n        int[] g = new int[gn];\n        int[] s = new int[sn];\n        for (int i = 0; i < gn; i++) g[i] = sc.nextInt();\n        for (int i = 0; i < sn; i++) s[i] = sc.nextInt();\n        Arrays.sort(g);\n        Arrays.sort(s);\n        int i = 0, j = 0, count = 0;\n        while (i < gn && j < sn) {\n            if (s[j] >= g[i]) {\n                count++;\n                i++;\n                j++;\n            } else {\n                j++;\n            }\n        }\n        System.out.println(count);\n    }\n}',NULL,1,'2026-09-27 13:04:56','2026-09-28 15:16:03'),(76,70,'TEXT','**概念**：继承是面向对象中让子类复用父类属性和方法的机制，表达“is-a”关系。\n\n**优点**：\n1. 代码复用，减少冗余。\n2. 提高可扩展性，子类可扩展父类功能。\n3. 多态基础，便于统一接口编程。\n\n**缺点**：\n1. 耦合度高，父类改动易影响子类（脆弱基类问题）。\n2. 破坏封装，子类依赖父类实现细节。\n3. 继承层次过深导致结构复杂、难维护。\n4. 灵活性差，运行期难以改变继承关系，常建议优先组合而非继承。',NULL,1,'2026-09-27 13:04:56','2026-09-28 15:16:03'),(77,14,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] prices = new int[n];\n        for (int i = 0; i < n; i++) {\n            prices[i] = sc.nextInt();\n        }\n        int maxProfit = 0;\n        for (int i = 1; i < n; i++) {\n            if (prices[i] > prices[i - 1]) {\n                maxProfit += prices[i] - prices[i - 1];\n            }\n        }\n        System.out.println(maxProfit);\n    }\n}',NULL,1,'2026-09-27 13:04:58','2026-09-28 15:16:03'),(78,71,'TEXT','函数式编程核心概念：\n\n1. **纯函数**：相同输入必得相同输出，无副作用，不修改外部状态。\n2. **不可变性**：数据一旦创建不可更改，变更通过创建新数据实现。\n3. **一等函数**：函数可作为参数传递、作为返回值、赋值给变量。\n4. **高阶函数**：接收函数或返回函数的函数，如 map、filter、reduce。\n5. **函数组合**：将小函数组合成复杂函数，强调声明式而非命令式。\n6. **引用透明**：表达式可被其计算结果替换而不影响程序。\n\n特点：无副作用、易于测试与并发、代码简洁可推理；但可能带来性能开销与学习成本。',NULL,1,'2026-09-27 13:04:58','2026-09-28 15:16:03'),(79,73,'TEXT','Stream API用于对集合进行声明式、函数式处理，核心用法：\n\n1. **创建**：集合.stream()、Arrays.stream()、Stream.of()。\n2. **中间操作**（惰性，返回新流）：filter过滤、map映射、flatMap扁平化、distinct去重、sorted排序、limit/skip截取。\n3. **终端操作**（触发执行）：forEach遍历、collect收集、reduce归约、count、anyMatch/allMatch、findFirst。\n4. **特性**：惰性求值，需终端操作才执行；不修改原数据；支持串行与parallelStream并行。\n\n核心思想：链式调用，将数据处理流程化。',NULL,1,'2026-09-27 13:04:58','2026-09-28 15:16:03'),(80,72,'TEXT','Lambda表达式是匿名函数，用于简化函数式接口（仅一个抽象方法的接口）的实例化。\n\n核心要点：\n1. 语法：(参数) -> 表达式或代码块，参数类型可省略，由编译器推断。\n2. 本质：编译后生成函数式接口的实现对象，可替代匿名内部类。\n3. 前提：目标类型必须是函数式接口，常用@FunctionalInterface标注。\n4. 变量捕获：只能引用final或事实上的final局部变量。\n5. 典型应用：集合遍历、排序、Stream流操作、线程创建。\n6. 与方法引用（::）配合，进一步简化代码。',NULL,1,'2026-09-27 13:04:58','2026-09-28 15:16:03'),(81,13,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int five = 0, ten = 0;\n        boolean ok = true;\n        for (int i = 0; i < n; i++) {\n            int bill = sc.nextInt();\n            if (bill == 5) {\n                five++;\n            } else if (bill == 10) {\n                if (five > 0) {\n                    five--;\n                    ten++;\n                } else {\n                    ok = false;\n                    break;\n                }\n            } else {\n                if (ten > 0 && five > 0) {\n                    ten--;\n                    five--;\n                } else if (five >= 3) {\n                    five -= 3;\n                } else {\n                    ok = false;\n                    break;\n                }\n            }\n        }\n        System.out.println(ok);\n    }\n}',NULL,1,'2026-09-27 13:04:58','2026-09-28 15:16:03'),(82,11,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int gn, sn;\n    cin >> gn >> sn;\n    vector<int> g(gn), s(sn);\n    for (int i = 0; i < gn; i++) {\n        cin >> g[i];\n    }\n    for (int i = 0; i < sn; i++) {\n        cin >> s[i];\n    }\n    sort(g.begin(), g.end());\n    sort(s.begin(), s.end());\n    int i = 0, j = 0;\n    while (i < gn && j < sn) {\n        if (s[j] >= g[i]) {\n            i++;\n        }\n        j++;\n    }\n    cout << i << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:04:58','2026-09-28 15:16:03'),(83,12,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int maxReach = 0;\n    bool canReach = true;\n    for (int i = 0; i < n; i++) {\n        if (i > maxReach) {\n            canReach = false;\n            break;\n        }\n        maxReach = max(maxReach, i + nums[i]);\n        if (maxReach >= n - 1) {\n            break;\n        }\n    }\n    cout << (canReach ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:04:59','2026-09-28 15:16:03'),(84,74,'TEXT','纯函数指满足以下两个条件的函数：\n\n1. **相同输入必返回相同输出**：结果只由入参决定，不依赖外部可变状态、时间、随机数等。\n2. **无副作用**：不修改外部状态，如不改全局变量、不修改入参、不做 I/O、不发请求、不打印日志。\n\n特点与意义：\n\n- **可预测**：调用结果稳定，便于推理和测试。\n- **易测试**：无需 mock 外部环境，给定输入即可断言输出。\n- **可缓存**：相同输入可复用结果（如 memoization）。\n- **利于并发**：不共享可变状态，天然线程安全。\n- **易组合**：可作为构建函数式编程的基础单元。\n\n核心一句话：**输出只依赖输入，且不产生任何可观察的副作用。**',NULL,1,'2026-09-27 13:04:59','2026-09-28 15:16:03'),(85,14,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> prices(n);\n    for (int i = 0; i < n; i++) {\n        cin >> prices[i];\n    }\n    int maxProfit = 0;\n    for (int i = 1; i < n; i++) {\n        if (prices[i] > prices[i - 1]) {\n            maxProfit += prices[i] - prices[i - 1];\n        }\n    }\n    cout << maxProfit << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:00','2026-09-28 15:16:03'),(86,76,'TEXT','**作用**：synchronized 用于实现线程同步，保证同一时刻只有一个线程执行临界区代码，具备原子性、可见性、有序性。\n\n**三种用法**：\n1. 修饰实例方法：锁为当前实例对象。\n2. 修饰静态方法：锁为当前类的 Class 对象。\n3. 修饰代码块：锁为括号内指定对象。\n\n**原理**：基于对象监视器（Monitor），通过 monitorenter/monitorexit 指令实现，锁信息存于对象头 Mark Word。\n\n**特性**：可重入、非公平（默认）、JDK1.6 后引入偏向锁、轻量级锁、自旋等优化，性能大幅提升。',NULL,1,'2026-09-27 13:05:00','2026-09-28 15:16:03'),(87,78,'TEXT','**概念**：线程池是预先创建并复用线程的并发框架，任务提交到队列，由空闲线程取出执行，避免频繁创建销毁线程。\n\n**优点**：\n1. 降低资源消耗，复用线程；\n2. 提高响应速度，任务到达即执行；\n3. 统一管理，可控并发数，防止资源耗尽；\n4. 提供任务队列、拒绝策略等扩展能力。\n\n**常见实现**：\n- Java：`ThreadPoolExecutor`（核心参数：核心/最大线程数、队列、拒绝策略），及 `Executors` 工具类；\n- 其他：C++ 手写线程池、Go 的 goroutine 调度、Python `concurrent.futures`。\n\n**核心考点**：任务调度流程、参数配置、拒绝策略、线程复用原理。',NULL,1,'2026-09-27 13:05:00','2026-09-28 15:16:03'),(88,77,'TEXT','**作用**：保证变量在多线程间的**可见性**和**有序性**，但不保证**原子性**。\n\n**原理**：\n1. **可见性**：写操作后立即刷回主内存，读操作直接从主内存读取，使其他线程能立即看到最新值。\n2. **有序性**：通过内存屏障禁止指令重排序，保证 volatile 读写前后的指令不被乱序执行。\n3. **不保证原子性**：如 `i++` 包含读、改、写三步，多线程下仍会出错，需配合锁或原子类。\n\n**典型场景**：状态标志位、双重检查锁定的单例（防止指令重排）。\n\n**与 synchronized 区别**：volatile 轻量，仅保证可见性和有序性；synchronized 还保证原子性和互斥。',NULL,1,'2026-09-27 13:05:00','2026-09-28 15:16:03'),(89,12,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int maxReach = 0;\n    int canReach = 1;\n    for (int i = 0; i < n; i++) {\n        if (i > maxReach) {\n            canReach = 0;\n            break;\n        }\n        if (i + nums[i] > maxReach) {\n            maxReach = i + nums[i];\n        }\n        if (maxReach >= n - 1) {\n            break;\n        }\n    }\n    if (canReach) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:05:00','2026-09-28 15:16:03'),(90,11,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nint main() {\n    int gn, sn;\n    scanf(\"%d %d\", &gn, &sn);\n    int *g = (int *)malloc(gn * sizeof(int));\n    int *s = (int *)malloc(sn * sizeof(int));\n    for (int i = 0; i < gn; i++) {\n        scanf(\"%d\", &g[i]);\n    }\n    for (int i = 0; i < sn; i++) {\n        scanf(\"%d\", &s[i]);\n    }\n    qsort(g, gn, sizeof(int), cmp);\n    qsort(s, sn, sizeof(int), cmp);\n    int i = 0, j = 0;\n    while (i < gn && j < sn) {\n        if (s[j] >= g[i]) {\n            i++;\n        }\n        j++;\n    }\n    printf(\"%d\\n\", i);\n    free(g);\n    free(s);\n    return 0;\n}',NULL,1,'2026-09-27 13:05:00','2026-09-28 15:16:03'),(91,75,'TEXT','**概念**：高阶函数是满足以下任一条件的函数：接收一个或多个函数作为参数；或返回一个函数作为结果。本质是把函数当作一等公民，可像普通值一样传递和返回。\n\n**使用场景**：\n1. **回调**：事件处理、异步回调，将行为参数化。\n2. **数组操作**：map、filter、reduce 等，用函数描述处理逻辑。\n3. **函数组合与柯里化**：compose、curry，复用和拼装逻辑。\n4. **装饰/增强**：在不改原函数前提下添加日志、缓存、权限等（如装饰器）。\n5. **抽象控制流**：把循环、条件等通用逻辑封装，只暴露变化部分。\n\n**核心价值**：提升抽象层次、代码复用性与可组合性。',NULL,1,'2026-09-27 13:05:00','2026-09-28 15:16:03'),(92,13,'CPP','#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int five = 0, ten = 0;\n    bool ok = true;\n    for (int i = 0; i < n; i++) {\n        int bill;\n        cin >> bill;\n        if (bill == 5) {\n            five++;\n        } else if (bill == 10) {\n            if (five > 0) {\n                five--;\n                ten++;\n            } else {\n                ok = false;\n                break;\n            }\n        } else {\n            if (ten > 0 && five > 0) {\n                ten--;\n                five--;\n            } else if (five >= 3) {\n                five -= 3;\n            } else {\n                ok = false;\n                break;\n            }\n        }\n    }\n    cout << (ok ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:00','2026-09-28 15:16:03'),(93,12,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\nmaxReach = 0\ncanReach = True\nfor i in range(n):\n    if i > maxReach:\n        canReach = False\n        break\n    maxReach = max(maxReach, i + nums[i])\n    if maxReach >= n - 1:\n        break\nprint(str(canReach).lower())',NULL,1,'2026-09-27 13:05:01','2026-09-28 15:16:03'),(94,11,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    gn = int(data[0])\n    sn = int(data[1])\n    g = list(map(int, data[2:2 + gn]))\n    s = list(map(int, data[2 + gn:2 + gn + sn]))\n    g.sort()\n    s.sort()\n    i = j = 0\n    while i < gn and j < sn:\n        if s[j] >= g[i]:\n            i += 1\n        j += 1\n    print(i)\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:05:01','2026-09-28 15:16:03'),(95,14,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int prices[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &prices[i]);\n    }\n    int maxProfit = 0;\n    for (int i = 1; i < n; i++) {\n        if (prices[i] > prices[i - 1]) {\n            maxProfit += prices[i] - prices[i - 1];\n        }\n    }\n    printf(\"%d\\n\", maxProfit);\n    return 0;\n}',NULL,1,'2026-09-27 13:05:02','2026-09-28 15:16:03'),(96,81,'TEXT','CAP定理：分布式系统中，一致性（Consistency）、可用性（Availability）、分区容错性（Partition tolerance）三者不可同时满足，最多满足两个。\n\n- **一致性C**：所有节点同一时刻看到相同数据，读操作总能返回最新写入值。\n- **可用性A**：每个请求都能在有限时间内得到非错误响应，但不保证是最新数据。\n- **分区容错性P**：网络分区（节点间消息丢失或延迟）时系统仍能继续运行。\n\n由于网络分区在分布式系统中不可避免，P通常必须保留，因此实际是在C和A之间取舍：如CP（ZooKeeper）、AP（Cassandra）。',NULL,1,'2026-09-27 13:05:02','2026-09-28 15:16:03'),(97,79,'TEXT','CAS（Compare-And-Swap）是一种无锁原子操作，用于实现并发同步。\n\n**概念**：包含三个操作数——内存位置V、预期旧值A、新值B。仅当V的当前值等于A时，才将V更新为B，否则不做任何操作。整个比较与交换过程由硬件保证原子性。\n\n**原理**：\n1. CPU提供原子指令（如x86的cmpxchg）实现，无需加锁。\n2. 返回操作是否成功，失败通常配合自旋重试。\n3. 存在ABA问题：值从A改为B又改回A，CAS无法察觉，可用版本号（如AtomicStampedReference）解决。\n\n**应用**：Java的AtomicInteger、AQS、无锁队列等底层均基于CAS。',NULL,1,'2026-09-27 13:05:02','2026-09-28 15:16:03'),(98,82,'TEXT','分布式事务指事务操作跨多个节点/数据源，需保证整体ACID。\n\n常见方案：\n1. **2PC/3PC**：协调者统一提交，强一致但阻塞、性能差。\n2. **TCC**：Try-Confirm-Cancel，业务层补偿，侵入性强。\n3. **本地消息表/事务消息**：借助MQ最终一致，实现简单。\n4. **Saga**：长事务拆分为子事务，失败逐级补偿。\n5. **Seata**：AT模式自动补偿，对业务侵入小。\n\n核心权衡：强一致（2PC）vs 最终一致（消息、Saga、TCC）。',NULL,1,'2026-09-27 13:05:02','2026-09-28 15:16:03'),(99,80,'TEXT','AQS（AbstractQueuedSynchronizer）是JUC中构建锁和同步器的核心框架，基于模板方法模式。\n\n核心要点：\n1. **核心结构**：一个volatile的state状态位 + 一个FIFO双向等待队列（CLH变体）。\n2. **state含义**：由子类定义，如ReentrantLock表示重入次数，Semaphore表示许可数。\n3. **获取/释放**：通过CAS修改state，失败则封装成Node入队并阻塞（LockSupport.park）。\n4. **两种模式**：独占（如ReentrantLock）和共享（如Semaphore、CountDownLatch）。\n5. **作用**：屏蔽排队、阻塞、唤醒等复杂细节，子类只需实现tryAcquire/tryRelease等方法即可自定义同步器。',NULL,1,'2026-09-27 13:05:02','2026-09-28 15:16:03'),(100,13,'C','#include <stdio.h>\n#include <stdbool.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int five = 0, ten = 0;\n    bool ok = true;\n    for (int i = 0; i < n; i++) {\n        int bill;\n        scanf(\"%d\", &bill);\n        if (bill == 5) {\n            five++;\n        } else if (bill == 10) {\n            if (five > 0) {\n                five--;\n                ten++;\n            } else {\n                ok = false;\n                break;\n            }\n        } else {\n            if (ten > 0 && five > 0) {\n                ten--;\n                five--;\n            } else if (five >= 3) {\n                five -= 3;\n            } else {\n                ok = false;\n                break;\n            }\n        }\n    }\n    printf(ok ? \"true\\n\" : \"false\\n\");\n    return 0;\n}',NULL,1,'2026-09-27 13:05:03','2026-09-28 15:16:03'),(101,12,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    let maxReach = 0;\n    let canReach = true;\n    for (let i = 0; i < n; i++) {\n        if (i > maxReach) {\n            canReach = false;\n            break;\n        }\n        maxReach = Math.max(maxReach, i + nums[i]);\n        if (maxReach >= n - 1) {\n            break;\n        }\n    }\n    console.log(canReach);\n});',NULL,1,'2026-09-27 13:05:03','2026-09-28 15:16:03'),(102,83,'TEXT','**概念**：一致性哈希将哈希空间组织成环（0~2³²-1），节点和数据都映射到环上，数据顺时针归属最近的节点。增删节点时只影响相邻区间，而非全部重映射。\n\n**核心机制**：\n- 普通哈希取模，节点数变化会导致几乎所有 key 失效；一致性哈希只迁移约 1/N 的数据。\n- 用**虚拟节点**解决数据倾斜：每个物理节点映射多个虚拟节点，使分布更均匀。\n\n**应用场景**：\n- 分布式缓存（如 Redis 集群）的 key 路由。\n- 负载均衡、分布式存储的数据分片。\n- 需动态扩缩容且要求最小数据迁移的场景。',NULL,1,'2026-09-27 13:05:03','2026-09-28 15:16:03'),(103,11,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const first = lines[0].split(/\\s+/).map(Number);\n    const gn = first[0];\n    const sn = first[1];\n    const g = lines[1].split(/\\s+/).map(Number);\n    const s = lines[2].split(/\\s+/).map(Number);\n\n    g.sort((a, b) => a - b);\n    s.sort((a, b) => a - b);\n\n    let i = 0, j = 0;\n    while (i < gn && j < sn) {\n        if (s[j] >= g[i]) {\n            i++;\n        }\n        j++;\n    }\n    console.log(i);\n});',NULL,1,'2026-09-27 13:05:03','2026-09-28 15:16:03'),(104,14,'PYTHON','n = int(input())\nprices = list(map(int, input().split()))\nmax_profit = 0\nfor i in range(1, n):\n    if prices[i] > prices[i - 1]:\n        max_profit += prices[i] - prices[i - 1]\nprint(max_profit)',NULL,1,'2026-09-27 13:05:04','2026-09-28 15:16:03'),(105,85,'TEXT','**概念**：将单一应用按业务拆分为多个独立部署的小服务，服务间通过轻量级通信（如 HTTP/RPC）协作，每个服务可独立开发、部署、扩展。\n\n**优点**：\n- 服务解耦，边界清晰，便于团队并行开发\n- 独立部署与扩容，故障隔离，单点问题不影响全局\n- 技术栈灵活，可按服务选型\n\n**缺点**：\n- 分布式复杂度高：网络延迟、调用失败、数据一致性难保证\n- 运维成本大：需服务发现、配置中心、链路追踪、监控等配套\n- 调试与测试困难，跨服务事务处理复杂\n\n**核心考点**：拆分粒度、分布式带来的复杂度与治理成本，适用场景是业务复杂、团队规模大的系统。',NULL,1,'2026-09-27 13:05:04','2026-09-28 15:16:03'),(106,86,'TEXT','学习编程的核心方法：\n\n1. **选对语言与方向**：根据目标（后端、前端、数据）选一门主流语言，避免频繁切换。\n2. **系统学习基础**：掌握语法、数据结构、算法、操作系统、网络等核心知识。\n3. **动手实践**：通过写小项目、刷题、复现轮子加深理解，拒绝只看不写。\n4. **阅读源码与文档**：学习优秀开源项目，理解工程化写法与设计思想。\n5. **调试与总结**：善用调试工具，记录踩坑与解决方案，形成知识体系。\n6. **持续迭代**：参与真实项目或开源，接受代码评审，保持输入与输出平衡。\n\n关键：**刻意练习 + 项目驱动 + 持续反馈**。',NULL,1,'2026-09-27 13:05:04','2026-09-28 15:16:03'),(107,84,'TEXT','**概念**：将请求按策略分发到多台服务器，避免单点过载。\n\n**作用**：\n- 提升吞吐量与可用性\n- 避免单点故障，支持水平扩展\n- 便于维护与灰度发布\n\n**常见算法**：\n- 轮询 / 加权轮询：依次分发，按性能加权\n- 随机 / 加权随机\n- 最少连接：发给当前连接最少的节点\n- 一致性哈希：同key固定落到同节点，减少缓存失效\n- IP哈希：同IP固定节点，保持会话\n\n**层次**：四层（LVS，基于IP/端口）、七层（Nginx，基于URL/Header）。',NULL,1,'2026-09-27 13:05:04','2026-09-28 15:16:03'),(108,13,'PYTHON','n = int(input())\nbills = list(map(int, input().split()))\nfive = 0\nten = 0\nok = True\nfor bill in bills:\n    if bill == 5:\n        five += 1\n    elif bill == 10:\n        if five > 0:\n            five -= 1\n            ten += 1\n        else:\n            ok = False\n            break\n    else:\n        if ten > 0 and five > 0:\n            ten -= 1\n            five -= 1\n        elif five >= 3:\n            five -= 3\n        else:\n            ok = False\n            break\nprint(\"true\" if ok else \"false\")',NULL,1,'2026-09-27 13:05:04','2026-09-28 15:16:03'),(109,87,'TEXT','**核心考点：稳定性、上进心、岗位匹配度。**\n\n回答分三层：\n\n1. **短期（1年）**：快速熟悉业务与团队协作，独立承担岗位职责，达到考核要求。\n2. **中期（2-3年）**：深耕专业领域，提升核心技能，能主导项目或模块，成为团队骨干。\n3. **长期（3-5年）**：结合公司发展，向更高阶方向（技术专家或管理）成长，持续为团队创造价值。\n\n**要点**：规划须与应聘岗位、公司方向一致；体现踏实、稳定、有目标，避免空泛或显得随时跳槽。',NULL,1,'2026-09-27 13:05:05','2026-09-28 15:16:03'),(110,15,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] ratings = new int[n];\n        for (int i = 0; i < n; i++) {\n            ratings[i] = sc.nextInt();\n        }\n        int[] candies = new int[n];\n        Arrays.fill(candies, 1);\n        for (int i = 1; i < n; i++) {\n            if (ratings[i] > ratings[i - 1]) {\n                candies[i] = candies[i - 1] + 1;\n            }\n        }\n        for (int i = n - 2; i >= 0; i--) {\n            if (ratings[i] > ratings[i + 1]) {\n                candies[i] = Math.max(candies[i], candies[i + 1] + 1);\n            }\n        }\n        int sum = 0;\n        for (int c : candies) {\n            sum += c;\n        }\n        System.out.println(sum);\n    }\n}',NULL,1,'2026-09-27 13:05:05','2026-09-28 15:16:03'),(111,14,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const prices = lines[1].split(\' \').map(Number);\n    let maxProfit = 0;\n    for (let i = 1; i < n; i++) {\n        if (prices[i] > prices[i - 1]) {\n            maxProfit += prices[i] - prices[i - 1];\n        }\n    }\n    console.log(maxProfit);\n});',NULL,1,'2026-09-27 13:05:05','2026-09-28 15:16:03'),(112,88,'TEXT','核心考点：用 STAR 法则讲清项目，突出个人贡献与量化结果。\n\n- **背景**：一句话说明项目目标、规模、你的角色。\n- **挑战**：点明最难的技术或协作难点（如高并发、性能瓶颈、跨团队）。\n- **行动**：重点讲“我”做了什么，而非团队做了什么；说清技术选型与决策理由。\n- **结果**：用数据量化，如性能提升、成本下降、上线收益。\n- **反思**：一句总结收获或改进点。\n\n避免流水账，突出个人不可替代性，准备被追问细节。',NULL,1,'2026-09-27 13:05:05','2026-09-28 15:16:03'),(113,89,'TEXT','**考点**：考察自我认知、岗位匹配度、改进意识。\n\n**优点**：选1-2个与岗位强相关的，用具体事例佐证。如\"执行力强，曾主导XX项目按期交付\"。\n\n**缺点**：说真实但非致命的，避免\"我太追求完美\"这类伪缺点。如\"公开表达经验不足\"。\n\n**改进**：给出可落地的行动，如\"主动争取汇报机会，已坚持每月做一次分享\"。\n\n**原则**：\n- 优点扣岗位需求，缺点不碰核心能力红线。\n- 缺点必须配改进措施，体现成长性。\n- 真诚具体，忌空泛套话。',NULL,1,'2026-09-27 13:05:06','2026-09-28 15:16:03'),(114,13,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const bills = lines[1].split(/\\s+/).map(Number);\n    let five = 0, ten = 0;\n    let ok = true;\n    for (let i = 0; i < n; i++) {\n        const bill = bills[i];\n        if (bill === 5) {\n            five++;\n        } else if (bill === 10) {\n            if (five > 0) {\n                five--;\n                ten++;\n            } else {\n                ok = false;\n                break;\n            }\n        } else {\n            if (ten > 0 && five > 0) {\n                ten--;\n                five--;\n            } else if (five >= 3) {\n                five -= 3;\n            } else {\n                ok = false;\n                break;\n            }\n        }\n    }\n    console.log(ok);\n});',NULL,1,'2026-09-27 13:05:06','2026-09-28 15:16:03'),(115,90,'TEXT','核心考点：动机真实性、岗位匹配度、公司认同感。\n\n1. **认同公司**：点出公司业务、产品、行业地位或文化中你真正认可的一点，避免空泛吹捧。\n2. **匹配岗位**：说明你的技能、经验与岗位要求高度契合，能快速上手并创造价值。\n3. **结合规划**：表达公司平台符合你的职业发展方向，你想在此长期成长。\n4. **差异化**：可提一个具体细节（如某产品、某技术、某价值观），体现你做过功课。\n\n答题结构：认可公司 + 我能贡献什么 + 我想获得什么成长。忌只谈公司好或只谈自己需要。',NULL,1,'2026-09-27 13:05:06','2026-09-28 15:16:03'),(116,16,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        List<List<Integer>> result = new ArrayList<>();\n        boolean[] used = new boolean[n];\n        backtrack(nums, used, new ArrayList<>(), result);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            sb.append(\"[\");\n            List<Integer> perm = result.get(i);\n            for (int j = 0; j < perm.size(); j++) {\n                sb.append(perm.get(j));\n                if (j < perm.size() - 1) {\n                    sb.append(\",\");\n                }\n            }\n            sb.append(\"]\");\n            if (i < result.size() - 1) {\n                sb.append(\",\");\n            }\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    private static void backtrack(int[] nums, boolean[] used, List<Integer> path, List<List<Integer>> result) {\n        if (path.size() == nums.length) {\n            result.add(new ArrayList<>(path));\n            return;\n        }\n        for (int i = 0; i < nums.length; i++) {\n            if (used[i]) continue;\n            used[i] = true;\n            path.add(nums[i]);\n            backtrack(nums, used, path, result);\n            path.remove(path.size() - 1);\n            used[i] = false;\n        }\n    }\n}',NULL,1,'2026-09-27 13:05:06','2026-09-28 15:16:03'),(117,91,'TEXT','1. 核心流程：长链→唯一短码→存储映射；访问短链→查映射→302重定向。\n2. 短码生成：可用自增ID转62进制，或哈希+冲突处理；需全局唯一、不可预测可选加随机盐。\n3. 存储：KV存储，短码为key，长链为value；量大时用Redis缓存热点，MySQL持久化。\n4. 高并发：读多写少，缓存+CDN+分库分表；写走发号器或分布式ID。\n5. 重定向：用302便于统计和后续修改；如需永久用301。\n6. 扩展：防刷、限流、过期清理、统计点击、自定义短码。',NULL,1,'2026-09-27 13:05:07','2026-09-28 15:16:03'),(118,15,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> ratings(n);\n    for (int i = 0; i < n; i++) {\n        cin >> ratings[i];\n    }\n\n    vector<int> candies(n, 1);\n\n    for (int i = 1; i < n; i++) {\n        if (ratings[i] > ratings[i - 1]) {\n            candies[i] = candies[i - 1] + 1;\n        }\n    }\n\n    for (int i = n - 2; i >= 0; i--) {\n        if (ratings[i] > ratings[i + 1]) {\n            candies[i] = max(candies[i], candies[i + 1] + 1);\n        }\n    }\n\n    int total = 0;\n    for (int c : candies) {\n        total += c;\n    }\n\n    cout << total << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:07','2026-09-28 15:16:03'),(119,92,'TEXT','1. 需求：单聊/群聊、在线状态、消息可靠投递、离线消息、多端同步。\n\n2. 架构：客户端通过 WebSocket 长连接接入网关层；网关无状态，用一致性哈希路由到同一用户连接。\n\n3. 存储：消息存 MySQL/Cassandra，按会话+时间分片；最近消息用 Redis 缓存；未读数、在线状态用 Redis。\n\n4. 投递：发送方消息先落库再推送；接收方在线则网关直推，离线则存离线表，上线拉取。\n\n5. 群聊：写扩散（小群）或读扩散（大群），用消息队列削峰异步投递。\n\n6. 可靠性：ACK 确认+重传、消息去重（seq/msgId）、有序性靠会话内递增序列号。\n\n7. 扩展：网关水平扩容，心跳保活，断线重连补拉增量消息。',NULL,1,'2026-09-27 13:05:08','2026-09-28 15:16:03'),(120,94,'TEXT','1. 架构：客户端→路由层（一致性哈希）→缓存节点，节点间无共享，支持水平扩展。\n2. 数据分布：一致性哈希+虚拟节点，减少扩缩容时的数据迁移。\n3. 缓存策略：LRU/LFU 淘汰，TTL 过期，读多写少场景用 Cache-Aside。\n4. 高可用：主从复制+哨兵/集群选主，故障自动切换；多副本防单点。\n5. 一致性：最终一致，写时更新 DB 后删缓存（延迟双删），读时回填。\n6. 穿透/击穿/雪崩：布隆过滤器、互斥锁重建、过期时间加随机。\n7. 监控：命中率、延迟、内存、热点 key，支撑扩容与调优。',NULL,1,'2026-09-27 13:05:08','2026-09-28 15:16:03'),(121,93,'TEXT','核心思路：层层过滤，把流量挡在数据库之前。\n\n1. **前端**：按钮置灰防重复提交；静态资源走 CDN。\n2. **网关/接入层**：限流（令牌桶）、黑名单、验证码削峰。\n3. **Redis 预扣库存**：用 Lua 脚本原子判断并扣减，库存不足直接返回，避免超卖。\n4. **异步下单**：扣减成功后发 MQ，异步落库创建订单，削峰填谷。\n5. **数据库**：库存字段加乐观锁/唯一索引兜底，防超卖。\n6. **兜底**：失败重试、幂等（订单号去重）、限购。\n\n要点：Redis 抗量、MQ 异步、DB 兜底，保证不超卖、高可用。',NULL,1,'2026-09-27 13:05:08','2026-09-28 15:16:03'),(122,95,'TEXT','1. 采集：Agent（Filebeat/Fluentd）收集日志，异步发送，本地磁盘缓冲防丢。\n2. 传输：Kafka 削峰解耦，按主题分区，保证高吞吐与顺序性。\n3. 存储：分冷热。热数据存 ES 供实时检索；冷数据压缩后入对象存储（S3/HDFS）降成本。\n4. 分析：实时用 Flink/Spark Streaming 做告警与聚合；离线跑批做统计。\n5. 查询：Kibana/Grafana 可视化，按时间+索引分片。\n6. 保障：限流、背压、副本容错、TTL 清理。',NULL,1,'2026-09-27 13:05:09','2026-09-28 15:16:03'),(123,18,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int target = sc.nextInt();\n        int[] candidates = new int[n];\n        for (int i = 0; i < n; i++) {\n            candidates[i] = sc.nextInt();\n        }\n        Arrays.sort(candidates);\n        List<List<Integer>> result = new ArrayList<>();\n        backtrack(candidates, target, 0, new ArrayList<>(), result);\n        System.out.println(format(result));\n    }\n\n    private static void backtrack(int[] candidates, int remain, int start, List<Integer> path, List<List<Integer>> result) {\n        if (remain == 0) {\n            result.add(new ArrayList<>(path));\n            return;\n        }\n        for (int i = start; i < candidates.length; i++) {\n            if (candidates[i] > remain) {\n                break;\n            }\n            path.add(candidates[i]);\n            backtrack(candidates, remain - candidates[i], i, path, result);\n            path.remove(path.size() - 1);\n        }\n    }\n\n    private static String format(List<List<Integer>> result) {\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            sb.append(\"[\");\n            List<Integer> list = result.get(i);\n            for (int j = 0; j < list.size(); j++) {\n                sb.append(list.get(j));\n                if (j < list.size() - 1) {\n                    sb.append(\",\");\n                }\n            }\n            sb.append(\"]\");\n            if (i < result.size() - 1) {\n                sb.append(\",\");\n            }\n        }\n        sb.append(\"]\");\n        return sb.toString();\n    }\n}',NULL,1,'2026-09-27 13:05:09','2026-09-28 15:16:03'),(124,15,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *ratings = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &ratings[i]);\n    }\n\n    int *candies = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        candies[i] = 1;\n    }\n\n    for (int i = 1; i < n; i++) {\n        if (ratings[i] > ratings[i - 1]) {\n            candies[i] = candies[i - 1] + 1;\n        }\n    }\n\n    for (int i = n - 2; i >= 0; i--) {\n        if (ratings[i] > ratings[i + 1]) {\n            int need = candies[i + 1] + 1;\n            if (need > candies[i]) {\n                candies[i] = need;\n            }\n        }\n    }\n\n    int total = 0;\n    for (int i = 0; i < n; i++) {\n        total += candies[i];\n    }\n\n    printf(\"%d\\n\", total);\n\n    free(ratings);\n    free(candies);\n    return 0;\n}',NULL,1,'2026-09-27 13:05:09','2026-09-28 15:16:03'),(125,16,'CPP','#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nvoid backtrack(vector<int>& nums, vector<bool>& used, vector<int>& path, vector<vector<int>>& res) {\n    if (path.size() == nums.size()) {\n        res.push_back(path);\n        return;\n    }\n    for (int i = 0; i < (int)nums.size(); i++) {\n        if (used[i]) continue;\n        used[i] = true;\n        path.push_back(nums[i]);\n        backtrack(nums, used, path, res);\n        path.pop_back();\n        used[i] = false;\n    }\n}\n\nstring format(vector<vector<int>>& res) {\n    string sb;\n    sb += \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        sb += \"[\";\n        vector<int>& list = res[i];\n        for (int j = 0; j < (int)list.size(); j++) {\n            sb += to_string(list[j]);\n            if (j != (int)list.size() - 1) sb += \",\";\n        }\n        sb += \"]\";\n        if (i != (int)res.size() - 1) sb += \",\";\n    }\n    sb += \"]\";\n    return sb;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    vector<vector<int>> res;\n    vector<bool> used(n, false);\n    vector<int> path;\n    backtrack(nums, used, path, res);\n    cout << format(res) << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:09','2026-09-28 15:16:03'),(126,15,'PYTHON','n = int(input())\nratings = list(map(int, input().split()))\n\ncandies = [1] * n\n\nfor i in range(1, n):\n    if ratings[i] > ratings[i - 1]:\n        candies[i] = candies[i - 1] + 1\n\nfor i in range(n - 2, -1, -1):\n    if ratings[i] > ratings[i + 1]:\n        candies[i] = max(candies[i], candies[i + 1] + 1)\n\nprint(sum(candies))',NULL,1,'2026-09-27 13:05:10','2026-09-28 15:16:03'),(127,16,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint n;\nint nums[100];\nint used[100];\nint path[100];\nint res[10000][100];\nint resCount = 0;\n\nvoid backtrack(int depth) {\n    if (depth == n) {\n        for (int i = 0; i < n; i++) {\n            res[resCount][i] = path[i];\n        }\n        resCount++;\n        return;\n    }\n    for (int i = 0; i < n; i++) {\n        if (used[i]) continue;\n        used[i] = 1;\n        path[depth] = nums[i];\n        backtrack(depth + 1);\n        used[i] = 0;\n    }\n}\n\nint main() {\n    scanf(\"%d\", &n);\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    backtrack(0);\n    printf(\"[\");\n    for (int i = 0; i < resCount; i++) {\n        printf(\"[\");\n        for (int j = 0; j < n; j++) {\n            printf(\"%d\", res[i][j]);\n            if (j != n - 1) printf(\",\");\n        }\n        printf(\"]\");\n        if (i != resCount - 1) printf(\",\");\n    }\n    printf(\"]\\n\");\n    return 0;\n}',NULL,1,'2026-09-27 13:05:12','2026-09-28 15:16:03'),(128,15,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const ratings = lines[1].split(\' \').map(Number);\n    \n    const candies = new Array(n).fill(1);\n    \n    for (let i = 1; i < n; i++) {\n        if (ratings[i] > ratings[i - 1]) {\n            candies[i] = candies[i - 1] + 1;\n        }\n    }\n    \n    for (let i = n - 2; i >= 0; i--) {\n        if (ratings[i] > ratings[i + 1]) {\n            candies[i] = Math.max(candies[i], candies[i + 1] + 1);\n        }\n    }\n    \n    let total = 0;\n    for (const c of candies) {\n        total += c;\n    }\n    \n    console.log(total);\n});',NULL,1,'2026-09-27 13:05:12','2026-09-28 15:16:03'),(129,18,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nvoid backtrack(vector<int>& candidates, int target, int start, vector<int>& current, vector<vector<int>>& result) {\n    if (target == 0) {\n        result.push_back(current);\n        return;\n    }\n    for (int i = start; i < (int)candidates.size(); i++) {\n        if (candidates[i] > target) {\n            break;\n        }\n        current.push_back(candidates[i]);\n        backtrack(candidates, target - candidates[i], i, current, result);\n        current.pop_back();\n    }\n}\n\nstring format(vector<vector<int>>& result) {\n    string sb = \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        sb += \"[\";\n        vector<int>& list = result[i];\n        for (int j = 0; j < (int)list.size(); j++) {\n            sb += to_string(list[j]);\n            if (j < (int)list.size() - 1) {\n                sb += \",\";\n            }\n        }\n        sb += \"]\";\n        if (i < (int)result.size() - 1) {\n            sb += \",\";\n        }\n    }\n    sb += \"]\";\n    return sb;\n}\n\nint main() {\n    int n, target;\n    cin >> n >> target;\n    vector<int> candidates(n);\n    for (int i = 0; i < n; i++) {\n        cin >> candidates[i];\n    }\n    sort(candidates.begin(), candidates.end());\n    vector<vector<int>> result;\n    vector<int> current;\n    backtrack(candidates, target, 0, current, result);\n    cout << format(result) << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:12','2026-09-28 15:16:03'),(130,16,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1+n]))\n    res = []\n    used = [False] * n\n    path = []\n\n    def backtrack():\n        if len(path) == n:\n            res.append(path[:])\n            return\n        for i in range(n):\n            if used[i]:\n                continue\n            used[i] = True\n            path.append(nums[i])\n            backtrack()\n            path.pop()\n            used[i] = False\n\n    backtrack()\n\n    parts = []\n    for perm in res:\n        parts.append(\"[\" + \",\".join(map(str, perm)) + \"]\")\n    print(\"[\" + \",\".join(parts) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:05:13','2026-09-28 15:16:03'),(131,19,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        List<String> res = new ArrayList<>();\n        backtrack(res, new StringBuilder(), 0, 0, n);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\'[\');\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\',\');\n            sb.append(\'\\\'\').append(res.get(i)).append(\'\\\'\');\n        }\n        sb.append(\']\');\n        System.out.println(sb.toString());\n    }\n\n    private static void backtrack(List<String> res, StringBuilder cur, int open, int close, int n) {\n        if (cur.length() == n * 2) {\n            res.add(cur.toString());\n            return;\n        }\n        if (open < n) {\n            cur.append(\'(\');\n            backtrack(res, cur, open + 1, close, n);\n            cur.deleteCharAt(cur.length() - 1);\n        }\n        if (close < open) {\n            cur.append(\')\');\n            backtrack(res, cur, open, close + 1, n);\n            cur.deleteCharAt(cur.length() - 1);\n        }\n    }\n}',NULL,1,'2026-09-27 13:05:14','2026-09-28 15:16:03'),(132,16,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    const res = [];\n    const used = new Array(n).fill(false);\n    backtrack(nums, used, [], res);\n    console.log(format(res));\n});\n\nfunction backtrack(nums, used, path, res) {\n    if (path.length === nums.length) {\n        res.push([...path]);\n        return;\n    }\n    for (let i = 0; i < nums.length; i++) {\n        if (used[i]) continue;\n        used[i] = true;\n        path.push(nums[i]);\n        backtrack(nums, used, path, res);\n        path.pop();\n        used[i] = false;\n    }\n}\n\nfunction format(res) {\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < res.length; i++) {\n        sb += \'[\';\n        const list = res[i];\n        for (let j = 0; j < list.length; j++) {\n            sb += list[j];\n            if (j !== list.length - 1) sb += \',\';\n        }\n        sb += \']\';\n        if (i !== res.length - 1) sb += \',\';\n    }\n    sb += \']\';\n    return sb;\n}',NULL,1,'2026-09-27 13:05:15','2026-09-28 15:16:03'),(133,18,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nvoid backtrack(int *candidates, int n, int target, int start, int *current, int curLen, int **result, int *resultSize, int **resultColSize) {\n    if (target == 0) {\n        result[*resultSize] = (int *)malloc(curLen * sizeof(int));\n        for (int i = 0; i < curLen; i++) {\n            result[*resultSize][i] = current[i];\n        }\n        (*resultColSize)[*resultSize] = curLen;\n        (*resultSize)++;\n        return;\n    }\n    for (int i = start; i < n; i++) {\n        if (candidates[i] > target) {\n            break;\n        }\n        current[curLen] = candidates[i];\n        backtrack(candidates, n, target - candidates[i], i, current, curLen + 1, result, resultSize, resultColSize);\n    }\n}\n\nint main() {\n    int n, target;\n    scanf(\"%d %d\", &n, &target);\n    int *candidates = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &candidates[i]);\n    }\n    qsort(candidates, n, sizeof(int), cmp);\n\n    int maxSize = 10000;\n    int **result = (int **)malloc(maxSize * sizeof(int *));\n    int *resultColSize = (int *)malloc(maxSize * sizeof(int));\n    int resultSize = 0;\n\n    int *current = (int *)malloc(1000 * sizeof(int));\n    backtrack(candidates, n, target, 0, current, 0, result, &resultSize, &resultColSize);\n\n    printf(\"[\");\n    for (int i = 0; i < resultSize; i++) {\n        printf(\"[\");\n        for (int j = 0; j < resultColSize[i]; j++) {\n            printf(\"%d\", result[i][j]);\n            if (j < resultColSize[i] - 1) {\n                printf(\",\");\n            }\n        }\n        printf(\"]\");\n        if (i < resultSize - 1) {\n            printf(\",\");\n        }\n    }\n    printf(\"]\\n\");\n\n    for (int i = 0; i < resultSize; i++) {\n        free(result[i]);\n    }\n    free(result);\n    free(resultColSize);\n    free(current);\n    free(candidates);\n\n    return 0;\n}',NULL,1,'2026-09-27 13:05:15','2026-09-28 15:16:03'),(134,20,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n        char[][] board = new char[m][n];\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine();\n            for (int j = 0; j < n; j++) {\n                board[i][j] = line.charAt(j);\n            }\n        }\n        String word = sc.nextLine();\n        boolean result = false;\n        for (int i = 0; i < m && !result; i++) {\n            for (int j = 0; j < n && !result; j++) {\n                if (dfs(board, word, i, j, 0)) {\n                    result = true;\n                }\n            }\n        }\n        System.out.println(result);\n    }\n\n    private static boolean dfs(char[][] board, String word, int i, int j, int k) {\n        if (i < 0 || i >= board.length || j < 0 || j >= board[0].length || board[i][j] != word.charAt(k)) {\n            return false;\n        }\n        if (k == word.length() - 1) {\n            return true;\n        }\n        char temp = board[i][j];\n        board[i][j] = \'#\';\n        boolean found = dfs(board, word, i + 1, j, k + 1)\n                || dfs(board, word, i - 1, j, k + 1)\n                || dfs(board, word, i, j + 1, k + 1)\n                || dfs(board, word, i, j - 1, k + 1);\n        board[i][j] = temp;\n        return found;\n    }\n}',NULL,1,'2026-09-27 13:05:15','2026-09-28 15:16:03'),(135,19,'CPP','#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nvoid backtrack(vector<string>& res, string& cur, int open, int close, int n) {\n    if ((int)cur.length() == n * 2) {\n        res.push_back(cur);\n        return;\n    }\n    if (open < n) {\n        cur.push_back(\'(\');\n        backtrack(res, cur, open + 1, close, n);\n        cur.pop_back();\n    }\n    if (close < open) {\n        cur.push_back(\')\');\n        backtrack(res, cur, open, close + 1, n);\n        cur.pop_back();\n    }\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<string> res;\n    string cur;\n    backtrack(res, cur, 0, 0, n);\n    cout << \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << \"\'\" << res[i] << \"\'\";\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:16','2026-09-28 15:16:03'),(136,18,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    target = int(data[1])\n    candidates = list(map(int, data[2:2 + n]))\n    candidates.sort()\n    result = []\n    \n    def backtrack(start, remaining, current):\n        if remaining == 0:\n            result.append(current[:])\n            return\n        for i in range(start, len(candidates)):\n            if candidates[i] > remaining:\n                break\n            current.append(candidates[i])\n            backtrack(i, remaining - candidates[i], current)\n            current.pop()\n    \n    backtrack(0, target, [])\n    \n    parts = []\n    for lst in result:\n        parts.append(\"[\" + \",\".join(map(str, lst)) + \"]\")\n    print(\"[\" + \",\".join(parts) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:05:16','2026-09-28 15:16:03'),(137,21,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) {\n            arr[i] = sc.nextInt();\n        }\n        quickSort(arr, 0, n - 1);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(arr[i]);\n        }\n        System.out.println(sb.toString());\n    }\n\n    private static void quickSort(int[] arr, int left, int right) {\n        if (left >= right) return;\n        int pivot = arr[left + (right - left) / 2];\n        int i = left, j = right;\n        while (i <= j) {\n            while (arr[i] < pivot) i++;\n            while (arr[j] > pivot) j--;\n            if (i <= j) {\n                int temp = arr[i];\n                arr[i] = arr[j];\n                arr[j] = temp;\n                i++;\n                j--;\n            }\n        }\n        quickSort(arr, left, j);\n        quickSort(arr, i, right);\n    }\n}',NULL,1,'2026-09-27 13:05:17','2026-09-28 15:16:03'),(138,20,'CPP','#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nbool dfs(vector<vector<char>>& board, const string& word, int i, int j, int k) {\n    if (i < 0 || i >= (int)board.size() || j < 0 || j >= (int)board[0].size() || board[i][j] != word[k]) {\n        return false;\n    }\n    if (k == (int)word.length() - 1) {\n        return true;\n    }\n    char temp = board[i][j];\n    board[i][j] = \'#\';\n    bool found = dfs(board, word, i + 1, j, k + 1)\n            || dfs(board, word, i - 1, j, k + 1)\n            || dfs(board, word, i, j + 1, k + 1)\n            || dfs(board, word, i, j - 1, k + 1);\n    board[i][j] = temp;\n    return found;\n}\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    cin.ignore();\n    vector<vector<char>> board(m, vector<char>(n));\n    for (int i = 0; i < m; i++) {\n        string line;\n        getline(cin, line);\n        for (int j = 0; j < n; j++) {\n            board[i][j] = line[j];\n        }\n    }\n    string word;\n    getline(cin, word);\n    bool result = false;\n    for (int i = 0; i < m && !result; i++) {\n        for (int j = 0; j < n && !result; j++) {\n            if (dfs(board, word, i, j, 0)) {\n                result = true;\n            }\n        }\n    }\n    cout << (result ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:18','2026-09-28 15:16:03'),(139,18,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const [n, target] = lines[0].split(\' \').map(Number);\n        const candidates = lines[1].split(\' \').map(Number);\n        candidates.sort((a, b) => a - b);\n        const result = [];\n        backtrack(candidates, target, 0, [], result);\n        console.log(format(result));\n        rl.close();\n    }\n});\n\nfunction backtrack(candidates, target, start, current, result) {\n    if (target === 0) {\n        result.push([...current]);\n        return;\n    }\n    for (let i = start; i < candidates.length; i++) {\n        if (candidates[i] > target) {\n            break;\n        }\n        current.push(candidates[i]);\n        backtrack(candidates, target - candidates[i], i, current, result);\n        current.pop();\n    }\n}\n\nfunction format(result) {\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < result.length; i++) {\n        sb += \'[\';\n        const list = result[i];\n        for (let j = 0; j < list.length; j++) {\n            sb += list[j];\n            if (j < list.length - 1) {\n                sb += \',\';\n            }\n        }\n        sb += \']\';\n        if (i < result.length - 1) {\n            sb += \',\';\n        }\n    }\n    sb += \']\';\n    return sb;\n}',NULL,1,'2026-09-27 13:05:18','2026-09-28 15:16:03'),(140,19,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nvoid backtrack(char ***res, int *returnSize, char *cur, int len, int open, int close, int n) {\n    if (len == n * 2) {\n        cur[len] = \'\\0\';\n        *res = (char **)realloc(*res, (*returnSize + 1) * sizeof(char *));\n        (*res)[*returnSize] = (char *)malloc((n * 2 + 1) * sizeof(char));\n        strcpy((*res)[*returnSize], cur);\n        (*returnSize)++;\n        return;\n    }\n    if (open < n) {\n        cur[len] = \'(\';\n        backtrack(res, returnSize, cur, len + 1, open + 1, close, n);\n    }\n    if (close < open) {\n        cur[len] = \')\';\n        backtrack(res, returnSize, cur, len + 1, open, close + 1, n);\n    }\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n\n    char **res = NULL;\n    int returnSize = 0;\n    char *cur = (char *)malloc((n * 2 + 1) * sizeof(char));\n\n    backtrack(&res, &returnSize, cur, 0, 0, 0, n);\n\n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"\'%s\'\", res[i]);\n    }\n    printf(\"]\\n\");\n\n    for (int i = 0; i < returnSize; i++) {\n        free(res[i]);\n    }\n    free(res);\n    free(cur);\n\n    return 0;\n}',NULL,1,'2026-09-27 13:05:19','2026-09-28 15:16:03'),(141,21,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid quickSort(vector<int>& arr, int left, int right);\nint partition(vector<int>& arr, int left, int right);\nvoid swap(int& a, int& b);\n\nint main() {\n    int n;\n    if (!(cin >> n)) return 0;\n    vector<int> arr(n);\n    for (int i = 0; i < n; i++) {\n        cin >> arr[i];\n    }\n    quickSort(arr, 0, n - 1);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) cout << \' \';\n        cout << arr[i];\n    }\n    cout << endl;\n    return 0;\n}\n\nvoid quickSort(vector<int>& arr, int left, int right) {\n    if (left >= right) return;\n    int pivot = partition(arr, left, right);\n    quickSort(arr, left, pivot - 1);\n    quickSort(arr, pivot + 1, right);\n}\n\nint partition(vector<int>& arr, int left, int right) {\n    int mid = left + (right - left) / 2;\n    int pivotValue = arr[mid];\n    swap(arr[mid], arr[right]);\n    int storeIndex = left;\n    for (int i = left; i < right; i++) {\n        if (arr[i] < pivotValue) {\n            swap(arr[i], arr[storeIndex]);\n            storeIndex++;\n        }\n    }\n    swap(arr[storeIndex], arr[right]);\n    return storeIndex;\n}\n\nvoid swap(int& a, int& b) {\n    int tmp = a;\n    a = b;\n    b = tmp;\n}',NULL,1,'2026-09-27 13:05:20','2026-09-28 15:16:03'),(142,19,'PYTHON','n = int(input())\nres = []\n\ndef backtrack(cur, open_count, close_count):\n    if len(cur) == n * 2:\n        res.append(cur)\n        return\n    if open_count < n:\n        backtrack(cur + \'(\', open_count + 1, close_count)\n    if close_count < open_count:\n        backtrack(cur + \')\', open_count, close_count + 1)\n\nbacktrack(\'\', 0, 0)\nprint(\'[\' + \',\'.join(\"\'\" + s + \"\'\" for s in res) + \']\')',NULL,1,'2026-09-27 13:05:20','2026-09-28 15:16:03'),(143,20,'C','#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n\nint m, n;\nchar board[100][100];\nchar word[1000];\n\nbool dfs(int i, int j, int k) {\n    if (i < 0 || i >= m || j < 0 || j >= n || board[i][j] != word[k]) {\n        return false;\n    }\n    if (k == (int)strlen(word) - 1) {\n        return true;\n    }\n    char temp = board[i][j];\n    board[i][j] = \'#\';\n    bool found = dfs(i + 1, j, k + 1)\n            || dfs(i - 1, j, k + 1)\n            || dfs(i, j + 1, k + 1)\n            || dfs(i, j - 1, k + 1);\n    board[i][j] = temp;\n    return found;\n}\n\nint main() {\n    scanf(\"%d %d\", &m, &n);\n    for (int i = 0; i < m; i++) {\n        scanf(\"%s\", board[i]);\n    }\n    scanf(\"%s\", word);\n    bool result = false;\n    for (int i = 0; i < m && !result; i++) {\n        for (int j = 0; j < n && !result; j++) {\n            if (dfs(i, j, 0)) {\n                result = true;\n            }\n        }\n    }\n    if (result) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:05:20','2026-09-28 15:16:03'),(144,22,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) {\n            arr[i] = sc.nextInt();\n        }\n        mergeSort(arr, 0, n - 1);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(arr[i]);\n        }\n        System.out.println(sb.toString());\n    }\n\n    private static void mergeSort(int[] arr, int left, int right) {\n        if (left >= right) return;\n        int mid = left + (right - left) / 2;\n        mergeSort(arr, left, mid);\n        mergeSort(arr, mid + 1, right);\n        merge(arr, left, mid, right);\n    }\n\n    private static void merge(int[] arr, int left, int mid, int right) {\n        int[] temp = new int[right - left + 1];\n        int i = left, j = mid + 1, k = 0;\n        while (i <= mid && j <= right) {\n            if (arr[i] <= arr[j]) {\n                temp[k++] = arr[i++];\n            } else {\n                temp[k++] = arr[j++];\n            }\n        }\n        while (i <= mid) temp[k++] = arr[i++];\n        while (j <= right) temp[k++] = arr[j++];\n        System.arraycopy(temp, 0, arr, left, temp.length);\n    }\n}',NULL,1,'2026-09-27 13:05:21','2026-09-28 15:16:03'),(145,19,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim(), 10);\n    const res = [];\n    backtrack(res, \'\', 0, 0, n);\n    let output = \'[\';\n    for (let i = 0; i < res.length; i++) {\n        if (i > 0) output += \',\';\n        output += \"\'\" + res[i] + \"\'\";\n    }\n    output += \']\';\n    console.log(output);\n    rl.close();\n});\n\nfunction backtrack(res, cur, open, close, n) {\n    if (cur.length === n * 2) {\n        res.push(cur);\n        return;\n    }\n    if (open < n) {\n        backtrack(res, cur + \'(\', open + 1, close, n);\n    }\n    if (close < open) {\n        backtrack(res, cur + \')\', open, close + 1, n);\n    }\n}',NULL,1,'2026-09-27 13:05:22','2026-09-28 15:16:03'),(146,20,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().splitlines()\n    if not data:\n        return\n    first = data[0].split()\n    m, n = int(first[0]), int(first[1])\n    board = []\n    for i in range(1, 1 + m):\n        board.append(list(data[i]))\n    word = data[1 + m]\n\n    def dfs(i, j, k):\n        if i < 0 or i >= m or j < 0 or j >= n or board[i][j] != word[k]:\n            return False\n        if k == len(word) - 1:\n            return True\n        temp = board[i][j]\n        board[i][j] = \'#\'\n        found = (dfs(i + 1, j, k + 1) or\n                 dfs(i - 1, j, k + 1) or\n                 dfs(i, j + 1, k + 1) or\n                 dfs(i, j - 1, k + 1))\n        board[i][j] = temp\n        return found\n\n    result = False\n    for i in range(m):\n        for j in range(n):\n            if dfs(i, j, 0):\n                result = True\n                break\n        if result:\n            break\n\n    print(\"true\" if result else \"false\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:05:22','2026-09-28 15:16:03'),(147,21,'C','#include <stdio.h>\n#include <stdlib.h>\n\nvoid swap(int *a, int *b) {\n    int tmp = *a;\n    *a = *b;\n    *b = tmp;\n}\n\nint partition(int arr[], int left, int right) {\n    int mid = left + (right - left) / 2;\n    int pivotValue = arr[mid];\n    swap(&arr[mid], &arr[right]);\n    int storeIndex = left;\n    for (int i = left; i < right; i++) {\n        if (arr[i] < pivotValue) {\n            swap(&arr[i], &arr[storeIndex]);\n            storeIndex++;\n        }\n    }\n    swap(&arr[storeIndex], &arr[right]);\n    return storeIndex;\n}\n\nvoid quickSort(int arr[], int left, int right) {\n    if (left >= right) return;\n    int pivot = partition(arr, left, right);\n    quickSort(arr, left, pivot - 1);\n    quickSort(arr, pivot + 1, right);\n}\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n    int *arr = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    quickSort(arr, 0, n - 1);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) printf(\" \");\n        printf(\"%d\", arr[i]);\n    }\n    printf(\"\\n\");\n    free(arr);\n    return 0;\n}',NULL,1,'2026-09-27 13:05:22','2026-09-28 15:16:03'),(148,22,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid merge(vector<int>& arr, int left, int mid, int right) {\n    vector<int> temp(right - left + 1);\n    int i = left, j = mid + 1, k = 0;\n    while (i <= mid && j <= right) {\n        if (arr[i] <= arr[j]) {\n            temp[k++] = arr[i++];\n        } else {\n            temp[k++] = arr[j++];\n        }\n    }\n    while (i <= mid) temp[k++] = arr[i++];\n    while (j <= right) temp[k++] = arr[j++];\n    for (int p = 0; p < temp.size(); p++) {\n        arr[left + p] = temp[p];\n    }\n}\n\nvoid mergeSort(vector<int>& arr, int left, int right) {\n    if (left >= right) return;\n    int mid = left + (right - left) / 2;\n    mergeSort(arr, left, mid);\n    mergeSort(arr, mid + 1, right);\n    merge(arr, left, mid, right);\n}\n\nint main() {\n    int n;\n    if (!(cin >> n)) return 0;\n    vector<int> arr(n);\n    for (int i = 0; i < n; i++) {\n        cin >> arr[i];\n    }\n    mergeSort(arr, 0, n - 1);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) cout << \' \';\n        cout << arr[i];\n    }\n    cout << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:23','2026-09-28 15:16:03'),(149,20,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const [m, n] = lines[idx++].trim().split(/\\s+/).map(Number);\n    const board = [];\n    for (let i = 0; i < m; i++) {\n        board.push(lines[idx++].trim().split(\'\'));\n    }\n    const word = lines[idx++].trim();\n\n    function dfs(i, j, k) {\n        if (i < 0 || i >= board.length || j < 0 || j >= board[0].length || board[i][j] !== word[k]) {\n            return false;\n        }\n        if (k === word.length - 1) {\n            return true;\n        }\n        const temp = board[i][j];\n        board[i][j] = \'#\';\n        const found = dfs(i + 1, j, k + 1)\n            || dfs(i - 1, j, k + 1)\n            || dfs(i, j + 1, k + 1)\n            || dfs(i, j - 1, k + 1);\n        board[i][j] = temp;\n        return found;\n    }\n\n    let result = false;\n    for (let i = 0; i < m && !result; i++) {\n        for (let j = 0; j < n && !result; j++) {\n            if (dfs(i, j, 0)) {\n                result = true;\n            }\n        }\n    }\n    console.log(result);\n});',NULL,1,'2026-09-27 13:05:24','2026-09-28 15:16:03'),(150,23,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) {\n            arr[i] = sc.nextInt();\n        }\n\n        for (int i = 0; i < n - 1; i++) {\n            for (int j = 0; j < n - 1 - i; j++) {\n                if (arr[j] > arr[j + 1]) {\n                    int temp = arr[j];\n                    arr[j] = arr[j + 1];\n                    arr[j + 1] = temp;\n                }\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(arr[i]);\n        }\n        System.out.println(sb.toString());\n    }\n}',NULL,1,'2026-09-27 13:05:24','2026-09-28 15:16:03'),(151,21,'PYTHON','import sys\n\ndef quick_sort(arr, left, right):\n    if left >= right:\n        return\n    pivot = partition(arr, left, right)\n    quick_sort(arr, left, pivot - 1)\n    quick_sort(arr, pivot + 1, right)\n\ndef partition(arr, left, right):\n    mid = left + (right - left) // 2\n    pivot_value = arr[mid]\n    arr[mid], arr[right] = arr[right], arr[mid]\n    store_index = left\n    for i in range(left, right):\n        if arr[i] < pivot_value:\n            arr[i], arr[store_index] = arr[store_index], arr[i]\n            store_index += 1\n    arr[store_index], arr[right] = arr[right], arr[store_index]\n    return store_index\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    quick_sort(arr, 0, n - 1)\n    print(\' \'.join(map(str, arr)))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:05:24','2026-09-28 15:16:03'),(152,22,'C','#include <stdio.h>\n#include <stdlib.h>\n\nvoid merge(int arr[], int left, int mid, int right) {\n    int n1 = mid - left + 1;\n    int n2 = right - mid;\n    int *L = (int *)malloc(n1 * sizeof(int));\n    int *R = (int *)malloc(n2 * sizeof(int));\n    for (int i = 0; i < n1; i++) L[i] = arr[left + i];\n    for (int j = 0; j < n2; j++) R[j] = arr[mid + 1 + j];\n    int i = 0, j = 0, k = left;\n    while (i < n1 && j < n2) {\n        if (L[i] <= R[j]) arr[k++] = L[i++];\n        else arr[k++] = R[j++];\n    }\n    while (i < n1) arr[k++] = L[i++];\n    while (j < n2) arr[k++] = R[j++];\n    free(L);\n    free(R);\n}\n\nvoid mergeSort(int arr[], int left, int right) {\n    if (left >= right) return;\n    int mid = left + (right - left) / 2;\n    mergeSort(arr, left, mid);\n    mergeSort(arr, mid + 1, right);\n    merge(arr, left, mid, right);\n}\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n    int *arr = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    mergeSort(arr, 0, n - 1);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) printf(\" \");\n        printf(\"%d\", arr[i]);\n    }\n    printf(\"\\n\");\n    free(arr);\n    return 0;\n}',NULL,1,'2026-09-27 13:05:26','2026-09-28 15:16:03'),(153,24,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) {\n            arr[i] = sc.nextInt();\n        }\n\n        for (int i = 0; i < n - 1; i++) {\n            int minIndex = i;\n            for (int j = i + 1; j < n; j++) {\n                if (arr[j] < arr[minIndex]) {\n                    minIndex = j;\n                }\n            }\n            int temp = arr[i];\n            arr[i] = arr[minIndex];\n            arr[minIndex] = temp;\n        }\n\n        for (int i = 0; i < n; i++) {\n            if (i > 0) {\n                System.out.print(\" \");\n            }\n            System.out.print(arr[i]);\n        }\n        System.out.println();\n    }\n}',NULL,1,'2026-09-27 13:05:26','2026-09-28 15:16:03'),(154,21,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\n\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    if (input.length === 0) return;\n    const n = parseInt(input[0]);\n    if (isNaN(n)) return;\n    const arr = input[1].split(\' \').map(Number);\n    quickSort(arr, 0, n - 1);\n    console.log(arr.join(\' \'));\n});\n\nfunction quickSort(arr, left, right) {\n    if (left >= right) return;\n    const pivot = partition(arr, left, right);\n    quickSort(arr, left, pivot - 1);\n    quickSort(arr, pivot + 1, right);\n}\n\nfunction partition(arr, left, right) {\n    const mid = left + Math.floor((right - left) / 2);\n    const pivotValue = arr[mid];\n    swap(arr, mid, right);\n    let storeIndex = left;\n    for (let i = left; i < right; i++) {\n        if (arr[i] < pivotValue) {\n            swap(arr, i, storeIndex);\n            storeIndex++;\n        }\n    }\n    swap(arr, storeIndex, right);\n    return storeIndex;\n}\n\nfunction swap(arr, i, j) {\n    const tmp = arr[i];\n    arr[i] = arr[j];\n    arr[j] = tmp;\n}',NULL,1,'2026-09-27 13:05:26','2026-09-28 15:16:03'),(155,23,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> arr(n);\n    for (int i = 0; i < n; i++) {\n        cin >> arr[i];\n    }\n    for (int i = 0; i < n - 1; i++) {\n        for (int j = 0; j < n - 1 - i; j++) {\n            if (arr[j] > arr[j + 1]) {\n                int temp = arr[j];\n                arr[j] = arr[j + 1];\n                arr[j + 1] = temp;\n            }\n        }\n    }\n    for (int i = 0; i < n; i++) {\n        if (i > 0) {\n            cout << \" \";\n        }\n        cout << arr[i];\n    }\n    cout << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:26','2026-09-28 15:16:03'),(156,22,'PYTHON','import sys\n\ndef merge_sort(arr, left, right):\n    if left >= right:\n        return\n    mid = left + (right - left) // 2\n    merge_sort(arr, left, mid)\n    merge_sort(arr, mid + 1, right)\n    merge(arr, left, mid, right)\n\ndef merge(arr, left, mid, right):\n    temp = []\n    i, j = left, mid + 1\n    while i <= mid and j <= right:\n        if arr[i] <= arr[j]:\n            temp.append(arr[i])\n            i += 1\n        else:\n            temp.append(arr[j])\n            j += 1\n    while i <= mid:\n        temp.append(arr[i])\n        i += 1\n    while j <= right:\n        temp.append(arr[j])\n        j += 1\n    arr[left:right + 1] = temp\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    merge_sort(arr, 0, n - 1)\n    print(\' \'.join(map(str, arr)))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:05:27','2026-09-28 15:16:03'),(157,23,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int arr[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    for (int i = 0; i < n - 1; i++) {\n        for (int j = 0; j < n - 1 - i; j++) {\n            if (arr[j] > arr[j + 1]) {\n                int temp = arr[j];\n                arr[j] = arr[j + 1];\n                arr[j + 1] = temp;\n            }\n        }\n    }\n    for (int i = 0; i < n; i++) {\n        if (i > 0) {\n            printf(\" \");\n        }\n        printf(\"%d\", arr[i]);\n    }\n    printf(\"\\n\");\n    return 0;\n}',NULL,1,'2026-09-27 13:05:28','2026-09-28 15:16:03'),(158,25,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) {\n            arr[i] = sc.nextInt();\n        }\n        insertionSort(arr);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(arr[i]);\n        }\n        System.out.println(sb.toString());\n    }\n\n    private static void insertionSort(int[] arr) {\n        for (int i = 1; i < arr.length; i++) {\n            int key = arr[i];\n            int j = i - 1;\n            while (j >= 0 && arr[j] > key) {\n                arr[j + 1] = arr[j];\n                j--;\n            }\n            arr[j + 1] = key;\n        }\n    }\n}',NULL,1,'2026-09-27 13:05:28','2026-09-28 15:16:03'),(159,24,'CPP','#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int arr[n];\n    for (int i = 0; i < n; i++) {\n        cin >> arr[i];\n    }\n\n    for (int i = 0; i < n - 1; i++) {\n        int minIndex = i;\n        for (int j = i + 1; j < n; j++) {\n            if (arr[j] < arr[minIndex]) {\n                minIndex = j;\n            }\n        }\n        int temp = arr[i];\n        arr[i] = arr[minIndex];\n        arr[minIndex] = temp;\n    }\n\n    for (int i = 0; i < n; i++) {\n        if (i > 0) {\n            cout << \" \";\n        }\n        cout << arr[i];\n    }\n    cout << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:28','2026-09-28 15:16:03'),(160,22,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\n\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    if (input.length === 0) return;\n    const tokens = input.join(\' \').split(/\\s+/).filter(s => s.length > 0);\n    if (tokens.length === 0) return;\n    const n = parseInt(tokens[0], 10);\n    const arr = [];\n    for (let i = 0; i < n; i++) {\n        arr.push(parseInt(tokens[i + 1], 10));\n    }\n    mergeSort(arr, 0, n - 1);\n    console.log(arr.join(\' \'));\n});\n\nfunction mergeSort(arr, left, right) {\n    if (left >= right) return;\n    const mid = left + Math.floor((right - left) / 2);\n    mergeSort(arr, left, mid);\n    mergeSort(arr, mid + 1, right);\n    merge(arr, left, mid, right);\n}\n\nfunction merge(arr, left, mid, right) {\n    const temp = new Array(right - left + 1);\n    let i = left, j = mid + 1, k = 0;\n    while (i <= mid && j <= right) {\n        if (arr[i] <= arr[j]) {\n            temp[k++] = arr[i++];\n        } else {\n            temp[k++] = arr[j++];\n        }\n    }\n    while (i <= mid) temp[k++] = arr[i++];\n    while (j <= right) temp[k++] = arr[j++];\n    for (let t = 0; t < temp.length; t++) {\n        arr[left + t] = temp[t];\n    }\n}',NULL,1,'2026-09-27 13:05:29','2026-09-28 15:16:03'),(161,23,'PYTHON','n = int(input())\narr = list(map(int, input().split()))\nfor i in range(n - 1):\n    for j in range(n - 1 - i):\n        if arr[j] > arr[j + 1]:\n            arr[j], arr[j + 1] = arr[j + 1], arr[j]\nprint(\' \'.join(map(str, arr)))',NULL,1,'2026-09-27 13:05:29','2026-09-28 15:16:03'),(162,24,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int arr[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n\n    for (int i = 0; i < n - 1; i++) {\n        int minIndex = i;\n        for (int j = i + 1; j < n; j++) {\n            if (arr[j] < arr[minIndex]) {\n                minIndex = j;\n            }\n        }\n        int temp = arr[i];\n        arr[i] = arr[minIndex];\n        arr[minIndex] = temp;\n    }\n\n    for (int i = 0; i < n; i++) {\n        if (i > 0) {\n            printf(\" \");\n        }\n        printf(\"%d\", arr[i]);\n    }\n    printf(\"\\n\");\n    return 0;\n}',NULL,1,'2026-09-27 13:05:30','2026-09-28 15:16:03'),(163,25,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid insertionSort(vector<int>& arr) {\n    for (int i = 1; i < (int)arr.size(); i++) {\n        int key = arr[i];\n        int j = i - 1;\n        while (j >= 0 && arr[j] > key) {\n            arr[j + 1] = arr[j];\n            j--;\n        }\n        arr[j + 1] = key;\n    }\n}\n\nint main() {\n    int n;\n    if (!(cin >> n)) return 0;\n    vector<int> arr(n);\n    for (int i = 0; i < n; i++) {\n        cin >> arr[i];\n    }\n    insertionSort(arr);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) cout << \' \';\n        cout << arr[i];\n    }\n    cout << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:30','2026-09-28 15:16:03'),(164,23,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n  input: process.stdin,\n  output: process.stdout\n});\n\nlet input = [];\nrl.on(\'line\', (line) => {\n  input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n  const n = parseInt(input[0]);\n  const arr = input[1].split(\' \').map(Number);\n\n  for (let i = 0; i < n - 1; i++) {\n    for (let j = 0; j < n - 1 - i; j++) {\n      if (arr[j] > arr[j + 1]) {\n        const temp = arr[j];\n        arr[j] = arr[j + 1];\n        arr[j + 1] = temp;\n      }\n    }\n  }\n\n  let output = \'\';\n  for (let i = 0; i < n; i++) {\n    if (i > 0) {\n      output += \' \';\n    }\n    output += arr[i];\n  }\n  console.log(output);\n});',NULL,1,'2026-09-27 13:05:31','2026-09-28 15:16:03'),(165,24,'PYTHON','n = int(input())\narr = list(map(int, input().split()))\n\nfor i in range(n - 1):\n    min_index = i\n    for j in range(i + 1, n):\n        if arr[j] < arr[min_index]:\n            min_index = j\n    arr[i], arr[min_index] = arr[min_index], arr[i]\n\nprint(\' \'.join(map(str, arr)))',NULL,1,'2026-09-27 13:05:31','2026-09-28 15:16:03'),(166,26,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = scanner.nextInt();\n        int count = 0;\n        while (n != 0) {\n            n &= (n - 1);\n            count++;\n        }\n        System.out.println(count);\n    }\n}',NULL,1,'2026-09-27 13:05:32','2026-09-28 15:16:03'),(167,25,'C','#include <stdio.h>\n\nvoid insertionSort(int arr[], int n) {\n    for (int i = 1; i < n; i++) {\n        int key = arr[i];\n        int j = i - 1;\n        while (j >= 0 && arr[j] > key) {\n            arr[j + 1] = arr[j];\n            j--;\n        }\n        arr[j + 1] = key;\n    }\n}\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n    int arr[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    insertionSort(arr, n);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) printf(\" \");\n        printf(\"%d\", arr[i]);\n    }\n    printf(\"\\n\");\n    return 0;\n}',NULL,1,'2026-09-27 13:05:32','2026-09-28 15:16:03'),(168,27,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int x = scanner.nextInt();\n        int y = scanner.nextInt();\n        int xor = x ^ y;\n        int distance = 0;\n        while (xor != 0) {\n            distance += xor & 1;\n            xor >>>= 1;\n        }\n        System.out.println(distance);\n    }\n}',NULL,1,'2026-09-27 13:05:32','2026-09-28 15:16:03'),(169,24,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(input[0]);\n    const arr = input[1].split(\' \').map(Number);\n\n    for (let i = 0; i < n - 1; i++) {\n        let minIndex = i;\n        for (let j = i + 1; j < n; j++) {\n            if (arr[j] < arr[minIndex]) {\n                minIndex = j;\n            }\n        }\n        let temp = arr[i];\n        arr[i] = arr[minIndex];\n        arr[minIndex] = temp;\n    }\n\n    let result = \'\';\n    for (let i = 0; i < n; i++) {\n        if (i > 0) {\n            result += \' \';\n        }\n        result += arr[i];\n    }\n    console.log(result);\n});',NULL,1,'2026-09-27 13:05:33','2026-09-28 15:16:03'),(170,25,'PYTHON','import sys\n\ndef insertion_sort(arr):\n    for i in range(1, len(arr)):\n        key = arr[i]\n        j = i - 1\n        while j >= 0 and arr[j] > key:\n            arr[j + 1] = arr[j]\n            j -= 1\n        arr[j + 1] = key\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    insertion_sort(arr)\n    print(\' \'.join(map(str, arr)))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:05:33','2026-09-28 15:16:03'),(171,26,'CPP','#include <iostream>\n\nint main() {\n    unsigned int n;\n    if (std::cin >> n) {\n        int count = 0;\n        while (n != 0) {\n            n &= (n - 1);\n            count++;\n        }\n        std::cout << count << std::endl;\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:05:34','2026-09-28 15:16:03'),(172,27,'CPP','#include <iostream>\nusing namespace std;\n\nint main() {\n    int x, y;\n    cin >> x >> y;\n    int xorValue = x ^ y;\n    int distance = 0;\n    while (xorValue != 0) {\n        distance += xorValue & 1;\n        xorValue >>= 1;\n    }\n    cout << distance << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:34','2026-09-28 15:16:03'),(173,28,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        long n = scanner.nextLong();\n        int result = 0;\n        for (int i = 0; i < 32; i++) {\n            result = (result << 1) | ((int)(n >> i) & 1);\n        }\n        System.out.println(Integer.toUnsignedString(result));\n    }\n}',NULL,1,'2026-09-27 13:05:35','2026-09-28 15:16:03'),(174,25,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\n\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    if (input.length === 0) return;\n    const n = parseInt(input[0]);\n    if (isNaN(n)) return;\n    const arr = input[1].split(\' \').map(Number);\n    insertionSort(arr);\n    console.log(arr.join(\' \'));\n});\n\nfunction insertionSort(arr) {\n    for (let i = 1; i < arr.length; i++) {\n        let key = arr[i];\n        let j = i - 1;\n        while (j >= 0 && arr[j] > key) {\n            arr[j + 1] = arr[j];\n            j--;\n        }\n        arr[j + 1] = key;\n    }\n}',NULL,1,'2026-09-27 13:05:35','2026-09-28 15:16:03'),(175,26,'C','#include <stdio.h>\n\nint main() {\n    unsigned int n;\n    if (scanf(\"%u\", &n) == 1) {\n        int count = 0;\n        while (n != 0) {\n            n &= (n - 1);\n            count++;\n        }\n        printf(\"%d\\n\", count);\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:05:35','2026-09-28 15:16:03'),(176,27,'C','#include <stdio.h>\n\nint main() {\n    int x, y;\n    scanf(\"%d %d\", &x, &y);\n    unsigned int xor_val = (unsigned int)(x ^ y);\n    int distance = 0;\n    while (xor_val != 0) {\n        distance += xor_val & 1;\n        xor_val >>= 1;\n    }\n    printf(\"%d\\n\", distance);\n    return 0;\n}',NULL,1,'2026-09-27 13:05:36','2026-09-28 15:16:03'),(177,26,'PYTHON','n = int(input())\ncount = 0\nwhile n != 0:\n    n &= (n - 1)\n    count += 1\nprint(count)',NULL,1,'2026-09-27 13:05:36','2026-09-28 15:16:03'),(178,29,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int ans = 0;\n        for (int i = 0; i < n; i++) {\n            ans ^= sc.nextInt();\n        }\n        System.out.println(ans);\n    }\n}',NULL,1,'2026-09-27 13:05:37','2026-09-28 15:16:03'),(179,28,'CPP','#include <iostream>\n#include <cstdint>\n\nint main() {\n    uint32_t n;\n    std::cin >> n;\n    uint32_t result = 0;\n    for (int i = 0; i < 32; i++) {\n        result <<= 1;\n        result |= (n & 1);\n        n >>= 1;\n    }\n    std::cout << result << std::endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:37','2026-09-28 15:16:03'),(180,27,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().split()\n    if len(data) < 2:\n        return\n    x = int(data[0])\n    y = int(data[1])\n    xor = x ^ y\n    distance = 0\n    while xor != 0:\n        distance += xor & 1\n        xor >>= 1\n    print(distance)\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:05:37','2026-09-28 15:16:03'),(181,26,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim(), 10);\n    if (!isNaN(n)) {\n        let count = 0;\n        let num = n;\n        while (num !== 0) {\n            num &= (num - 1);\n            count++;\n        }\n        console.log(count);\n    }\n    rl.close();\n});',NULL,1,'2026-09-27 13:05:38','2026-09-28 15:16:03'),(182,29,'CPP','#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int ans = 0;\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        ans ^= x;\n    }\n    cout << ans << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:38','2026-09-28 15:16:03'),(183,27,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const [x, y] = line.trim().split(/\\s+/).map(Number);\n    let xor = x ^ y;\n    let distance = 0;\n    while (xor !== 0) {\n        distance += xor & 1;\n        xor >>>= 1;\n    }\n    console.log(distance);\n    rl.close();\n});',NULL,1,'2026-09-27 13:05:39','2026-09-28 15:16:03'),(184,28,'C','#include <stdio.h>\n#include <stdint.h>\n\nint main() {\n    uint32_t n;\n    scanf(\"%u\", &n);\n    uint32_t result = 0;\n    for (int i = 0; i < 32; i++) {\n        result <<= 1;\n        result |= (n & 1);\n        n >>= 1;\n    }\n    printf(\"%u\\n\", result);\n    return 0;\n}',NULL,1,'2026-09-27 13:05:39','2026-09-28 15:16:03'),(185,30,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        int shift = 0;\n        while (m < n) {\n            m >>= 1;\n            n >>= 1;\n            shift++;\n        }\n        System.out.println(m << shift);\n    }\n}',NULL,1,'2026-09-27 13:05:39','2026-09-28 15:16:03'),(186,29,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int ans = 0;\n    for (int i = 0; i < n; i++) {\n        int x;\n        scanf(\"%d\", &x);\n        ans ^= x;\n    }\n    printf(\"%d\\n\", ans);\n    return 0;\n}',NULL,1,'2026-09-27 13:05:40','2026-09-28 15:16:03'),(187,28,'PYTHON','n = int(input())\nresult = 0\nfor _ in range(32):\n    result <<= 1\n    result |= (n & 1)\n    n >>= 1\nprint(result & 0xFFFFFFFF)',NULL,1,'2026-09-27 13:05:40','2026-09-28 15:16:03'),(188,31,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long a = 0, b = 1;\n        for (int i = 1; i < n; i++) {\n            long c = a + b;\n            a = b;\n            b = c;\n        }\n        System.out.println(n == 0 ? 0 : b);\n    }\n}',NULL,1,'2026-09-27 13:05:41','2026-09-28 15:16:03'),(189,30,'CPP','#include <iostream>\nusing namespace std;\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    int shift = 0;\n    while (m < n) {\n        m >>= 1;\n        n >>= 1;\n        shift++;\n    }\n    cout << (m << shift) << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:41','2026-09-28 15:16:03'),(190,29,'PYTHON','n = int(input())\nans = 0\nfor x in map(int, input().split()):\n    ans ^= x\nprint(ans)',NULL,1,'2026-09-27 13:05:41','2026-09-28 15:16:03'),(191,28,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    let n = BigInt(line.trim());\n    let result = 0;\n    for (let i = 0; i < 32; i++) {\n        result = (result << 1) >>> 0;\n        result = (result | Number(n & 1n)) >>> 0;\n        n >>= 1n;\n    }\n    console.log(result >>> 0);\n    rl.close();\n});',NULL,1,'2026-09-27 13:05:41','2026-09-28 15:16:03'),(192,29,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const n = parseInt(lines[0]);\n        const nums = lines[1].split(/\\s+/).map(Number);\n        let ans = 0;\n        for (let i = 0; i < n; i++) {\n            ans ^= nums[i];\n        }\n        console.log(ans);\n        rl.close();\n    }\n});',NULL,1,'2026-09-27 13:05:42','2026-09-28 15:16:03'),(193,30,'C','#include <stdio.h>\n\nint main() {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n    int shift = 0;\n    while (m < n) {\n        m >>= 1;\n        n >>= 1;\n        shift++;\n    }\n    printf(\"%d\\n\", m << shift);\n    return 0;\n}',NULL,1,'2026-09-27 13:05:43','2026-09-28 15:16:03'),(194,31,'CPP','#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    long long a = 0, b = 1;\n    for (int i = 1; i < n; i++) {\n        long long c = a + b;\n        a = b;\n        b = c;\n    }\n    cout << (n == 0 ? 0 : b) << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:43','2026-09-28 15:16:03'),(195,32,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        String s = scanner.nextLine().trim();\n        int result = 0;\n        int prev = 0;\n        for (int i = s.length() - 1; i >= 0; i--) {\n            int curr = value(s.charAt(i));\n            if (curr < prev) {\n                result -= curr;\n            } else {\n                result += curr;\n            }\n            prev = curr;\n        }\n        System.out.println(result);\n    }\n\n    private static int value(char c) {\n        switch (c) {\n            case \'I\': return 1;\n            case \'V\': return 5;\n            case \'X\': return 10;\n            case \'L\': return 50;\n            case \'C\': return 100;\n            case \'D\': return 500;\n            case \'M\': return 1000;\n            default: return 0;\n        }\n    }\n}',NULL,1,'2026-09-27 13:05:43','2026-09-28 15:16:03'),(196,30,'PYTHON','m, n = map(int, input().split())\nshift = 0\nwhile m < n:\n    m >>= 1\n    n >>= 1\n    shift += 1\nprint(m << shift)',NULL,1,'2026-09-27 13:05:43','2026-09-28 15:16:03'),(197,31,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    long long a = 0, b = 1;\n    for (int i = 1; i < n; i++) {\n        long long c = a + b;\n        a = b;\n        b = c;\n    }\n    printf(\"%lld\\n\", n == 0 ? 0LL : b);\n    return 0;\n}',NULL,1,'2026-09-27 13:05:44','2026-09-28 15:16:03'),(198,33,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int x = sc.nextInt();\n        int rev = 0;\n        while (x != 0) {\n            int pop = x % 10;\n            x /= 10;\n            if (rev > Integer.MAX_VALUE / 10 || (rev == Integer.MAX_VALUE / 10 && pop > 7)) {\n                System.out.println(0);\n                return;\n            }\n            if (rev < Integer.MIN_VALUE / 10 || (rev == Integer.MIN_VALUE / 10 && pop < -8)) {\n                System.out.println(0);\n                return;\n            }\n            rev = rev * 10 + pop;\n        }\n        System.out.println(rev);\n    }\n}',NULL,1,'2026-09-27 13:05:44','2026-09-28 15:16:03'),(199,30,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n  input: process.stdin,\n  output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n  const [mStr, nStr] = line.trim().split(/\\s+/);\n  let m = parseInt(mStr, 10);\n  let n = parseInt(nStr, 10);\n  let shift = 0;\n  while (m < n) {\n    m >>= 1;\n    n >>= 1;\n    shift++;\n  }\n  console.log(m << shift);\n  rl.close();\n});',NULL,1,'2026-09-27 13:05:45','2026-09-28 15:16:03'),(200,32,'CPP','#include <iostream>\n#include <string>\nusing namespace std;\n\nint getValue(char c) {\n    switch (c) {\n        case \'I\': return 1;\n        case \'V\': return 5;\n        case \'X\': return 10;\n        case \'L\': return 50;\n        case \'C\': return 100;\n        case \'D\': return 500;\n        case \'M\': return 1000;\n        default: return 0;\n    }\n}\n\nint main() {\n    string s;\n    getline(cin, s);\n    int result = 0;\n    int prev = 0;\n    for (int i = s.length() - 1; i >= 0; i--) {\n        int value = getValue(s[i]);\n        if (value < prev) {\n            result -= value;\n        } else {\n            result += value;\n            prev = value;\n        }\n    }\n    cout << result << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:45','2026-09-28 15:16:03'),(201,31,'PYTHON','n = int(input())\na, b = 0, 1\nfor i in range(1, n):\n    a, b = b, a + b\nprint(0 if n == 0 else b)',NULL,1,'2026-09-27 13:05:45','2026-09-28 15:16:03'),(202,33,'CPP','#include <iostream>\n#include <climits>\n\nint main() {\n    int x;\n    std::cin >> x;\n    int rev = 0;\n    while (x != 0) {\n        int pop = x % 10;\n        x /= 10;\n        if (rev > INT_MAX / 10 || (rev == INT_MAX / 10 && pop > 7)) {\n            std::cout << 0 << std::endl;\n            return 0;\n        }\n        if (rev < INT_MIN / 10 || (rev == INT_MIN / 10 && pop < -8)) {\n            std::cout << 0 << std::endl;\n            return 0;\n        }\n        rev = rev * 10 + pop;\n    }\n    std::cout << rev << std::endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:47','2026-09-28 15:16:03'),(203,31,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim());\n    let a = 0, b = 1;\n    for (let i = 1; i < n; i++) {\n        const c = a + b;\n        a = b;\n        b = c;\n    }\n    console.log(n === 0 ? 0 : b);\n    rl.close();\n});',NULL,1,'2026-09-27 13:05:47','2026-09-28 15:16:03'),(204,34,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int x = scanner.nextInt();\n        System.out.println(isPalindrome(x));\n    }\n\n    private static boolean isPalindrome(int x) {\n        if (x < 0 || (x % 10 == 0 && x != 0)) {\n            return false;\n        }\n        int reversed = 0;\n        while (x > reversed) {\n            reversed = reversed * 10 + x % 10;\n            x /= 10;\n        }\n        return x == reversed || x == reversed / 10;\n    }\n}',NULL,1,'2026-09-27 13:05:47','2026-09-28 15:16:03'),(205,32,'C','#include <stdio.h>\n#include <string.h>\n\nint getValue(char c) {\n    switch (c) {\n        case \'I\': return 1;\n        case \'V\': return 5;\n        case \'X\': return 10;\n        case \'L\': return 50;\n        case \'C\': return 100;\n        case \'D\': return 500;\n        case \'M\': return 1000;\n        default: return 0;\n    }\n}\n\nint main() {\n    char s[1000];\n    if (fgets(s, sizeof(s), stdin) == NULL) return 0;\n    s[strcspn(s, \"\\n\")] = \'\\0\';\n    int result = 0;\n    int prev = 0;\n    int len = strlen(s);\n    for (int i = len - 1; i >= 0; i--) {\n        int value = getValue(s[i]);\n        if (value < prev) {\n            result -= value;\n        } else {\n            result += value;\n            prev = value;\n        }\n    }\n    printf(\"%d\\n\", result);\n    return 0;\n}',NULL,1,'2026-09-27 13:05:47','2026-09-28 15:16:03'),(206,32,'PYTHON','s = input().strip()\nresult = 0\nprev = 0\nvalues = {\'I\': 1, \'V\': 5, \'X\': 10, \'L\': 50, \'C\': 100, \'D\': 500, \'M\': 1000}\nfor c in reversed(s):\n    value = values.get(c, 0)\n    if value < prev:\n        result -= value\n    else:\n        result += value\n        prev = value\nprint(result)',NULL,1,'2026-09-27 13:05:49','2026-09-28 15:16:03'),(207,33,'C','#include <stdio.h>\n#include <limits.h>\n\nint main() {\n    int x;\n    scanf(\"%d\", &x);\n    int rev = 0;\n    while (x != 0) {\n        int pop = x % 10;\n        x /= 10;\n        if (rev > INT_MAX / 10 || (rev == INT_MAX / 10 && pop > 7)) {\n            printf(\"0\\n\");\n            return 0;\n        }\n        if (rev < INT_MIN / 10 || (rev == INT_MIN / 10 && pop < -8)) {\n            printf(\"0\\n\");\n            return 0;\n        }\n        rev = rev * 10 + pop;\n    }\n    printf(\"%d\\n\", rev);\n    return 0;\n}',NULL,1,'2026-09-27 13:05:49','2026-09-28 15:16:03'),(208,35,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String num1 = sc.next();\n        String num2 = sc.next();\n        System.out.println(multiply(num1, num2));\n    }\n\n    public static String multiply(String num1, String num2) {\n        if (\"0\".equals(num1) || \"0\".equals(num2)) {\n            return \"0\";\n        }\n        int m = num1.length();\n        int n = num2.length();\n        int[] res = new int[m + n];\n        for (int i = m - 1; i >= 0; i--) {\n            int x = num1.charAt(i) - \'0\';\n            for (int j = n - 1; j >= 0; j--) {\n                int y = num2.charAt(j) - \'0\';\n                int sum = res[i + j + 1] + x * y;\n                res[i + j + 1] = sum % 10;\n                res[i + j] += sum / 10;\n            }\n        }\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < res.length; i++) {\n            if (sb.length() == 0 && res[i] == 0) {\n                continue;\n            }\n            sb.append(res[i]);\n        }\n        return sb.toString();\n    }\n}',NULL,1,'2026-09-27 13:05:49','2026-09-28 15:16:03'),(209,34,'CPP','#include <iostream>\nusing namespace std;\n\nbool isPalindrome(int x) {\n    if (x < 0 || (x % 10 == 0 && x != 0)) {\n        return false;\n    }\n    int reversed = 0;\n    while (x > reversed) {\n        reversed = reversed * 10 + x % 10;\n        x /= 10;\n    }\n    return x == reversed || x == reversed / 10;\n}\n\nint main() {\n    int x;\n    if (cin >> x) {\n        cout << (isPalindrome(x) ? \"true\" : \"false\") << endl;\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:05:49','2026-09-28 15:16:03'),(210,32,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (input) => {\n    const s = input.trim();\n    let result = 0;\n    let prev = 0;\n    for (let i = s.length - 1; i >= 0; i--) {\n        const value = getValue(s[i]);\n        if (value < prev) {\n            result -= value;\n        } else {\n            result += value;\n            prev = value;\n        }\n    }\n    console.log(result);\n    rl.close();\n});\n\nfunction getValue(c) {\n    switch (c) {\n        case \'I\': return 1;\n        case \'V\': return 5;\n        case \'X\': return 10;\n        case \'L\': return 50;\n        case \'C\': return 100;\n        case \'D\': return 500;\n        case \'M\': return 1000;\n        default: return 0;\n    }\n}',NULL,1,'2026-09-27 13:05:50','2026-09-28 15:16:03'),(211,33,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    x = int(data[0])\n    rev = 0\n    INT_MAX = 2**31 - 1\n    INT_MIN = -2**31\n    while x != 0:\n        pop = x % 10\n        x = int(x / 10)\n        if rev > INT_MAX // 10 or (rev == INT_MAX // 10 and pop > 7):\n            print(0)\n            return\n        if rev < INT_MIN // 10 or (rev == INT_MIN // 10 and pop < -8):\n            print(0)\n            return\n        rev = rev * 10 + pop\n    print(rev)\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:05:50','2026-09-28 15:16:03'),(212,34,'C','#include <stdio.h>\n#include <stdbool.h>\n\nbool isPalindrome(int x) {\n    if (x < 0 || (x % 10 == 0 && x != 0)) {\n        return false;\n    }\n    int reversed = 0;\n    while (x > reversed) {\n        reversed = reversed * 10 + x % 10;\n        x /= 10;\n    }\n    return x == reversed || x == reversed / 10;\n}\n\nint main() {\n    int x;\n    if (scanf(\"%d\", &x) == 1) {\n        if (isPalindrome(x)) {\n            printf(\"true\\n\");\n        } else {\n            printf(\"false\\n\");\n        }\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:05:51','2026-09-28 15:16:03'),(213,35,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n\nusing namespace std;\n\nstring multiply(string num1, string num2) {\n    if (num1 == \"0\" || num2 == \"0\") {\n        return \"0\";\n    }\n    int m = num1.length();\n    int n = num2.length();\n    vector<int> res(m + n, 0);\n    for (int i = m - 1; i >= 0; i--) {\n        int x = num1[i] - \'0\';\n        for (int j = n - 1; j >= 0; j--) {\n            int y = num2[j] - \'0\';\n            int sum = res[i + j + 1] + x * y;\n            res[i + j + 1] = sum % 10;\n            res[i + j] += sum / 10;\n        }\n    }\n    string sb;\n    for (int i = 0; i < (int)res.size(); i++) {\n        if (sb.empty() && res[i] == 0) {\n            continue;\n        }\n        sb += to_string(res[i]);\n    }\n    return sb;\n}\n\nint main() {\n    string num1, num2;\n    cin >> num1 >> num2;\n    cout << multiply(num1, num2) << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:51','2026-09-28 15:16:03'),(214,33,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    let x = parseInt(line.trim(), 10);\n    let rev = 0;\n    while (x !== 0) {\n        let pop = x % 10;\n        x = Math.trunc(x / 10);\n        if (rev > 214748364 || (rev === 214748364 && pop > 7)) {\n            console.log(0);\n            rl.close();\n            return;\n        }\n        if (rev < -214748364 || (rev === -214748364 && pop < -8)) {\n            console.log(0);\n            rl.close();\n            return;\n        }\n        rev = rev * 10 + pop;\n    }\n    console.log(rev);\n    rl.close();\n});',NULL,1,'2026-09-27 13:05:52','2026-09-28 15:16:03'),(215,34,'PYTHON','import sys\n\ndef is_palindrome(x):\n    if x < 0 or (x % 10 == 0 and x != 0):\n        return False\n    reversed_num = 0\n    while x > reversed_num:\n        reversed_num = reversed_num * 10 + x % 10\n        x //= 10\n    return x == reversed_num or x == reversed_num // 10\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if data:\n        x = int(data[0])\n        print(\"true\" if is_palindrome(x) else \"false\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:05:52','2026-09-28 15:16:03'),(216,36,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) {\n            line = line.substring(1, line.length() - 1);\n        }\n        if (line.isEmpty()) {\n            System.out.println(0);\n            return;\n        }\n        String[] parts = line.split(\",\");\n        Integer[] nums = new Integer[parts.length];\n        for (int i = 0; i < parts.length; i++) {\n            String s = parts[i].trim();\n            if (s.equals(\"null\")) {\n                nums[i] = null;\n            } else {\n                nums[i] = Integer.parseInt(s);\n            }\n        }\n        TreeNode root = buildTree(nums);\n        System.out.println(maxDepth(root));\n    }\n\n    private static TreeNode buildTree(Integer[] nums) {\n        if (nums == null || nums.length == 0 || nums[0] == null) {\n            return null;\n        }\n        TreeNode root = new TreeNode(nums[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < nums.length) {\n            TreeNode node = queue.poll();\n            if (i < nums.length && nums[i] != null) {\n                node.left = new TreeNode(nums[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < nums.length && nums[i] != null) {\n                node.right = new TreeNode(nums[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    private static int maxDepth(TreeNode root) {\n        if (root == null) {\n            return 0;\n        }\n        return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) {\n            this.val = val;\n        }\n    }\n}',NULL,1,'2026-09-27 13:05:52','2026-09-28 15:16:03'),(217,34,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const x = parseInt(line.trim(), 10);\n    if (!isNaN(x)) {\n        console.log(isPalindrome(x));\n    }\n    rl.close();\n});\n\nfunction isPalindrome(x) {\n    if (x < 0 || (x % 10 === 0 && x !== 0)) {\n        return false;\n    }\n    let reversed = 0;\n    while (x > reversed) {\n        reversed = reversed * 10 + x % 10;\n        x = Math.floor(x / 10);\n    }\n    return x === reversed || x === Math.floor(reversed / 10);\n}',NULL,1,'2026-09-27 13:05:54','2026-09-28 15:16:03'),(218,37,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine().trim();\n        if (s.startsWith(\"[\")) s = s.substring(1, s.length() - 1);\n        String[] parts = s.isEmpty() ? new String[0] : s.split(\",\");\n        TreeNode root = buildTree(parts);\n        List<List<Integer>> res = levelOrder(root);\n        System.out.println(format(res));\n    }\n\n    static TreeNode buildTree(String[] parts) {\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> q = new LinkedList<>();\n        q.offer(root);\n        int i = 1;\n        while (!q.isEmpty() && i < parts.length) {\n            TreeNode cur = q.poll();\n            if (i < parts.length) {\n                String left = parts[i++].trim();\n                if (!left.equals(\"null\")) {\n                    cur.left = new TreeNode(Integer.parseInt(left));\n                    q.offer(cur.left);\n                }\n            }\n            if (i < parts.length) {\n                String right = parts[i++].trim();\n                if (!right.equals(\"null\")) {\n                    cur.right = new TreeNode(Integer.parseInt(right));\n                    q.offer(cur.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    static List<List<Integer>> levelOrder(TreeNode root) {\n        List<List<Integer>> res = new ArrayList<>();\n        if (root == null) return res;\n        Queue<TreeNode> q = new LinkedList<>();\n        q.offer(root);\n        while (!q.isEmpty()) {\n            int size = q.size();\n            List<Integer> level = new ArrayList<>();\n            for (int i = 0; i < size; i++) {\n                TreeNode node = q.poll();\n                level.add(node.val);\n                if (node.left != null) q.offer(node.left);\n                if (node.right != null) q.offer(node.right);\n            }\n            res.add(level);\n        }\n        return res;\n    }\n\n    static String format(List<List<Integer>> res) {\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            sb.append(\"[\");\n            List<Integer> level = res.get(i);\n            for (int j = 0; j < level.size(); j++) {\n                sb.append(level.get(j));\n                if (j < level.size() - 1) sb.append(\",\");\n            }\n            sb.append(\"]\");\n            if (i < res.size() - 1) sb.append(\",\");\n        }\n        sb.append(\"]\");\n        return sb.toString();\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n    }\n}',NULL,1,'2026-09-27 13:05:55','2026-09-28 15:16:03'),(219,35,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nchar* multiply(char* num1, char* num2) {\n    if (strcmp(num1, \"0\") == 0 || strcmp(num2, \"0\") == 0) {\n        char* zero = (char*)malloc(2);\n        zero[0] = \'0\';\n        zero[1] = \'\\0\';\n        return zero;\n    }\n    int m = strlen(num1);\n    int n = strlen(num2);\n    int* res = (int*)calloc(m + n, sizeof(int));\n    for (int i = m - 1; i >= 0; i--) {\n        for (int j = n - 1; j >= 0; j--) {\n            int mul = (num1[i] - \'0\') * (num2[j] - \'0\');\n            int p1 = i + j;\n            int p2 = i + j + 1;\n            int sum = mul + res[p2];\n            res[p2] = sum % 10;\n            res[p1] += sum / 10;\n        }\n    }\n    char* result = (char*)malloc(m + n + 1);\n    int idx = 0;\n    int i = 0;\n    while (i < m + n && res[i] == 0) i++;\n    while (i < m + n) {\n        result[idx++] = res[i] + \'0\';\n        i++;\n    }\n    result[idx] = \'\\0\';\n    free(res);\n    return result;\n}\n\nint main() {\n    char num1[1000], num2[1000];\n    scanf(\"%s %s\", num1, num2);\n    char* result = multiply(num1, num2);\n    printf(\"%s\\n\", result);\n    free(result);\n    return 0;\n}',NULL,1,'2026-09-27 13:05:55','2026-09-28 15:16:03'),(220,36,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n#include <algorithm>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(vector<string>& nums) {\n    if (nums.empty() || nums[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(nums[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)nums.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->left = new TreeNode(stoi(nums[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->right = new TreeNode(stoi(nums[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nint maxDepth(TreeNode* root) {\n    if (root == nullptr) return 0;\n    return 1 + max(maxDepth(root->left), maxDepth(root->right));\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.front() == \' \' || line.front() == \'\\t\')) line.erase(line.begin());\n    while (!line.empty() && (line.back() == \' \' || line.back() == \'\\t\' || line.back() == \'\\r\')) line.pop_back();\n    if (!line.empty() && line.front() == \'[\') {\n        line = line.substr(1, line.size() - 2);\n    }\n    if (line.empty()) {\n        cout << 0 << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\");\n        size_t end = token.find_last_not_of(\" \\t\");\n        if (start == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(token.substr(start, end - start + 1));\n        }\n    }\n    TreeNode* root = buildTree(parts);\n    cout << maxDepth(root) << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:56','2026-09-28 15:16:03'),(221,35,'PYTHON','import sys\n\ndef multiply(num1, num2):\n    if num1 == \"0\" or num2 == \"0\":\n        return \"0\"\n    m, n = len(num1), len(num2)\n    res = [0] * (m + n)\n    for i in range(m - 1, -1, -1):\n        x = ord(num1[i]) - ord(\'0\')\n        for j in range(n - 1, -1, -1):\n            y = ord(num2[j]) - ord(\'0\')\n            total = res[i + j + 1] + x * y\n            res[i + j + 1] = total % 10\n            res[i + j] += total // 10\n    result = []\n    for num in res:\n        if not result and num == 0:\n            continue\n        result.append(str(num))\n    return \'\'.join(result)\n\ndef main():\n    data = sys.stdin.read().split()\n    num1, num2 = data[0], data[1]\n    print(multiply(num1, num2))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:05:57','2026-09-28 15:16:03'),(222,38,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.isEmpty()) {\n            System.out.println(\"[]\");\n            return;\n        }\n        line = line.substring(1, line.length() - 1).trim();\n        if (line.isEmpty()) {\n            System.out.println(\"[]\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        Integer[] nums = new Integer[parts.length];\n        for (int i = 0; i < parts.length; i++) {\n            String s = parts[i].trim();\n            if (s.equals(\"null\")) {\n                nums[i] = null;\n            } else {\n                nums[i] = Integer.parseInt(s);\n            }\n        }\n        TreeNode root = buildTree(nums);\n        List<Integer> res = new ArrayList<>();\n        preorder(root, res);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(res.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    private static TreeNode buildTree(Integer[] nums) {\n        if (nums == null || nums.length == 0 || nums[0] == null) return null;\n        TreeNode root = new TreeNode(nums[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < nums.length) {\n            TreeNode node = queue.poll();\n            if (i < nums.length && nums[i] != null) {\n                node.left = new TreeNode(nums[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < nums.length && nums[i] != null) {\n                node.right = new TreeNode(nums[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    private static void preorder(TreeNode root, List<Integer> res) {\n        if (root == null) return;\n        res.add(root.val);\n        preorder(root.left, res);\n        preorder(root.right, res);\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) {\n            this.val = val;\n        }\n    }\n}',NULL,1,'2026-09-27 13:05:57','2026-09-28 15:16:03'),(223,35,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const [num1, num2] = input[0].split(\' \');\n    console.log(multiply(num1, num2));\n});\n\nfunction multiply(num1, num2) {\n    if (num1 === \"0\" || num2 === \"0\") {\n        return \"0\";\n    }\n    const m = num1.length;\n    const n = num2.length;\n    const res = new Array(m + n).fill(0);\n    for (let i = m - 1; i >= 0; i--) {\n        const x = num1.charCodeAt(i) - \'0\'.charCodeAt(0);\n        for (let j = n - 1; j >= 0; j--) {\n            const y = num2.charCodeAt(j) - \'0\'.charCodeAt(0);\n            const sum = res[i + j + 1] + x * y;\n            res[i + j + 1] = sum % 10;\n            res[i + j] += Math.floor(sum / 10);\n        }\n    }\n    let sb = \"\";\n    for (let i = 0; i < res.length; i++) {\n        if (sb.length === 0 && res[i] === 0) {\n            continue;\n        }\n        sb += res[i];\n    }\n    return sb;\n}',NULL,1,'2026-09-27 13:05:58','2026-09-28 15:16:03'),(224,37,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const string& s) {\n    string str = s;\n    size_t start = str.find_first_not_of(\" \\t\\n\\r\");\n    size_t end = str.find_last_not_of(\" \\t\\n\\r\");\n    if (start == string::npos) return nullptr;\n    str = str.substr(start, end - start + 1);\n    if (str.length() <= 2) return nullptr;\n    string content = str.substr(1, str.length() - 2);\n    size_t cstart = content.find_first_not_of(\" \\t\\n\\r\");\n    size_t cend = content.find_last_not_of(\" \\t\\n\\r\");\n    if (cstart == string::npos) return nullptr;\n    content = content.substr(cstart, cend - cstart + 1);\n    if (content.empty()) return nullptr;\n\n    vector<string> parts;\n    stringstream ss(content);\n    string item;\n    while (getline(ss, item, \',\')) {\n        size_t istart = item.find_first_not_of(\" \\t\\n\\r\");\n        size_t iend = item.find_last_not_of(\" \\t\\n\\r\");\n        if (istart == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(item.substr(istart, iend - istart + 1));\n        }\n    }\n\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i];\n            if (leftVal != \"null\") {\n                node->left = new TreeNode(stoi(leftVal));\n                q.push(node->left);\n            }\n            i++;\n        }\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i];\n            if (rightVal != \"null\") {\n                node->right = new TreeNode(stoi(rightVal));\n                q.push(node->right);\n            }\n            i++;\n        }\n    }\n    return root;\n}\n\nvector<vector<int>> levelOrder(TreeNode* root) {\n    vector<vector<int>> result;\n    if (root == nullptr) return result;\n    queue<TreeNode*> q;\n    q.push(root);\n    while (!q.empty()) {\n        int size = q.size();\n        vector<int> level;\n        for (int i = 0; i < size; i++) {\n            TreeNode* node = q.front();\n            q.pop();\n            level.push_back(node->val);\n            if (node->left != nullptr) q.push(node->left);\n            if (node->right != nullptr) q.push(node->right);\n        }\n        result.push_back(level);\n    }\n    return result;\n}\n\nstring format(const vector<vector<int>>& result) {\n    string sb;\n    sb += \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        sb += \"[\";\n        const vector<int>& level = result[i];\n        for (int j = 0; j < (int)level.size(); j++) {\n            sb += to_string(level[j]);\n            if (j < (int)level.size() - 1) sb += \",\";\n        }\n        sb += \"]\";\n        if (i < (int)result.size() - 1) sb += \",\";\n    }\n    sb += \"]\";\n    return sb;\n}\n\nint main() {\n    string s;\n    getline(cin, s);\n    TreeNode* root = buildTree(s);\n    vector<vector<int>> result = levelOrder(root);\n    cout << format(result) << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:05:59','2026-09-28 15:16:03'),(225,36,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstruct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n};\n\nstatic int maxDepth(struct TreeNode* root) {\n    if (root == NULL) return 0;\n    int left = maxDepth(root->left);\n    int right = maxDepth(root->right);\n    return 1 + (left > right ? left : right);\n}\n\nstatic struct TreeNode* newNode(int val) {\n    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nint main(void) {\n    char line[1000000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n\n    size_t len = strlen(line);\n    while (len > 0 && (line[len - 1] == \'\\n\' || line[len - 1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n\n    char *start = line;\n    while (*start == \' \' || *start == \'\\t\') start++;\n    char *end = start + strlen(start);\n    while (end > start && (end[-1] == \' \' || end[-1] == \'\\t\')) {\n        *--end = \'\\0\';\n    }\n\n    if (*start == \'[\') {\n        start++;\n        if (end > start && end[-1] == \']\') {\n            end[-1] = \'\\0\';\n        }\n    }\n\n    if (*start == \'\\0\') {\n        printf(\"0\\n\");\n        return 0;\n    }\n\n    int capacity = 1024;\n    int *nums = (int*)malloc(sizeof(int) * capacity);\n    int *isNull = (int*)malloc(sizeof(int) * capacity);\n    int count = 0;\n\n    char *token = strtok(start, \",\");\n    while (token != NULL) {\n        while (*token == \' \' || *token == \'\\t\') token++;\n        char *tend = token + strlen(token);\n        while (tend > token && (tend[-1] == \' \' || tend[-1] == \'\\t\')) {\n            *--tend = \'\\0\';\n        }\n\n        if (count >= capacity) {\n            capacity *= 2;\n            nums = (int*)realloc(nums, sizeof(int) * capacity);\n            isNull = (int*)realloc(isNull, sizeof(int) * capacity);\n        }\n\n        if (strcmp(token, \"null\") == 0) {\n            isNull[count] = 1;\n            nums[count] = 0;\n        } else {\n            isNull[count] = 0;\n            nums[count] = atoi(token);\n        }\n        count++;\n        token = strtok(NULL, \",\");\n    }\n\n    if (count == 0 || isNull[0]) {\n        printf(\"0\\n\");\n        free(nums);\n        free(isNull);\n        return 0;\n    }\n\n    struct TreeNode **queue = (struct TreeNode**)malloc(sizeof(struct TreeNode*) * (count + 1));\n    int head = 0, tail = 0;\n\n    struct TreeNode *root = newNode(nums[0]);\n    queue[tail++] = root;\n    int i = 1;\n\n    while (head < tail && i < count) {\n        struct TreeNode *node = queue[head++];\n\n        if (i < count && !isNull[i]) {\n            node->left = newNode(nums[i]);\n            queue[tail++] = node->left;\n        }\n        i++;\n\n        if (i < count && !isNull[i]) {\n            node->right = newNode(nums[i]);\n            queue[tail++] = node->right;\n        }\n        i++;\n    }\n\n    printf(\"%d\\n\", maxDepth(root));\n\n    free(queue);\n    free(nums);\n    free(isNull);\n    return 0;\n}',NULL,1,'2026-09-27 13:05:59','2026-09-28 15:16:03'),(226,38,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <stack>\n#include <sstream>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const vector<string>& parts) {\n    if (parts.empty() || parts[0] == \"null\") {\n        return nullptr;\n    }\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size() && parts[i] != \"null\") {\n            node->left = new TreeNode(stoi(parts[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < (int)parts.size() && parts[i] != \"null\") {\n            node->right = new TreeNode(stoi(parts[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nvector<int> preorderTraversal(TreeNode* root) {\n    vector<int> result;\n    if (root == nullptr) {\n        return result;\n    }\n    stack<TreeNode*> st;\n    st.push(root);\n    while (!st.empty()) {\n        TreeNode* node = st.top();\n        st.pop();\n        result.push_back(node->val);\n        if (node->right != nullptr) {\n            st.push(node->right);\n        }\n        if (node->left != nullptr) {\n            st.push(node->left);\n        }\n    }\n    return result;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) {\n        line.pop_back();\n    }\n    if (line.empty()) {\n        cout << \"[]\" << endl;\n        return 0;\n    }\n    line = line.substr(1, line.length() - 2);\n    vector<string> parts;\n    stringstream ss(line);\n    string item;\n    while (getline(ss, item, \',\')) {\n        size_t start = item.find_first_not_of(\" \\t\");\n        size_t end = item.find_last_not_of(\" \\t\");\n        if (start == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(item.substr(start, end - start + 1));\n        }\n    }\n    TreeNode* root = buildTree(parts);\n    vector<int> result = preorderTraversal(root);\n    cout << \"[\";\n    for (size_t i = 0; i < result.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << result[i];\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:06:00','2026-09-28 15:16:03'),(227,36,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(nums):\n    if not nums or nums[0] is None:\n        return None\n    root = TreeNode(nums[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(nums):\n        node = queue.popleft()\n        if i < len(nums) and nums[i] is not None:\n            node.left = TreeNode(nums[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(nums) and nums[i] is not None:\n            node.right = TreeNode(nums[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef max_depth(root):\n    if root is None:\n        return 0\n    return 1 + max(max_depth(root.left), max_depth(root.right))\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:-1]\n    if not line:\n        print(0)\n        return\n    parts = line.split(\",\")\n    nums = []\n    for s in parts:\n        s = s.strip()\n        if s == \"null\":\n            nums.append(None)\n        else:\n            nums.append(int(s))\n    root = build_tree(nums)\n    print(max_depth(root))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:06:01','2026-09-28 15:16:03'),(228,36,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (input) => {\n    let line = input.trim();\n    if (line.startsWith(\'[\')) {\n        line = line.substring(1, line.length - 1);\n    }\n    if (line.length === 0) {\n        console.log(0);\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const nums = parts.map(s => {\n        s = s.trim();\n        return s === \'null\' ? null : parseInt(s, 10);\n    });\n\n    const root = buildTree(nums);\n    console.log(maxDepth(root));\n    rl.close();\n});\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(nums) {\n    if (!nums || nums.length === 0 || nums[0] === null) return null;\n    const root = new TreeNode(nums[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < nums.length) {\n        const node = queue.shift();\n        if (i < nums.length && nums[i] !== null) {\n            node.left = new TreeNode(nums[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < nums.length && nums[i] !== null) {\n            node.right = new TreeNode(nums[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction maxDepth(root) {\n    if (root === null) return 0;\n    return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));\n}',NULL,1,'2026-09-27 13:06:03','2026-09-28 15:16:03'),(229,37,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\ntypedef struct {\n    TreeNode **data;\n    int front;\n    int rear;\n    int size;\n} Queue;\n\nvoid initQueue(Queue *q, int size) {\n    q->data = (TreeNode **)malloc(sizeof(TreeNode *) * size);\n    q->front = 0;\n    q->rear = 0;\n    q->size = size;\n}\n\nvoid enqueue(Queue *q, TreeNode *node) {\n    q->data[q->rear++] = node;\n}\n\nTreeNode *dequeue(Queue *q) {\n    return q->data[q->front++];\n}\n\nint isEmpty(Queue *q) {\n    return q->front == q->rear;\n}\n\nTreeNode *newNode(int val) {\n    TreeNode *node = (TreeNode *)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nTreeNode *buildTree(char *s) {\n    int len = strlen(s);\n    while (len > 0 && isspace(s[len - 1])) {\n        s[--len] = \'\\0\';\n    }\n    int start = 0;\n    while (start < len && isspace(s[start])) {\n        start++;\n    }\n    if (len - start <= 2) return NULL;\n    char *content = (char *)malloc(sizeof(char) * (len - start));\n    strncpy(content, s + start + 1, len - start - 2);\n    content[len - start - 2] = \'\\0\';\n\n    char *trimmed = content;\n    while (*trimmed && isspace(*trimmed)) trimmed++;\n    if (*trimmed == \'\\0\') {\n        free(content);\n        return NULL;\n    }\n\n    char *parts[10000];\n    int partCount = 0;\n    char *token = strtok(content, \",\");\n    while (token != NULL) {\n        parts[partCount++] = token;\n        token = strtok(NULL, \",\");\n    }\n\n    char *first = parts[0];\n    while (*first && isspace(*first)) first++;\n    if (strcmp(first, \"null\") == 0) {\n        free(content);\n        return NULL;\n    }\n\n    TreeNode *root = newNode(atoi(first));\n    Queue q;\n    initQueue(&q, partCount + 1);\n    enqueue(&q, root);\n    int i = 1;\n    while (!isEmpty(&q) && i < partCount) {\n        TreeNode *node = dequeue(&q);\n        if (i < partCount) {\n            char *leftVal = parts[i];\n            while (*leftVal && isspace(*leftVal)) leftVal++;\n            if (strcmp(leftVal, \"null\") != 0) {\n                node->left = newNode(atoi(leftVal));\n                enqueue(&q, node->left);\n            }\n            i++;\n        }\n        if (i < partCount) {\n            char *rightVal = parts[i];\n            while (*rightVal && isspace(*rightVal)) rightVal++;\n            if (strcmp(rightVal, \"null\") != 0) {\n                node->right = newNode(atoi(rightVal));\n                enqueue(&q, node->right);\n            }\n            i++;\n        }\n    }\n    free(q.data);\n    free(content);\n    return root;\n}\n\nint **levelOrder(TreeNode *root, int **columnSizes, int *returnSize) {\n    *returnSize = 0;\n    if (root == NULL) {\n        *columnSizes = NULL;\n        return NULL;\n    }\n\n    int capacity = 10000;\n    int **result = (int **)malloc(sizeof(int *) * capacity);\n    *columnSizes = (int *)malloc(sizeof(int) * capacity);\n\n    Queue q;\n    initQueue(&q, capacity);\n    enqueue(&q, root);\n\n    while (!isEmpty(&q)) {\n        int size = q.rear - q.front;\n        int *level = (int *)malloc(sizeof(int) * size);\n        for (int i = 0; i < size; i++) {\n            TreeNode *node = dequeue(&q);\n            level[i] = node->val;\n            if (node->left != NULL) enqueue(&q, node->left);\n            if (node->right != NULL) enqueue(&q, node->right);\n        }\n        result[*returnSize] = level;\n        (*columnSizes)[*returnSize] = size;\n        (*returnSize)++;\n    }\n\n    free(q.data);\n    return result;\n}\n\nvoid printResult(int **result, int *columnSizes, int returnSize) {\n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        printf(\"[\");\n        for (int j = 0; j < columnSizes[i]; j++) {\n            printf(\"%d\", result[i][j]);\n            if (j < columnSizes[i] - 1) printf(\",\");\n        }\n        printf(\"]\");\n        if (i < returnSize - 1) printf(\",\");\n    }\n    printf(\"]\\n\");\n}\n\nint main() {\n    char s[100000];\n    if (fgets(s, sizeof(s), stdin) == NULL) return 0;\n    int len = strlen(s);\n    while (len > 0 && (s[len - 1] == \'\\n\' || s[len - 1] == \'\\r\')) {\n        s[--len] = \'\\0\';\n    }\n\n    TreeNode *root = buildTree(s);\n    int *columnSizes;\n    int returnSize;\n    int **result = levelOrder(root, &columnSizes, &returnSize);\n    printResult(result, columnSizes, returnSize);\n\n    return 0;\n}',NULL,1,'2026-09-27 13:06:04','2026-09-28 15:16:03'),(230,38,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nTreeNode* createNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nTreeNode* buildTree(char** parts, int partsSize) {\n    if (partsSize == 0 || strcmp(parts[0], \"null\") == 0) {\n        return NULL;\n    }\n    TreeNode* root = createNode(atoi(parts[0]));\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * partsSize);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < partsSize) {\n        TreeNode* node = queue[front++];\n        if (i < partsSize && strcmp(parts[i], \"null\") != 0) {\n            node->left = createNode(atoi(parts[i]));\n            queue[rear++] = node->left;\n        }\n        i++;\n        if (i < partsSize && strcmp(parts[i], \"null\") != 0) {\n            node->right = createNode(atoi(parts[i]));\n            queue[rear++] = node->right;\n        }\n        i++;\n    }\n    free(queue);\n    return root;\n}\n\nint* preorderTraversal(TreeNode* root, int* returnSize) {\n    int* result = (int*)malloc(sizeof(int) * 10000);\n    *returnSize = 0;\n    if (root == NULL) {\n        return result;\n    }\n    TreeNode** stack = (TreeNode**)malloc(sizeof(TreeNode*) * 10000);\n    int top = 0;\n    stack[top++] = root;\n    while (top > 0) {\n        TreeNode* node = stack[--top];\n        result[(*returnSize)++] = node->val;\n        if (node->right != NULL) {\n            stack[top++] = node->right;\n        }\n        if (node->left != NULL) {\n            stack[top++] = node->left;\n        }\n    }\n    free(stack);\n    return result;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    if (len == 0) {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    char* content = line;\n    if (line[0] == \'[\' && line[len-1] == \']\') {\n        line[len-1] = \'\\0\';\n        content = line + 1;\n    }\n    char* parts[10000];\n    int partsSize = 0;\n    char* token = strtok(content, \",\");\n    while (token != NULL) {\n        while (*token == \' \') token++;\n        int tlen = strlen(token);\n        while (tlen > 0 && token[tlen-1] == \' \') {\n            token[--tlen] = \'\\0\';\n        }\n        parts[partsSize++] = token;\n        token = strtok(NULL, \",\");\n    }\n    TreeNode* root = buildTree(parts, partsSize);\n    int returnSize = 0;\n    int* result = preorderTraversal(root, &returnSize);\n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", result[i]);\n    }\n    printf(\"]\\n\");\n    free(result);\n    return 0;\n}',NULL,1,'2026-09-27 13:06:04','2026-09-28 15:16:03'),(231,38,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(parts):\n    if not parts or parts[0] == \"null\":\n        return None\n    root = TreeNode(int(parts[0]))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts) and parts[i] != \"null\":\n            node.left = TreeNode(int(parts[i]))\n            queue.append(node.left)\n        i += 1\n        if i < len(parts) and parts[i] != \"null\":\n            node.right = TreeNode(int(parts[i]))\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef preorder_traversal(root):\n    result = []\n    if root is None:\n        return result\n    stack = [root]\n    while stack:\n        node = stack.pop()\n        result.append(node.val)\n        if node.right:\n            stack.append(node.right)\n        if node.left:\n            stack.append(node.left)\n    return result\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if not line:\n        print(\"[]\")\n        return\n    line = line[1:-1]\n    parts = [p.strip() for p in line.split(\",\")]\n    root = build_tree(parts)\n    result = preorder_traversal(root)\n    print(str(result).replace(\" \", \"\"))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:06:06','2026-09-28 15:16:03'),(232,37,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(s):\n    s = s.strip()\n    if len(s) <= 2:\n        return None\n    content = s[1:-1].strip()\n    if not content:\n        return None\n    parts = content.split(\',\')\n    if not parts or parts[0].strip() == \'null\':\n        return None\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts):\n            left_val = parts[i].strip()\n            if left_val != \'null\':\n                node.left = TreeNode(int(left_val))\n                queue.append(node.left)\n            i += 1\n        if i < len(parts):\n            right_val = parts[i].strip()\n            if right_val != \'null\':\n                node.right = TreeNode(int(right_val))\n                queue.append(node.right)\n            i += 1\n    return root\n\ndef level_order(root):\n    result = []\n    if root is None:\n        return result\n    queue = deque([root])\n    while queue:\n        size = len(queue)\n        level = []\n        for _ in range(size):\n            node = queue.popleft()\n            level.append(node.val)\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n        result.append(level)\n    return result\n\ndef format_result(result):\n    sb = []\n    sb.append(\'[\')\n    for i, level in enumerate(result):\n        sb.append(\'[\')\n        for j, val in enumerate(level):\n            sb.append(str(val))\n            if j < len(level) - 1:\n                sb.append(\',\')\n        sb.append(\']\')\n        if i < len(result) - 1:\n            sb.append(\',\')\n    sb.append(\']\')\n    return \'\'.join(sb)\n\ndef main():\n    s = sys.stdin.readline().strip()\n    root = build_tree(s)\n    result = level_order(root)\n    print(format_result(result))\n\nif __name__ == \'__main__\':\n    main()',NULL,1,'2026-09-27 13:06:06','2026-09-28 15:16:03'),(233,40,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.isEmpty()) {\n            System.out.println(\"true\");\n            return;\n        }\n        line = line.substring(1, line.length() - 1).trim();\n        if (line.isEmpty()) {\n            System.out.println(\"true\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        Integer[] nums = new Integer[parts.length];\n        for (int i = 0; i < parts.length; i++) {\n            String s = parts[i].trim();\n            if (s.equals(\"null\")) {\n                nums[i] = null;\n            } else {\n                nums[i] = Integer.parseInt(s);\n            }\n        }\n        TreeNode root = buildTree(nums);\n        System.out.println(isSymmetric(root));\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n    }\n\n    static TreeNode buildTree(Integer[] nums) {\n        if (nums == null || nums.length == 0 || nums[0] == null) return null;\n        TreeNode root = new TreeNode(nums[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < nums.length) {\n            TreeNode node = queue.poll();\n            if (i < nums.length && nums[i] != null) {\n                node.left = new TreeNode(nums[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < nums.length && nums[i] != null) {\n                node.right = new TreeNode(nums[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    static boolean isSymmetric(TreeNode root) {\n        if (root == null) return true;\n        return check(root.left, root.right);\n    }\n\n    static boolean check(TreeNode left, TreeNode right) {\n        if (left == null && right == null) return true;\n        if (left == null || right == null) return false;\n        if (left.val != right.val) return false;\n        return check(left.left, right.right) && check(left.right, right.left);\n    }\n}',NULL,1,'2026-09-27 13:06:06','2026-09-28 15:16:03'),(234,38,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line === \'\') {\n        console.log(\'[]\');\n        rl.close();\n        return;\n    }\n    line = line.substring(1, line.length - 1);\n    const parts = line.split(\',\');\n    const root = buildTree(parts);\n    const result = preorderTraversal(root);\n    console.log(\'[\' + result.join(\',\') + \']\');\n    rl.close();\n});\n\nfunction buildTree(parts) {\n    if (parts.length === 0 || parts[0].trim() === \'null\') {\n        return null;\n    }\n    const root = new TreeNode(parseInt(parts[0].trim()));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length && parts[i].trim() !== \'null\') {\n            node.left = new TreeNode(parseInt(parts[i].trim()));\n            queue.push(node.left);\n        }\n        i++;\n        if (i < parts.length && parts[i].trim() !== \'null\') {\n            node.right = new TreeNode(parseInt(parts[i].trim()));\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction preorderTraversal(root) {\n    const result = [];\n    if (root === null) {\n        return result;\n    }\n    const stack = [root];\n    while (stack.length > 0) {\n        const node = stack.pop();\n        result.push(node.val);\n        if (node.right !== null) {\n            stack.push(node.right);\n        }\n        if (node.left !== null) {\n            stack.push(node.left);\n        }\n    }\n    return result;\n}\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}',NULL,1,'2026-09-27 13:06:08','2026-09-28 15:16:03'),(235,41,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n        char[][] grid = new char[m][n];\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine();\n            grid[i] = line.toCharArray();\n        }\n        int count = 0;\n        for (int i = 0; i < m; i++) {\n            for (int j = 0; j < n; j++) {\n                if (grid[i][j] == \'1\') {\n                    count++;\n                    dfs(grid, i, j, m, n);\n                }\n            }\n        }\n        System.out.println(count);\n    }\n\n    private static void dfs(char[][] grid, int i, int j, int m, int n) {\n        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] != \'1\') {\n            return;\n        }\n        grid[i][j] = \'0\';\n        dfs(grid, i + 1, j, m, n);\n        dfs(grid, i - 1, j, m, n);\n        dfs(grid, i, j + 1, m, n);\n        dfs(grid, i, j - 1, m, n);\n    }\n}',NULL,1,'2026-09-27 13:06:09','2026-09-28 15:16:03'),(236,37,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(s) {\n    s = s.trim();\n    if (s.length <= 2) return null;\n    const content = s.substring(1, s.length - 1).trim();\n    if (content.length === 0) return null;\n    const parts = content.split(\',\');\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n    const root = new TreeNode(parseInt(parts[0].trim(), 10));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length) {\n            const leftVal = parts[i].trim();\n            if (leftVal !== \'null\') {\n                node.left = new TreeNode(parseInt(leftVal, 10));\n                queue.push(node.left);\n            }\n            i++;\n        }\n        if (i < parts.length) {\n            const rightVal = parts[i].trim();\n            if (rightVal !== \'null\') {\n                node.right = new TreeNode(parseInt(rightVal, 10));\n                queue.push(node.right);\n            }\n            i++;\n        }\n    }\n    return root;\n}\n\nfunction levelOrder(root) {\n    const result = [];\n    if (root === null) return result;\n    const queue = [root];\n    while (queue.length > 0) {\n        const size = queue.length;\n        const level = [];\n        for (let i = 0; i < size; i++) {\n            const node = queue.shift();\n            level.push(node.val);\n            if (node.left !== null) queue.push(node.left);\n            if (node.right !== null) queue.push(node.right);\n        }\n        result.push(level);\n    }\n    return result;\n}\n\nfunction format(result) {\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < result.length; i++) {\n        sb += \'[\';\n        const level = result[i];\n        for (let j = 0; j < level.length; j++) {\n            sb += level[j];\n            if (j < level.length - 1) sb += \',\';\n        }\n        sb += \']\';\n        if (i < result.length - 1) sb += \',\';\n    }\n    sb += \']\';\n    return sb;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const s = line.trim();\n    const root = buildTree(s);\n    const result = levelOrder(root);\n    console.log(format(result));\n    rl.close();\n});',NULL,1,'2026-09-27 13:06:09','2026-09-28 15:16:03'),(237,40,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(vector<string>& nums) {\n    if (nums.empty() || nums[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(nums[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)nums.size()) {\n        TreeNode* node = q.front(); q.pop();\n        if (i < (int)nums.size()) {\n            if (nums[i] != \"null\") {\n                node->left = new TreeNode(stoi(nums[i]));\n                q.push(node->left);\n            }\n            i++;\n        }\n        if (i < (int)nums.size()) {\n            if (nums[i] != \"null\") {\n                node->right = new TreeNode(stoi(nums[i]));\n                q.push(node->right);\n            }\n            i++;\n        }\n    }\n    return root;\n}\n\nbool check(TreeNode* left, TreeNode* right) {\n    if (!left && !right) return true;\n    if (!left || !right) return false;\n    if (left->val != right->val) return false;\n    return check(left->left, right->right) && check(left->right, right->left);\n}\n\nbool isSymmetric(TreeNode* root) {\n    if (!root) return true;\n    return check(root->left, root->right);\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) line.pop_back();\n    if (line.empty()) {\n        cout << \"true\" << endl;\n        return 0;\n    }\n    line = line.substr(1, line.size() - 2);\n    if (line.find_first_not_of(\" \\t\") == string::npos) {\n        cout << \"true\" << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\");\n        size_t end = token.find_last_not_of(\" \\t\");\n        if (start == string::npos) parts.push_back(\"\");\n        else parts.push_back(token.substr(start, end - start + 1));\n    }\n    TreeNode* root = buildTree(parts);\n    cout << (isSymmetric(root) ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:06:10','2026-09-28 15:16:03'),(238,41,'CPP','#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nvoid dfs(vector<string>& grid, int i, int j, int m, int n) {\n    if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] != \'1\') {\n        return;\n    }\n    grid[i][j] = \'0\';\n    dfs(grid, i - 1, j, m, n);\n    dfs(grid, i + 1, j, m, n);\n    dfs(grid, i, j - 1, m, n);\n    dfs(grid, i, j + 1, m, n);\n}\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    cin.ignore();\n    vector<string> grid(m);\n    for (int i = 0; i < m; i++) {\n        getline(cin, grid[i]);\n    }\n    int count = 0;\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            if (grid[i][j] == \'1\') {\n                count++;\n                dfs(grid, i, j, m, n);\n            }\n        }\n    }\n    cout << count << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:06:11','2026-09-28 15:16:03'),(239,41,'C','#include <stdio.h>\n#include <stdlib.h>\n\nvoid dfs(char **grid, int i, int j, int m, int n) {\n    if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] != \'1\') {\n        return;\n    }\n    grid[i][j] = \'0\';\n    dfs(grid, i - 1, j, m, n);\n    dfs(grid, i + 1, j, m, n);\n    dfs(grid, i, j - 1, m, n);\n    dfs(grid, i, j + 1, m, n);\n}\n\nint main() {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n\n    char **grid = (char **)malloc(m * sizeof(char *));\n    for (int i = 0; i < m; i++) {\n        grid[i] = (char *)malloc((n + 1) * sizeof(char));\n        scanf(\"%s\", grid[i]);\n    }\n\n    int count = 0;\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            if (grid[i][j] == \'1\') {\n                count++;\n                dfs(grid, i, j, m, n);\n            }\n        }\n    }\n\n    printf(\"%d\\n\", count);\n\n    for (int i = 0; i < m; i++) {\n        free(grid[i]);\n    }\n    free(grid);\n\n    return 0;\n}',NULL,1,'2026-09-27 13:06:14','2026-09-28 15:16:03'),(240,40,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdbool.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nstatic TreeNode* newTreeNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nstatic TreeNode* buildTree(int* nums, int* isNull, int len) {\n    if (len == 0 || isNull[0]) return NULL;\n    TreeNode* root = newTreeNode(nums[0]);\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * len);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < len) {\n        TreeNode* node = queue[front++];\n        if (i < len) {\n            if (!isNull[i]) {\n                node->left = newTreeNode(nums[i]);\n                queue[rear++] = node->left;\n            }\n            i++;\n        }\n        if (i < len) {\n            if (!isNull[i]) {\n                node->right = newTreeNode(nums[i]);\n                queue[rear++] = node->right;\n            }\n            i++;\n        }\n    }\n    free(queue);\n    return root;\n}\n\nstatic bool check(TreeNode* left, TreeNode* right) {\n    if (left == NULL && right == NULL) return true;\n    if (left == NULL || right == NULL) return false;\n    if (left->val != right->val) return false;\n    return check(left->left, right->right) && check(left->right, right->left);\n}\n\nstatic bool isSymmetric(TreeNode* root) {\n    if (root == NULL) return true;\n    return check(root->left, root->right);\n}\n\nint main(void) {\n    char line[1000005];\n    if (fgets(line, sizeof(line), stdin) == NULL) {\n        printf(\"true\\n\");\n        return 0;\n    }\n    size_t len = strlen(line);\n    while (len > 0 && (line[len - 1] == \'\\n\' || line[len - 1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    if (len == 0) {\n        printf(\"true\\n\");\n        return 0;\n    }\n    if (line[0] == \'[\' && len >= 2 && line[len - 1] == \']\') {\n        memmove(line, line + 1, len - 2);\n        line[len - 2] = \'\\0\';\n        len -= 2;\n    }\n    bool empty = true;\n    for (size_t i = 0; i < len; i++) {\n        if (line[i] != \' \' && line[i] != \'\\t\') {\n            empty = false;\n            break;\n        }\n    }\n    if (empty) {\n        printf(\"true\\n\");\n        return 0;\n    }\n\n    int capacity = 16;\n    int* nums = (int*)malloc(sizeof(int) * capacity);\n    int* isNull = (int*)malloc(sizeof(int) * capacity);\n    int count = 0;\n\n    char* p = line;\n    while (*p) {\n        while (*p == \' \' || *p == \'\\t\') p++;\n        if (*p == \'\\0\') break;\n        char* start = p;\n        while (*p && *p != \',\') p++;\n        char* end = p;\n        while (end > start && (end[-1] == \' \' || end[-1] == \'\\t\')) end--;\n        if (end > start) {\n            if (count >= capacity) {\n                capacity *= 2;\n                nums = (int*)realloc(nums, sizeof(int) * capacity);\n                isNull = (int*)realloc(isNull, sizeof(int) * capacity);\n            }\n            if ((end - start) == 4 && strncmp(start, \"null\", 4) == 0) {\n                nums[count] = 0;\n                isNull[count] = 1;\n            } else {\n                char tmp[64];\n                int l = (int)(end - start);\n                if (l > 63) l = 63;\n                memcpy(tmp, start, l);\n                tmp[l] = \'\\0\';\n                nums[count] = atoi(tmp);\n                isNull[count] = 0;\n            }\n            count++;\n        }\n        if (*p == \',\') p++;\n    }\n\n    TreeNode* root = buildTree(nums, isNull, count);\n    printf(\"%s\\n\", isSymmetric(root) ? \"true\" : \"false\");\n\n    free(nums);\n    free(isNull);\n    return 0;\n}',NULL,1,'2026-09-27 13:06:14','2026-09-28 15:16:03'),(241,41,'PYTHON','import sys\n\ndef dfs(grid, i, j, m, n):\n    if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] != \'1\':\n        return\n    grid[i][j] = \'0\'\n    dfs(grid, i - 1, j, m, n)\n    dfs(grid, i + 1, j, m, n)\n    dfs(grid, i, j - 1, m, n)\n    dfs(grid, i, j + 1, m, n)\n\ndef main():\n    data = sys.stdin.read().splitlines()\n    if not data:\n        return\n    m, n = map(int, data[0].split())\n    grid = []\n    for i in range(1, m + 1):\n        grid.append(list(data[i].strip()))\n    count = 0\n    for i in range(m):\n        for j in range(n):\n            if grid[i][j] == \'1\':\n                count += 1\n                dfs(grid, i, j, m, n)\n    print(count)\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:06:15','2026-09-28 15:16:03'),(242,40,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(nums):\n    if not nums or nums[0] is None:\n        return None\n    root = TreeNode(nums[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(nums):\n        node = queue.popleft()\n        if i < len(nums):\n            if nums[i] is not None:\n                node.left = TreeNode(nums[i])\n                queue.append(node.left)\n            i += 1\n        if i < len(nums):\n            if nums[i] is not None:\n                node.right = TreeNode(nums[i])\n                queue.append(node.right)\n            i += 1\n    return root\n\ndef is_symmetric(root):\n    if root is None:\n        return True\n    return check(root.left, root.right)\n\ndef check(left, right):\n    if left is None and right is None:\n        return True\n    if left is None or right is None:\n        return False\n    if left.val != right.val:\n        return False\n    return check(left.left, right.right) and check(left.right, right.left)\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if not line:\n        print(\"true\")\n        return\n    line = line[1:-1]\n    if not line.strip():\n        print(\"true\")\n        return\n    parts = line.split(\",\")\n    nums = []\n    for s in parts:\n        s = s.strip()\n        if s == \"null\":\n            nums.append(None)\n        else:\n            nums.append(int(s))\n    root = build_tree(nums)\n    print(\"true\" if is_symmetric(root) else \"false\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:06:16','2026-09-28 15:16:03'),(243,41,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const [m, n] = lines[0].trim().split(/\\s+/).map(Number);\n    const grid = [];\n    for (let i = 0; i < m; i++) {\n        grid.push(lines[i + 1].trim().split(\'\'));\n    }\n\n    let count = 0;\n\n    function dfs(i, j) {\n        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] !== \'1\') {\n            return;\n        }\n        grid[i][j] = \'0\';\n        dfs(i - 1, j);\n        dfs(i + 1, j);\n        dfs(i, j - 1);\n        dfs(i, j + 1);\n    }\n\n    for (let i = 0; i < m; i++) {\n        for (let j = 0; j < n; j++) {\n            if (grid[i][j] === \'1\') {\n                count++;\n                dfs(i, j);\n            }\n        }\n    }\n\n    console.log(count);\n});',NULL,1,'2026-09-27 13:06:17','2026-09-28 15:16:03'),(244,43,'JAVA','import java.util.*;\n\npublic class Main {\n    static class Node {\n        public int val;\n        public List<Node> neighbors;\n        public Node() {\n            val = 0;\n            neighbors = new ArrayList<>();\n        }\n        public Node(int _val) {\n            val = _val;\n            neighbors = new ArrayList<>();\n        }\n        public Node(int _val, ArrayList<Node> _neighbors) {\n            val = _val;\n            neighbors = _neighbors;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        sc.nextLine();\n\n        Node[] nodes = new Node[n + 1];\n        for (int i = 1; i <= n; i++) {\n            nodes[i] = new Node(i);\n        }\n\n        for (int i = 1; i <= n; i++) {\n            String line = sc.nextLine().trim();\n            if (line.isEmpty()) continue;\n            String[] parts = line.split(\"\\\\s+\");\n            for (String p : parts) {\n                if (p.isEmpty()) continue;\n                int v = Integer.parseInt(p);\n                nodes[i].neighbors.add(nodes[v]);\n            }\n        }\n\n        Node cloned = cloneGraph(nodes[1]);\n\n        List<List<Integer>> result = new ArrayList<>();\n        for (int i = 1; i <= n; i++) {\n            List<Integer> list = new ArrayList<>();\n            for (Node nb : nodes[i].neighbors) {\n                list.add(nb.val);\n            }\n            result.add(list);\n        }\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            sb.append(\"[\");\n            List<Integer> list = result.get(i);\n            for (int j = 0; j < list.size(); j++) {\n                sb.append(list.get(j));\n                if (j < list.size() - 1) sb.append(\",\");\n            }\n            sb.append(\"]\");\n            if (i < result.size() - 1) sb.append(\",\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    public static Node cloneGraph(Node node) {\n        if (node == null) return null;\n        Map<Node, Node> map = new HashMap<>();\n        return dfs(node, map);\n    }\n\n    private static Node dfs(Node node, Map<Node, Node> map) {\n        if (map.containsKey(node)) return map.get(node);\n        Node copy = new Node(node.val);\n        map.put(node, copy);\n        for (Node nb : node.neighbors) {\n            copy.neighbors.add(dfs(nb, map));\n        }\n        return copy;\n    }\n}',NULL,1,'2026-09-27 13:06:17','2026-09-28 15:16:03'),(245,40,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line === \'\') {\n        console.log(\'true\');\n        rl.close();\n        return;\n    }\n    line = line.substring(1, line.length - 1);\n    if (line.trim() === \'\') {\n        console.log(\'true\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const nums = parts.map(s => {\n        s = s.trim();\n        return s === \'null\' ? null : parseInt(s, 10);\n    });\n    const root = buildTree(nums);\n    console.log(isSymmetric(root));\n    rl.close();\n});\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(nums) {\n    if (!nums || nums.length === 0 || nums[0] === null) return null;\n    const root = new TreeNode(nums[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < nums.length) {\n        const node = queue.shift();\n        if (i < nums.length) {\n            if (nums[i] !== null) {\n                node.left = new TreeNode(nums[i]);\n                queue.push(node.left);\n            }\n            i++;\n        }\n        if (i < nums.length) {\n            if (nums[i] !== null) {\n                node.right = new TreeNode(nums[i]);\n                queue.push(node.right);\n            }\n            i++;\n        }\n    }\n    return root;\n}\n\nfunction isSymmetric(root) {\n    if (root === null) return true;\n    return check(root.left, root.right);\n}\n\nfunction check(left, right) {\n    if (left === null && right === null) return true;\n    if (left === null || right === null) return false;\n    if (left.val !== right.val) return false;\n    return check(left.left, right.right) && check(left.right, right.left);\n}',NULL,1,'2026-09-27 13:06:19','2026-09-28 15:16:03'),(246,45,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] isConnected = new int[n][n];\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                isConnected[i][j] = sc.nextInt();\n            }\n        }\n        boolean[] visited = new boolean[n];\n        int provinces = 0;\n        for (int i = 0; i < n; i++) {\n            if (!visited[i]) {\n                dfs(isConnected, visited, i);\n                provinces++;\n            }\n        }\n        System.out.println(provinces);\n    }\n\n    private static void dfs(int[][] isConnected, boolean[] visited, int i) {\n        visited[i] = true;\n        for (int j = 0; j < isConnected.length; j++) {\n            if (isConnected[i][j] == 1 && !visited[j]) {\n                dfs(isConnected, visited, j);\n            }\n        }\n    }\n}',NULL,1,'2026-09-27 13:06:19','2026-09-28 15:16:03'),(247,43,'CPP','#include <iostream>\n#include <vector>\n#include <string>\n#include <sstream>\n#include <unordered_map>\n\nusing namespace std;\n\nstruct Node {\n    int val;\n    vector<Node*> neighbors;\n    Node() : val(0) {}\n    Node(int _val) : val(_val) {}\n    Node(int _val, vector<Node*> _neighbors) : val(_val), neighbors(_neighbors) {}\n};\n\nNode* dfs(Node* node, unordered_map<Node*, Node*>& mp) {\n    if (mp.count(node)) return mp[node];\n    Node* copy = new Node(node->val);\n    mp[node] = copy;\n    for (Node* nei : node->neighbors) {\n        copy->neighbors.push_back(dfs(nei, mp));\n    }\n    return copy;\n}\n\nNode* cloneGraph(Node* node) {\n    if (!node) return nullptr;\n    unordered_map<Node*, Node*> mp;\n    return dfs(node, mp);\n}\n\nint main() {\n    int n;\n    if (!(cin >> n)) return 0;\n    cin.ignore();\n    vector<Node*> nodes;\n    for (int i = 0; i < n; i++) {\n        nodes.push_back(new Node(i + 1));\n    }\n    for (int i = 0; i < n; i++) {\n        string line;\n        getline(cin, line);\n        if (line.empty()) continue;\n        istringstream iss(line);\n        int v;\n        while (iss >> v) {\n            nodes[i]->neighbors.push_back(nodes[v - 1]);\n        }\n    }\n    Node* cloned = cloneGraph(nodes[0]);\n    (void)cloned;\n    stringstream sb;\n    sb << \"[\";\n    for (int i = 0; i < n; i++) {\n        sb << \"[\";\n        vector<Node*>& nei = nodes[i]->neighbors;\n        for (size_t j = 0; j < nei.size(); j++) {\n            sb << nei[j]->val;\n            if (j + 1 < nei.size()) sb << \",\";\n        }\n        sb << \"]\";\n        if (i < n - 1) sb << \",\";\n    }\n    sb << \"]\";\n    cout << sb.str() << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:06:20','2026-09-28 15:16:03'),(248,96,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int target = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        Map<Integer, Integer> map = new HashMap<>();\n        for (int i = 0; i < n; i++) {\n            int complement = target - nums[i];\n            if (map.containsKey(complement)) {\n                System.out.println(\"[\" + map.get(complement) + \",\" + i + \"]\");\n                return;\n            }\n            map.put(nums[i], i);\n        }\n    }\n}',NULL,1,'2026-09-27 13:06:20','2026-09-28 15:16:03'),(249,45,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid dfs(const vector<vector<int>>& isConnected, vector<bool>& visited, int i) {\n    visited[i] = true;\n    for (int j = 0; j < (int)isConnected.size(); j++) {\n        if (isConnected[i][j] == 1 && !visited[j]) {\n            dfs(isConnected, visited, j);\n        }\n    }\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> isConnected(n, vector<int>(n));\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            cin >> isConnected[i][j];\n        }\n    }\n    vector<bool> visited(n, false);\n    int provinces = 0;\n    for (int i = 0; i < n; i++) {\n        if (!visited[i]) {\n            dfs(isConnected, visited, i);\n            provinces++;\n        }\n    }\n    cout << provinces << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:06:21','2026-09-28 15:16:03'),(250,96,'CPP','#include <iostream>\n#include <vector>\n#include <unordered_map>\nusing namespace std;\n\nint main() {\n    int n, target;\n    cin >> n >> target;\n    vector