    for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        List<List<Integer>> result = new ArrayList<>();\n        int total = 1 << n;\n        for (int mask = 0; mask < total; mask++) {\n            List<Integer> subset = new ArrayList<>();\n            for (int i = 0; i < n; i++) {\n                if ((mask & (1 << i)) != 0) {\n                    subset.add(nums[i]);\n                }\n            }\n            result.add(subset);\n        }\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"[\");\n            List<Integer> subset = result.get(i);\n            for (int j = 0; j < subset.size(); j++) {\n                if (j > 0) sb.append(\",\");\n                sb.append(subset.get(j));\n            }\n            sb.append(\"]\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1,'2026-09-27 13:06:44','2026-09-28 15:16:03'),(277,17,'CPP','#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    vector<vector<int>> result;\n    int total = 1 << n;\n    for (int mask = 0; mask < total; mask++) {\n        vector<int> subset;\n        for (int i = 0; i < n; i++) {\n            if ((mask & (1 << i)) != 0) {\n                subset.push_back(nums[i]);\n            }\n        }\n        result.push_back(subset);\n    }\n\n    string sb;\n    sb += \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        if (i > 0) sb += \",\";\n        sb += \"[\";\n        const vector<int>& subset = result[i];\n        for (int j = 0; j < (int)subset.size(); j++) {\n            if (j > 0) sb += \",\";\n            sb += to_string(subset[j]);\n        }\n        sb += \"]\";\n    }\n    sb += \"]\";\n    cout << sb << endl;\n\n    return 0;\n}',NULL,1,'2026-09-27 13:06:47','2026-09-28 15:16:03'),(280,17,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[20];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int total = 1 << n;\n    printf(\"[\");\n    for (int mask = 0; mask < total; mask++) {\n        if (mask > 0) printf(\",\");\n        printf(\"[\");\n        int first = 1;\n        for (int i = 0; i < n; i++) {\n            if (mask & (1 << i)) {\n                if (!first) printf(\",\");\n                printf(\"%d\", nums[i]);\n                first = 0;\n            }\n        }\n        printf(\"]\");\n    }\n    printf(\"]\\n\");\n    return 0;\n}',NULL,1,'2026-09-27 13:06:49','2026-09-28 15:16:03'),(283,17,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\n\nresult = []\ntotal = 1 << n\nfor mask in range(total):\n    subset = []\n    for i in range(n):\n        if mask & (1 << i):\n            subset.append(nums[i])\n    result.append(subset)\n\nsb = []\nsb.append(\"[\")\nfor i in range(len(result)):\n    if i > 0:\n        sb.append(\",\")\n    sb.append(\"[\")\n    subset = result[i]\n    for j in range(len(subset)):\n        if j > 0:\n            sb.append(\",\")\n        sb.append(str(subset[j]))\n    sb.append(\"]\")\nsb.append(\"]\")\nprint(\"\".join(sb))',NULL,1,'2026-09-27 13:06:51','2026-09-28 15:16:03'),(286,17,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(input[0]);\n    const nums = input[1].split(\' \').map(Number);\n\n    const result = [];\n    const total = 1 << n;\n    for (let mask = 0; mask < total; mask++) {\n        const subset = [];\n        for (let i = 0; i < n; i++) {\n            if ((mask & (1 << i)) !== 0) {\n                subset.push(nums[i]);\n            }\n        }\n        result.push(subset);\n    }\n\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < result.length; i++) {\n        if (i > 0) sb += \',\';\n        sb += \'[\';\n        const subset = result[i];\n        for (let j = 0; j < subset.length; j++) {\n            if (j > 0) sb += \',\';\n            sb += subset[j];\n        }\n        sb += \']\';\n    }\n    sb += \']\';\n    console.log(sb);\n});',NULL,1,'2026-09-27 13:06:53','2026-09-28 15:16:03'),(293,39,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) {\n            line = line.substring(1, line.length() - 1);\n        }\n        if (line.isEmpty()) {\n            System.out.println(\"[]\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        Integer[] nums = new Integer[parts.length];\n        for (int i = 0; i < parts.length; i++) {\n            String s = parts[i].trim();\n            if (s.equals(\"null\")) {\n                nums[i] = null;\n            } else {\n                nums[i] = Integer.parseInt(s);\n            }\n        }\n        TreeNode root = buildTree(nums);\n        List<Integer> res = inorderTraversal(root);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(res.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    private static TreeNode buildTree(Integer[] nums) {\n        if (nums == null || nums.length == 0 || nums[0] == null) return null;\n        TreeNode root = new TreeNode(nums[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < nums.length) {\n            TreeNode node = queue.poll();\n            if (i < nums.length && nums[i] != null) {\n                node.left = new TreeNode(nums[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < nums.length && nums[i] != null) {\n                node.right = new TreeNode(nums[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    private static List<Integer> inorderTraversal(TreeNode root) {\n        List<Integer> res = new ArrayList<>();\n        Deque<TreeNode> stack = new ArrayDeque<>();\n        TreeNode cur = root;\n        while (cur != null || !stack.isEmpty()) {\n            while (cur != null) {\n                stack.push(cur);\n                cur = cur.left;\n            }\n            cur = stack.pop();\n            res.add(cur.val);\n            cur = cur.right;\n        }\n        return res;\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) {\n            this.val = val;\n        }\n    }\n}',NULL,1,'2026-09-27 13:06:59','2026-09-28 15:16:03'),(297,39,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <stack>\n#include <sstream>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const vector<string>& nums) {\n    if (nums.empty() || nums[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(nums[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)nums.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->left = new TreeNode(stoi(nums[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->right = new TreeNode(stoi(nums[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nvector<int> inorderTraversal(TreeNode* root) {\n    vector<int> res;\n    stack<TreeNode*> st;\n    TreeNode* cur = root;\n    while (cur != nullptr || !st.empty()) {\n        while (cur != nullptr) {\n            st.push(cur);\n            cur = cur->left;\n        }\n        cur = st.top();\n        st.pop();\n        res.push_back(cur->val);\n        cur = cur->right;\n    }\n    return res;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\' || line.back() == \' \')) {\n        line.pop_back();\n    }\n    if (!line.empty() && line.front() == \'[\') {\n        line = line.substr(1, line.size() - 2);\n    }\n    if (line.empty()) {\n        cout << \"[]\" << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\");\n        size_t end = token.find_last_not_of(\" \\t\");\n        if (start == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(token.substr(start, end - start + 1));\n        }\n    }\n    TreeNode* root = buildTree(parts);\n    vector<int> res = inorderTraversal(root);\n    cout << \"[\";\n    for (size_t i = 0; i < res.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << res[i];\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:07:02','2026-09-28 15:16:03'),(299,39,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nTreeNode* createNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nTreeNode* buildTree(int* nums, int* isNull, int len) {\n    if (len == 0 || isNull[0]) return NULL;\n    TreeNode* root = createNode(nums[0]);\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * len);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < len) {\n        TreeNode* node = queue[front++];\n        if (i < len && !isNull[i]) {\n            node->left = createNode(nums[i]);\n            queue[rear++] = node->left;\n        }\n        i++;\n        if (i < len && !isNull[i]) {\n            node->right = createNode(nums[i]);\n            queue[rear++] = node->right;\n        }\n        i++;\n    }\n    free(queue);\n    return root;\n}\n\nint* inorderTraversal(TreeNode* root, int* returnSize) {\n    int* res = (int*)malloc(sizeof(int) * 10000);\n    TreeNode** stack = (TreeNode**)malloc(sizeof(TreeNode*) * 10000);\n    int top = 0;\n    int count = 0;\n    TreeNode* cur = root;\n    while (cur != NULL || top > 0) {\n        while (cur != NULL) {\n            stack[top++] = cur;\n            cur = cur->left;\n        }\n        cur = stack[--top];\n        res[count++] = cur->val;\n        cur = cur->right;\n    }\n    free(stack);\n    *returnSize = count;\n    return res;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    char* p = line;\n    while (*p == \' \' || *p == \'\\t\') p++;\n    if (*p == \'[\') {\n        p++;\n        char* end = strrchr(p, \']\');\n        if (end) *end = \'\\0\';\n    }\n    if (*p == \'\\0\') {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    int nums[10000];\n    int isNull[10000];\n    int n = 0;\n    char* token = strtok(p, \",\");\n    while (token != NULL) {\n        while (*token == \' \' || *token == \'\\t\') token++;\n        char* e = token + strlen(token) - 1;\n        while (e > token && (*e == \' \' || *e == \'\\t\')) *e-- = \'\\0\';\n        if (strcmp(token, \"null\") == 0) {\n            isNull[n] = 1;\n            nums[n] = 0;\n        } else {\n            isNull[n] = 0;\n            nums[n] = atoi(token);\n        }\n        n++;\n        token = strtok(NULL, \",\");\n    }\n    TreeNode* root = buildTree(nums, isNull, n);\n    int returnSize = 0;\n    int* res = inorderTraversal(root, &returnSize);\n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", res[i]);\n    }\n    printf(\"]\\n\");\n    free(res);\n    return 0;\n}',NULL,1,'2026-09-27 13:07:06','2026-09-28 15:16:03'),(300,43,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct Node {\n    int val;\n    struct Node** neighbors;\n    int neighborCount;\n    int capacity;\n} Node;\n\nNode* createNode(int val) {\n    Node* node = (Node*)malloc(sizeof(Node));\n    node->val = val;\n    node->neighborCount = 0;\n    node->capacity = 4;\n    node->neighbors = (Node**)malloc(sizeof(Node*) * node->capacity);\n    return node;\n}\n\nvoid addNeighbor(Node* node, Node* neighbor) {\n    if (node->neighborCount >= node->capacity) {\n        node->capacity *= 2;\n        node->neighbors = (Node**)realloc(node->neighbors, sizeof(Node*) * node->capacity);\n    }\n    node->neighbors[node->neighborCount++] = neighbor;\n}\n\nNode* dfs(Node* node, Node** map, int n) {\n    if (node == NULL) return NULL;\n    if (map[node->val] != NULL) return map[node->val];\n    Node* copy = createNode(node->val);\n    map[node->val] = copy;\n    for (int i = 0; i < node->neighborCount; i++) {\n        addNeighbor(copy, dfs(node->neighbors[i], map, n));\n    }\n    return copy;\n}\n\nNode* cloneGraph(Node* node, int n) {\n    if (node == NULL) return NULL;\n    Node** map = (Node**)calloc(n + 1, sizeof(Node*));\n    Node* result = dfs(node, map, n);\n    free(map);\n    return result;\n}\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n    int c;\n    while ((c = getchar()) != \'\\n\' && c != EOF);\n\n    Node** nodes = (Node**)malloc(sizeof(Node*) * (n + 1));\n    for (int i = 1; i <= n; i++) {\n        nodes[i] = createNode(i);\n    }\n\n    char line[100000];\n    for (int i = 1; i <= n; i++) {\n        if (fgets(line, sizeof(line), stdin) == NULL) break;\n        char* p = line;\n        while (*p) {\n            while (*p == \' \' || *p == \'\\t\' || *p == \'\\n\' || *p == \'\\r\') p++;\n            if (*p == \'\\0\') break;\n            int v = 0;\n            while (*p >= \'0\' && *p <= \'9\') {\n                v = v * 10 + (*p - \'0\');\n                p++;\n            }\n            if (v >= 1 && v <= n) {\n                addNeighbor(nodes[i], nodes[v]);\n            }\n        }\n    }\n\n    Node* cloned = cloneGraph(nodes[1], n);\n\n    printf(\"[\");\n    for (int i = 1; i <= n; i++) {\n        printf(\"[\");\n        for (int j = 0; j < nodes[i]->neighborCount; j++) {\n            printf(\"%d\", nodes[i]->neighbors[j]->val);\n            if (j < nodes[i]->neighborCount - 1) printf(\",\");\n        }\n        printf(\"]\");\n        if (i < n) printf(\",\");\n    }\n    printf(\"]\\n\");\n\n    return 0;\n}',NULL,1,'2026-09-27 13:07:06','2026-09-28 15:16:03'),(301,39,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(nums):\n    if not nums or nums[0] is None:\n        return None\n    root = TreeNode(nums[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(nums):\n        node = queue.popleft()\n        if i < len(nums) and nums[i] is not None:\n            node.left = TreeNode(nums[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(nums) and nums[i] is not None:\n            node.right = TreeNode(nums[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef inorder_traversal(root):\n    res = []\n    stack = []\n    cur = root\n    while cur or stack:\n        while cur:\n            stack.append(cur)\n            cur = cur.left\n        cur = stack.pop()\n        res.append(cur.val)\n        cur = cur.right\n    return res\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:-1]\n    if not line:\n        print(\"[]\")\n        return\n    parts = line.split(\",\")\n    nums = []\n    for s in parts:\n        s = s.strip()\n        if s == \"null\":\n            nums.append(None)\n        else:\n            nums.append(int(s))\n    root = build_tree(nums)\n    res = inorder_traversal(root)\n    print(\"[\" + \",\".join(str(x) for x in res) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:07:08','2026-09-28 15:16:03'),(302,43,'PYTHON','import sys\n\nclass Node:\n    def __init__(self, val=0, neighbors=None):\n        self.val = val\n        self.neighbors = neighbors if neighbors is not None else []\n\ndef clone_graph(node, visited):\n    if node is None:\n        return None\n    if node in visited:\n        return visited[node]\n    copy = Node(node.val)\n    visited[node] = copy\n    for nb in node.neighbors:\n        copy.neighbors.append(clone_graph(nb, visited))\n    return copy\n\ndef main():\n    data = sys.stdin.read().splitlines()\n    if not data:\n        return\n    n = int(data[0].strip())\n    nodes = [None] + [Node(i) for i in range(1, n + 1)]\n    for i in range(1, n + 1):\n        if i >= len(data):\n            break\n        line = data[i].strip()\n        if not line:\n            continue\n        for p in line.split():\n            v = int(p)\n            nodes[i].neighbors.append(nodes[v])\n    clone_graph(nodes[1], {})\n    result = []\n    for i in range(1, n + 1):\n        result.append([nb.val for nb in nodes[i].neighbors])\n    out = \"[\" + \",\".join(\"[\" + \",\".join(map(str, lst)) + \"]\" for lst in result) + \"]\"\n    print(out)\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:07:08','2026-09-28 15:16:03'),(303,39,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.startsWith(\'[\')) {\n        line = line.substring(1, line.length - 1);\n    }\n    if (line.length === 0) {\n        console.log(\'[]\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const nums = parts.map(s => {\n        s = s.trim();\n        return s === \'null\' ? null : parseInt(s, 10);\n    });\n    const root = buildTree(nums);\n    const res = inorderTraversal(root);\n    console.log(\'[\' + res.join(\',\') + \']\');\n    rl.close();\n});\n\nfunction buildTree(nums) {\n    if (!nums || nums.length === 0 || nums[0] === null) return null;\n    const root = new TreeNode(nums[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < nums.length) {\n        const node = queue.shift();\n        if (i < nums.length && nums[i] !== null) {\n            node.left = new TreeNode(nums[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < nums.length && nums[i] !== null) {\n            node.right = new TreeNode(nums[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction inorderTraversal(root) {\n    const res = [];\n    const stack = [];\n    let cur = root;\n    while (cur !== null || stack.length > 0) {\n        while (cur !== null) {\n            stack.push(cur);\n            cur = cur.left;\n        }\n        cur = stack.pop();\n        res.push(cur.val);\n        cur = cur.right;\n    }\n    return res;\n}\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}',NULL,1,'2026-09-27 13:07:10','2026-09-28 15:16:03'),(304,43,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass Node {\n    constructor(val = 0, neighbors = []) {\n        this.val = val;\n        this.neighbors = neighbors;\n    }\n}\n\nfunction cloneGraph(node) {\n    if (node === null) return null;\n    const map = new Map();\n    return dfs(node, map);\n}\n\nfunction dfs(node, map) {\n    if (map.has(node)) return map.get(node);\n    const copy = new Node(node.val);\n    map.set(node, copy);\n    for (const nb of node.neighbors) {\n        copy.neighbors.push(dfs(nb, map));\n    }\n    return copy;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    if (lines.length === 0) return;\n    let idx = 0;\n    const n = parseInt(lines[idx++].trim());\n    const nodes = new Array(n + 1);\n    for (let i = 1; i <= n; i++) {\n        nodes[i] = new Node(i);\n    }\n    for (let i = 1; i <= n; i++) {\n        const line = (lines[idx++] || \'\').trim();\n        if (line === \'\') continue;\n        const parts = line.split(/\\s+/);\n        for (const p of parts) {\n            if (p === \'\') continue;\n            const v = parseInt(p);\n            nodes[i].neighbors.push(nodes[v]);\n        }\n    }\n\n    cloneGraph(nodes[1]);\n\n    const result = [];\n    for (let i = 1; i <= n; i++) {\n        const list = [];\n        for (const nb of nodes[i].neighbors) {\n            list.push(nb.val);\n        }\n        result.push(list);\n    }\n\n    let sb = \'[\';\n    for (let i = 0; i < result.length; i++) {\n        sb += \'[\';\n        const list = result[i];\n        for (let j = 0; j < list.length; j++) {\n            sb += list[j];\n            if (j < list.length - 1) sb += \',\';\n        }\n        sb += \']\';\n        if (i < result.length - 1) sb += \',\';\n    }\n    sb += \']\';\n    console.log(sb);\n});',NULL,1,'2026-09-27 13:07:10','2026-09-28 15:16:03'),(307,97,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        if (scanner.hasNextLine()) {\n            String s = scanner.nextLine();\n            System.out.println(lengthOfLongestSubstring(s));\n        }\n    }\n\n    public static int lengthOfLongestSubstring(String s) {\n        int[] last = new int[128];\n        for (int i = 0; i < 128; i++) {\n            last[i] = -1;\n        }\n        int maxLen = 0;\n        int left = 0;\n        for (int right = 0; right < s.length(); right++) {\n            char c = s.charAt(right);\n            if (last[c] >= left) {\n                left = last[c] + 1;\n            }\n            last[c] = right;\n            maxLen = Math.max(maxLen, right - left + 1);\n        }\n        return maxLen;\n    }\n}',NULL,1,'2026-09-27 13:07:13','2026-09-28 15:16:03'),(308,45,'C','#include <stdio.h>\n#include <stdlib.h>\n\nvoid dfs(int **isConnected, int *visited, int n, int i) {\n    visited[i] = 1;\n    for (int j = 0; j < n; j++) {\n        if (isConnected[i][j] == 1 && !visited[j]) {\n            dfs(isConnected, visited, n, j);\n        }\n    }\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n\n    int **isConnected = (int **)malloc(n * sizeof(int *));\n    for (int i = 0; i < n; i++) {\n        isConnected[i] = (int *)malloc(n * sizeof(int));\n        for (int j = 0; j < n; j++) {\n            scanf(\"%d\", &isConnected[i][j]);\n        }\n    }\n\n    int *visited = (int *)calloc(n, sizeof(int));\n    int provinces = 0;\n\n    for (int i = 0; i < n; i++) {\n        if (!visited[i]) {\n            dfs(isConnected, visited, n, i);\n            provinces++;\n        }\n    }\n\n    printf(\"%d\\n\", provinces);\n\n    for (int i = 0; i < n; i++) {\n        free(isConnected[i]);\n    }\n    free(isConnected);\n    free(visited);\n\n    return 0;\n}',NULL,1,'2026-09-27 13:07:13','2026-09-28 15:16:03'),(309,96,'C','#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int key;\n    int value;\n} Entry;\n\nint main() {\n    int n, target;\n    scanf(\"%d %d\", &n, &target);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    Entry *map = (Entry *)malloc(n * sizeof(Entry));\n    int size = 0;\n\n    for (int i = 0; i < n; i++) {\n        int complement = target - nums[i];\n        for (int j = 0; j < size; j++) {\n            if (map[j].key == complement) {\n                printf(\"[%d,%d]\\n\", map[j].value, i);\n                free(nums);\n                free(map);\n                return 0;\n            }\n        }\n        map[size].key = nums[i];\n        map[size].value = i;\n        size++;\n    }\n\n    free(nums);\n    free(map);\n    return 0;\n}',NULL,1,'2026-09-27 13:07:14','2026-09-28 15:16:03'),(310,45,'PYTHON','import sys\n\ndef dfs(isConnected, visited, i):\n    visited[i] = True\n    for j in range(len(isConnected)):\n        if isConnected[i][j] == 1 and not visited[j]:\n            dfs(isConnected, visited, j)\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    isConnected = []\n    idx = 1\n    for i in range(n):\n        row = []\n        for j in range(n):\n            row.append(int(data[idx]))\n            idx += 1\n        isConnected.append(row)\n    visited = [False] * n\n    provinces = 0\n    for i in range(n):\n        if not visited[i]:\n            dfs(isConnected, visited, i)\n            provinces += 1\n    print(provinces)\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:07:14','2026-09-28 15:16:03'),(311,97,'CPP','#include <iostream>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nint lengthOfLongestSubstring(const string& s) {\n    int last[128];\n    for (int i = 0; i < 128; i++) {\n        last[i] = -1;\n    }\n    int maxLen = 0;\n    int left = 0;\n    for (int right = 0; right < (int)s.length(); right++) {\n        char c = s[right];\n        if (last[(int)c] >= left) {\n            left = last[(int)c] + 1;\n        }\n        last[(int)c] = right;\n        maxLen = max(maxLen, right - left + 1);\n    }\n    return maxLen;\n}\n\nint main() {\n    string s;\n    if (getline(cin, s)) {\n        cout << lengthOfLongestSubstring(s) << endl;\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:07:15','2026-09-28 15:16:03'),(312,96,'PYTHON','n, target = map(int, input().split())\nnums = list(map(int, input().split()))\nseen = {}\nfor i, num in enumerate(nums):\n    complement = target - num\n    if complement in seen:\n        print(f\"[{seen[complement]},{i}]\")\n        break\n    seen[num] = i',NULL,1,'2026-09-27 13:07:15','2026-09-28 15:16:03'),(313,45,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const n = parseInt(lines[idx++]);\n    const isConnected = [];\n    for (let i = 0; i < n; i++) {\n        isConnected.push(lines[idx++].split(/\\s+/).map(Number));\n    }\n    const visited = new Array(n).fill(false);\n    let provinces = 0;\n\n    function dfs(i) {\n        visited[i] = true;\n        for (let j = 0; j < n; j++) {\n            if (isConnected[i][j] === 1 && !visited[j]) {\n                dfs(j);\n            }\n        }\n    }\n\n    for (let i = 0; i < n; i++) {\n        if (!visited[i]) {\n            dfs(i);\n            provinces++;\n        }\n    }\n\n    console.log(provinces);\n});',NULL,1,'2026-09-27 13:07:16','2026-09-28 15:16:03'),(314,96,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n  input: process.stdin,\n  output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n  lines.push(line.trim());\n  if (lines.length === 2) {\n    const [n, target] = lines[0].split(\' \').map(Number);\n    const nums = lines[1].split(\' \').map(Number);\n    const map = new Map();\n    for (let i = 0; i < n; i++) {\n      const complement = target - nums[i];\n      if (map.has(complement)) {\n        console.log(`[${map.get(complement)},${i}]`);\n        rl.close();\n        return;\n      }\n      map.set(nums[i], i);\n    }\n    rl.close();\n  }\n});',NULL,1,'2026-09-27 13:07:16','2026-09-28 15:16:03'),(315,97,'C','#include <stdio.h>\n#include <string.h>\n\nint lengthOfLongestSubstring(char *s) {\n    int last[128];\n    for (int i = 0; i < 128; i++) {\n        last[i] = -1;\n    }\n    int maxLen = 0;\n    int left = 0;\n    int len = strlen(s);\n    for (int right = 0; right < len; right++) {\n        unsigned char c = (unsigned char)s[right];\n        if (last[c] >= left) {\n            left = last[c] + 1;\n        }\n        last[c] = right;\n        int curLen = right - left + 1;\n        if (curLen > maxLen) {\n            maxLen = curLen;\n        }\n    }\n    return maxLen;\n}\n\nint main() {\n    char s[1000000];\n    if (fgets(s, sizeof(s), stdin) != NULL) {\n        size_t len = strlen(s);\n        if (len > 0 && s[len - 1] == \'\\n\') {\n            s[len - 1] = \'\\0\';\n        }\n        printf(\"%d\\n\", lengthOfLongestSubstring(s));\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:07:17','2026-09-28 15:16:03'),(316,97,'PYTHON','import sys\n\ndef lengthOfLongestSubstring(s):\n    last = [-1] * 128\n    maxLen = 0\n    left = 0\n    for right, c in enumerate(s):\n        code = ord(c)\n        if last[code] >= left:\n            left = last[code] + 1\n        last[code] = right\n        maxLen = max(maxLen, right - left + 1)\n    return maxLen\n\nif __name__ == \"__main__\":\n    s = sys.stdin.readline().rstrip(\'\\n\')\n    print(lengthOfLongestSubstring(s))',NULL,1,'2026-09-27 13:07:18','2026-09-28 15:16:03'),(317,99,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static ListNode reverseList(ListNode head) {\n        ListNode prev = null;\n        ListNode curr = head;\n        while (curr != null) {\n            ListNode nextTemp = curr.next;\n            curr.next = prev;\n            prev = curr;\n            curr = nextTemp;\n        }\n        return prev;\n    }\n\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        String input = scanner.nextLine().trim();\n        String[] parts = input.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode tail = dummy;\n        for (String part : parts) {\n            if (part.equals(\"NULL\")) {\n                break;\n            }\n            int val = Integer.parseInt(part);\n            tail.next = new ListNode(val);\n            tail = tail.next;\n        }\n\n        ListNode reversed = reverseList(dummy.next);\n\n        StringBuilder sb = new StringBuilder();\n        ListNode curr = reversed;\n        while (curr != null) {\n            sb.append(curr.val).append(\"->\");\n            curr = curr.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1,'2026-09-27 13:07:19','2026-09-28 15:16:03'),(318,98,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextLine()) return;\n        String s = sc.nextLine();\n        if (s == null || s.length() == 0) {\n            System.out.println(\"\");\n            return;\n        }\n        int start = 0, end = 0;\n        for (int i = 0; i < s.length(); i++) {\n            int len1 = expand(s, i, i);\n            int len2 = expand(s, i, i + 1);\n            int len = Math.max(len1, len2);\n            if (len > end - start + 1) {\n                start = i - (len - 1) / 2;\n                end = i + len / 2;\n            }\n        }\n        System.out.println(s.substring(start, end + 1));\n    }\n\n    private static int expand(String s, int left, int right) {\n        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {\n            left--;\n            right++;\n        }\n        return right - left - 1;\n    }\n}',NULL,1,'2026-09-27 13:07:19','2026-09-28 15:16:03'),(319,97,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    console.log(lengthOfLongestSubstring(s));\n    rl.close();\n});\n\nfunction lengthOfLongestSubstring(s) {\n    const last = new Array(128).fill(-1);\n    let maxLen = 0;\n    let left = 0;\n    for (let right = 0; right < s.length; right++) {\n        const c = s.charCodeAt(right);\n        if (last[c] >= left) {\n            left = last[c] + 1;\n        }\n        last[c] = right;\n        maxLen = Math.max(maxLen, right - left + 1);\n    }\n    return maxLen;\n}',NULL,1,'2026-09-27 13:07:20','2026-09-28 15:16:03'),(320,98,'CPP','#include <iostream>\n#include <string>\nusing namespace std;\n\nint expand(const string& s, int left, int right) {\n    while (left >= 0 && right < (int)s.length() && s[left] == s[right]) {\n        left--;\n        right++;\n    }\n    return right - left - 1;\n}\n\nint main() {\n    string s;\n    if (!getline(cin, s)) return 0;\n    if (s.empty()) {\n        cout << \"\" << endl;\n        return 0;\n    }\n    int start = 0, end = 0;\n    for (int i = 0; i < (int)s.length(); i++) {\n        int len1 = expand(s, i, i);\n        int len2 = expand(s, i, i + 1);\n        int len = max(len1, len2);\n        if (len > end - start + 1) {\n            start = i - (len - 1) / 2;\n            end = i + len / 2;\n        }\n    }\n    cout << s.substr(start, end - start + 1) << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:07:22','2026-09-28 15:16:03'),(321,100,'JAVA','import java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        String line1 = br.readLine();\n        String line2 = br.readLine();\n\n        ListNode l1 = parseList(line1);\n        ListNode l2 = parseList(line2);\n\n        ListNode merged = mergeTwoLists(l1, l2);\n\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = merged;\n        while (cur != null) {\n            sb.append(cur.val);\n            if (cur.next != null) {\n                sb.append(\"->\");\n            }\n            cur = cur.next;\n        }\n        System.out.println(sb.toString());\n    }\n\n    private static ListNode parseList(String line) {\n        if (line == null) return null;\n        line = line.trim();\n        if (line.isEmpty() || line.equals(\"NULL\")) return null;\n\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String part : parts) {\n            part = part.trim();\n            if (part.equals(\"NULL\")) break;\n            cur.next = new ListNode(Integer.parseInt(part));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    private static ListNode mergeTwoLists(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        while (l1 != null && l2 != null) {\n            if (l1.val <= l2.val) {\n                cur.next = l1;\n                l1 = l1.next;\n            } else {\n                cur.next = l2;\n                l2 = l2.next;\n            }\n            cur = cur.next;\n        }\n        if (l1 != null) cur.next = l1;\n        if (l2 != null) cur.next = l2;\n        return dummy.next;\n    }\n}',NULL,1,'2026-09-27 13:07:22','2026-09-28 15:16:03'),(322,101,'JAVA','import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    static class LRUCache {\n        class Node {\n            int key, value;\n            Node prev, next;\n            Node(int k, int v) {\n                key = k;\n                value = v;\n            }\n        }\n\n        private int capacity;\n        private Map<Integer, Node> map;\n        private Node head, tail;\n\n        public LRUCache(int capacity) {\n            this.capacity = capacity;\n            this.map = new HashMap<>();\n            head = new Node(-1, -1);\n            tail = new Node(-1, -1);\n            head.next = tail;\n            tail.prev = head;\n        }\n\n        public int get(int key) {\n            Node node = map.get(key);\n            if (node == null) return -1;\n            moveToHead(node);\n            return node.value;\n        }\n\n        public void put(int key, int value) {\n            Node node = map.get(key);\n            if (node != null) {\n                node.value = value;\n                moveToHead(node);\n            } else {\n                if (map.size() == capacity) {\n                    Node removed = removeTail();\n                    map.remove(removed.key);\n                }\n                Node newNode = new Node(key, value);\n                map.put(key, newNode);\n                addToHead(newNode);\n            }\n        }\n\n        private void addToHead(Node node) {\n            node.prev = head;\n            node.next = head.next;\n            head.next.prev = node;\n            head.next = node;\n        }\n\n        private void removeNode(Node node) {\n            node.prev.next = node.next;\n            node.next.prev = node.prev;\n        }\n\n        private void moveToHead(Node node) {\n            removeNode(node);\n            addToHead(node);\n        }\n\n        private Node removeTail() {\n            Node node = tail.prev;\n            removeNode(node);\n            return node;\n        }\n    }\n\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int capacity = Integer.parseInt(br.readLine().trim());\n        int m = Integer.parseInt(br.readLine().trim());\n        LRUCache cache = new LRUCache(capacity);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < m; i++) {\n            String line = br.readLine().trim();\n            if (line.isEmpty()) continue;\n            String[] parts = line.split(\"\\\\s+\");\n            if (parts[0].equals(\"put\")) {\n                int key = Integer.parseInt(parts[1]);\n                int value = Integer.parseInt(parts[2]);\n                cache.put(key, value);\n            } else if (parts[0].equals(\"get\")) {\n                int key = Integer.parseInt(parts[1]);\n                sb.append(cache.get(key)).append(\'\\n\');\n            }\n        }\n        System.out.print(sb);\n    }\n}',NULL,1,'2026-09-27 13:07:23','2026-09-28 15:16:03'),(323,98,'C','#include <stdio.h>\n#include <string.h>\n\nint expand(char *s, int left, int right, int n) {\n    while (left >= 0 && right < n && s[left] == s[right]) {\n        left--;\n        right++;\n    }\n    return right - left - 1;\n}\n\nint main() {\n    char s[100000];\n    if (!fgets(s, sizeof(s), stdin)) return 0;\n    int n = strlen(s);\n    if (n > 0 && s[n - 1] == \'\\n\') {\n        s[n - 1] = \'\\0\';\n        n--;\n    }\n    if (n == 0) {\n        printf(\"\\n\");\n        return 0;\n    }\n    int start = 0, end = 0;\n    for (int i = 0; i < n; i++) {\n        int len1 = expand(s, i, i, n);\n        int len2 = expand(s, i, i + 1, n);\n        int len = len1 > len2 ? len1 : len2;\n        if (len > end - start + 1) {\n            start = i - (len - 1) / 2;\n            end = i + len / 2;\n        }\n    }\n    for (int i = start; i <= end; i++) {\n        putchar(s[i]);\n    }\n    putchar(\'\\n\');\n    return 0;\n}',NULL,1,'2026-09-27 13:07:24','2026-09-28 15:16:03'),(324,98,'PYTHON','import sys\n\ndef expand(s, left, right):\n    while left >= 0 and right < len(s) and s[left] == s[right]:\n        left -= 1\n        right += 1\n    return right - left - 1\n\ndef main():\n    s = sys.stdin.readline().rstrip(\'\\n\')\n    if not s:\n        print(\"\")\n        return\n    start, end = 0, 0\n    for i in range(len(s)):\n        len1 = expand(s, i, i)\n        len2 = expand(s, i, i + 1)\n        length = max(len1, len2)\n        if length > end - start + 1:\n            start = i - (length - 1) // 2\n            end = i + length // 2\n    print(s[start:end + 1])\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:07:25','2026-09-28 15:16:03'),(325,101,'CPP','#include <bits/stdc++.h>\nusing namespace std;\n\nclass LRUCache {\nprivate:\n    struct Node {\n        int key, value;\n        Node *prev, *next;\n        Node(int k, int v) : key(k), value(v), prev(nullptr), next(nullptr) {}\n    };\n\n    int capacity;\n    unordered_map<int, Node*> mp;\n    Node *head, *tail;\n\n    void addToHead(Node* node) {\n        node->prev = head;\n        node->next = head->next;\n        head->next->prev = node;\n        head->next = node;\n    }\n\n    void removeNode(Node* node) {\n        node->prev->next = node->next;\n        node->next->prev = node->prev;\n    }\n\n    void moveToHead(Node* node) {\n        removeNode(node);\n        addToHead(node);\n    }\n\n    Node* removeTail() {\n        Node* node = tail->prev;\n        removeNode(node);\n        return node;\n    }\n\npublic:\n    LRUCache(int capacity) : capacity(capacity) {\n        head = new Node(-1, -1);\n        tail = new Node(-1, -1);\n        head->next = tail;\n        tail->prev = head;\n    }\n\n    int get(int key) {\n        auto it = mp.find(key);\n        if (it == mp.end()) return -1;\n        Node* node = it->second;\n        moveToHead(node);\n        return node->value;\n    }\n\n    void put(int key, int value) {\n        auto it = mp.find(key);\n        if (it != mp.end()) {\n            Node* node = it->second;\n            node->value = value;\n            moveToHead(node);\n        } else {\n            if ((int)mp.size() == capacity) {\n                Node* removed = removeTail();\n                mp.erase(removed->key);\n                delete removed;\n            }\n            Node* newNode = new Node(key, value);\n            mp[key] = newNode;\n            addToHead(newNode);\n        }\n    }\n};\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int capacity;\n    cin >> capacity;\n    int m;\n    cin >> m;\n\n    LRUCache cache(capacity);\n    string op;\n    while (m--) {\n        cin >> op;\n        if (op == \"put\") {\n            int key, value;\n            cin >> key >> value;\n            cache.put(key, value);\n        } else if (op == \"get\") {\n            int key;\n            cin >> key;\n            cout << cache.get(key) << \'\\n\';\n        }\n    }\n\n    return 0;\n}',NULL,1,'2026-09-27 13:07:26','2026-09-28 15:16:03'),(326,100,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int val) : val(val), next(nullptr) {}\n};\n\nListNode* parseList(const std::string& line) {\n    if (line.empty()) {\n        return nullptr;\n    }\n    std::string s = line;\n    // trim\n    size_t start = s.find_first_not_of(\" \\t\\r\\n\");\n    if (start == std::string::npos) return nullptr;\n    size_t end = s.find_last_not_of(\" \\t\\r\\n\");\n    s = s.substr(start, end - start + 1);\n\n    if (s.empty() || s == \"NULL\") {\n        return nullptr;\n    }\n    if (s.size() >= 6 && s.substr(s.size() - 6) == \"->NULL\") {\n        s = s.substr(0, s.size() - 6);\n    } else if (s.size() >= 4 && s.substr(s.size() - 4) == \"NULL\") {\n        s = s.substr(0, s.size() - 4);\n        if (s.size() >= 2 && s.substr(s.size() - 2) == \"->\") {\n            s = s.substr(0, s.size() - 2);\n        }\n    }\n    if (s.empty()) {\n        return nullptr;\n    }\n\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    std::stringstream ss(s);\n    std::string part;\n    while (std::getline(ss, part, \'-\')) {\n        // getline with \'-\' delimiter will split \"1->2\" into \"1\" and \">2\"\n        // Better to manually parse\n    }\n\n    // Manual parse by \"->\"\n    size_t pos = 0;\n    while (pos < s.size()) {\n        size_t nextPos = s.find(\"->\", pos);\n        std::string token;\n        if (nextPos == std::string::npos) {\n            token = s.substr(pos);\n            pos = s.size();\n        } else {\n            token = s.substr(pos, nextPos - pos);\n            pos = nextPos + 2;\n        }\n        // trim token\n        size_t ts = token.find_first_not_of(\" \\t\\r\\n\");\n        if (ts == std::string::npos) continue;\n        size_t te = token.find_last_not_of(\" \\t\\r\\n\");\n        token = token.substr(ts, te - ts + 1);\n        if (token.empty()) continue;\n        cur->next = new ListNode(std::stoi(token));\n        cur = cur->next;\n    }\n    return dummy.next;\n}\n\nListNode* mergeTwoLists(ListNode* l1, ListNode* l2) {\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    while (l1 != nullptr && l2 != nullptr) {\n        if (l1->val <= l2->val) {\n            cur->next = l1;\n            l1 = l1->next;\n        } else {\n            cur->next = l2;\n            l2 = l2->next;\n        }\n        cur = cur->next;\n    }\n    if (l1 != nullptr) {\n        cur->next = l1;\n    } else {\n        cur->next = l2;\n    }\n    return dummy.next;\n}\n\nint main() {\n    std::string line1, line2;\n    std::getline(std::cin, line1);\n    std::getline(std::cin, line2);\n\n    ListNode* l1 = parseList(line1);\n    ListNode* l2 = parseList(line2);\n\n    ListNode* merged = mergeTwoLists(l1, l2);\n\n    std::string result;\n    ListNode* cur = merged;\n    while (cur != nullptr) {\n        result += std::to_string(cur->val);\n        if (cur->next != nullptr) {\n            result += \"->\";\n        }\n        cur = cur->next;\n    }\n    std::cout << result;\n    return 0;\n}',NULL,1,'2026-09-27 13:07:27','2026-09-28 15:16:03'),(327,98,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    if (s === null || s.length === 0) {\n        console.log(\"\");\n        rl.close();\n        return;\n    }\n    let start = 0, end = 0;\n    for (let i = 0; i < s.length; i++) {\n        let len1 = expand(s, i, i);\n        let len2 = expand(s, i, i + 1);\n        let len = Math.max(len1, len2);\n        if (len > end - start + 1) {\n            start = i - Math.floor((len - 1) / 2);\n            end = i + Math.floor(len / 2);\n        }\n    }\n    console.log(s.substring(start, end + 1));\n    rl.close();\n});\n\nfunction expand(s, left, right) {\n    while (left >= 0 && right < s.length && s[left] === s[right]) {\n        left--;\n        right++;\n    }\n    return right - left - 1;\n}',NULL,1,'2026-09-27 13:07:27','2026-09-28 15:16:03'),(328,102,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextLine()) {\n            return;\n        }\n        String s = sc.nextLine();\n        System.out.println(isValid(s));\n    }\n\n    public static boolean isValid(String s) {\n        Deque<Character> stack = new ArrayDeque<>();\n        for (char c : s.toCharArray()) {\n            if (c == \'(\' || c == \'{\' || c == \'[\') {\n                stack.push(c);\n            } else {\n                if (stack.isEmpty()) {\n                    return false;\n                }\n                char top = stack.pop();\n                if ((c == \')\' && top != \'(\') ||\n                    (c == \'}\' && top != \'{\') ||\n                    (c == \']\' && top != \'[\')) {\n                    return false;\n                }\n            }\n        }\n        return stack.isEmpty();\n    }\n}',NULL,1,'2026-09-27 13:07:29','2026-09-28 15:16:03'),(329,99,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int x) : val(x), next(nullptr) {}\n};\n\nListNode* reverseList(ListNode* head) {\n    ListNode* prev = nullptr;\n    ListNode* curr = head;\n    while (curr != nullptr) {\n        ListNode* nextTemp = curr->next;\n        curr->next = prev;\n        prev = curr;\n        curr = nextTemp;\n    }\n    return prev;\n}\n\nint main() {\n    std::ios::sync_with_stdio(false);\n    std::cin.tie(nullptr);\n\n    std::string input;\n    std::getline(std::cin, input);\n\n    ListNode dummy(0);\n    ListNode* tail = &dummy;\n\n    size_t pos = 0;\n    while (pos < input.size()) {\n        size_t nextPos = input.find(\"->\", pos);\n        std::string part;\n        if (nextPos == std::string::npos) {\n            part = input.substr(pos);\n            pos = input.size();\n        } else {\n            part = input.substr(pos, nextPos - pos);\n            pos = nextPos + 2;\n        }\n\n        if (part == \"NULL\") {\n            break;\n        }\n\n        int val = std::stoi(part);\n        tail->next = new ListNode(val);\n        tail = tail->next;\n    }\n\n    ListNode* reversed = reverseList(dummy.next);\n\n    std::ostringstream oss;\n    ListNode* curr = reversed;\n    while (curr != nullptr) {\n        oss << curr->val << \"->\";\n        curr = curr->next;\n    }\n    oss << \"NULL\";\n    std::cout << oss.str() << \"\\n\";\n\n    return 0;\n}',NULL,1,'2026-09-27 13:07:29','2026-09-28 15:16:03'),(330,101,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct Node {\n    int key, value;\n    struct Node *prev, *next;\n} Node;\n\ntypedef struct {\n    int capacity;\n    int size;\n    Node **map;\n    int mapSize;\n    Node *head, *tail;\n} LRUCache;\n\nstatic unsigned int hash(int key, int mod) {\n    unsigned int x = (unsigned int)key;\n    x = ((x >> 16) ^ x) * 0x45d9f3b;\n    x = ((x >> 16) ^ x) * 0x45d9f3b;\n    x = (x >> 16) ^ x;\n    return x % (unsigned int)mod;\n}\n\nstatic Node* mapGet(LRUCache *cache, int key) {\n    unsigned int idx = hash(key, cache->mapSize);\n    Node *cur = cache->map[idx];\n    while (cur) {\n        if (cur->key == key) return cur;\n        cur = cur->next;\n    }\n    return NULL;\n}\n\nstatic void mapPut(LRUCache *cache, int key, Node *node) {\n    unsigned int idx = hash(key, cache->mapSize);\n    node->next = cache->map[idx];\n    cache->map[idx] = node;\n}\n\nstatic void mapRemove(LRUCache *cache, int key) {\n    unsigned int idx = hash(key, cache->mapSize);\n    Node *cur = cache->map[idx];\n    Node *prev = NULL;\n    while (cur) {\n        if (cur->key == key) {\n            if (prev) prev->next = cur->next;\n            else cache->map[idx] = cur->next;\n            return;\n        }\n        prev = cur;\n        cur = cur->next;\n    }\n}\n\nstatic void addToHead(LRUCache *cache, Node *node) {\n    node->prev = cache->head;\n    node->next = cache->head->next;\n    cache->head->next->prev = node;\n    cache->head->next = node;\n}\n\nstatic void removeNode(LRUCache *cache, Node *node) {\n    (void)cache;\n    node->prev->next = node->next;\n    node->next->prev = node->prev;\n}\n\nstatic void moveToHead(LRUCache *cache, Node *node) {\n    removeNode(cache, node);\n    addToHead(cache, node);\n}\n\nstatic Node* removeTail(LRUCache *cache) {\n    Node *node = cache->tail->prev;\n    removeNode(cache, node);\n    return node;\n}\n\nstatic LRUCache* LRUCacheCreate(int capacity) {\n    LRUCache *cache = (LRUCache*)malloc(sizeof(LRUCache));\n    cache->capacity = capacity;\n    cache->size = 0;\n    cache->mapSize = capacity * 4 + 17;\n    cache->map = (Node**)calloc(cache->mapSize, sizeof(Node*));\n    cache->head = (Node*)malloc(sizeof(Node));\n    cache->tail = (Node*)malloc(sizeof(Node));\n    cache->head->key = -1;\n    cache->head->value = -1;\n    cache->tail->key = -1;\n    cache->tail->value = -1;\n    cache->head->prev = NULL;\n    cache->head->next = cache->tail;\n    cache->tail->prev = cache->head;\n    cache->tail->next = NULL;\n    return cache;\n}\n\nstatic int LRUCacheGet(LRUCache *cache, int key) {\n    Node *node = mapGet(cache, key);\n    if (!node) return -1;\n    moveToHead(cache, node);\n    return node->value;\n}\n\nstatic void LRUCachePut(LRUCache *cache, int key, int value) {\n    Node *node = mapGet(cache, key);\n    if (node) {\n        node->value = value;\n        moveToHead(cache, node);\n    } else {\n        if (cache->size == cache->capacity) {\n            Node *removed = removeTail(cache);\n            mapRemove(cache, removed->key);\n            free(removed);\n            cache->size--;\n        }\n        Node *newNode = (Node*)malloc(sizeof(Node));\n        newNode->key = key;\n        newNode->value = value;\n        newNode->prev = NULL;\n        newNode->next = NULL;\n        mapPut(cache, key, newNode);\n        addToHead(cache, newNode);\n        cache->size++;\n    }\n}\n\nint main(void) {\n    int capacity, m;\n    if (scanf(\"%d\", &capacity) != 1) return 0;\n    if (scanf(\"%d\", &m) != 1) return 0;\n\n    LRUCache *cache = LRUCacheCreate(capacity);\n\n    char op[16];\n    for (int i = 0; i < m; i++) {\n        if (scanf(\"%15s\", op) != 1) break;\n        if (strcmp(op, \"put\") == 0) {\n            int key, value;\n            scanf(\"%d %d\", &key, &value);\n            LRUCachePut(cache, key, value);\n        } else if (strcmp(op, \"get\") == 0) {\n            int key;\n            scanf(\"%d\", &key);\n            printf(\"%d\\n\", LRUCacheGet(cache, key));\n        }\n    }\n\n    return 0;\n}',NULL,1,'2026-09-27 13:07:31','2026-09-28 15:16:03'),(331,102,'CPP','#include <iostream>\n#include <string>\n#include <stack>\nusing namespace std;\n\nbool isValid(const string& s) {\n    stack<char> st;\n    for (char c : s) {\n        if (c == \'(\' || c == \'{\' || c == \'[\') {\n            st.push(c);\n        } else {\n            if (st.empty()) {\n                return false;\n            }\n            char top = st.top();\n            st.pop();\n            if ((c == \')\' && top != \'(\') ||\n                (c == \'}\' && top != \'{\') ||\n                (c == \']\' && top != \'[\')) {\n                return false;\n            }\n        }\n    }\n    return st.empty();\n}\n\nint main() {\n    string s;\n    if (!getline(cin, s)) {\n        return 0;\n    }\n    cout << (isValid(s) ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:07:31','2026-09-28 15:16:03'),(332,99,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstruct ListNode {\n    int val;\n    struct ListNode *next;\n};\n\nstruct ListNode* reverseList(struct ListNode* head) {\n    struct ListNode* prev = NULL;\n    struct ListNode* curr = head;\n    while (curr != NULL) {\n        struct ListNode* nextTemp = curr->next;\n        curr->next = prev;\n        prev = curr;\n        curr = nextTemp;\n    }\n    return prev;\n}\n\nint main() {\n    char input[100000];\n    if (fgets(input, sizeof(input), stdin) == NULL) {\n        return 0;\n    }\n\n    size_t len = strlen(input);\n    while (len > 0 && (input[len - 1] == \'\\n\' || input[len - 1] == \'\\r\')) {\n        input[--len] = \'\\0\';\n    }\n\n    struct ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    struct ListNode* tail = &dummy;\n\n    char* token = strtok(input, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) {\n            break;\n        }\n        int val = atoi(token);\n        struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));\n        node->val = val;\n        node->next = NULL;\n        tail->next = node;\n        tail = node;\n        token = strtok(NULL, \"->\");\n    }\n\n    struct ListNode* reversed = reverseList(dummy.next);\n\n    struct ListNode* curr = reversed;\n    while (curr != NULL) {\n        printf(\"%d->\", curr->val);\n        curr = curr->next;\n    }\n    printf(\"NULL\\n\");\n\n    return 0;\n}',NULL,1,'2026-09-27 13:07:32','2026-09-28 15:16:03'),(333,101,'PYTHON','import sys\n\nclass Node:\n    __slots__ = (\'key\', \'value\', \'prev\', \'next\')\n    def __init__(self, k, v):\n        self.key = k\n        self.value = v\n        self.prev = None\n        self.next = None\n\nclass LRUCache:\n    def __init__(self, capacity):\n        self.capacity = capacity\n        self.map = {}\n        self.head = Node(-1, -1)\n        self.tail = Node(-1, -1)\n        self.head.next = self.tail\n        self.tail.prev = self.head\n\n    def get(self, key):\n        node = self.map.get(key)\n        if node is None:\n            return -1\n        self.moveToHead(node)\n        return node.value\n\n    def put(self, key, value):\n        node = self.map.get(key)\n        if node is not None:\n            node.value = value\n            self.moveToHead(node)\n        else:\n            if len(self.map) == self.capacity:\n                removed = self.removeTail()\n                del self.map[removed.key]\n            newNode = Node(key, value)\n            self.map[key] = newNode\n            self.addToHead(newNode)\n\n    def addToHead(self, node):\n        node.prev = self.head\n        node.next = self.head.next\n        self.head.next.prev = node\n        self.head.next = node\n\n    def removeNode(self, node):\n        node.prev.next = node.next\n        node.next.prev = node.prev\n\n    def moveToHead(self, node):\n        self.removeNode(node)\n        self.addToHead(node)\n\n    def removeTail(self):\n        node = self.tail.prev\n        self.removeNode(node)\n        return node\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    idx = 0\n    capacity = int(data[idx]); idx += 1\n    m = int(data[idx]); idx += 1\n    cache = LRUCache(capacity)\n    out = []\n    for _ in range(m):\n        op = data[idx]; idx += 1\n        if op == \'put\':\n            key = int(data[idx]); idx += 1\n            value = int(data[idx]); idx += 1\n            cache.put(key, value)\n        elif op == \'get\':\n            key = int(data[idx]); idx += 1\n            out.append(str(cache.get(key)))\n    sys.stdout.write(\'\\n\'.join(out) + (\'\\n\' if out else \'\'))\n\nif __name__ == \'__main__\':\n    main()',NULL,1,'2026-09-27 13:07:33','2026-09-28 15:16:03'),(334,99,'PYTHON','import sys\n\nclass ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef reverseList(head):\n    prev = None\n    curr = head\n    while curr is not None:\n        nextTemp = curr.next\n        curr.next = prev\n        prev = curr\n        curr = nextTemp\n    return prev\n\ndef main():\n    input_str = sys.stdin.readline().strip()\n    parts = input_str.split(\"->\")\n    dummy = ListNode(0)\n    tail = dummy\n    for part in parts:\n        if part == \"NULL\":\n            break\n        val = int(part)\n        tail.next = ListNode(val)\n        tail = tail.next\n\n    reversed_head = reverseList(dummy.next)\n\n    sb = []\n    curr = reversed_head\n    while curr is not None:\n        sb.append(str(curr.val))\n        sb.append(\"->\")\n        curr = curr.next\n    sb.append(\"NULL\")\n    print(\"\".join(sb))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:07:33','2026-09-28 15:16:03'),(335,102,'C','#include <stdio.h>\n#include <string.h>\n#include <stdbool.h>\n\nbool isValid(const char *s) {\n    char stack[10000];\n    int top = -1;\n    for (int i = 0; s[i] != \'\\0\'; i++) {\n        char c = s[i];\n        if (c == \'(\' || c == \'{\' || c == \'[\') {\n            stack[++top] = c;\n        } else {\n            if (top == -1) {\n                return false;\n            }\n            char t = stack[top--];\n            if ((c == \')\' && t != \'(\') ||\n                (c == \'}\' && t != \'{\') ||\n                (c == \']\' && t != \'[\')) {\n                return false;\n            }\n        }\n    }\n    return top == -1;\n}\n\nint main(void) {\n    char s[10000];\n    if (fgets(s, sizeof(s), stdin) == NULL) {\n        return 0;\n    }\n    size_t len = strlen(s);\n    if (len > 0 && s[len - 1] == \'\\n\') {\n        s[len - 1] = \'\\0\';\n    }\n    if (isValid(s)) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:07:34','2026-09-28 15:16:03'),(336,102,'PYTHON','import sys\n\ndef isValid(s: str) -> bool:\n    stack = []\n    for c in s:\n        if c in \'({[\':\n            stack.append(c)\n        else:\n            if not stack:\n                return False\n            top = stack.pop()\n            if (c == \')\' and top != \'(\') or \\\n               (c == \'}\' and top != \'{\') or \\\n               (c == \']\' and top != \'[\'):\n                return False\n    return not stack\n\ndef main():\n    s = sys.stdin.readline().rstrip(\'\\n\')\n    print(\"true\" if isValid(s) else \"false\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:07:35','2026-09-28 15:16:03'),(337,99,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction reverseList(head) {\n    let prev = null;\n    let curr = head;\n    while (curr !== null) {\n        let nextTemp = curr.next;\n        curr.next = prev;\n        prev = curr;\n        curr = nextTemp;\n    }\n    return prev;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const input = line.trim();\n    const parts = input.split(\'->\');\n    const dummy = new ListNode(0);\n    let tail = dummy;\n    for (const part of parts) {\n        if (part === \'NULL\') {\n            break;\n        }\n        const val = parseInt(part, 10);\n        tail.next = new ListNode(val);\n        tail = tail.next;\n    }\n\n    const reversed = reverseList(dummy.next);\n\n    let sb = \'\';\n    let curr = reversed;\n    while (curr !== null) {\n        sb += curr.val + \'->\';\n        curr = curr.next;\n    }\n    sb += \'NULL\';\n    console.log(sb);\n    rl.close();\n});',NULL,1,'2026-09-27 13:07:35','2026-09-28 15:16:03'),(338,101,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass Node {\n    constructor(key, value) {\n        this.key = key;\n        this.value = value;\n        this.prev = null;\n        this.next = null;\n    }\n}\n\nclass LRUCache {\n    constructor(capacity) {\n        this.capacity = capacity;\n        this.map = new Map();\n        this.head = new Node(-1, -1);\n        this.tail = new Node(-1, -1);\n        this.head.next = this.tail;\n        this.tail.prev = this.head;\n    }\n\n    get(key) {\n        const node = this.map.get(key);\n        if (node === undefined) return -1;\n        this.moveToHead(node);\n        return node.value;\n    }\n\n    put(key, value) {\n        const node = this.map.get(key);\n        if (node !== undefined) {\n            node.value = value;\n            this.moveToHead(node);\n        } else {\n            if (this.map.size === this.capacity) {\n                const removed = this.removeTail();\n                this.map.delete(removed.key);\n            }\n            const newNode = new Node(key, value);\n            this.map.set(key, newNode);\n            this.addToHead(newNode);\n        }\n    }\n\n    addToHead(node) {\n        node.prev = this.head;\n        node.next = this.head.next;\n        this.head.next.prev = node;\n        this.head.next = node;\n    }\n\n    removeNode(node) {\n        node.prev.next = node.next;\n        node.next.prev = node.prev;\n    }\n\n    moveToHead(node) {\n        this.removeNode(node);\n        this.addToHead(node);\n    }\n\n    removeTail() {\n        const node = this.tail.prev;\n        this.removeNode(node);\n        return node;\n    }\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout,\n    terminal: false\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const capacity = parseInt(lines[idx++]);\n    const m = parseInt(lines[idx++]);\n    const cache = new LRUCache(capacity);\n    const output = [];\n    for (let i = 0; i < m; i++) {\n        const line = lines[idx++];\n        if (!line) continue;\n        const parts = line.split(/\\s+/);\n        if (parts[0] === \'put\') {\n            const key = parseInt(parts[1]);\n            const value = parseInt(parts[2]);\n            cache.put(key, value);\n        } else if (parts[0] === \'get\') {\n            const key = parseInt(parts[1]);\n            output.push(cache.get(key));\n        }\n    }\n    process.stdout.write(output.join(\'\\n\') + (output.length ? \'\\n\' : \'\'));\n});',NULL,1,'2026-09-27 13:07:36','2026-09-28 15:16:03'),(339,102,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    console.log(isValid(s));\n    rl.close();\n});\n\nfunction isValid(s) {\n    const stack = [];\n    for (const c of s) {\n        if (c === \'(\' || c === \'{\' || c === \'[\') {\n            stack.push(c);\n        } else {\n            if (stack.length === 0) {\n                return false;\n            }\n            const top = stack.pop();\n            if ((c === \')\' && top !== \'(\') ||\n                (c === \'}\' && top !== \'{\') ||\n                (c === \']\' && top !== \'[\')) {\n                return false;\n            }\n        }\n    }\n    return stack.length === 0;\n}',NULL,1,'2026-09-27 13:07:36','2026-09-28 15:16:03'),(340,103,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        Arrays.sort(nums);\n        List<List<Integer>> res = new ArrayList<>();\n        for (int i = 0; i < n - 2; i++) {\n            if (i > 0 && nums[i] == nums[i - 1]) continue;\n            int left = i + 1, right = n - 1;\n            while (left < right) {\n                int sum = nums[i] + nums[left] + nums[right];\n                if (sum == 0) {\n                    res.add(Arrays.asList(nums[i], nums[left], nums[right]));\n                    while (left < right && nums[left] == nums[left + 1]) left++;\n                    while (left < right && nums[right] == nums[right - 1]) right--;\n                    left++;\n                    right--;\n                } else if (sum < 0) {\n                    left++;\n                } else {\n                    right--;\n                }\n            }\n        }\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            sb.append(\"[\");\n            sb.append(res.get(i).get(0)).append(\",\");\n            sb.append(res.get(i).get(1)).append(\",\");\n            sb.append(res.get(i).get(2));\n            sb.append(\"]\");\n            if (i != res.size() - 1) sb.append(\",\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1,'2026-09-27 13:07:37','2026-09-28 15:16:03'),(341,105,'JAVA','import java.util.PriorityQueue;\nimport java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int k = sc.nextInt();\n        PriorityQueue<Integer> pq = new PriorityQueue<>();\n        for (int i = 0; i < n; i++) {\n            int x = sc.nextInt();\n            pq.offer(x);\n            if (pq.size() > k) {\n                pq.poll();\n            }\n        }\n        System.out.println(pq.peek());\n    }\n}',NULL,1,'2026-09-27 13:07:38','2026-09-28 15:16:03'),(342,104,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int x) { val = x; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] vals = new int[n];\n        for (int i = 0; i < n; i++) {\n            vals[i] = sc.nextInt();\n        }\n        int pos = sc.nextInt();\n\n        if (n == 0) {\n            System.out.println(\"false\");\n            return;\n        }\n\n        ListNode[] nodes = new ListNode[n];\n        for (int i = 0; i < n; i++) {\n            nodes[i] = new ListNode(vals[i]);\n        }\n        for (int i = 0; i < n - 1; i++) {\n            nodes[i].next = nodes[i + 1];\n        }\n        if (pos != -1) {\n            nodes[n - 1].next = nodes[pos];\n        }\n\n        ListNode slow = nodes[0];\n        ListNode fast = nodes[0];\n        boolean hasCycle = false;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                hasCycle = true;\n                break;\n            }\n        }\n\n        System.out.println(hasCycle ? \"true\" : \"false\");\n    }\n}',NULL,1,'2026-09-27 13:07:38','2026-09-28 15:16:03'),(343,103,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    sort(nums.begin(), nums.end());\n    vector<vector<int>> res;\n    for (int i = 0; i < n - 2; i++) {\n        if (i > 0 && nums[i] == nums[i - 1]) continue;\n        int left = i + 1, right = n - 1;\n        while (left < right) {\n            int sum = nums[i] + nums[left] + nums[right];\n            if (sum == 0) {\n                res.push_back({nums[i], nums[left], nums[right]});\n                while (left < right && nums[left] == nums[left + 1]) left++;\n                while (left < right && nums[right] == nums[right - 1]) right--;\n                left++;\n                right--;\n            } else if (sum < 0) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n    }\n    cout << \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        cout << \"[\" << res[i][0] << \",\" << res[i][1] << \",\" << res[i][2] << \"]\";\n        if (i != (int)res.size() - 1) cout << \",\";\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:07:40','2026-09-28 15:16:03'),(344,105,'CPP','#include <iostream>\n#include <queue>\n#include <vector>\n\nusing namespace std;\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    priority_queue<int, vector<int>, greater<int>> pq;\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        pq.push(x);\n        if ((int)pq.size() > k) {\n            pq.pop();\n        }\n    }\n    cout << pq.top() << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:07:40','2026-09-28 15:16:03'),(345,104,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int x) : val(x), next(nullptr) {}\n};\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> vals(n);\n    for (int i = 0; i < n; i++) {\n        cin >> vals[i];\n    }\n    int pos;\n    cin >> pos;\n\n    if (n == 0) {\n        cout << \"false\" << endl;\n        return 0;\n    }\n\n    vector<ListNode*> nodes(n);\n    for (int i = 0; i < n; i++) {\n        nodes[i] = new ListNode(vals[i]);\n    }\n    for (int i = 0; i < n - 1; i++) {\n        nodes[i]->next = nodes[i + 1];\n    }\n    if (pos != -1) {\n        nodes[n - 1]->next = nodes[pos];\n    }\n\n    ListNode* slow = nodes[0];\n    ListNode* fast = nodes[0];\n    bool hasCycle = false;\n    while (fast != nullptr && fast->next != nullptr) {\n        slow = slow->next;\n        fast = fast->next->next;\n        if (slow == fast) {\n            hasCycle = true;\n            break;\n        }\n    }\n\n    cout << (hasCycle ? \"true\" : \"false\") << endl;\n\n    return 0;\n}',NULL,1,'2026-09-27 13:07:41','2026-09-28 15:16:03'),(346,100,'PYTHON','import sys\n\nclass ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef parse_list(line):\n    if line is None:\n        return None\n    line = line.strip()\n    if not line or line == \"NULL\":\n        return None\n    if line.endswith(\"->NULL\"):\n        line = line[:-6]\n    elif line.endswith(\"NULL\"):\n        line = line[:-4]\n        if line.endswith(\"->\"):\n            line = line[:-2]\n    if not line:\n        return None\n    parts = line.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for part in parts:\n        part = part.strip()\n        if not part:\n            continue\n        cur.next = ListNode(int(part))\n        cur = cur.next\n    return dummy.next\n\ndef merge_two_lists(l1, l2):\n    dummy = ListNode(0)\n    cur = dummy\n    while l1 is not None and l2 is not None:\n        if l1.val <= l2.val:\n            cur.next = l1\n            l1 = l1.next\n        else:\n            cur.next = l2\n            l2 = l2.next\n        cur = cur.next\n    if l1 is not None:\n        cur.next = l1\n    else:\n        cur.next = l2\n    return dummy.next\n\ndef main():\n    lines = sys.stdin.read().splitlines()\n    line1 = lines[0] if len(lines) > 0 else None\n    line2 = lines[1] if len(lines) > 1 else None\n\n    l1 = parse_list(line1)\n    l2 = parse_list(line2)\n\n    merged = merge_two_lists(l1, l2)\n\n    result = []\n    cur = merged\n    while cur is not None:\n        result.append(str(cur.val))\n        cur = cur.next\n    sys.stdout.write(\"->\".join(result))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:07:41','2026-09-28 15:16:03'),(347,103,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    qsort(nums, n, sizeof(int), cmp);\n\n    int **res = (int **)malloc(n * n * sizeof(int *));\n    int resSize = 0;\n\n    for (int i = 0; i < n - 2; i++) {\n        if (i > 0 && nums[i] == nums[i - 1]) continue;\n        int left = i + 1, right = n - 1;\n        while (left < right) {\n            int sum = nums[i] + nums[left] + nums[right];\n            if (sum == 0) {\n                res[resSize] = (int *)malloc(3 * sizeof(int));\n                res[resSize][0] = nums[i];\n                res[resSize][1] = nums[left];\n                res[resSize][2] = nums[right];\n                resSize++;\n                while (left < right && nums[left] == nums[left + 1]) left++;\n                while (left < right && nums[right] == nums[right - 1]) right--;\n                left++;\n                right--;\n            } else if (sum < 0) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n    }\n\n    printf(\"[\");\n    for (int i = 0; i < resSize; i++) {\n        printf(\"[%d,%d,%d]\", res[i][0], res[i][1], res[i][2]);\n        if (i != resSize - 1) printf(\",\");\n    }\n    printf(\"]\\n\");\n\n    for (int i = 0; i < resSize; i++) {\n        free(res[i]);\n    }\n    free(res);\n    free(nums);\n    return 0;\n}',NULL,1,'2026-09-27 13:07:42','2026-09-28 15:16:03'),(348,105,'C','#include <stdio.h>\n#include <stdlib.h>\n\nvoid swap(int *a, int *b) {\n    int t = *a;\n    *a = *b;\n    *b = t;\n}\n\nvoid heapify(int *heap, int size, int i) {\n    int smallest = i;\n    int left = 2 * i + 1;\n    int right = 2 * i + 2;\n\n    if (left < size && heap[left] < heap[smallest]) {\n        smallest = left;\n    }\n    if (right < size && heap[right] < heap[smallest]) {\n        smallest = right;\n    }\n    if (smallest != i) {\n        swap(&heap[i], &heap[smallest]);\n        heapify(heap, size, smallest);\n    }\n}\n\nvoid push(int *heap, int *size, int value) {\n    heap[*size] = value;\n    (*size)++;\n    int i = *size - 1;\n    while (i > 0) {\n        int parent = (i - 1) / 2;\n        if (heap[parent] <= heap[i]) {\n            break;\n        }\n        swap(&heap[parent], &heap[i]);\n        i = parent;\n    }\n}\n\nvoid pop(int *heap, int *size) {\n    heap[0] = heap[*size - 1];\n    (*size)--;\n    heapify(heap, *size, 0);\n}\n\nint main(void) {\n    int n, k;\n    scanf(\"%d %d\", &n, &k);\n\n    int *heap = (int *)malloc(sizeof(int) * (k + 1));\n    int size = 0;\n\n    for (int i = 0; i < n; i++) {\n        int x;\n        scanf(\"%d\", &x);\n        push(heap, &size, x);\n        if (size > k) {\n            pop(heap, &size);\n        }\n    }\n\n    printf(\"%d\\n\", heap[0]);\n\n    free(heap);\n    return 0;\n}',NULL,1,'2026-09-27 13:07:42','2026-09-28 15:16:03'),(349,104,'C','#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n\n    int *vals = (int *)malloc(sizeof(int) * (n > 0 ? n : 1));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &vals[i]);\n    }\n\n    int pos;\n    scanf(\"%d\", &pos);\n\n    if (n == 0) {\n        printf(\"false\\n\");\n        free(vals);\n        return 0;\n    }\n\n    ListNode **nodes = (ListNode **)malloc(sizeof(ListNode *) * n);\n    for (int i = 0; i < n; i++) {\n        nodes[i] = (ListNode *)malloc(sizeof(ListNode));\n        nodes[i]->val = vals[i];\n        nodes[i]->next = NULL;\n    }\n\n    for (int i = 0; i < n - 1; i++) {\n        nodes[i]->next = nodes[i + 1];\n    }\n\n    if (pos != -1) {\n        nodes[n - 1]->next = nodes[pos];\n    }\n\n    ListNode *slow = nodes[0];\n    ListNode *fast = nodes[0];\n    int hasCycle = 0;\n\n    while (fast != NULL && fast->next != NULL) {\n        slow = slow->next;\n        fast = fast->next->next;\n        if (slow == fast) {\n            hasCycle = 1;\n            break;\n        }\n    }\n\n    printf(\"%s\\n\", hasCycle ? \"true\" : \"false\");\n\n    for (int i = 0; i < n; i++) {\n        free(nodes[i]);\n    }\n    free(nodes);\n    free(vals);\n\n    return 0;\n}',NULL,1,'2026-09-27 13:07:43','2026-09-28 15:16:03'),(350,105,'PYTHON','import sys\nimport heapq\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    n = int(data[0])\n    k = int(data[1])\n    nums = list(map(int, data[2:2+n]))\n    heap = []\n    for x in nums:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:07:44','2026-09-28 15:16:03'),(351,100,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction parseList(line) {\n    if (line === null || line === undefined) {\n        return null;\n    }\n    line = line.trim();\n    if (line === \'\' || line === \'NULL\') {\n        return null;\n    }\n    if (line.endsWith(\'->NULL\')) {\n        line = line.substring(0, line.length - 6);\n    } else if (line.endsWith(\'NULL\')) {\n        line = line.substring(0, line.length - 4);\n        if (line.endsWith(\'->\')) {\n            line = line.substring(0, line.length - 2);\n        }\n    }\n    if (line === \'\') {\n        return null;\n    }\n    const parts = line.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (let part of parts) {\n        part = part.trim();\n        if (part === \'\') {\n            continue;\n        }\n        cur.next = new ListNode(parseInt(part, 10));\n        cur = cur.next;\n    }\n    return dummy.next;\n}\n\nfunction mergeTwoLists(l1, l2) {\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    while (l1 !== null && l2 !== null) {\n        if (l1.val <= l2.val) {\n            cur.next = l1;\n            l1 = l1.next;\n        } else {\n            cur.next = l2;\n            l2 = l2.next;\n        }\n        cur = cur.next;\n    }\n    if (l1 !== null) {\n        cur.next = l1;\n    } else {\n        cur.next = l2;\n    }\n    return dummy.next;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nconst lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 2) {\n        rl.close();\n    }\n});\n\nrl.on(\'close\', () => {\n    const l1 = parseList(lines[0]);\n    const l2 = parseList(lines[1]);\n    const merged = mergeTwoLists(l1, l2);\n    let sb = \'\';\n    let cur = merged;\n    while (cur !== null) {\n        sb += cur.val;\n        if (cur.next !== null) {\n            sb += \'->\';\n        }\n        cur = cur.next;\n    }\n    process.stdout.write(sb);\n});',NULL,1,'2026-09-27 13:07:44','2026-09-28 15:16:03'),(352,103,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\nnums.sort()\nres = []\nfor i in range(n - 2):\n    if i > 0 and nums[i] == nums[i - 1]:\n        continue\n    left, right = i + 1, n - 1\n    while left < right:\n        s = nums[i] + nums[left] + nums[right]\n        if s == 0:\n            res.append([nums[i], nums[left], nums[right]])\n            while left < right and nums[left] == nums[left + 1]:\n                left += 1\n            while left < right and nums[right] == nums[right - 1]:\n                right -= 1\n            left += 1\n            right -= 1\n        elif s < 0:\n            left += 1\n        else:\n            right -= 1\nsb = \"[\"\nfor i in range(len(res)):\n    sb += \"[\" + \",\".join(map(str, res[i])) + \"]\"\n    if i != len(res) - 1:\n        sb += \",\"\nsb += \"]\"\nprint(sb)',NULL,1,'2026-09-27 13:07:44','2026-09-28 15:16:03'),(353,104,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    vals = list(map(int, data[1:1+n]))\n    pos = int(data[1+n])\n\n    if n == 0:\n        print(\"false\")\n        return\n\n    class ListNode:\n        __slots__ = (\'val\', \'next\')\n        def __init__(self, x):\n            self.val = x\n            self.next = None\n\n    nodes = [ListNode(v) for v in vals]\n    for i in range(n - 1):\n        nodes[i].next = nodes[i + 1]\n    if pos != -1:\n        nodes[n - 1].next = nodes[pos]\n\n    slow = nodes[0]\n    fast = nodes[0]\n    has_cycle = False\n    while fast is not None and fast.next is not None:\n        slow = slow.next\n        fast = fast.next.next\n        if slow is fast:\n            has_cycle = True\n            break\n\n    print(\"true\" if has_cycle else \"false\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:07:45','2026-09-28 15:16:03'),(354,106,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int left = 0, right = n - 1;\n        while (left < right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] > nums[mid + 1]) {\n                right = mid;\n            } else {\n                left = mid + 1;\n            }\n        }\n        System.out.println(left);\n    }\n}',NULL,1,'2026-09-27 13:07:46','2026-09-28 15:16:03'),(355,105,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const [n, k] = lines[0].split(\' \').map(Number);\n        const nums = lines[1].split(\' \').map(Number);\n        const pq = [];\n        const push = (x) => {\n            pq.push(x);\n            let i = pq.length - 1;\n            while (i > 0) {\n                const p = (i - 1) >> 1;\n                if (pq[p] <= pq[i]) break;\n                [pq[p], pq[i]] = [pq[i], pq[p]];\n                i = p;\n            }\n        };\n        const pop = () => {\n            const top = pq[0];\n            const last = pq.pop();\n            if (pq.length > 0) {\n                pq[0] = last;\n                let i = 0;\n                while (true) {\n                    let l = i * 2 + 1, r = i * 2 + 2, m = i;\n                    if (l < pq.length && pq[l] < pq[m]) m = l;\n                    if (r < pq.length && pq[r] < pq[m]) m = r;\n                    if (m === i) break;\n                    [pq[i], pq[m]] = [pq[m], pq[i]];\n                    i = m;\n                }\n            }\n            return top;\n        };\n        for (let i = 0; i < n; i++) {\n            push(nums[i]);\n            if (pq.length > k) pop();\n        }\n        console.log(pq[0]);\n        rl.close();\n    }\n});',NULL,1,'2026-09-27 13:07:46','2026-09-28 15:16:03'),(356,103,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    nums.sort((a, b) => a - b);\n    const res = [];\n    for (let i = 0; i < n - 2; i++) {\n        if (i > 0 && nums[i] === nums[i - 1]) continue;\n        let left = i + 1, right = n - 1;\n        while (left < right) {\n            const sum = nums[i] + nums[left] + nums[right];\n            if (sum === 0) {\n                res.push([nums[i], nums[left], nums[right]]);\n                while (left < right && nums[left] === nums[left + 1]) left++;\n                while (left < right && nums[right] === nums[right - 1]) right--;\n                left++;\n                right--;\n            } else if (sum < 0) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n    }\n    let sb = \'[\';\n    for (let i = 0; i < res.length; i++) {\n        sb += \'[\';\n        sb += res[i][0] + \',\';\n        sb += res[i][1] + \',\';\n        sb += res[i][2];\n        sb += \']\';\n        if (i !== res.length - 1) sb += \',\';\n    }\n    sb += \']\';\n    console.log(sb);\n});',NULL,1,'2026-09-27 13:07:46','2026-09-28 15:16:03'),(357,104,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const vals = lines[1] ? lines[1].split(\' \').map(Number) : [];\n    const pos = parseInt(lines[2]);\n\n    if (n === 0) {\n        console.log(\"false\");\n        return;\n    }\n\n    class ListNode {\n        constructor(x) {\n            this.val = x;\n            this.next = null;\n        }\n    }\n\n    const nodes = [];\n    for (let i = 0; i < n; i++) {\n        nodes.push(new ListNode(vals[i]));\n    }\n    for (let i = 0; i < n - 1; i++) {\n        nodes[i].next = nodes[i + 1];\n    }\n    if (pos !== -1) {\n        nodes[n - 1].next = nodes[pos];\n    }\n\n    let slow = nodes[0];\n    let fast = nodes[0];\n    let hasCycle = false;\n    while (fast !== null && fast.next !== null) {\n        slow = slow.next;\n        fast = fast.next.next;\n        if (slow === fast) {\n            hasCycle = true;\n            break;\n        }\n    }\n\n    console.log(hasCycle ? \"true\" : \"false\");\n});',NULL,1,'2026-09-27 13:07:47','2026-09-28 15:16:03'),(358,106,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int left = 0, right = n - 1;\n    while (left < right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] > nums[mid + 1]) {\n            right = mid;\n        } else {\n            left = mid + 1;\n        }\n    }\n    cout << left << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:07:48','2026-09-28 15:16:03'),(359,107,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int maxSum = nums[0];\n        int currentSum = nums[0];\n        for (int i = 1; i < n; i++) {\n            currentSum = Math.max(nums[i], currentSum + nums[i]);\n            maxSum = Math.max(maxSum, currentSum);\n        }\n        System.out.println(maxSum);\n    }\n}',NULL,1,'2026-09-27 13:07:48','2026-09-28 15:16:03'),(360,108,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] height = new int[n];\n        for (int i = 0; i < n; i++) {\n            height[i] = sc.nextInt();\n        }\n        int left = 0, right = n - 1;\n        int maxWater = 0;\n        while (left < right) {\n            int h = Math.min(height[left], height[right]);\n            int w = right - left;\n            maxWater = Math.max(maxWater, h * w);\n            if (height[left] < height[right]) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n        System.out.println(maxWater);\n    }\n}',NULL,1,'2026-09-27 13:07:48','2026-09-28 15:16:03'),(361,109,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] intervals = new int[n][2];\n        for (int i = 0; i < n; i++) {\n            intervals[i][0] = sc.nextInt();\n            intervals[i][1] = sc.nextInt();\n        }\n        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));\n        List<int[]> merged = new ArrayList<>();\n        for (int[] interval : intervals) {\n            if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < interval[0]) {\n                merged.add(new int[]{interval[0], interval[1]});\n            } else {\n                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], interval[1]);\n            }\n        }\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < merged.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"[\").append(merged.get(i)[0]).appe