)\nleft, right = 0, n - 1\nwhile left < right:\n    mid = left + (right - left) // 2\n    if nums[mid] > nums[mid + 1]:\n        right = mid\n    else:\n        left = mid + 1\nprint(left)',NULL,1,'2026-09-27 13:07:51','2026-09-28 15:16:03'),(366,109,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> intervals(n, vector<int>(2));\n    for (int i = 0; i < n; i++) {\n        cin >> intervals[i][0] >> intervals[i][1];\n    }\n    sort(intervals.begin(), intervals.end(), [](const vector<int>& a, const vector<int>& b) {\n        return a[0] < b[0];\n    });\n    vector<vector<int>> merged;\n    for (const auto& interval : intervals) {\n        if (merged.empty() || merged.back()[1] < interval[0]) {\n            merged.push_back({interval[0], interval[1]});\n        } else {\n            merged.back()[1] = max(merged.back()[1], interval[1]);\n        }\n    }\n    cout << \"[\";\n    for (size_t i = 0; i < merged.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << \"[\" << merged[i][0] << \",\" << merged[i][1] << \"]\";\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:07:52','2026-09-28 15:16:03'),(367,107,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int maxSum = nums[0];\n    int currentSum = nums[0];\n    for (int i = 1; i < n; i++) {\n        currentSum = (nums[i] > currentSum + nums[i]) ? nums[i] : currentSum + nums[i];\n        maxSum = (maxSum > currentSum) ? maxSum : currentSum;\n    }\n    printf(\"%d\\n\", maxSum);\n    return 0;\n}',NULL,1,'2026-09-27 13:07:52','2026-09-28 15:16:03'),(368,106,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    let left = 0, right = n - 1;\n    while (left < right) {\n        const mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] > nums[mid + 1]) {\n            right = mid;\n        } else {\n            left = mid + 1;\n        }\n    }\n    console.log(left);\n});',NULL,1,'2026-09-27 13:07:52','2026-09-28 15:16:03'),(369,108,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int height[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &height[i]);\n    }\n    int left = 0, right = n - 1;\n    int maxWater = 0;\n    while (left < right) {\n        int h = height[left] < height[right] ? height[left] : height[right];\n        int w = right - left;\n        int water = h * w;\n        if (water > maxWater) {\n            maxWater = water;\n        }\n        if (height[left] < height[right]) {\n            left++;\n        } else {\n            right--;\n        }\n    }\n    printf(\"%d\\n\", maxWater);\n    return 0;\n}',NULL,1,'2026-09-27 13:07:53','2026-09-28 15:16:03'),(370,107,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\nmax_sum = nums[0]\ncurrent_sum = nums[0]\nfor i in range(1, n):\n    current_sum = max(nums[i], current_sum + nums[i])\n    max_sum = max(max_sum, current_sum)\nprint(max_sum)',NULL,1,'2026-09-27 13:07:53','2026-09-28 15:16:03'),(371,108,'PYTHON','n = int(input())\nheight = list(map(int, input().split()))\nleft, right = 0, n - 1\nmax_water = 0\nwhile left < right:\n    h = min(height[left], height[right])\n    w = right - left\n    max_water = max(max_water, h * w)\n    if height[left] < height[right]:\n        left += 1\n    else:\n        right -= 1\nprint(max_water)',NULL,1,'2026-09-27 13:07:54','2026-09-28 15:16:03'),(372,109,'C','#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int start;\n    int end;\n} Interval;\n\nint cmp(const void *a, const void *b) {\n    Interval *ia = (Interval *)a;\n    Interval *ib = (Interval *)b;\n    if (ia->start < ib->start) return -1;\n    if (ia->start > ib->start) return 1;\n    return 0;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n\n    Interval *intervals = (Interval *)malloc(n * sizeof(Interval));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d %d\", &intervals[i].start, &intervals[i].end);\n    }\n\n    qsort(intervals, n, sizeof(Interval), cmp);\n\n    Interval *merged = (Interval *)malloc(n * sizeof(Interval));\n    int m = 0;\n\n    for (int i = 0; i < n; i++) {\n        if (m == 0 || merged[m - 1].end < intervals[i].start) {\n            merged[m++] = intervals[i];\n        } else {\n            if (intervals[i].end > merged[m - 1].end) {\n                merged[m - 1].end = intervals[i].end;\n            }\n        }\n    }\n\n    printf(\"[\");\n    for (int i = 0; i < m; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"[%d,%d]\", merged[i].start, merged[i].end);\n    }\n    printf(\"]\\n\");\n\n    free(intervals);\n    free(merged);\n    return 0;\n}',NULL,1,'2026-09-27 13:07:54','2026-09-28 15:16:03'),(373,107,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(/\\s+/).map(Number);\n    let maxSum = nums[0];\n    let currentSum = nums[0];\n    for (let i = 1; i < n; i++) {\n        currentSum = Math.max(nums[i], currentSum + nums[i]);\n        maxSum = Math.max(maxSum, currentSum);\n    }\n    console.log(maxSum);\n});',NULL,1,'2026-09-27 13:07:54','2026-09-28 15:16:03'),(374,110,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String word1 = sc.nextLine();\n        String word2 = sc.nextLine();\n        int n = word1.length();\n        int m = word2.length();\n        int[][] dp = new int[n + 1][m + 1];\n        for (int i = 0; i <= n; i++) {\n            dp[i][0] = i;\n        }\n        for (int j = 0; j <= m; j++) {\n            dp[0][j] = j;\n        }\n        for (int i = 1; i <= n; i++) {\n            for (int j = 1; j <= m; j++) {\n                if (word1.charAt(i - 1) == word2.charAt(j - 1)) {\n                    dp[i][j] = dp[i - 1][j - 1];\n                } else {\n                    dp[i][j] = Math.min(Math.min(dp[i - 1][j], dp[i][j - 1]), dp[i - 1][j - 1]) + 1;\n                }\n            }\n        }\n        System.out.println(dp[n][m]);\n    }\n}',NULL,1,'2026-09-27 13:07:55','2026-09-28 15:16:03'),(375,108,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const height = lines[1].split(\' \').map(Number);\n    let left = 0, right = n - 1;\n    let maxWater = 0;\n    while (left < right) {\n        const h = Math.min(height[left], height[right]);\n        const w = right - left;\n        maxWater = Math.max(maxWater, h * w);\n        if (height[left] < height[right]) {\n            left++;\n        } else {\n            right--;\n        }\n    }\n    console.log(maxWater);\n});',NULL,1,'2026-09-27 13:07:55','2026-09-28 15:16:03'),(376,109,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    intervals = []\n    idx = 1\n    for _ in range(n):\n        intervals.append([int(data[idx]), int(data[idx + 1])])\n        idx += 2\n\n    intervals.sort(key=lambda x: x[0])\n\n    merged = []\n    for interval in intervals:\n        if not merged or merged[-1][1] < interval[0]:\n            merged.append([interval[0], interval[1]])\n        else:\n            merged[-1][1] = max(merged[-1][1], interval[1])\n\n    result = \"[\" + \",\".join(f\"[{a},{b}]\" for a, b in merged) + \"]\"\n    print(result)\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:07:55','2026-09-28 15:16:03'),(377,110,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nusing namespace std;\n\nint main() {\n    string word1, word2;\n    getline(cin, word1);\n    getline(cin, word2);\n    int n = word1.length();\n    int m = word2.length();\n    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));\n    for (int i = 0; i <= n; i++) {\n        dp[i][0] = i;\n    }\n    for (int j = 0; j <= m; j++) {\n        dp[0][j] = j;\n    }\n    for (int i = 1; i <= n; i++) {\n        for (int j = 1; j <= m; j++) {\n            if (word1[i - 1] == word2[j - 1]) {\n                dp[i][j] = dp[i - 1][j - 1];\n            } else {\n                dp[i][j] = min(min(dp[i - 1][j], dp[i][j - 1]), dp[i - 1][j - 1]) + 1;\n            }\n        }\n    }\n    cout << dp[n][m] << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:07:57','2026-09-28 15:16:03'),(378,111,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = scanner.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = scanner.nextInt();\n        }\n        \n        if (n == 0) {\n            System.out.println(0);\n            return;\n        }\n        if (n == 1) {\n            System.out.println(nums[0]);\n            return;\n        }\n        \n        int prev2 = nums[0];\n        int prev1 = Math.max(nums[0], nums[1]);\n        \n        for (int i = 2; i < n; i++) {\n            int current = Math.max(prev1, prev2 + nums[i]);\n            prev2 = prev1;\n            prev1 = current;\n        }\n        \n        System.out.println(prev1);\n    }\n}',NULL,1,'2026-09-27 13:07:57','2026-09-28 15:16:03'),(379,109,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const intervals = [];\n    for (let i = 1; i <= n; i++) {\n        const [a, b] = lines[i].split(\' \').map(Number);\n        intervals.push([a, b]);\n    }\n    intervals.sort((a, b) => a[0] - b[0]);\n    const merged = [];\n    for (const interval of intervals) {\n        if (merged.length === 0 || merged[merged.length - 1][1] < interval[0]) {\n            merged.push([interval[0], interval[1]]);\n        } else {\n            merged[merged.length - 1][1] = Math.max(merged[merged.length - 1][1], interval[1]);\n        }\n    }\n    let result = \'[\';\n    for (let i = 0; i < merged.length; i++) {\n        if (i > 0) result += \',\';\n        result += \'[\' + merged[i][0] + \',\' + merged[i][1] + \']\';\n    }\n    result += \']\';\n    console.log(result);\n});',NULL,1,'2026-09-27 13:07:57','2026-09-28 15:16:03'),(380,112,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        nextPermutation(nums);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(nums[i]);\n        }\n        System.out.println(sb.toString());\n    }\n\n    private static void nextPermutation(int[] nums) {\n        int i = nums.length - 2;\n        while (i >= 0 && nums[i] >= nums[i + 1]) {\n            i--;\n        }\n        if (i >= 0) {\n            int j = nums.length - 1;\n            while (nums[j] <= nums[i]) {\n                j--;\n            }\n            swap(nums, i, j);\n        }\n        reverse(nums, i + 1, nums.length - 1);\n    }\n\n    private static void swap(int[] nums, int i, int j) {\n        int tmp = nums[i];\n        nums[i] = nums[j];\n        nums[j] = tmp;\n    }\n\n    private static void reverse(int[] nums, int left, int right) {\n        while (left < right) {\n            swap(nums, left, right);\n            left++;\n            right--;\n        }\n    }\n}',NULL,1,'2026-09-27 13:07:57','2026-09-28 15:16:03'),(381,113,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = Integer.parseInt(scanner.nextLine().trim());\n        String[] strs = new String[n];\n        for (int i = 0; i < n; i++) {\n            strs[i] = scanner.nextLine();\n        }\n        System.out.println(longestCommonPrefix(strs));\n    }\n\n    public static String longestCommonPrefix(String[] strs) {\n        if (strs == null || strs.length == 0) {\n            return \"\";\n        }\n        String prefix = strs[0];\n        for (int i = 1; i < strs.length; i++) {\n            while (strs[i].indexOf(prefix) != 0) {\n                prefix = prefix.substring(0, prefix.length() - 1);\n                if (prefix.isEmpty()) {\n                    return \"\";\n                }\n            }\n        }\n        return prefix;\n    }\n}',NULL,1,'2026-09-27 13:07:59','2026-09-28 15:16:03'),(382,111,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    if (n == 0) {\n        cout << 0 << endl;\n        return 0;\n    }\