 1\n    while left < right:\n        nums[left], nums[right] = nums[right], nums[left]\n        left += 1\n        right -= 1\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    next_permutation(nums)\n    print(\' \'.join(map(str, nums)))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:08:04','2026-09-28 15:16:03'),(388,111,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\n\nif n == 0:\n    print(0)\nelif n == 1:\n    print(nums[0])\nelse:\n    prev2 = nums[0]\n    prev1 = max(nums[0], nums[1])\n    for i in range(2, n):\n        current = max(prev1, prev2 + nums[i])\n        prev2 = prev1\n        prev1 = current\n    print(prev1)',NULL,1,'2026-09-27 13:08:04','2026-09-28 15:16:03'),(389,113,'C','#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    int n;\n    if (scanf(\"%d\", &n) != 1) {\n        return 0;\n    }\n    getchar();\n\n    char strs[1000][1000];\n    for (int i = 0; i < n; i++) {\n        if (fgets(strs[i], sizeof(strs[i]), stdin) == NULL) {\n            strs[i][0] = \'\\0\';\n            continue;\n        }\n        size_t len = strlen(strs[i]);\n        if (len > 0 && strs[i][len - 1] == \'\\n\') {\n            strs[i][len - 1] = \'\\0\';\n        }\n    }\n\n    if (n == 0) {\n        printf(\"\\n\");\n        return 0;\n    }\n\n    char prefix[1000];\n    strcpy(prefix, strs[0]);\n\n    for (int i = 1; i < n; i++) {\n        while (strncmp(strs[i], prefix, strlen(prefix)) != 0) {\n            size_t len = strlen(prefix);\n            if (len == 0) {\n                printf(\"\\n\");\n                return 0;\n            }\n            prefix[len - 1] = \'\\0\';\n        }\n    }\n\n    printf(\"%s\\n\", prefix);\n    return 0;\n}',NULL,1,'2026-09-27 13:08:04','2026-09-28 15:16:03'),(390,113,'PYTHON','n = int(input().strip())\nstrs = []\nfor _ in range(n):\n    strs.append(input())\n\ndef longestCommonPrefix(strs):\n    if not strs:\n        return \"\"\n    prefix = strs[0]\n    for s in strs[1:]:\n        while not s.startswith(prefix):\n            prefix = prefix[:-1]\n            if not prefix:\n                return \"\"\n    return prefix\n\nprint(longestCommonPrefix(strs))',NULL,1,'2026-09-27 13:08:05','2026-09-28 15:16:03'),(391,112,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const n = parseInt(lines[0]);\n        const nums = lines[1].split(\' \').map(Number);\n        nextPermutation(nums);\n        console.log(nums.join(\' \'));\n        rl.close();\n    }\n});\n\nfunction nextPermutation(nums) {\n    let i = nums.length - 2;\n    while (i >= 0 && nums[i] >= nums[i + 1]) {\n        i--;\n    }\n    if (i >= 0) {\n        let j = nums.length - 1;\n        while (nums[j] <= nums[i]) {\n            j--;\n        }\n        swap(nums, i, j);\n    }\n    reverse(nums, i + 1, nums.length - 1);\n}\n\nfunction swap(nums, i, j) {\n    let tmp = nums[i];\n    nums[i] = nums[j];\n    nums[j] = tmp;\n}\n\nfunction reverse(nums, left, right) {\n    while (left < right) {\n        swap(nums, left, right);\n        left++;\n        right--;\n    }\n}',NULL,1,'2026-09-27 13:08:06','2026-09-28 15:16:03'),(392,111,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n\n    if (n === 0) {\n        console.log(0);\n        return;\n    }\n    if (n === 1) {\n        console.log(nums[0]);\n        return;\n    }\n\n    let prev2 = nums[0];\n    let prev1 = Math.max(nums[0], nums[1]);\n\n    for (let i = 2; i < n; i++) {\n        let current = Math.max(prev1, prev2 + nums[i]);\n        prev2 = prev1;\n        prev1 = current;\n    }\n\n    console.log(prev1);\n});',NULL,1,'2026-09-27 13:08:06','2026-09-28 15:16:03'),(393,113,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0].trim(), 10);\n    const strs = [];\n    for (let i = 0; i < n; i++) {\n        strs.push(lines[i + 1]);\n    }\n    console.log(longestCommonPrefix(strs));\n});\n\nfunction longestCommonPrefix(strs) {\n    if (strs == null || strs.length === 0) {\n        return \"\";\n    }\n    let prefix = strs[0];\n    for (let i = 1; i < strs.length; i++) {\n        while (strs[i].indexOf(prefix) !== 0) {\n            prefix = prefix.substring(0, prefix.length - 1);\n            if (prefix.length === 0) {\n                return \"\";\n            }\n        }\n    }\n    return prefix;\n}',NULL,1,'2026-09-27 13:08:07','2026-09-28 15:16:03'),(394,114,'JAVA','import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m = Integer.parseInt(br.readLine().trim());\n        Deque<Integer> inStack = new ArrayDeque<>();\n        Deque<Integer> outStack = new ArrayDeque<>();\n        StringBuilder sb = new StringBuilder();\n\n        for (int i = 0; i < m; i++) {\n            String line = br.readLine().trim();\n            if (line.startsWith(\"push\")) {\n                int x = Integer.parseInt(line.substring(5).trim());\n                inStack.push(x);\n            } else if (line.equals(\"pop\")) {\n                if (outStack.isEmpty()) {\n                    while (!inStack.isEmpty()) {\n                        outStack.push(inStack.pop());\n                    }\n                }\n                sb.append(outStack.pop()).append(\'\\n\');\n            } else if (line.equals(\"peek\")) {\n                if (outStack.isEmpty()) {\n                    while (!inStack.isEmpty()) {\n                        outStack.push(inStack.pop());\n                    }\n                }\n                sb.append(outStack.peek()).append(\'\\n\');\n            } else if (line.equals(\"empty\")) {\n                sb.append(inStack.isEmpty() && outStack.isEmpty() ? \"true\" : \"false\").append(\'\\n\');\n            }\n        }\n\n        System.out.print(sb);\n    }\n}',NULL,1,'2026-09-27 13:08:08','2026-09-28 15:16:03'),(395,115,'JAVA','import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m = Integer.parseInt(br.readLine().trim());\n        MinStack stack = new MinStack();\n        StringBuilder sb = new StringBuilder();\n\n        for (int i = 0; i < m; i++) {\n            String line = br.readLine().trim();\n            if (line.startsWith(\"push\")) {\n                int val = Integer.parseInt(line.substring(5).trim());\n                stack.push(val);\n            } else if (line.equals(\"pop\")) {\n                stack.pop();\n            } else if (line.equals(\"top\")) {\n                sb.append(stack.top()).append(\'\\n\');\n            } else if (line.equals(\"getMin\")) {\n                sb.append(stack.getMin()).append(\'\\n\');\n            }\n        }\n\n        System.out.print(sb.toString());\n    }\n\n    static class MinStack {\n        private Deque<Integer> stack;\n        private Deque<Integer> minStack;\n\n        public MinStack() {\n            stack = new ArrayDeque<>();\n            minStack = new ArrayDeque<>();\n        }\n\n        public void push(int val) {\n            stack.push(val);\n            if (minStack.isEmpty() || val <= minStack.peek()) {\n                minStack.push(val);\n            }\n        }\n\n        public void pop() {\n            int val = stack.pop();\n            if (val == minStack.peek()) {\n                minStack.pop();\n            }\n        }\n\n        public int top() {\n            return stack.peek();\n        }\n\n        public int getMin() {\n            return minStack.peek();\n        }\n    }\n}',NULL,1,'2026-09-27 13:08:08','2026-09-28 15:16:03'),(396,116,'JAVA','import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int x) { val = x; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        int pVal = Integer.parseInt(sc.nextLine().trim());\n        int qVal = Integer.parseInt(sc.nextLine().trim());\n\n        TreeNode root = buildTree(line);\n        TreeNode p = findNode(root, pVal);\n        TreeNode q = findNode(root, qVal);\n        TreeNode lca = lowestCommonAncestor(root, p, q);\n        System.out.println(lca.val);\n    }\n\n    private static TreeNode buildTree(String line) {\n        String s = line.trim();\n        if (s.startsWith(\"[\")) s = s.substring(1);\n        if (s.endsWith(\"]\")) s = s.substring(0, s.length() - 1);\n        if (s.isEmpty()) return null;\n\n        String[] parts = s.split(\",\");\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode cur = queue.poll();\n            if (i < parts.length) {\n                String leftVal = parts[i++].trim();\n                if (!leftVal.equals(\"null\")) {\n                    cur.left = new TreeNode(Integer.parseInt(leftVal));\n                    queue.offer(cur.left);\n                }\n            }\n            if (i < parts.length) {\n                String rightVal = parts[i++].trim();\n                if (!rightVal.equals(\"null\")) {\n                    cur.right = new TreeNode(Integer.parseInt(rightVal));\n                    queue.offer(cur.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    private static TreeNode findNode(TreeNode root, int val) {\n        if (root == null) return null;\n        if (root.val == val) return root;\n        TreeNode left = findNode(root.left, val);\n        if (left != null) return left;\n        return findNode(root.right, val);\n    }\n\n    private static TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\n        if (root == null || root == p || root == q) return root;\n        TreeNode left = lowestCommonAncestor(root.left, p, q);\n        TreeNode right = lowestCommonAncestor(root.right, p, q);\n        if (left != null && right != null) return root;\n        return left != null ? left : right;\n    }\n}',NULL,1,'2026-09-27 13:08:10','2026-09-28 15:16:03'),(397,114,'CPP','#include <iostream>\n#include <stack>\n#include <string>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int m;\n    cin >> m;\n    stack<int> inStack, outStack;\n    string op;\n\n    while (m--) {\n        cin >> op;\n        if (op == \"push\") {\n            int x;\n            cin >> x;\n            inStack.push(x);\n        } else if (op == \"pop\") {\n            if (outStack.empty()) {\n                while (!inStack.empty()) {\n                    outStack.push(inStack.top());\n                    inStack.pop();\n                }\n            }\n            cout << outStack.top() << \'\\n\';\n            outStack.pop();\n        } else if (op == \"peek\") {\n            if (outStack.empty()) {\n                while (!inStack.empty()) {\n                    outStack.push(inStack.top());\n                    inStack.pop();\n                }\n            }\n            cout << outStack.top() << \'\\n\';\n        } else if (op == \"empty\") {\n            cout << (inStack.empty() && outStack.empty() ? \"true\" : \"false\") << \'\\n\';\n        }\n    }\n\n    return 0;\n}',NULL,1,'2026-09-27 13:08:10','2026-09-28 15:16:03'),(398,115,'CPP','#include <iostream>\n#include <string>\n#include <stack>\nusing namespace std;\n\nclass MinStack {\nprivate:\n    stack<int> st;\n    stack<int> minSt;\npublic:\n    void push(int val) {\n        st.push(val);\n        if (minSt.empty() || val <= minSt.top()) {\n            minSt.push(val);\n        }\n    }\n    void pop() {\n        int val = st.top();\n        st.pop();\n        if (val == minSt.top()) {\n            minSt.pop();\n        }\n    }\n    int top() {\n        return st.top();\n    }\n    int getMin() {\n        return minSt.top();\n    }\n};\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int m;\n    cin >> m;\n    MinStack stack;\n    string op;\n    for (int i = 0; i < m; ++i) {\n        cin >> op;\n        if (op == \"push\") {\n            int val;\n            cin >> val;\n            stack.push(val);\n        } else if (op == \"pop\") {\n            stack.pop();\n        } else if (op == \"top\") {\n            cout << stack.top() << \'\\n\';\n        } else if (op == \"getMin\") {\n            cout << stack.getMin() << \'\\n\';\n        }\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:08:11','2026-09-28 15:16:03'),(399,114,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\n#define MAXN 1000005\n\nint inStack[MAXN], outStack[MAXN];\nint inTop = 0, outTop = 0;\n\nvoid pushIn(int x) {\n    inStack[inTop++] = x;\n}\n\nint popIn() {\n    return inStack[--inTop];\n}\n\nint emptyIn() {\n    return inTop == 0;\n}\n\nvoid pushOut(int x) {\n    outStack[outTop++] = x;\n}\n\nint popOut() {\n    return outStack[--outTop];\n}\n\nint peekOut() {\n    return outStack[outTop - 1];\n}\n\nint emptyOut() {\n    return outTop == 0;\n}\n\nint main() {\n    int m;\n    scanf(\"%d\", &m);\n    getchar();\n\n    char line[100];\n    char output[1000000];\n    int outLen = 0;\n\n    for (int i = 0; i < m; i++) {\n        fgets(line, sizeof(line), stdin);\n        line[strcspn(line, \"\\n\")] = \'\\0\';\n\n        if (strncmp(line, \"push\", 4) == 0) {\n            int x = atoi(line + 5);\n            pushIn(x);\n        } else if (strcmp(line, \"pop\") == 0) {\n            if (emptyOut()) {\n                while (!emptyIn()) {\n                    pushOut(popIn());\n                }\n            }\n            outLen += sprintf(output + outLen, \"%d\\n\", popOut());\n        } else if (strcmp(line, \"peek\") == 0) {\n            if (emptyOut()) {\n                while (!emptyIn()) {\n                    pushOut(popIn());\n                }\n            }\n            outLen += sprintf(output + outLen, \"%d\\n\", peekOut());\n        } else if (strcmp(line, \"empty\") == 0) {\n            outLen += sprintf(output + outLen, \"%s\\n\", (emptyIn() && emptyOut()) ? \"true\" : \"false\");\n        }\n    }\n\n    printf(\"%s\", output);\n    return 0;\n}',NULL,1,'2026-09-27 13:08:13','2026-09-28 15:16:03'),(400,110,'C','#include <stdio.h>\n#include <string.h>\n#include <stdlib.h>\n\nint main(void) {\n    char word1[10005], word2[10005];\n    if (fgets(word1, sizeof(word1), stdin) == NULL) return 0;\n    if (fgets(word2, sizeof(word2), stdin) == NULL) return 0;\n\n    size_t n = strlen(word1);\n    size_t m = strlen(word2);\n    if (n > 0 && word1[n - 1] == \'\\n\') word1[--n] = \'\\0\';\n    if (m > 0 && word2[m - 1] == \'\\n\') word2[--m] = \'\\0\';\n\n    int *prev = (int *)malloc((m + 1) * sizeof(int));\n    int *cur = (int *)malloc((m + 1) * sizeof(int));\n    if (!prev || !cur) return 0;\n\n    for (size_t j = 0; j <= m; ++j) prev[j] = (int)j;\n\n    for (size_t i = 1; i <= n; ++i) {\n        cur[0] = (int)i;\n        for (size_t j = 1; j <= m; ++j) {\n            if (word1[i - 1] == word2[j - 1]) {\n                cur[j] = prev[j - 1];\n            } else {\n                int a = prev[j];\n                int b = cur[j - 1];\n                int c = prev[j - 1];\n                int min = a < b ? a : b;\n                if (c < min) min = c;\n                cur[j] = min + 1;\n            }\n        }\n        int *tmp = prev;\n        prev = cur;\n        cur = tmp;\n    }\n\n    printf(\"%d\\n\", prev[m]);\n\n    free(prev);\n    free(cur);\n    return 0;\n}',NULL,1,'2026-09-27 13:08:14','2026-09-28 15:16:03'),(401,114,'PYTHON','import sys\n\ndef main():\n    input_data = sys.stdin.read().splitlines()\n    m = int(input_data[0].strip())\n    in_stack = []\n    out_stack = []\n    output = []\n\n    for i in range(1, m + 1):\n        line = input_data[i].strip()\n        if line.startswith(\"push\"):\n            x = int(line[5:].strip())\n            in_stack.append(x)\n        elif line == \"pop\":\n            if not out_stack:\n                while in_stack:\n                    out_stack.append(in_stack.pop())\n            output.append(str(out_stack.pop()))\n        elif line == \"peek\":\n            if not out_stack:\n                while in_stack:\n                    out_stack.append(in_stack.pop())\n            output.append(str(out_stack[-1]))\n        elif line == \"empty\":\n            output.append(\"true\" if not in_stack and not out_stack else \"false\")\n\n    sys.stdout.write(\"\\n\".join(output) + (\"\\n\" if output else \"\"))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:08:15','2026-09-28 15:16:03'),(402,110,'PYTHON','word1 = input()\nword2 = input()\nn = len(word1)\nm = len(word2)\ndp = [[0] * (m + 1) for _ in range(n + 1)]\nfor i in range(n + 1):\n    dp[i][0] = i\nfor j in range(m + 1):\n    dp[0][j] = j\nfor i in range(1, n + 1):\n    for j in range(1, m + 1):\n        if word1[i - 1] == word2[j - 1]:\n            dp[i][j] = dp[i - 1][j - 1]\n        else:\n            dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1\nprint(dp[n][m])',NULL,1,'2026-09-27 13:08:16','2026-09-28 15:16:03'),(403,114,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const m = parseInt(lines[0]);\n    const inStack = [];\n    const outStack = [];\n    let output = [];\n\n    for (let i = 1; i <= m; i++) {\n        const line = lines[i];\n        if (line.startsWith(\'push\')) {\n            const x = parseInt(line.substring(5).trim());\n            inStack.push(x);\n        } else if (line === \'pop\') {\n            if (outStack.length === 0) {\n                while (inStack.length > 0) {\n                    outStack.push(inStack.pop());\n                }\n            }\n            output.push(outStack.pop());\n        } else if (line === \'peek\') {\n            if (outStack.length === 0) {\n                while (inStack.length > 0) {\n                    outStack.push(inStack.pop());\n                }\n            }\n            output.push(outStack[outStack.length - 1]);\n        } else if (line === \'empty\') {\n            output.push(inStack.length === 0 && outStack.length === 0 ? \'true\' : \'false\');\n        }\n    }\n\n    process.stdout.write(output.join(\'\\n\') + (output.length > 0 ? \'\\n\' : \'\'));\n});',NULL,1,'2026-09-27 13:08:17','2026-09-28 15:16:03'),(404,115,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct {\n    int *data;\n    int *minData;\n    int top;\n    int minTop;\n    int capacity;\n} MinStack;\n\nMinStack* minStackCreate(int capacity) {\n    MinStack *obj = (MinStack*)malloc(sizeof(MinStack));\n    obj->data = (int*)malloc(sizeof(int) * capacity);\n    obj->minData = (int*)malloc(sizeof(int) * capacity);\n    obj->top = -1;\n    obj->minTop = -1;\n    obj->capacity = capacity;\n    return obj;\n}\n\nvoid minStackPush(MinStack *obj, int val) {\n    obj->data[++obj->top] = val;\n    if (obj->minTop == -1 || val <= obj->minData[obj->minTop]) {\n        obj->minData[++obj->minTop] = val;\n    }\n}\n\nvoid minStackPop(MinStack *obj) {\n    int val = obj->data[obj->top--];\n    if (val == obj->minData[obj->minTop]) {\n        obj->minTop--;\n    }\n}\n\nint minStackTop(MinStack *obj) {\n    return obj->data[obj->top];\n}\n\nint minStackGetMin(MinStack *obj) {\n    return obj->minData[obj->minTop];\n}\n\nvoid minStackFree(MinStack *obj) {\n    free(obj->data);\n    free(obj->minData);\n    free(obj);\n}\n\nint main() {\n    int m;\n    if (scanf(\"%d\", &m) != 1) return 0;\n\n    MinStack *stack = minStackCreate(m + 5);\n\n    char op[20];\n    int val;\n    char output[1000000];\n    int outPos = 0;\n\n    for (int i = 0; i < m; i++) {\n        scanf(\"%s\", op);\n        if (strcmp(op, \"push\") == 0) {\n            scanf(\"%d\", &val);\n            minStackPush(stack, val);\n        } else if (strcmp(op, \"pop\") == 0) {\n            minStackPop(stack);\n        } else if (strcmp(op, \"top\") == 0) {\n            outPos += sprintf(output + outPos, \"%d\\n\", minStackTop(stack));\n        } else if (strcmp(op, \"getMin\") == 0) {\n            outPos += sprintf(output + outPos, \"%d\\n\", minStackGetMin(stack));\n        }\n    }\n\n    fwrite(output, 1, outPos, stdout);\n\n    minStackFree(stack);\n    return 0;\n}',NULL,1,'2026-09-27 13:08:18','2026-09-28 15:16:03'),(405,110,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 2) {\n        const word1 = lines[0];\n        const word2 = lines[1];\n        const n = word1.length;\n        const m = word2.length;\n        const dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));\n        for (let i = 0; i <= n; i++) {\n            dp[i][0] = i;\n        }\n        for (let j = 0; j <= m; j++) {\n            dp[0][j] = j;\n        }\n        for (let i = 1; i <= n; i++) {\n            for (let j = 1; j <= m; j++) {\n                if (word1[i - 1] === word2[j - 1]) {\n                    dp[i][j] = dp[i - 1][j - 1];\n                } else {\n                    dp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1;\n                }\n            }\n        }\n        console.log(dp[n][m]);\n        rl.close();\n    }\n});',NULL,1,'2026-09-27 13:08:18','2026-09-28 15:16:03'),(406,116,'CPP','#include <bits/stdc++.h>\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const string& line) {\n    string s = line;\n    size_t start = s.find_first_not_of(\" \\t\\r\\n\");\n    size_t end = s.find_last_not_of(\" \\t\\r\\n\");\n    if (start == string::npos) return nullptr;\n    s = s.substr(start, end - start + 1);\n\n    if (!s.empty() && s.front() == \'[\') s.erase(s.begin());\n    if (!s.empty() && s.back() == \']\') s.pop_back();\n\n    if (s.empty()) return nullptr;\n\n    vector<string> parts;\n    stringstream ss(s);\n    string item;\n    while (getline(ss, item, \',\')) {\n        size_t l = item.find_first_not_of(\" \\t\\r\\n\");\n        size_t r = item.find_last_not_of(\" \\t\\r\\n\");\n        if (l == string::npos) parts.push_back(\"\");\n        else parts.push_back(item.substr(l, r - l + 1));\n    }\n\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* cur = q.front();\n        q.pop();\n\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i++];\n            if (leftVal != \"null\") {\n                cur->left = new TreeNode(stoi(leftVal));\n                q.push(cur->left);\n            }\n        }\n\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i++];\n            if (rightVal != \"null\") {\n                cur->right = new TreeNode(stoi(rightVal));\n                q.push(cur->right);\n            }\n        }\n    }\n\n    return root;\n}\n\nTreeNode* findNode(TreeNode* root, int val) {\n    if (!root) return nullptr;\n    if (root->val == val) return root;\n    TreeNode* left = findNode(root->left, val);\n    if (left) return left;\n    return findNode(root->right, val);\n}\n\nTreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {\n    if (!root || root == p || root == q) return root;\n    TreeNode* left = lowestCommonAncestor(root->left, p, q);\n    TreeNode* right = lowestCommonAncestor(root->right, p, q);\n    if (left && right) return root;\n    return left ? left : right;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    string line;\n    getline(cin, line);\n\n    string pLine, qLine;\n    getline(cin, pLine);\n    getline(cin, qLine);\n\n    int pVal = stoi(pLine);\n    int qVal = stoi(qLine);\n\n    TreeNode* root = buildTree(line);\n    TreeNode* p = findNode(root, pVal);\n    TreeNode* q = findNode(root, qVal);\n    TreeNode* lca = lowestCommonAncestor(root, p, q);\n\n    cout << lca->val << \'\\n\';\n    return 0;\n}',NULL,1,'2026-09-27 13:08:19','2026-09-28 15:16:03'),(407,115,'PYTHON','import sys\n\nclass MinStack:\n    def __init__(self):\n        self.stack = []\n        self.min_stack = []\n\n    def push(self, val):\n        self.stack.append(val)\n        if not self.min_stack or val <= self.min_stack[-1]:\n            self.min_stack.append(val)\n\n    def pop(self):\n        val = self.stack.pop()\n        if val == self.min_stack[-1]:\n            self.min_stack.pop()\n\n    def top(self):\n        return self.stack[-1]\n\n    def getMin(self):\n        return self.min_stack[-1]\n\ndef main():\n    data = sys.stdin.read().strip().split(\'\\n\')\n    if not data:\n        return\n    m = int(data[0].strip())\n    stack = MinStack()\n    out = []\n    for i in range(1, m + 1):\n        line = data[i].strip()\n        if line.startswith(\"push\"):\n            val = int(line[5:].strip())\n            stack.push(val)\n        elif line == \"pop\":\n            stack.pop()\n        elif line == \"top\":\n            out.append(str(stack.top()))\n        elif line == \"getMin\":\n            out.append(str(stack.getMin()))\n    sys.stdout.write(\'\\n\'.join(out))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:08:20','2026-09-28 15:16:03'),(408,117,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextLine()) return;\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) line = line.substring(1);\n        if (line.endsWith(\"]\")) line = line.substring(0, line.length() - 1);\n        if (line.isEmpty()) {\n            System.out.println(\"true\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        Integer[] nums = new Integer[parts.length];\n        for (int i = 0; i < parts.length; i++) {\n            String s = parts[i].trim();\n            if (s.equals(\"null\")) nums[i] = null;\n            else nums[i] = Integer.parseInt(s);\n        }\n        TreeNode root = buildTree(nums);\n        System.out.println(isValidBST(root));\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left, right;\n        TreeNode(int val) { this.val = val; }\n    }\n\n    static TreeNode buildTree(Integer[] nums) {\n        if (nums.length == 0 || nums[0] == null) return null;\n        TreeNode root = new TreeNode(nums[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < nums.length) {\n            TreeNode node = queue.poll();\n            if (i < nums.length && nums[i] != null) {\n                node.left = new TreeNode(nums[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < nums.length && nums[i] != null) {\n                node.right = new TreeNode(nums[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    static boolean isValidBST(TreeNode root) {\n        return validate(root, null, null);\n    }\n\n    static boolean validate(TreeNode node, Integer min, Integer max) {\n        if (node == null) return true;\n        if (min != null && node.val <= min) return false;\n        if (max != null && node.val >= max) return false;\n        return validate(node.left, min, node.val) && validate(node.right, node.val, max);\n    }\n}',NULL,1,'2026-09-27 13:08:20','2026-09-28 15:16:03'),(409,118,'JAVA','import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) line = line.substring(1, line.length() - 1);\n        String[] parts = line.isEmpty() ? new String[0] : line.split(\",\");\n        TreeNode root = buildTree(parts);\n        root = invertTree(root);\n        System.out.println(serialize(root));\n    }\n\n    private static TreeNode buildTree(String[] parts) {\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode node = queue.poll();\n            if (i < parts.length) {\n                String leftVal = parts[i++].trim();\n                if (!leftVal.equals(\"null\")) {\n                    node.left = new TreeNode(Integer.parseInt(leftVal));\n                    queue.offer(node.left);\n                }\n            }\n            if (i < parts.length) {\n                String rightVal = parts[i++].trim();\n                if (!rightVal.equals(\"null\")) {\n                    node.right = new TreeNode(Integer.parseInt(rightVal));\n                    queue.offer(node.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    private static TreeNode invertTree(TreeNode root) {\n        if (root == null) return null;\n        TreeNode temp = root.left;\n        root.left = invertTree(root.right);\n        root.right = invertTree(temp);\n        return root;\n    }\n\n    private static String serialize(TreeNode root) {\n        if (root == null) return \"[]\";\n        List<String> res = new ArrayList<>();\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        while (!queue.isEmpty()) {\n            TreeNode node = queue.poll();\n            if (node == null) {\n                res.add(\"null\");\n            } else {\n                res.add(String.valueOf(node.val));\n                queue.offer(node.left);\n                queue.offer(node.right);\n            }\n        }\n        while (!res.isEmpty() && res.get(res.size() - 1).equals(\"null\")) {\n            res.remove(res.size() - 1);\n        }\n        return \"[\" + String.join(\",\", res) + \"]\";\n    }\n}',NULL,1,'2026-09-27 13:08:21','2026-09-28 15:16:03'),(410,115,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nclass MinStack {\n    constructor() {\n        this.stack = [];\n        this.minStack = [];\n    }\n\n    push(val) {\n        this.stack.push(val);\n        if (this.minStack.length === 0 || val <= this.minStack[this.minStack.length - 1]) {\n            this.minStack.push(val);\n        }\n    }\n\n    pop() {\n        const val = this.stack.pop();\n        if (val === this.minStack[this.minStack.length - 1]) {\n            this.minStack.pop();\n        }\n    }\n\n    top() {\n        return this.stack[this.stack.length - 1];\n    }\n\n    getMin() {\n        return this.minStack[this.minStack.length - 1];\n    }\n}\n\nlet m = null;\nlet count = 0;\nconst stack = new MinStack();\nconst output = [];\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (m === null) {\n        m = parseInt(line);\n        return;\n    }\n\n    if (count >= m) return;\n    count++;\n\n    if (line.startsWith(\'push\')) {\n        const val = parseInt(line.substring(5).trim());\n        stack.push(val);\n    } else if (line === \'pop\') {\n        stack.pop();\n    } else if (line === \'top\') {\n        output.push(stack.top());\n    } else if (line === \'getMin\') {\n        output.push(stack.getMin());\n    }\n\n    if (count === m) {\n        console.log(output.join(\'\\n\'));\n        rl.close();\n    }\n});',NULL,1,'2026-09-27 13:08:21','2026-09-28 15:16:03'),(411,116,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nTreeNode* createNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nTreeNode* buildTree(char* line) {\n    char* s = line;\n    while (*s == \' \' || *s == \'\\t\') s++;\n    if (*s == \'[\') s++;\n    int len = strlen(s);\n    while (len > 0 && (s[len-1] == \']\' || s[len-1] == \'\\n\' || s[len-1] == \'\\r\' || s[len-1] == \' \' || s[len-1] == \'\\t\')) {\n        s[--len] = \'\\0\';\n    }\n    if (len == 0) return NULL;\n\n    char* parts[10000];\n    int count = 0;\n    char* token = strtok(s, \",\");\n    while (token != NULL) {\n        while (*token == \' \') token++;\n        parts[count++] = token;\n        token = strtok(NULL, \",\");\n    }\n    if (count == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n\n    TreeNode* root = createNode(atoi(parts[0]));\n    TreeNode* queue[10000];\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < count) {\n        TreeNode* cur = queue[front++];\n        if (i < count) {\n            char* leftVal = parts[i++];\n            if (strcmp(leftVal, \"null\") != 0) {\n                cur->left = createNode(atoi(leftVal));\n                queue[rear++] = cur->left;\n            }\n        }\n        if (i < count) {\n            char* rightVal = parts[i++];\n            if (strcmp(rightVal, \"null\") != 0) {\n                cur->right = createNode(atoi(rightVal));\n                queue[rear++] = cur->right;\n            }\n        }\n    }\n    return root;\n}\n\nTreeNode* findNode(TreeNode* root, int val) {\n    if (root == NULL) return NULL;\n    if (root->val == val) return root;\n    TreeNode* left = findNode(root->left, val);\n    if (left != NULL) return left;\n    return findNode(root->right, val);\n}\n\nTreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {\n    if (root == NULL || root == p || root == q) return root;\n    TreeNode* left = lowestCommonAncestor(root->left, p, q);\n    TreeNode* right = lowestCommonAncestor(root->right, p, q);\n    if (left != NULL && right != NULL) return root;\n    return left != NULL ? left : right;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    int pVal, qVal;\n    scanf(\"%d\", &pVal);\n    scanf(\"%d\", &qVal);\n\n    TreeNode* root = buildTree(line);\n    TreeNode* p = findNode(root, pVal);\n    TreeNode* q = findNode(root, qVal);\n    TreeNode* lca = lowestCommonAncestor(root, p, q);\n    printf(\"%d\\n\", lca->val);\n    return 0;\n}',NULL,1,'2026-09-27 13:08:23','2026-09-28 15:16:03'),(412,117,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n#include <climits>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left, *right;\n    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(vector<string>& nums) {\n    if (nums.empty() || nums[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(nums[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)nums.size()) {\n        TreeNode* node = q.front(); q.pop();\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->left = new TreeNode(stoi(nums[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->right = new TreeNode(stoi(nums[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nbool validate(TreeNode* node, long long minVal, long long maxVal) {\n    if (!node) return true;\n    if (node->val <= minVal || node->val >= maxVal) return false;\n    return validate(node->left, minVal, node->val) && validate(node->right, node->val, maxVal);\n}\n\nbool isValidBST(TreeNode* root) {\n    return validate(root, LLONG_MIN, LLONG_MAX);\n}\n\nint main() {\n    string line;\n    if (!getline(cin, line)) return 0;\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) line.pop_back();\n    if (!line.empty() && line.front() == \'[\') line = line.substr(1);\n    if (!line.empty() && line.back() == \']\') line.pop_back();\n    if (line.empty()) {\n        cout << \"true\" << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\");\n        size_t end = token.find_last_not_of(\" \\t\");\n        if (start == string::npos) parts.push_back(\"\");\n        else parts.push_back(token.substr(start, end - start + 1));\n    }\n    TreeNode* root = buildTree(parts);\n    cout << (isValidBST(root) ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:08:23','2026-09-28 15:16:03'),(413,119,'JAVA','import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) line = line.substring(1, line.length() - 1);\n        if (line.isEmpty()) {\n            System.out.println(\"[]\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        TreeNode root = buildTree(parts);\n        List<Integer> res = rightSideView(root);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(res.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    static TreeNode buildTree(String[] parts) {\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode node = queue.poll();\n            if (i < parts.length) {\n                String leftVal = parts[i++].trim();\n                if (!leftVal.equals(\"null\")) {\n                    node.left = new TreeNode(Integer.parseInt(leftVal));\n                    queue.offer(node.left);\n                }\n            }\n            if (i < parts.length) {\n                String rightVal = parts[i++].trim();\n                if (!rightVal.equals(\"null\")) {\n                    node.right = new TreeNode(Integer.parseInt(rightVal));\n                    queue.offer(node.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    static List<Integer> rightSideView(TreeNode root) {\n        List<Integer> res = new ArrayList<>();\n        if (root == null) return res;\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        while (!queue.isEmpty()) {\n            int size = queue.size();\n            for (int i = 0; i < size; i++) {\n                TreeNode node = queue.poll();\n                if (i == size - 1) res.add(node.val);\n                if (node.left != null) queue.offer(node.left);\n                if (node.right != null) queue.offer(node.right);\n            }\n        }\n        return res;\n    }\n}',NULL,1,'2026-09-27 13:08:24','2026-09-28 15:16:03'),(414,116,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, x):\n        self.val = x\n        self.left = None\n        self.right = None\n\ndef build_tree(line):\n    s = line.strip()\n    if s.startswith(\"[\"):\n        s = s[1:]\n    if s.endswith(\"]\"):\n        s = s[:-1]\n    if not s:\n        return None\n    parts = [x.strip() for x in s.split(\",\")]\n    if not parts or parts[0] == \"null\":\n        return None\n    root = TreeNode(int(parts[0]))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        cur = queue.popleft()\n        if i < len(parts):\n            left_val = parts[i]\n            i += 1\n            if left_val != \"null\":\n                cur.left = TreeNode(int(left_val))\n                queue.append(cur.left)\n        if i < len(parts):\n            right_val = parts[i]\n            i += 1\n            if right_val != \"null\":\n                cur.right = TreeNode(int(right_val))\n                queue.append(cur.right)\n    return root\n\ndef find_node(root, val):\n    if root is None:\n        return None\n    if root.val == val:\n        return root\n    left = find_node(root.left, val)\n    if left is not None:\n        return left\n    return find_node(root.right, val)\n\ndef lowest_common_ancestor(root, p, q):\n    if root is None or root is p or root is q:\n        return root\n    left = lowest_common_ancestor(root.left, p, q)\n    right = lowest_common_ancestor(root.right, p, q)\n    if left is not None and right is not None:\n        return root\n    return left if left is not None else right\n\ndef main():\n    line = sys.stdin.readline().strip()\n    p_val = int(sys.stdin.readline().strip())\n    q_val = int(sys.stdin.readline().strip())\n    root = build_tree(line)\n    p = find_node(root, p_val)\n    q = find_node(root, q_val)\n    lca = lowest_common_ancestor(root, p, q)\n    print(lca.val)\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:08:25','2026-09-28 15:16:03'),(415,118,'CPP','#include <bits/stdc++.h>\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const vector<string>& parts) {\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i++];\n            if (leftVal != \"null\") {\n                node->left = new TreeNode(stoi(leftVal));\n                q.push(node->left);\n            }\n        }\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i++];\n            if (rightVal != \"null\") {\n                node->right = new TreeNode(stoi(rightVal));\n                q.push(node->right);\n            }\n        }\n    }\n    return root;\n}\n\nTreeNode* invertTree(TreeNode* root) {\n    if (!root) return nullptr;\n    TreeNode* temp = root->left;\n    root->left = invertTree(root->right);\n    root->right = invertTree(temp);\n    return root;\n}\n\nstring serialize(TreeNode* root) {\n    if (!root) return \"[]\";\n    vector<string> res;\n    queue<TreeNode*> q;\n    q.push(root);\n    while (!q.empty()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (!node) {\n            res.push_back(\"null\");\n        } else {\n            res.push_back(to_string(node->val));\n            q.push(node->left);\n            q.push(node->right);\n        }\n    }\n    while (!res.empty() && res.back() == \"null\") {\n        res.pop_back();\n    }\n    string ans = \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        if (i) ans += \",\";\n        ans += res[i];\n    }\n    ans += \"]\";\n    return ans;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) line.pop_back();\n    if (!line.empty() && line.front() == \'[\') line = line.substr(1, line.size() - 2);\n    vector<string> parts;\n    if (!line.empty()) {\n        stringstream ss(line);\n        string item;\n        while (getline(ss, item, \',\')) {\n            while (!item.empty() && item.front() == \' \') item.erase(item.begin());\n            while (!item.empty() && item.back() == \' \') item.pop_back();\n            parts.push_back(item);\n        }\n    }\n    TreeNode* root = buildTree(parts);\n    root = invertTree(root);\n    cout << serialize(root) << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:08:25','2026-09-28 15:16:03'),(416,117,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdbool.h>\n#include <limits.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nstatic TreeNode* newTreeNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nstatic TreeNode* buildTree(int* nums, int* isNull, int n) {\n    if (n == 0 || isNull[0]) return NULL;\n    TreeNode* root = newTreeNode(nums[0]);\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * n);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < n) {\n        TreeNode* node = queue[front++];\n        if (i < n && !isNull[i]) {\n            node->left = newTreeNode(nums[i]);\n            queue[rear++] = node->left;\n        }\n        i++;\n        if (i < n && !isNull[i]) {\n            node->right = newTreeNode(nums[i]);\n            queue[rear++] = node->right;\n        }\n        i++;\n    }\n    free(queue);\n    return root;\n}\n\nstatic bool validate(TreeNode* node, long long min, long long max) {\n    if (node == NULL) return true;\n    if (node->val <= min) return false;\n    if (node->val >= max) return false;\n    return validate(node->left, min, node->val) && validate(node->right, node->val, max);\n}\n\nstatic bool isValidBST(TreeNode* root) {\n    return validate(root, LLONG_MIN, LLONG_MAX);\n}\n\nint main(void) {\n    char line[1000005];\n    if (!fgets(line, sizeof(line), stdin)) return 0;\n    size_t len = strlen(line);\n    while (len > 0 && (line[len - 1] == \'\\n\' || line[len - 1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    char* s = line;\n    while (*s == \' \' || *s == \'\\t\') s++;\n    if (*s == \'[\') s++;\n    len = strlen(s);\n    while (len > 0 && (s[len - 1] == \' \' || s[len - 1] == \'\\t\')) {\n        s[--len] = \'\\0\';\n    }\n    if (len > 0 && s[len - 1] == \']\') s[--len] = \'\\0\';\n    if (len == 0) {\n        printf(\"true\\n\");\n        return 0;\n    }\n\n    int capacity = 16;\n    int* nums = (int*)malloc(sizeof(int) * capacity);\n    int* isNull = (int*)malloc(sizeof(int) * capacity);\n    int n = 0;\n\n    char* token = strtok(s, \",\");\n    while (token != NULL) {\n        while (*token == \' \' || *token == \'\\t\') token++;\n        size_t tlen = strlen(token);\n        while (tlen > 0 && (token[tlen - 1] == \' \' || token[tlen - 1] == \'\\t\')) {\n            token[--tlen] = \'\\0\';\n        }\n        if (n >= capacity) {\n            capacity *= 2;\n            nums = (int*)realloc(nums, sizeof(int) * capacity);\n            isNull = (int*)realloc(isNull, sizeof(int) * capacity);\n        }\n        if (strcmp(token, \"null\") == 0) {\n            nums[n] = 0;\n            isNull[n] = 1;\n        } else {\n            nums[n] = atoi(token);\n            isNull[n] = 0;\n        }\n        n++;\n        token = strtok(NULL, \",\");\n    }\n\n    TreeNode* root = buildTree(nums, isNull, n);\n    printf(\"%s\\n\", isValidBST(root) ? \"true\" : \"false\");\n\n    free(nums);\n    free(isNull);\n    return 0;\n}',NULL,1,'2026-09-27 13:08:27','2026-09-28 15:16:03'),(417,116,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(line) {\n    let s = line.trim();\n    if (s.startsWith(\'[\')) s = s.substring(1);\n    if (s.endsWith(\']\')) s = s.substring(0, s.length - 1);\n    if (s.length === 0) return null;\n\n    const parts = s.split(\',\');\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n\n    const root = new TreeNode(parseInt(parts[0].trim(), 10));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const cur = queue.shift();\n        if (i < parts.length) {\n            const leftVal = parts[i++].trim();\n            if (leftVal !== \'null\') {\n                cur.left = new TreeNode(parseInt(leftVal, 10));\n                queue.push(cur.left);\n            }\n        }\n        if (i < parts.length) {\n            const rightVal = parts[i++].trim();\n            if (rightVal !== \'null\') {\n                cur.right = new TreeNode(parseInt(rightVal, 10));\n                queue.push(cur.right);\n            }\n        }\n    }\n    return root;\n}\n\nfunction findNode(root, val) {\n    if (root === null) return null;\n    if (root.val === val) return root;\n    const left = findNode(root.left, val);\n    if (left !== null) return left;\n    return findNode(root.right, val);\n}\n\nfunction lowestCommonAncestor(root, p, q) {\n    if (root === null || root === p || root === q) return root;\n    const left = lowestCommonAncestor(root.left, p, q);\n    const right = lowestCommonAncestor(root.right, p, q);\n    if (left !== null && right !== null) return root;\n    return left !== null ? left : right;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nconst lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 3) {\n        rl.close();\n        const treeLine = lines[0].trim();\n        const pVal = parseInt(lines[1].trim(), 10);\n        const qVal = parseInt(lines[2].trim(), 10);\n\n        const root = buildTree(treeLine);\n        const p = findNode(root, pVal);\n        const q = findNode(root, qVal);\n        const lca = lowestCommonAncestor(root, p, q);\n        console.log(lca.val);\n    }\n});',NULL,1,'2026-09-27 13:08:27','2026-09-28 15:16:03'),(418,119,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const vector<string>& parts) {\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i++];\n            if (leftVal != \"null\") {\n                node->left = new TreeNode(stoi(leftVal));\n                q.push(node->left);\n            }\n        }\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i++];\n            if (rightVal != \"null\") {\n                node->right = new TreeNode(stoi(rightVal));\n                q.push(node->right);\n            }\n        }\n    }\n    return root;\n}\n\nvector<int> rightSideView(TreeNode* root) {\n    vector<int> res;\n    if (!root) return res;\n    queue<TreeNode*> q;\n    q.push(root);\n    while (!q.empty()) {\n        int size = q.size();\n        for (int i = 0; i < size; i++) {\n            TreeNode* node = q.front();\n            q.pop();\n            if (i == size - 1) res.push_back(node->val);\n            if (node->left) q.push(node->left);\n            if (node->right) q.push(node->right);\n        }\n    }\n    return res;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) line.pop_back();\n    if (!line.empty() && line.front() == \'[\') line = line.substr(1, line.size() - 2);\n    if (line.empty()) {\n        cout << \"[]\" << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\");\n        size_t end = token.find_last_not_of(\" \\t\");\n        if (start == string::npos) parts.push_back(\"\");\n        else parts.push_back(token.substr(start, end - start + 1));\n    }\n    TreeNode* root = buildTree(parts);\n    vector<int> res = rightSideView(root);\n    cout << \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << res[i];\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:08:28','2026-09-28 15:16:03'),(419,117,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(nums):\n    if not nums or nums[0] is None:\n        return None\n    root = TreeNode(nums[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(nums):\n        node = queue.popleft()\n        if i < len(nums) and nums[i] is not None:\n            node.left = TreeNode(nums[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(nums) and nums[i] is not None:\n            node.right = TreeNode(nums[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef validate(node, min_val, max_val):\n    if node is None:\n        return True\n    if min_val is not None and node.val <= min_val:\n        return False\n    if max_val is not None and node.val >= max_val:\n        return False\n    return validate(node.left, min_val, node.val) and validate(node.right, node.val, max_val)\n\ndef main():\n    line = sys.stdin.readline()\n    if not line:\n        return\n    line = line.strip()\n    if line.startswith(\"[\"):\n        line = line[1:]\n    if line.endswith(\"]\"):\n        line = line[:-1]\n    if line == \"\":\n        print(\"true\")\n        return\n    parts = line.split(\",\")\n    nums = []\n    for s in parts:\n        s = s.strip()\n        if s == \"null\":\n            nums.append(None)\n        else:\n            nums.append(int(s))\n    root = build_tree(nums)\n    print(\"true\" if validate(root, None, None) else \"false\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:08:29','2026-09-28 15:16:03'),(420,120,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int candidate = 0;\n        int count = 0;\n        for (int i = 0; i < n; i++) {\n            int num = sc.nextInt();\n            if (count == 0) {\n                candidate = num;\n                count = 1;\n            } else if (num == candidate) {\n                count++;\n            } else {\n                count--;\n            }\n        }\n        System.out.println(candidate);\n    }\n}',NULL,1,'2026-09-27 13:08:29','2026-09-28 15:16:03'),(421,118,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nTreeNode* createNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nTreeNode* buildTree(char** parts, int partsSize) {\n    if (partsSize == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n    TreeNode* root = createNode(atoi(parts[0]));\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * (partsSize + 1));\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < partsSize) {\n        TreeNode* node = queue[front++];\n        if (i < partsSize) {\n            char* leftVal = parts[i++];\n            if (strcmp(leftVal, \"null\") != 0) {\n                node->left = createNode(atoi(leftVal));\n                queue[rear++] = node->left;\n            }\n        }\n        if (i < partsSize) {\n            char* rightVal = parts[i++];\n            if (strcmp(rightVal, \"null\") != 0) {\n                node->right = createNode(atoi(rightVal));\n                queue[rear++] = node->right;\n            }\n        }\n    }\n    free(queue);\n    return root;\n}\n\nTreeNode* invertTree(TreeNode* root) {\n    if (root == NULL) return NULL;\n    TreeNode* temp = root->left;\n    root->left = invertTree(root->right);\n    root->right = invertTree(temp);\n    return root;\n}\n\nchar* serialize(TreeNode* root) {\n    if (root == NULL) {\n        char* res = (char*)malloc(3);\n        strcpy(res, \"[]\");\n        return res;\n    }\n    int capacity = 1024;\n    char** res = (char**)malloc(sizeof(char*) * capacity);\n    int count = 0;\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * capacity);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    while (front < rear) {\n        TreeNode* node = queue[front++];\n        if (count >= capacity) {\n            capacity *= 2;\n            res = (char**)realloc(res, sizeof(char*) * capacity);\n            queue = (TreeNode**)realloc(queue, sizeof(TreeNode*) * capacity);\n        }\n        if (node == NULL) {\n            res[count] = (char*)malloc(5);\n            strcpy(res[count], \"null\");\n            count++;\n        } else {\n            char* buf = (char*)malloc(16);\n            sprintf(buf, \"%d\", node->val);\n            res[count] = buf;\n            count++;\n            queue[rear++] = node->left;\n            queue[rear++] = node->right;\n        }\n    }\n    while (count > 0 && strcmp(res[count - 1], \"null\") == 0) {\n        count--;\n    }\n    int totalLen = 3;\n    for (int i = 0; i < count; i++) {\n        totalLen += strlen(res[i]) + 1;\n    }\n    char* result = (char*)malloc(totalLen);\n    result[0] = \'\\0\';\n    strcat(result, \"[\");\n    for (int i = 0; i < count; i++) {\n        if (i > 0) strcat(result, \",\");\n        strcat(result, res[i]);\n    }\n    strcat(result, \"]\");\n    for (int i = 0; i < count; i++) free(res[i]);\n    free(res);\n    free(queue);\n    return result;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    char* start = line;\n    while (*start == \' \' || *start == \'\\t\') start++;\n    int slen = strlen(start);\n    while (slen > 0 && (start[slen-1] == \' \' || start[slen-1] == \'\\t\')) {\n        start[--slen] = \'\\0\';\n    }\n    if (slen >= 2 && start[0] == \'[\') {\n        start[slen-1] = \'\\0\';\n        start++;\n    }\n    char** parts = (char**)malloc(sizeof(char*) * 100000);\n    int partsSize = 0;\n    if (strlen(start) > 0) {\n        char* token = strtok(start, \",\");\n        while (token != NULL) {\n            while (*token == \' \') token++;\n            int tlen = strlen(token);\n            while (tlen > 0 && token[tlen-1] == \' \') token[--tlen] = \'\\0\';\n            parts[partsSize++] = token;\n            token = strtok(NULL, \",\");\n        }\n    }\n    TreeNode* root = buildTree(parts, partsSize);\n    root = invertTree(root);\n    char* output = serialize(root);\n    printf(\"%s\\n\", output);\n    free(output);\n    free(parts);\n    return 0;\n}',NULL,1,'2026-09-27 13:08:30','2026-09-28 15:16:03'),(422,117,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (input) => {\n    let line = input.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1);\n    if (line.endsWith(\']\')) line = line.substring(0, line.length - 1);\n    if (line.length === 0) {\n        console.log(\'true\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const nums = parts.map(s => {\n        s = s.trim();\n        return s === \'null\' ? null : parseInt(s, 10);\n    });\n    const root = buildTree(nums);\n    console.log(isValidBST(root));\n    rl.close();\n});\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(nums) {\n    if (nums.length === 0 || nums[0] === null) return null;\n    const root = new TreeNode(nums[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < nums.length) {\n        const node = queue.shift();\n        if (i < nums.length && nums[i] !== null) {\n            node.left = new TreeNode(nums[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < nums.length && nums[i] !== null) {\n            node.right = new TreeNode(nums[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction isValidBST(root) {\n    return validate(root, null, null);\n}\n\nfunction validate(node, min, max) {\n    if (node === null) return true;\n    if (min !== null && node.val <= min) return false;\n    if (max !== null && node.val >= max) return false;\n    return validate(node.left, min, node.val) && validate(node.right, node.val, max);\n}',NULL,1,'2026-09-27 13:08:31','2026-09-28 15:16:03'),(423,120,'CPP','#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int candidate = 0;\n    int count = 0;\n    for (int i = 0; i < n; i++) {\n        int num;\n        cin >> num;\n        if (count == 0) {\n            candidate = num;\n            count = 1;\n        } else if (num == candidate) {\n            count++;\n        } else {\n            count--;\n        }\n    }\n    cout << candidate << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:08:32','2026-09-28 15:16:03'),(424,118,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(parts):\n    if not parts or parts[0].strip() == \"null\":\n        return None\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts):\n            left_val = parts[i].strip()\n            i += 1\n            if left_val != \"null\":\n                node.left = TreeNode(int(left_val))\n                queue.append(node.left)\n        if i < len(parts):\n            right_val = parts[i].strip()\n            i += 1\n            if right_val != \"null\":\n                node.right = TreeNode(int(right_val))\n                queue.append(node.right)\n    return root\n\ndef invert_tree(root):\n    if root is None:\n        return None\n    root.left, root.right = invert_tree(root.right), invert_tree(root.left)\n    return root\n\ndef serialize(root):\n    if root is None:\n        return \"[]\"\n    res = []\n    queue = deque([root])\n    while queue:\n        node = queue.popleft()\n        if node is None:\n            res.append(\"null\")\n        else:\n            res.append(str(node.val))\n            queue.append(node.left)\n            queue.append(node.right)\n    while res and res[-1] == \"null\":\n        res.pop()\n    return \"[\" + \",\".join(res) + \"]\"\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:-1]\n    parts = [] if line == \"\" else line.split(\",\")\n    root = build_tree(parts)\n    root = invert_tree(root)\n    print(serialize(root))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:08:32','2026-09-28 15:16:03'),(425,119,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\ntypedef struct {\n    TreeNode **data;\n    int front;\n    int rear;\n    int size;\n    int capacity;\n} Queue;\n\nQueue* createQueue(int capacity) {\n    Queue *q = (Queue*)malloc(sizeof(Queue));\n    q->data = (TreeNode**)malloc(sizeof(TreeNode*) * capacity);\n    q->front = 0;\n    q->rear = 0;\n    q->size = 0;\n    q->capacity = capacity;\n    return q;\n}\n\nvoid enqueue(Queue *q, TreeNode *node) {\n    if (q->size == q->capacity) {\n        q->capacity *= 2;\n        q->data = (TreeNode**)realloc(q->data, sizeof(TreeNode*) * q->capacity);\n    }\n    q->data[q->rear] = node;\n    q->rear = (q->rear + 1) % q->capacity;\n    q->size++;\n}\n\nTreeNode* dequeue(Queue *q) {\n    if (q->size == 0) return NULL;\n    TreeNode *node = q->data[q->front];\n    q->front = (q->front + 1) % q->capacity;\n    q->size--;\n    return node;\n}\n\nint isEmpty(Queue *q) {\n    return q->size == 0;\n}\n\nvoid freeQueue(Queue *q) {\n    free(q->data);\n    free(q);\n}\n\nTreeNode* buildTree(char **parts, int partsSize) {\n    if (partsSize == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n    TreeNode *root = (TreeNode*)malloc(sizeof(TreeNode));\n    root->val = atoi(parts[0]);\n    root->left = NULL;\n    root->right = NULL;\n    \n    Queue *queue = createQueue(partsSize);\n    enqueue(queue, root);\n    int i = 1;\n    while (!isEmpty(queue) && i < partsSize) {\n        TreeNode *node = dequeue(queue);\n        if (i < partsSize) {\n            char *leftVal = parts[i++];\n            if (strcmp(leftVal, \"null\") != 0) {\n                node->left = (TreeNode*)malloc(sizeof(TreeNode));\n                node->left->val = atoi(leftVal);\n                node->left->left = NULL;\n                node->left->right = NULL;\n                enqueue(queue, node->left);\n            }\n        }\n        if (i < partsSize) {\n            char *rightVal = parts[i++];\n            if (strcmp(rightVal, \"null\") != 0) {\n                node->right = (TreeNode*)malloc(sizeof(TreeNode));\n                node->right->val = atoi(rightVal);\n                node->right->left = NULL;\n                node->right->right = NULL;\n                enqueue(queue, node->right);\n            }\n        }\n    }\n    freeQueue(queue);\n    return root;\n}\n\nint* rightSideView(TreeNode *root, int *returnSize) {\n    *returnSize = 0;\n    if (root == NULL) return NULL;\n    \n    int *res = (int*)malloc(sizeof(int) * 1000);\n    Queue *queue = createQueue(1000);\n    enqueue(queue, root);\n    \n    while (!isEmpty(queue)) {\n        int size = queue->size;\n        for (int i = 0; i < size; i++) {\n            TreeNode *node = dequeue(queue);\n            if (i == size - 1) {\n                res[(*returnSize)++] = node->val;\n            }\n            if (node->left != NULL) enqueue(queue, node->left);\n            if (node->right != NULL) enqueue(queue, node->right);\n        }\n    }\n    freeQueue(queue);\n    return res;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    \n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    \n    if (len > 0 && line[0] == \'[\') {\n        memmove(line, line + 1, len - 1);\n        len--;\n        line[len] = \'\\0\';\n    }\n    if (len > 0 && line[len-1] == \']\') {\n        line[--len] = \'\\0\';\n    }\n    \n    if (len == 0) {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    \n    char *parts[10000];\n    int partsSize = 0;\n    char *token = strtok(line, \",\");\n    while (token != NULL) {\n        while (*token == \' \') token++;\n        char *end = token + strlen(token) - 1;\n        while (end > token && *end == \' \') *end-- = \'\\0\';\n        parts[partsSize++] = token;\n        token = strtok(NULL, \",\");\n    }\n    \n    TreeNode *root = buildTree(parts, partsSize);\n    int returnSize = 0;\n    int *res = rightSideView(root, &returnSize);\n    \n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", res[i]);\n    }\n    printf(\"]\\n\");\n    \n    free(res);\n    return 0;\n}',NULL,1,'2026-09-27 13:08:33','2026-09-28 15:16:03'),(426,120,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int candidate = 0;\n    int count = 0;\n    for (int i = 0; i < n; i++) {\n        int num;\n        scanf(\"%d\", &num);\n        if (count == 0) {\n            candidate = num;\n            count = 1;\n        } else if (num == candidate) {\n            count++;\n        } else {\n            count--;\n        }\n    }\n    printf(\"%d\\n\", candidate);\n    return 0;\n}',NULL,1,'2026-09-27 13:08:33','2026-09-28 15:16:03'),(427,121,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String num1 = sc.nextLine().trim();\n        String num2 = sc.nextLine().trim();\n        System.out.println(addStrings(num1, num2));\n    }\n\n    public static String addStrings(String num1, String num2) {\n        StringBuilder sb = new StringBuilder();\n        int i = num1.length() - 1;\n        int j = num2.length() - 1;\n        int carry = 0;\n\n        while (i >= 0 || j >= 0 || carry != 0) {\n            int x = i >= 0 ? num1.charAt(i) - \'0\' : 0;\n            int y = j >= 0 ? num2.charAt(j) - \'0\' : 0;\n            int sum = x + y + carry;\n            sb.append(sum % 10);\n            carry = sum / 10;\n            i--;\n            j--;\n        }\n\n        return sb.reverse().toString();\n    }\n}',NULL,1,'2026-09-27 13:08:33','2026-09-28 15:16:03'),(428,118,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(parts) {\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n    const root = new TreeNode(parseInt(parts[0].trim(), 10));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length) {\n            const leftVal = parts[i++].trim();\n            if (leftVal !== \'null\') {\n                node.left = new TreeNode(parseInt(leftVal, 10));\n                queue.push(node.left);\n            }\n        }\n        if (i < parts.length) {\n            const rightVal = parts[i++].trim();\n            if (rightVal !== \'null\') {\n                node.right = new TreeNode(parseInt(rightVal, 10));\n                queue.push(node.right);\n            }\n        }\n    }\n    return root;\n}\n\nfunction invertTree(root) {\n    if (root === null) return null;\n    const temp = root.left;\n    root.left = invertTree(root.right);\n    root.right = invertTree(temp);\n    return root;\n}\n\nfunction serialize(root) {\n    if (root === null) return \'[]\';\n    const res = [];\n    const queue = [root];\n    while (queue.length > 0) {\n        const node = queue.shift();\n        if (node === null) {\n            res.push(\'null\');\n        } else {\n            res.push(String(node.val));\n            queue.push(node.left);\n            queue.push(node.right);\n        }\n    }\n    while (res.length > 0 && res[res.length - 1] === \'null\') {\n        res.pop();\n    }\n    return \'[\' + res.join(\',\') + \']\';\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1, line.length - 1);\n    const parts = line.length === 0 ? [] : line.split(\',\');\n    let root = buildTree(parts);\n    root = invertTree(root);\n    console.log(serialize(root));\n    rl.close();\n});',NULL,1,'2026-09-27 13:08:34','2026-09-28 15:16:03'),(429,120,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\ncandidate = 0\ncount = 0\nfor num in nums:\n    if count == 0:\n        candidate = num\n        count = 1\n    elif num == candidate:\n        count += 1\n    else:\n        count -= 1\nprint(candidate)',NULL,1,'2026-09-27 13:08:34','2026-09-28 15:16:03'),(430,119,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(parts):\n    if not parts or parts[0].strip() == \"null\":\n        return None\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts):\n            left_val = parts[i].strip()\n            i += 1\n            if left_val != \"null\":\n                node.left = TreeNode(int(left_val))\n                queue.append(node.left)\n        if i < len(parts):\n            right_val = parts[i].strip()\n            i += 1\n            if right_val != \"null\":\n                node.right = TreeNode(int(right_val))\n                queue.append(node.right)\n    return root\n\ndef right_side_view(root):\n    res = []\n    if root is None:\n        return res\n    queue = deque([root])\n    while queue:\n        size = len(queue)\n        for i in range(size):\n            node = queue.popleft()\n            if i == size - 1:\n                res.append(node.val)\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n    return res\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:-1]\n    if not line:\n        print(\"[]\")\n        return\n    parts = line.split(\",\")\n    root = build_tree(parts)\n    res = right_side_view(root)\n    print(\"[\" + \",\".join(map(str, res)) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:08:35','2026-09-28 15:16:03'),(431,120,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(/\\s+/).map(Number);\n    let candidate = 0;\n    let count = 0;\n    for (let i = 0; i < n; i++) {\n        const num = nums[i];\n        if (count === 0) {\n            candidate = num;\n            count = 1;\n        } else if (num === candidate) {\n            count++;\n        } else {\n            count--;\n        }\n    }\n    console.log(candidate);\n});',NULL,1,'2026-09-27 13:08:36','2026-09-28 15:16:03'),(432,121,'CPP','#include <iostream>\n#include <string>\n#include <algorithm>\n\nusing namespace std;\n\nstring addStrings(string num1, string num2) {\n    string result;\n    int i = num1.length() - 1;\n    int j = num2.length() - 1;\n    int carry = 0;\n\n    while (i >= 0 || j >= 0 || carry != 0) {\n        int x = i >= 0 ? num1[i] - \'0\' : 0;\n        int y = j >= 0 ? num2[j] - \'0\' : 0;\n        int sum = x + y + carry;\n        result.push_back(\'0\' + sum % 10);\n        carry = sum / 10;\n        i--;\n        j--;\n    }\n\n    reverse(result.begin(), result.end());\n    return result;\n}\n\nint main() {\n    string num1, num2;\n    getline(cin, num1);\n    getline(cin, num2);\n\n    while (!num1.empty() && (num1.back() == \'\\r\' || num1.back() == \'\\n\' || num1.back() == \' \')) {\n        num1.pop_back();\n    }\n    while (!num2.empty() && (num2.back() == \'\\r\' || num2.back() == \'\\n\' || num2.back() == \' \')) {\n        num2.pop_back();\n    }\n\n    cout << addStrings(num1, num2) << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:08:36','2026-09-28 15:16:03'),(433,122,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (sc.hasNextLine()) {\n            String s = sc.nextLine();\n            System.out.println(myAtoi(s));\n        }\n    }\n\n    public static int myAtoi(String s) {\n        int i = 0, n = s.length();\n        while (i < n && s.charAt(i) == \' \') {\n            i++;\n        }\n        int sign = 1;\n        if (i < n && (s.charAt(i) == \'+\' || s.charAt(i) == \'-\')) {\n            sign = s.charAt(i) == \'-\' ? -1 : 1;\n            i++;\n        }\n        int result = 0;\n        while (i < n && Character.isDigit(s.charAt(i))) {\n            int digit = s.charAt(i) - \'0\';\n            if (result > (Integer.MAX_VALUE - digit) / 10) {\n                return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;\n            }\n            result = result * 10 + digit;\n            i++;\n        }\n        return sign * result;\n    }\n}',NULL,1,'2026-09-27 13:08:36','2026-09-28 15:16:03'),(434,119,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(parts) {\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n    const root = new TreeNode(parseInt(parts[0].trim()));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length) {\n            const leftVal = parts[i++].trim();\n            if (leftVal !== \'null\') {\n                node.left = new TreeNode(parseInt(leftVal));\n                queue.push(node.left);\n            }\n        }\n        if (i < parts.length) {\n            const rightVal = parts[i++].trim();\n            if (rightVal !== \'null\') {\n                node.right = new TreeNode(parseInt(rightVal));\n                queue.push(node.right);\n            }\n        }\n    }\n    return root;\n}\n\nfunction rightSideView(root) {\n    const res = [];\n    if (root === null) return res;\n    const queue = [root];\n    while (queue.length > 0) {\n        const size = queue.length;\n        for (let i = 0; i < size; i++) {\n            const node = queue.shift();\n            if (i === size - 1) res.push(node.val);\n            if (node.left !== null) queue.push(node.left);\n            if (node.right !== null) queue.push(node.right);\n        }\n    }\n    return res;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1, line.length - 1);\n    if (line.length === 0) {\n        console.log(\'[]\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const root = buildTree(parts);\n    const res = rightSideView(root);\n    console.log(\'[\' + res.join(\',\') + \']\');\n    rl.close();\n});',NULL,1,'2026-09-27 13:08:37','2026-09-28 15:16:03'),(435,123,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        String s = scanner.nextLine();\n        int left = 0, right = s.length() - 1;\n        while (left < right) {\n            while (left < right && !Character.isLetterOrDigit(s.charAt(left))) {\n                left++;\n            }\n            while (left < right && !Character.isLetterOrDigit(s.charAt(right))) {\n                right--;\n            }\n            if (Character.toLowerCase(s.charAt(left)) != Character.toLowerCase(s.charAt(right))) {\n                System.out.println(\"false\");\n                return;\n            }\n            left++;\n            right--;\n        }\n        System.out.println(\"true\");\n    }\n}',NULL,1,'2026-09-27 13:08:38','2026-09-28 15:16:03'),(436,121,'C','#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    char num1[100005], num2[100005];\n    char result[100010];\n    if (scanf(\"%s\", num1) != 1) return 0;\n    if (scanf(\"%s\", num2) != 1) return 0;\n\n    int i = (int)strlen(num1) - 1;\n    int j = (int)strlen(num2) - 1;\n    int carry = 0;\n    int k = 0;\n\n    while (i >= 0 || j >= 0 || carry != 0) {\n        int x = i >= 0 ? num1[i] - \'0\' : 0;\n        int y = j >= 0 ? num2[j] - \'0\' : 0;\n        int sum = x + y + carry;\n        result[k++] = (char)(\'0\' + sum % 10);\n        carry = sum / 10;\n        i--;\n        j--;\n    }\n\n    for (int left = 0, right = k - 1; left < right; left++, right--) {\n        char tmp = result[left];\n        result[left] = result[right];\n        result[right] = tmp;\n    }\n    result[k] = \'\\0\';\n\n    printf(\"%s\\n\", result);\n    return 0;\n}',NULL,1,'2026-09-27 13:08:38','2026-09-28 15:16:03'),(437,122,'CPP','#include <iostream>\n#include <string>\n#include <climits>\n\nint myAtoi(const std::string& s) {\n    int i = 0, n = s.length();\n    while (i < n && s[i] == \' \') {\n        i++;\n    }\n    int sign = 1;\n    if (i < n && (s[i] == \'+\' || s[i] == \'-\')) {\n        sign = (s[i] == \'-\') ? -1 : 1;\n        i++;\n    }\n    int result = 0;\n    while (i < n && s[i] >= \'0\' && s[i] <= \'9\') {\n        int digit = s[i] - \'0\';\n        if (result > (INT_MAX - digit) / 10) {\n            return sign == 1 ? INT_MAX : INT_MIN;\n        }\n        result = result * 10 + digit;\n        i++;\n    }\n    return sign * result;\n}\n\nint main() {\n    std::string s;\n    if (std::getline(std::cin, s)) {\n        std::cout << myAtoi(s) << std::endl;\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:08:39','2026-09-28 15:16:03'),(438,124,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] matrix = new int[n][n];\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                matrix[i][j] = sc.nextInt();\n            }\n        }\n\n        for (int i = 0; i < n / 2; i++) {\n            for (int j = i; j < n - 1 - i; j++) {\n                int temp = matrix[i][j];\n                matrix[i][j] = matrix[n - 1 - j][i];\n                matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j];\n                matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i];\n                matrix[j][n - 1 - i] = temp;\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                sb.append(matrix[i][j]);\n                if (j < n - 1) {\n                    sb.append(\' \');\n                }\n            }\n            sb.append(\'\\n\');\n        }\n        System.out.print(sb);\n    }\n}',NULL,1,'2026-09-27 13:08:39','2026-09-28 15:16:03'),(439,123,'CPP','#include <iostream>\n#include <string>\n#include <cctype>\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n    int left = 0, right = (int)s.length() - 1;\n    while (left < right) {\n        while (left < right && !isalnum((unsigned char)s[left])) {\n            left++;\n        }\n        while (left < right && !isalnum((unsigned char)s[right])) {\n            right--;\n        }\n        if (tolower((unsigned char)s[left]) != tolower((unsigned char)s[right])) {\n            cout << \"false\" << endl;\n            return 0;\n        }\n        left++;\n        right--;\n    }\n    cout << \"true\" << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:08:40','2026-09-28 15:16:03'),(440,121,'PYTHON','import sys\n\ndef addStrings(num1, num2):\n    i, j = len(num1) - 1, len(num2) - 1\n    carry = 0\n    res = []\n    while i >= 0 or j >= 0 or carry:\n        x = int(num1[i]) if i >= 0 else 0\n        y = int(num2[j]) if j >= 0 else 0\n        s = x + y + carry\n        res.append(str(s % 10))\n        carry = s // 10\n        i -= 1\n        j -= 1\n    return \'\'.join(reversed(res))\n\ndef main():\n    num1 = sys.stdin.readline().strip()\n    num2 = sys.stdin.readline().strip()\n    print(addStrings(num1, num2))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:08:40','2026-09-28 15:16:03'),(441,122,'C','#include <stdio.h>\n#include <limits.h>\n\nint myAtoi(const char *s) {\n    int i = 0;\n    while (s[i] == \' \') {\n        i++;\n    }\n\n    int sign = 1;\n    if (s[i] == \'+\' || s[i] == \'-\') {\n        sign = (s[i] == \'-\') ? -1 : 1;\n        i++;\n    }\n\n    int result = 0;\n    while (s[i] >= \'0\' && s[i] <= \'9\') {\n        int digit = s[i] - \'0\';\n        if (result > (INT_MAX - digit) / 10) {\n            return sign == 1 ? INT_MAX : INT_MIN;\n        }\n        result = result * 10 + digit;\n        i++;\n    }\n\n    return sign * result;\n}\n\nint main(void) {\n    char s[100000];\n    if (fgets(s, sizeof(s), stdin)) {\n        int i = 0;\n        while (s[i] != \'\\0\' && s[i] != \'\\n\') {\n            i++;\n        }\n        s[i] = \'\\0\';\n        printf(\"%d\\n\", myAtoi(s));\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:08:41','2026-09-28 15:16:03'),(442,121,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\n\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        console.log(addStrings(lines[0], lines[1]));\n        rl.close();\n    }\n});\n\nfunction addStrings(num1, num2) {\n    let sb = [];\n    let i = num1.length - 1;\n    let j = num2.length - 1;\n    let carry = 0;\n\n    while (i >= 0 || j >= 0 || carry !== 0) {\n        let x = i >= 0 ? num1.charCodeAt(i) - \'0\'.charCodeAt(0) : 0;\n        let y = j >= 0 ? num2.charCodeAt(j) - \'0\'.charCodeAt(0) : 0;\n        let sum = x + y + carry;\n        sb.push(sum % 10);\n        carry = Math.floor(sum / 10);\n        i--;\n        j--;\n    }\n\n    return sb.reverse().join(\'\');\n}',NULL,1,'2026-09-27 13:08:41','2026-09-28 15:16:03'),(443,123,'C','#include <stdio.h>\n#include <ctype.h>\n#include <string.h>\n\nint main() {\n    char s[100005];\n    if (fgets(s, sizeof(s), stdin) == NULL) {\n        return 0;\n    }\n    size_t len = strlen(s);\n    if (len > 0 && s[len - 1] == \'\\n\') {\n        s[len - 1] = \'\\0\';\n        len--;\n    }\n\n    int left = 0, right = (int)len - 1;\n    while (left < right) {\n        while (left < right && !isalnum((unsigned char)s[left])) {\n            left++;\n        }\n        while (left < right && !isalnum((unsigned char)s[right])) {\n            right--;\n        }\n        if (tolower((unsigned char)s[left]) != tolower((unsigned char)s[right])) {\n            printf(\"false\\n\");\n            return 0;\n        }\n        left++;\n        right--;\n    }\n    printf(\"true\\n\");\n    return 0;\n}',NULL,1,'2026-09-27 13:08:42','2026-09-28 15:16:03'),(444,124,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> matrix(n, vector<int>(n));\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            cin >> matrix[i][j];\n        }\n    }\n\n    for (int i = 0; i < n / 2; i++) {\n        for (int j = i; j < n - 1 - i; j++) {\n            int temp = matrix[i][j];\n            matrix[i][j] = matrix[n - 1 - j][i];\n            matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j];\n            matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i];\n            matrix[j][n - 1 - i] = temp;\n        }\n    }\n\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            cout << matrix[i][j];\n            if (j < n - 1) {\n                cout << \' \';\n            }\n        }\n        cout << \'\\n\';\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:08:42','2026-09-28 15:16:03'),(445,122,'PYTHON','import sys\n\ndef myAtoi(s: str) -> int:\n    i, n = 0, len(s)\n    while i < n and s[i] == \' \':\n        i += 1\n    sign = 1\n    if i < n and (s[i] == \'+\' or s[i] == \'-\'):\n        sign = -1 if s[i] == \'-\' else 1\n        i += 1\n    result = 0\n    while i < n and s[i].isdigit():\n        digit = ord(s[i]) - ord(\'0\')\n        if result > (2**31 - 1 - digit) // 10:\n            return 2**31 - 1 if sign == 1 else -2**31\n        result = result * 10 + digit\n        i += 1\n    return sign * result\n\nif __name__ == \"__main__\":\n    line = sys.stdin.readline()\n    if line:\n        s = line.rstrip(\'\\n\')\n        print(myAtoi(s))',NULL,1,'2026-09-27 13:08:43','2026-09-28 15:16:03'),(446,125,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        for (int i = 0; i < n; i++) {\n            while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {\n                int temp = nums[nums[i] - 1];\n                nums[nums[i] - 1] = nums[i];\n                nums[i] = temp;\n            }\n        }\n        for (int i = 0; i < n; i++) {\n            if (nums[i] != i + 1) {\n                System.out.println(i + 1);\n                return;\n            }\n        }\n        System.out.println(n + 1);\n    }\n}',NULL,1,'2026-09-27 13:08:43','2026-09-28 15:16:03'),(447,123,'PYTHON','s = input()\nleft, right = 0, len(s) - 1\nwhile left < right:\n    while left < right and not s[left].isalnum():\n        left += 1\n    while left < right and not s[right].isalnum():\n        right -= 1\n    if s[left].lower() != s[right].lower():\n        print(\"false\")\n        break\n    left += 1\n    right -= 1\nelse:\n    print(\"true\")',NULL,1,'2026-09-27 13:08:43','2026-09-28 15:16:03'),(448,122,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    console.log(myAtoi(s));\n    rl.close();\n});\n\nfunction myAtoi(s) {\n    let i = 0, n = s.length;\n    while (i < n && s[i] === \' \') {\n        i++;\n    }\n    let sign = 1;\n    if (i < n && (s[i] === \'+\' || s[i] === \'-\')) {\n        sign = s[i] === \'-\' ? -1 : 1;\n        i++;\n    }\n    let result = 0;\n    while (i < n && s[i] >= \'0\' && s[i] <= \'9\') {\n        let digit = s.charCodeAt(i) - \'0\'.charCodeAt(0);\n        if (result > (2147483647 - digit) / 10) {\n            return sign === 1 ? 2147483647 : -2147483648;\n        }\n        result = result * 10 + digit;\n        i++;\n    }\n    return sign * result;\n}',NULL,1,'2026-09-27 13:08:45','2026-09-28 15:16:03'),(449,123,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    let left = 0, right = s.length - 1;\n    while (left < right) {\n        while (left < right && !/[a-zA-Z0-9]/.test(s[left])) {\n            left++;\n        }\n        while (left < right && !/[a-zA-Z0-9]/.test(s[right])) {\n            right--;\n        }\n        if (s[left].toLowerCase() !== s[right].toLowerCase()) {\n            console.log(\"false\");\n            rl.close();\n            return;\n        }\n        left++;\n        right--;\n    }\n    console.log(\"true\");\n    rl.close();\n});',NULL,1,'2026-09-27 13:08:45','2026-09-28 15:16:03'),(450,124,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n\n    int **matrix = (int **)malloc(n * sizeof(int *));\n    for (int i = 0; i < n; i++) {\n        matrix[i] = (int *)malloc(n * sizeof(int));\n        for (int j = 0; j < n; j++) {\n            scanf(\"%d\", &matrix[i][j]);\n        }\n    }\n\n    for (int i = 0; i < n / 2; i++) {\n        for (int j = i; j < n - 1 - i; j++) {\n            int temp = matrix[i][j];\n            matrix[i][j] = matrix[n - 1 - j][i];\n            matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j];\n            matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i];\n            matrix[j][n - 1 - i] = temp;\n        }\n    }\n\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            printf(\"%d\", matrix[i][j]);\n            if (j < n - 1) {\n                printf(\" \");\n            }\n        }\n        printf(\"\\n\");\n    }\n\n    for (int i = 0; i < n; i++) {\n        free(matrix[i]);\n    }\n    free(matrix);\n\n    return 0;\n}',NULL,1,'2026-09-27 13:08:45','2026-09-28 15:16:03'),(451,125,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    for (int i = 0; i < n; i++) {\n        while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {\n            int temp = nums[nums[i] - 1];\n            nums[nums[i] - 1] = nums[i];\n            nums[i] = temp;\n        }\n    }\n    for (int i = 0; i < n; i++) {\n        if (nums[i] != i + 1) {\n            cout << i + 1 << endl;\n            return 0;\n        }\n    }\n    cout << n + 1 << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:08:45','2026-09-28 15:16:03'),(452,124,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    matrix = []\n    idx = 1\n    for i in range(n):\n        row = []\n        for j in range(n):\n            row.append(int(data[idx]))\n            idx += 1\n        matrix.append(row)\n\n    for i in range(n // 2):\n        for j in range(i, n - 1 - i):\n            temp = matrix[i][j]\n            matrix[i][j] = matrix[n - 1 - j][i]\n            matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j]\n            matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i]\n            matrix[j][n - 1 - i] = temp\n\n    out = []\n    for i in range(n):\n        out.append(\' \'.join(map(str, matrix[i])))\n    sys.stdout.write(\'\\n\'.join(out) + \'\\n\')\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:08:46','2026-09-28 15:16:03'),(453,126,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        int maxProd = nums[0];\n        int minProd = nums[0];\n        int result = nums[0];\n\n        for (int i = 1; i < n; i++) {\n            int cur = nums[i];\n            int tempMax = Math.max(cur, Math.max(maxProd * cur, minProd * cur));\n            int tempMin = Math.min(cur, Math.min(maxProd * cur, minProd * cur));\n            maxProd = tempMax;\n            minProd = tempMin;\n            result = Math.max(result, maxProd);\n        }\n\n        System.out.println(result);\n    }\n}',NULL,1,'2026-09-27 13:08:47','2026-09-28 15:16:03'),(454,125,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    for (int i = 0; i < n; i++) {\n        while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {\n            int temp = nums[nums[i] - 1];\n            nums[nums[i] - 1] = nums[i];\n            nums[i] = temp;\n        }\n    }\n    for (int i = 0; i < n; i++) {\n        if (nums[i] != i + 1) {\n            printf(\"%d\\n\", i + 1);\n            return 0;\n        }\n    }\n    printf(\"%d\\n\", n + 1);\n    return 0;\n}',NULL,1,'2026-09-27 13:08:47','2026-09-28 15:16:03'),(455,127,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.equals(\"NULL\")) {\n            System.out.println(\"NULL\");\n            return;\n        }\n\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String part : parts) {\n            if (part.equals(\"NULL\")) {\n                break;\n            }\n            cur.next = new ListNode(Integer.parseInt(part));\n            cur = cur.next;\n        }\n\n        ListNode head = dummy.next;\n        ListNode newHead = swapPairs(head);\n\n        StringBuilder sb = new StringBuilder();\n        ListNode p = newHead;\n        while (p != null) {\n            sb.append(p.val).append(\"->\");\n            p = p.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n\n    private static ListNode swapPairs(ListNode head) {\n        ListNode dummy = new ListNode(0);\n        dummy.next = head;\n        ListNode prev = dummy;\n\n        while (prev.next != null && prev.next.next != null) {\n            ListNode first = prev.next;\n            ListNode second = first.next;\n\n            first.next = second.next;\n            second.next = first;\n            prev.next = second;\n\n            prev = first;\n        }\n\n        return dummy.next;\n    }\n}',NULL,1,'2026-09-27 13:08:47','2026-09-28 15:16:03'),(456,124,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let n = parseInt(lines[0]);\n    let matrix = [];\n    for (let i = 0; i < n; i++) {\n        matrix.push(lines[i + 1].split(\' \').map(Number));\n    }\n\n    for (let i = 0; i < Math.floor(n / 2); i++) {\n        for (let j = i; j < n - 1 - i; j++) {\n            let temp = matrix[i][j];\n            matrix[i][j] = matrix[n - 1 - j][i];\n            matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j];\n            matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i];\n            matrix[j][n - 1 - i] = temp;\n        }\n    }\n\n    let sb = \'\';\n    for (let i = 0; i < n; i++) {\n        for (let j = 0; j < n; j++) {\n            sb += matrix[i][j];\n            if (j < n - 1) {\n                sb += \' \';\n            }\n        }\n        sb += \'\\n\';\n    }\n    process.stdout.write(sb);\n});',NULL,1,'2026-09-27 13:08:48','2026-09-28 15:16:03'),(457,125,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\n\nfor i in range(n):\n    while 0 < nums[i] <= n and nums[nums[i] - 1] != nums[i]:\n        nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]\n\nfor i in range(n):\n    if nums[i] != i + 1:\n        print(i + 1)\n        break\nelse:\n    print(n + 1)',NULL,1,'2026-09-27 13:08:48','2026-09-28 15:16:03'),(458,126,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    int maxProd = nums[0];\n    int minProd = nums[0];\n    int result = nums[0];\n\n    for (int i = 1; i < n; i++) {\n        int cur = nums[i];\n        int tempMax = max(cur, max(maxProd * cur, minProd * cur));\n        int tempMin = min(cur, min(maxProd * cur, minProd * cur));\n        maxProd = tempMax;\n        minProd = tempMin;\n        result = max(result, maxProd);\n    }\n\n    cout << result << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:08:49','2026-09-28 15:16:03'),(459,125,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const n = parseInt(lines[0]);\n        const nums = lines[1].split(\' \').map(Number);\n        \n        for (let i = 0; i < n; i++) {\n            while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] !== nums[i]) {\n                const temp = nums[nums[i] - 1];\n                nums[nums[i] - 1] = nums[i];\n                nums[i] = temp;\n            }\n        }\n        \n        for (let i = 0; i < n; i++) {\n            if (nums[i] !== i + 1) {\n                console.log(i + 1);\n                rl.close();\n                return;\n            }\n        }\n        \n        console.log(n + 1);\n        rl.close();\n    }\n});',NULL,1,'2026-09-27 13:08:50','2026-09-28 15:16:03'),(460,128,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.equals(\"NULL\")) {\n            System.out.println(\"NULL\");\n            return;\n        }\n\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode tail = dummy;\n\n        for (String part : parts) {\n            if (part.equals(\"NULL\")) {\n                break;\n            }\n            int val = Integer.parseInt(part);\n            if (dummy.next == null || tail.val != val) {\n                tail.next = new ListNode(val);\n                tail = tail.next;\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = dummy.next;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1,'2026-09-27 13:08:50','2026-09-28 15:16:03'),(461,126,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int maxProd = nums[0];\n    int minProd = nums[0];\n    int result = nums[0];\n\n    for (int i = 1; i < n; i++) {\n        int cur = nums[i];\n        int a = maxProd * cur;\n        int b = minProd * cur;\n        int tempMax = cur;\n        if (a > tempMax) tempMax = a;\n        if (b > tempMax) tempMax = b;\n        int tempMin = cur;\n        if (a < tempMin) tempMin = a;\n        if (b < tempMin) tempMin = b;\n        maxProd = tempMax;\n        minProd = tempMin;\n        if (maxProd > result) result = maxProd;\n    }\n\n    printf(\"%d\\n\", result);\n    return 0;\n}',NULL,1,'2026-09-27 13:08:51','2026-09-28 15:16:03'),(462,129,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] vals = new int[n];\n        for (int i = 0; i < n; i++) {\n            vals[i] = sc.nextInt();\n        }\n        int pos = sc.nextInt();\n\n        if (n == 0) {\n            System.out.println(-1);\n            return;\n        }\n\n        ListNode[] nodes = new ListNode[n];\n        for (int i = 0; i < n; i++) {\n            nodes[i] = new ListNode(vals[i]);\n        }\n        for (int i = 0; i < n - 1; i++) {\n            nodes[i].next = nodes[i + 1];\n        }\n        if (pos != -1) {\n            nodes[n - 1].next = nodes[pos];\n        }\n\n        ListNode head = nodes[0];\n        ListNode slow = head;\n        ListNode fast = head;\n        boolean hasCycle = false;\n\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                hasCycle = true;\n                break;\n            }\n        }\n\n        if (!hasCycle) {\n            System.out.println(-1);\n            return;\n        }\n\n        slow = head;\n        while (slow != fast) {\n            slow = slow.next;\n            fast = fast.next;\n        }\n\n        int index = 0;\n        ListNode cur = head;\n        while (cur != slow) {\n            cur = cur.next;\n            index++;\n        }\n        System.out.println(index);\n    }\n}',NULL,1,'2026-09-27 13:08:52','2026-09-28 15:16:03'),(463,126,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\n\nmax_prod = nums[0]\nmin_prod = nums[0]\nresult = nums[0]\n\nfor i in range(1, n):\n    cur = nums[i]\n    temp_max = max(cur, max_prod * cur, min_prod * cur)\n    temp_min = min(cur, max_prod * cur, min_prod * cur)\n    max_prod = temp_max\n    min_prod = temp_min\n    result = max(result, max_prod)\n\nprint(result)',NULL,1,'2026-09-27 13:08:52','2026-09-28 15:16:03'),(464,126,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(/\\s+/).map(Number);\n\n    let maxProd = nums[0];\n    let minProd = nums[0];\n    let result = nums[0];\n\n    for (let i = 1; i < n; i++) {\n        const cur = nums[i];\n        const tempMax = Math.max(cur, Math.max(maxProd * cur, minProd * cur));\n        const tempMin = Math.min(cur, Math.min(maxProd * cur, minProd * cur));\n        maxProd = tempMax;\n        minProd = tempMin;\n        result = Math.max(result, maxProd);\n    }\n\n    console.log(result);\n});',NULL,1,'2026-09-27 13:08:54','2026-09-28 15:16:03'),(465,129,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> vals(n);\n    for (int i = 0; i < n; i++) {\n        cin >> vals[i];\n    }\n    int pos;\n    cin >> pos;\n\n    if (n == 0) {\n        cout << -1 << endl;\n        return 0;\n    }\n\n    vector<ListNode*> nodes(n);\n    for (int i = 0; i < n; i++) {\n        nodes[i] = new ListNode(vals[i]);\n    }\n    for (int i = 0; i < n - 1; i++) {\n        nodes[i]->next = nodes[i + 1];\n    }\n    if (pos != -1) {\n        nodes[n - 1]->next = nodes[pos];\n    }\n\n    ListNode* head = nodes[0];\n    ListNode* slow = head;\n    ListNode* fast = head;\n    bool hasCycle = false;\n\n    while (fast != nullptr && fast->next != nullptr) {\n        slow = slow->next;\n        fast = fast->next->next;\n        if (slow == fast) {\n            hasCycle = true;\n            break;\n        }\n    }\n\n    if (!hasCycle) {\n        cout << -1 << endl;\n        return 0;\n    }\n\n    slow = head;\n    while (slow != fast) {\n        slow = slow->next;\n        fast = fast->next;\n    }\n\n    int index = 0;\n    ListNode* cur = head;\n    while (cur != slow) {\n        cur = cur->next;\n        index++;\n    }\n    cout << index << endl;\n\n    return 0;\n}',NULL,1,'2026-09-27 13:08:55','2026-09-28 15:16:03'),(466,130,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        ListNode dummy = new ListNode(0);\n        ListNode tail = dummy;\n        for (int i = 0; i < len; i++) {\n            tail.next = new ListNode(sc.nextInt());\n            tail = tail.next;\n        }\n        int n = sc.nextInt();\n\n        ListNode fast = dummy;\n        ListNode slow = dummy;\n        for (int i = 0; i <= n; i++) {\n            fast = fast.next;\n        }\n        while (fast != null) {\n            fast = fast.next;\n            slow = slow.next;\n        }\n        slow.next = slow.next.next;\n\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = dummy.next;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1,'2026-09-27 13:08:56','2026-09-28 15:16:03'),(467,129,'C','#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n\n    int *vals = (int *)malloc(sizeof(int) * (n > 0 ? n : 1));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &vals[i]);\n    }\n\n    int pos;\n    scanf(\"%d\", &pos);\n\n    if (n == 0) {\n        printf(\"-1\\n\");\n        free(vals);\n        return 0;\n    }\n\n    ListNode **nodes = (ListNode **)malloc(sizeof(ListNode *) * n);\n    for (int i = 0; i < n; i++) {\n        nodes[i] = (ListNode *)malloc(sizeof(ListNode));\n        nodes[i]->val = vals[i];\n        nodes[i]->next = NULL;\n    }\n\n    for (int i = 0; i < n - 1; i++) {\n        nodes[i]->next = nodes[i + 1];\n    }\n\n    if (pos != -1) {\n        nodes[n - 1]->next = nodes[pos];\n    }\n\n    ListNode *head = nodes[0];\n    ListNode *slow = head;\n    ListNode *fast = head;\n    int hasCycle = 0;\n\n    while (fast != NULL && fast->next != NULL) {\n        slow = slow->next;\n        fast = fast->next->next;\n        if (slow == fast) {\n            hasCycle = 1;\n            break;\n        }\n    }\n\n    if (!hasCycle) {\n        printf(\"-1\\n\");\n    } else {\n        slow = head;\n        while (slow != fast) {\n            slow = slow->next;\n            fast = fast->next;\n        }\n\n        int index = 0;\n        ListNode *cur = head;\n        while (cur != slow) {\n            cur = cur->next;\n            index++;\n        }\n        printf(\"%d\\n\", index);\n    }\n\n    for (int i = 0; i < n; i++) {\n        free(nodes[i]);\n    }\n    free(nodes);\n    free(vals);\n\n    return 0;\n}',NULL,1,'2026-09-27 13:08:57','2026-09-28 15:16:03'),(468,127,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* swapPairs(ListNode* head) {\n    ListNode dummy(0);\n    dummy.next = head;\n    ListNode* prev = &dummy;\n\n    while (prev->next != nullptr && prev->next->next != nullptr) {\n        ListNode* first = prev->next;\n        ListNode* second = first->next;\n\n        first->next = second->next;\n        second->next = first;\n        prev->next = second;\n\n        prev = first;\n    }\n\n    return dummy.next;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    string line;\n    if (!getline(cin, line)) return 0;\n\n    if (line == \"NULL\") {\n        cout << \"NULL\\n\";\n        return 0;\n    }\n\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n\n    size_t pos = 0;\n    while (pos < line.size()) {\n        size_t nextPos = line.find(\"->\", pos);\n        string part;\n        if (nextPos == string::npos) {\n            part = line.substr(pos);\n            pos = line.size();\n        } else {\n            part = line.substr(pos, nextPos - pos);\n            pos = nextPos + 2;\n        }\n\n        if (part == \"NULL\" || part.empty()) break;\n\n        cur->next = new ListNode(stoi(part));\n        cur = cur->next;\n    }\n\n    ListNode* newHead = swapPairs(dummy.next);\n\n    string out;\n    ListNode* p = newHead;\n    while (p != nullptr) {\n        out += to_string(p->val);\n        out += \"->\";\n        p = p->next;\n    }\n    out += \"NULL\";\n\n    cout << out << \'\\n\';\n    return 0;\n}',NULL,1,'2026-09-27 13:08:58','2026-09-28 15:16:03'),(469,130,'CPP','#include <iostream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nint main() {\n    int len;\n    cin >> len;\n\n    ListNode* dummy = new ListNode(0);\n    ListNode* tail = dummy;\n    for (int i = 0; i < len; ++i) {\n        int x;\n        cin >> x;\n        tail->next = new ListNode(x);\n        tail = tail->next;\n    }\n\n    int n;\n    cin >> n;\n\n    ListNode* fast = dummy;\n    ListNode* slow = dummy;\n    for (int i = 0; i <= n; ++i) {\n        fast = fast->next;\n    }\n    while (fast != nullptr) {\n        fast = fast->next;\n        slow = slow->next;\n    }\n    slow->next = slow->next->next;\n\n    ListNode* cur = dummy->next;\n    while (cur != nullptr) {\n        cout << cur->val << \"->\";\n        cur = cur->next;\n    }\n    cout << \"NULL\" << endl;\n\n    return 0;\n}',NULL,1,'2026-09-27 13:08:58','2026-09-28 15:16:03'),(470,129,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    vals = list(map(int, data[1:1+n]))\n    pos = int(data[1+n])\n\n    if n == 0:\n        print(-1)\n        return\n\n    class ListNode:\n        __slots__ = (\'val\', \'next\')\n        def __init__(self, val):\n            self.val = val\n            self.next = None\n\n    nodes = [ListNode(v) for v in vals]\n    for i in range(n - 1):\n        nodes[i].next = nodes[i + 1]\n    if pos != -1:\n        nodes[n - 1].next = nodes[pos]\n\n    head = nodes[0]\n    slow = head\n    fast = head\n    has_cycle = False\n\n    while fast is not None and fast.next is not None:\n        slow = slow.next\n        fast = fast.next.next\n        if slow is fast:\n            has_cycle = True\n            break\n\n    if not has_cycle:\n        print(-1)\n        return\n\n    slow = head\n    while slow is not fast:\n        slow = slow.next\n        fast = fast.next\n\n    index = 0\n    cur = head\n    while cur is not slow:\n        cur = cur.next\n        index += 1\n    print(index)\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:08:59','2026-09-28 15:16:03'),(471,128,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    string line;\n    if (!getline(cin, line)) return 0;\n\n    if (line == \"NULL\") {\n        cout << \"NULL\\n\";\n        return 0;\n    }\n\n    ListNode dummy(0);\n    ListNode* tail = &dummy;\n\n    size_t pos = 0;\n    while (pos < line.size()) {\n        size_t nextPos = line.find(\"->\", pos);\n        string part;\n        if (nextPos == string::npos) {\n            part = line.substr(pos);\n            pos = line.size();\n        } else {\n            part = line.substr(pos, nextPos - pos);\n            pos = nextPos + 2;\n        }\n\n        if (part == \"NULL\") break;\n\n        int val = 0;\n        for (char c : part) {\n            val = val * 10 + (c - \'0\');\n        }\n\n        if (dummy.next == nullptr || tail->val != val) {\n            tail->next = new ListNode(val);\n            tail = tail->next;\n        }\n    }\n\n    ListNode* cur = dummy.next;\n    bool first = true;\n    while (cur != nullptr) {\n        if (!first) cout << \"->\";\n        cout << cur->val;\n        first = false;\n        cur = cur->next;\n    }\n    if (!first) cout << \"->\";\n    cout << \"NULL\\n\";\n\n    return 0;\n}',NULL,1,'2026-09-27 13:09:00','2026-09-28 15:16:03'),(472,127,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstruct ListNode {\n    int val;\n    struct ListNode *next;\n};\n\nstruct ListNode* swapPairs(struct ListNode* head) {\n    struct ListNode dummy;\n    dummy.next = head;\n    struct ListNode *prev = &dummy;\n\n    while (prev->next != NULL && prev->next->next != NULL) {\n        struct ListNode *first = prev->next;\n        struct ListNode *second = first->next;\n\n        first->next = second->next;\n        second->next = first;\n        prev->next = second;\n\n        prev = first;\n    }\n\n    return dummy.next;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) {\n        return 0;\n    }\n\n    line[strcspn(line, \"\\r\\n\")] = \'\\0\';\n\n    if (strcmp(line, \"NULL\") == 0) {\n        printf(\"NULL\\n\");\n        return 0;\n    }\n\n    struct ListNode dummy;\n    dummy.next = NULL;\n    struct ListNode *cur = &dummy;\n\n    char *token = strtok(line, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) {\n            break;\n        }\n        struct ListNode *node = (struct ListNode *)malloc(sizeof(struct ListNode));\n        node->val = atoi(token);\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n        token = strtok(NULL, \"->\");\n    }\n\n    struct ListNode *newHead = swapPairs(dummy.next);\n\n    struct ListNode *p = newHead;\n    while (p != NULL) {\n        printf(\"%d->\", p->val);\n        p = p->next;\n    }\n    printf(\"NULL\\n\");\n\n    return 0;\n}',NULL,1,'2026-09-27 13:09:00','2026-09-28 15:16:03'),(473,130,'C','#include <stdio.h>\n#include <stdlib.h>\n\nstruct ListNode {\n    int val;\n    struct ListNode *next;\n};\n\nint main() {\n    int len;\n    scanf(\"%d\", &len);\n\n    struct ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    struct ListNode *tail = &dummy;\n\n    for (int i = 0; i < len; i++) {\n        int x;\n        scanf(\"%d\", &x);\n        struct ListNode *node = (struct ListNode *)malloc(sizeof(struct ListNode));\n        node->val = x;\n        node->next = NULL;\n        tail->next = node;\n        tail = node;\n    }\n\n    int n;\n    scanf(\"%d\", &n);\n\n    struct ListNode *fast = &dummy;\n    struct ListNode *slow = &dummy;\n\n    for (int i = 0; i <= n; i++) {\n        fast = fast->next;\n    }\n\n    while (fast != NULL) {\n        fast = fast->next;\n        slow = slow->next;\n    }\n\n    struct ListNode *toDelete = slow->next;\n    slow->next = slow->next->next;\n    free(toDelete);\n\n    struct ListNode *cur = dummy.next;\n    while (cur != NULL) {\n        printf(\"%d->\", cur->val);\n        cur = cur->next;\n    }\n    printf(\"NULL\\n\");\n\n    return 0;\n}',NULL,1,'2026-09-27 13:09:01','2026-09-28 15:16:03'),(474,129,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const vals = lines[1] ? lines[1].split(\' \').map(Number) : [];\n    const pos = parseInt(lines[2]);\n\n    if (n === 0) {\n        console.log(-1);\n        return;\n    }\n\n    class ListNode {\n        constructor(val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    const nodes = [];\n    for (let i = 0; i < n; i++) {\n        nodes.push(new ListNode(vals[i]));\n    }\n    for (let i = 0; i < n - 1; i++) {\n        nodes[i].next = nodes[i + 1];\n    }\n    if (pos !== -1) {\n        nodes[n - 1].next = nodes[pos];\n    }\n\n    const head = nodes[0];\n    let slow = head;\n    let fast = head;\n    let hasCycle = false;\n\n    while (fast !== null && fast.next !== null) {\n        slow = slow.next;\n        fast = fast.next.next;\n        if (slow === fast) {\n            hasCycle = true;\n            break;\n        }\n    }\n\n    if (!hasCycle) {\n        console.log(-1);\n        return;\n    }\n\n    slow = head;\n    while (slow !== fast) {\n        slow = slow.next;\n        fast = fast.next;\n    }\n\n    let index = 0;\n    let cur = head;\n    while (cur !== slow) {\n        cur = cur.next;\n        index++;\n    }\n    console.log(index);\n});',NULL,1,'2026-09-27 13:09:01','2026-09-28 15:16:03'),(475,130,'PYTHON','import sys\n\nclass ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    length = int(data[0])\n    dummy = ListNode(0)\n    tail = dummy\n    idx = 1\n    for _ in range(length):\n        tail.next = ListNode(int(data[idx]))\n        tail = tail.next\n        idx += 1\n    n = int(data[idx])\n\n    fast = dummy\n    slow = dummy\n    for _ in range(n + 1):\n        fast = fast.next\n    while fast is not None:\n        fast = fast.next\n        slow = slow.next\n    slow.next = slow.next.next\n\n    res = []\n    cur = dummy.next\n    while cur is not None:\n        res.append(str(cur.val))\n        cur = cur.next\n    print(\"->\".join(res) + \"->NULL\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:09:02','2026-09-28 15:16:03'),(476,127,'PYTHON','import sys\n\nclass ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef swapPairs(head):\n    dummy = ListNode(0)\n    dummy.next = head\n    prev = dummy\n\n    while prev.next is not None and prev.next.next is not None:\n        first = prev.next\n        second = first.next\n\n        first.next = second.next\n        second.next = first\n        prev.next = second\n\n        prev = first\n\n    return dummy.next\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line == \"NULL\":\n        print(\"NULL\")\n        return\n\n    parts = line.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for part in parts:\n        if part == \"NULL\":\n            break\n        cur.next = ListNode(int(part))\n        cur = cur.next\n\n    head = dummy.next\n    new_head = swapPairs(head)\n\n    sb = []\n    p = new_head\n    while p is not None:\n        sb.append(str(p.val))\n        sb.append(\"->\")\n        p = p.next\n    sb.append(\"NULL\")\n    print(\"\".join(sb))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:09:02','2026-09-28 15:16:03'),(477,128,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n\n    line[strcspn(line, \"\\r\\n\")] = \'\\0\';\n\n    if (strcmp(line, \"NULL\") == 0) {\n        printf(\"NULL\\n\");\n        return 0;\n    }\n\n    ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    ListNode *tail = &dummy;\n\n    char *token = strtok(line, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) {\n            break;\n        }\n        int val = atoi(token);\n        if (dummy.next == NULL || tail->val != val) {\n            ListNode *node = (ListNode *)malloc(sizeof(ListNode));\n            node->val = val;\n            node->next = NULL;\n            tail->next = node;\n            tail = node;\n        }\n        token = strtok(NULL, \"->\");\n    }\n\n    ListNode *cur = dummy.next;\n    while (cur != NULL) {\n        printf(\"%d->\", cur->val);\n        cur = cur->next;\n    }\n    printf(\"NULL\\n\");\n\n    cur = dummy.next;\n    while (cur != NULL) {\n        ListNode *tmp = cur;\n        cur = cur->next;\n        free(tmp);\n    }\n\n    return 0;\n}',NULL,1,'2026-09-27 13:09:03','2026-09-28 15:16:03'),(478,131,'JAVA','import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.endsWith(\"->NULL\")) {\n            line = line.substring(0, line.length() - 6);\n        }\n        if (line.isEmpty()) {\n            System.out.println(\"NULL\");\n            return;\n        }\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String p : parts) {\n            cur.next = new ListNode(Integer.parseInt(p.trim()));\n            cur = cur.next;\n        }\n        ListNode head = dummy.next;\n        reorderList(head);\n        StringBuilder sb = new StringBuilder();\n        cur = head;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n\n    public static void reorderList(ListNode head) {\n        if (head == null || head.next == null) return;\n        ListNode slow = head, fast = head;\n        while (fast.next != null && fast.next.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        ListNode second = slow.next;\n        slow.next = null;\n        second = reverse(second);\n        ListNode first = head;\n        while (second != null) {\n            ListNode tmp1 = first.next;\n            ListNode tmp2 = second.next;\n            first.next = second;\n            second.next = tmp1;\n            first = tmp1;\n            second = tmp2;\n        }\n    }\n\n    private static ListNode reverse(ListNode head) {\n        ListNode prev = null;\n        while (head != null) {\n            ListNode next = head.next;\n            head.next = prev;\n            prev = head;\n            head = next;\n        }\n        return prev;\n    }\n}',NULL,1,'2026-09-27 13:09:04','2026-09-28 15:16:03'),(479,130,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const len = parseInt(lines[0]);\n    const values = lines[1].split(\' \').map(Number);\n    const n = parseInt(lines[2]);\n\n    class ListNode {\n        constructor(val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    const dummy = new ListNode(0);\n    let tail = dummy;\n    for (let i = 0; i < len; i++) {\n        tail.next = new ListNode(values[i]);\n        tail = tail.next;\n    }\n\n    let fast = dummy;\n    let slow = dummy;\n    for (let i = 0; i <= n; i++) {\n        fast = fast.next;\n    }\n    while (fast !== null) {\n        fast = fast.next;\n        slow = slow.next;\n    }\n    slow.next = slow.next.next;\n\n    let result = \'\';\n    let cur = dummy.next;\n    while (cur !== null) {\n        result += cur.val + \'->\';\n        cur = cur.next;\n    }\n    result += \'NULL\';\n    console.log(result);\n});',NULL,1,'2026-09-27 13:09:04','2026-09-28 15:16:03'),(480,127,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction swapPairs(head) {\n    const dummy = new ListNode(0);\n    dummy.next = head;\n    let prev = dummy;\n\n    while (prev.next !== null && prev.next.next !== null) {\n        const first = prev.next;\n        const second = first.next;\n\n        first.next = second.next;\n        second.next = first;\n        prev.next = second;\n\n        prev = first;\n    }\n\n    return dummy.next;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line === \'NULL\') {\n        console.log(\'NULL\');\n        rl.close();\n        return;\n    }\n\n    const parts = line.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (const part of parts) {\n        if (part === \'NULL\') {\n            break;\n        }\n        cur.next = new ListNode(parseInt(part));\n        cur = cur.next;\n    }\n\n    const head = dummy.next;\n    const newHead = swapPairs(head);\n\n    let sb = \'\';\n    let p = newHead;\n    while (p !== null) {\n        sb += p.val + \'->\';\n        p = p.next;\n    }\n    sb += \'NULL\';\n    console.log(sb);\n    rl.close();\n});',NULL,1,'2026-09-27 13:09:04','2026-09-28 15:16:03'),(481,128,'PYTHON','import sys\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line == \"NULL\":\n        print(\"NULL\")\n        return\n\n    parts = line.split(\"->\")\n    dummy = type(\'ListNode\', (object,), {})()\n    dummy.val = 0\n    dummy.next = None\n    tail = dummy\n\n    for part in parts:\n        if part == \"NULL\":\n            break\n        val = int(part)\n        if dummy.next is None or tail.val != val:\n            node = type(\'ListNode\', (object,), {})()\n            node.val = val\n            node.next = None\n            tail.next = node\n            tail = node\n\n    sb = []\n    cur = dummy.next\n    while cur is not None:\n        sb.append(str(cur.val))\n        sb.append(\"->\")\n        cur = cur.next\n    sb.append(\"NULL\")\n    print(\"\".join(sb))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:09:04','2026-09-28 15:16:03'),(482,128,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line === \'NULL\') {\n        console.log(\'NULL\');\n        rl.close();\n        return;\n    }\n\n    const parts = line.split(\'->\');\n    const dummy = { val: 0, next: null };\n    let tail = dummy;\n\n    for (const part of parts) {\n        if (part === \'NULL\') {\n            break;\n        }\n        const val = parseInt(part, 10);\n        if (dummy.next === null || tail.val !== val) {\n            tail.next = { val: val, next: null };\n            tail = tail.next;\n        }\n    }\n\n    let result = \'\';\n    let cur = dummy.next;\n    while (cur !== null) {\n        result += cur.val + \'->\';\n        cur = cur.next;\n    }\n    result += \'NULL\';\n    console.log(result);\n    rl.close();\n});',NULL,1,'2026-09-27 13:09:06','2026-09-28 15:16:03'),(483,132,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        int k = Integer.parseInt(sc.nextLine().trim());\n\n        ListNode head = buildList(line);\n        head = rotateRight(head, k);\n        System.out.println(printList(head));\n    }\n\n    private static ListNode buildList(String s) {\n        if (s == null || s.isEmpty() || s.equals(\"NULL\")) {\n            return null;\n        }\n        String[] parts = s.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String part : parts) {\n            if (part.equals(\"NULL\")) {\n                break;\n            }\n            cur.next = new ListNode(Integer.parseInt(part));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    private static String printList(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = head;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    private static ListNode rotateRight(ListNode head, int k) {\n        if (head == null || head.next == null || k == 0) {\n            return head;\n        }\n\n        int len = 1;\n        ListNode tail = head;\n        while (tail.next != null) {\n            tail = tail.next;\n            len++;\n        }\n\n        k = k % len;\n        if (k == 0) {\n            return head;\n        }\n\n        tail.next = head;\n        ListNode newTail = head;\n        for (int i = 0; i < len - k - 1; i++) {\n            newTail = newTail.next;\n        }\n\n        ListNode newHead = newTail.next;\n        newTail.next = null;\n        return newHead;\n    }\n}',NULL,1,'2026-09-27 13:09:06','2026-09-28 15:16:03'),(484,133,'JAVA','import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int k = Integer.parseInt(sc.nextLine().trim());\n        List<ListNode> lists = new ArrayList<>();\n        for (int i = 0; i < k; i++) {\n            String line = sc.nextLine().trim();\n            lists.add(parseList(line));\n        }\n        ListNode merged = mergeKLists(lists);\n        System.out.println(formatList(merged));\n    }\n\n    private static ListNode parseList(String s) {\n        if (s == null || s.isEmpty() || s.equals(\"NULL\")) return null;\n        String[] parts = s.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String p : parts) {\n            if (p.equals(\"NULL\")) break;\n            cur.next = new ListNode(Integer.parseInt(p.trim()));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    private static String formatList(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = head;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    private static ListNode mergeKLists(List<ListNode> lists) {\n        PriorityQueue<ListNode> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a.val));\n        for (ListNode node : lists) {\n            if (node != null) pq.offer(node);\n        }\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        while (!pq.isEmpty()) {\n            ListNode node = pq.poll();\n            cur.next = node;\n            cur = cur.next;\n            if (node.next != null) pq.offer(node.next);\n        }\n        return dummy.next;\n    }\n}',NULL,1,'2026-09-27 13:09:07','2026-09-28 15:16:03'),(485,131,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* reverseList(ListNode* head) {\n    ListNode* prev = nullptr;\n    while (head != nullptr) {\n        ListNode* nxt = head->next;\n        head->next = prev;\n        prev = head;\n        head = nxt;\n    }\n    return prev;\n}\n\nvoid reorderList(ListNode* head) {\n    if (head == nullptr || head->next == nullptr) return;\n    ListNode* slow = head;\n    ListNode* fast = head;\n    while (fast->next != nullptr && fast->next->next != nullptr) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    ListNode* second = slow->next;\n    slow->next = nullptr;\n    second = reverseList(second);\n    ListNode* first = head;\n    while (second != nullptr) {\n        ListNode* tmp1 = first->next;\n        ListNode* tmp2 = second->next;\n        first->next = second;\n        second->next = tmp1;\n        first = tmp1;\n        second = tmp2;\n    }\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\' || line.back() == \' \')) {\n        line.pop_back();\n    }\n    if (line.size() >= 6 && line.substr(line.size() - 6) == \"->NULL\") {\n        line = line.substr(0, line.size() - 6);\n    }\n    if (line.empty()) {\n        cout << \"NULL\" << endl;\n        return 0;\n    }\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    stringstream ss(line);\n    string part;\n    while (getline(ss, part, \'-\')) {\n        if (part == \">\") continue;\n        if (!part.empty() && part[0] == \'>\') part = part.substr(1);\n        if (part.empty()) continue;\n        cur->next = new ListNode(stoi(part));\n        cur = cur->next;\n    }\n    ListNode* head = dummy.next;\n    reorderList(head);\n    ListNode* p = head;\n    while (p != nullptr) {\n        cout << p->val << \"->\";\n        p = p->next;\n    }\n    cout << \"NULL\" << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:09:07','2026-09-28 15:16:03'),(486,134,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (int i = 0; i < n; i++) {\n            cur.next = new ListNode(sc.nextInt());\n            cur = cur.next;\n        }\n        ListNode sorted = sortList(dummy.next);\n        StringBuilder sb = new StringBuilder();\n        while (sorted != null) {\n            sb.append(sorted.val).append(\"->\");\n            sorted = sorted.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n\n    public static ListNode sortList(ListNode head) {\n        if (head == null || head.next == null) return head;\n        ListNode slow = head, fast = head.next;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        ListNode mid = slow.next;\n        slow.next = null;\n        ListNode left = sortList(head);\n        ListNode right = sortList(mid);\n        return merge(left, right);\n    }\n\n    private static ListNode merge(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        while (l1 != null && l2 != null) {\n            if (l1.val <= l2.val) {\n                cur.next = l1;\n                l1 = l1.next;\n            } else {\n                cur.next = l2;\n                l2 = l2.next;\n            }\n            cur = cur.next;\n        }\n        cur.next = (l1 != null) ? l1 : l2;\n        return dummy.next;\n    }\n}',NULL,1,'2026-09-27 13:09:08','2026-09-28 15:16:03'),(487,131,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\nListNode* reverse(ListNode* head) {\n    ListNode* prev = NULL;\n    while (head != NULL) {\n        ListNode* next = head->next;\n        head->next = prev;\n        prev = head;\n        head = next;\n    }\n    return prev;\n}\n\nvoid reorderList(ListNode* head) {\n    if (head == NULL || head->next == NULL) return;\n    ListNode *slow = head, *fast = head;\n    while (fast->next != NULL && fast->next->next != NULL) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    ListNode* second = slow->next;\n    slow->next = NULL;\n    second = reverse(second);\n    ListNode* first = head;\n    while (second != NULL) {\n        ListNode* tmp1 = first->next;\n        ListNode* tmp2 = second->next;\n        first->next = second;\n        second->next = tmp1;\n        first = tmp1;\n        second = tmp2;\n    }\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    size_t len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    if (len >= 6 && strcmp(line + len - 6, \"->NULL\") == 0) {\n        line[len - 6] = \'\\0\';\n    }\n    if (line[0] == \'\\0\') {\n        printf(\"NULL\\n\");\n        return 0;\n    }\n    ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    ListNode* cur = &dummy;\n    char* token = strtok(line, \"->\");\n    while (token != NULL) {\n        cur->next = (ListNode*)malloc(sizeof(ListNode));\n        cur->next->val = atoi(token);\n        cur->next->next = NULL;\n        cur = cur->next;\n        token = strtok(NULL, \"->\");\n    }\n    ListNode* head = dummy.next;\n    reorderList(head);\n    cur = head;\n    while (cur != NULL) {\n        printf(\"%d->\", cur->val);\n        cur = cur->next;\n    }\n    printf(\"NULL\\n\");\n    return 0;\n}',NULL,1,'2026-09-27 13:09:10','2026-09-28 15:16:03'),(488,134,'CPP','#include <iostream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* merge(ListNode* l1, ListNode* l2) {\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    while (l1 != nullptr && l2 != nullptr) {\n        if (l1->val <= l2->val) {\n            cur->next = l1;\n            l1 = l1->next;\n        } else {\n            cur->next = l2;\n            l2 = l2->next;\n        }\n        cur = cur->next;\n    }\n    cur->next = (l1 != nullptr) ? l1 : l2;\n    return dummy.next;\n}\n\nListNode* sortList(ListNode* head) {\n    if (head == nullptr || head->next == nullptr) return head;\n    ListNode* slow = head;\n    ListNode* fast = head->next;\n    while (fast != nullptr && fast->next != nullptr) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    ListNode* mid = slow->next;\n    slow->next = nullptr;\n    ListNode* left = sortList(head);\n    ListNode* right = sortList(mid);\n    return merge(left, right);\n}\n\nint main() {\n    int n;\n    cin >> n;\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        cur->next = new ListNode(x);\n        cur = cur->next;\n    }\n    ListNode* sorted = sortList(dummy.next);\n    while (sorted != nullptr) {\n        cout << sorted->val << \"->\";\n        sorted = sorted->next;\n    }\n    cout << \"NULL\" << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:09:11','2026-09-28 15:16:03'),(489,131,'PYTHON','import sys\n\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef reorder_list(head):\n    if not head or not head.next:\n        return\n    slow = head\n    fast = head\n    while fast.next and fast.next.next:\n        slow = slow.next\n        fast = fast.next.next\n    second = slow.next\n    slow.next = None\n    second = reverse(second)\n    first = head\n    while second:\n        tmp1 = first.next\n        tmp2 = second.next\n        first.next = second\n        second.next = tmp1\n        first = tmp1\n        second = tmp2\n\ndef reverse(head):\n    prev = None\n    while head:\n        nxt = head.next\n        head.next = prev\n        prev = head\n        head = nxt\n    return prev\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.endswith(\"->NULL\"):\n        line = line[:-6]\n    if not line:\n        print(\"NULL\")\n        return\n    parts = line.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for p in parts:\n        cur.next = ListNode(int(p.strip()))\n        cur = cur.next\n    head = dummy.next\n    reorder_list(head)\n    sb = []\n    cur = head\n    while cur:\n        sb.append(str(cur.val))\n        sb.append(\"->\")\n        cur = cur.next\n    sb.append(\"NULL\")\n    print(\"\".join(sb))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:09:12','2026-09-28 15:16:03'),(490,134,'C','#include <stdio.h>\n#include <stdlib.h>\n\nstruct ListNode {\n    int val;\n    struct ListNode *next;\n};\n\nstruct ListNode* merge(struct ListNode* l1, struct ListNode* l2) {\n    struct ListNode dummy;\n    struct ListNode* cur = &dummy;\n    dummy.next = NULL;\n    while (l1 != NULL && l2 != NULL) {\n        if (l1->val <= l2->val) {\n            cur->next = l1;\n            l1 = l1->next;\n        } else {\n            cur->next = l2;\n            l2 = l2->next;\n        }\n        cur = cur->next;\n    }\n    cur->next = (l1 != NULL) ? l1 : l2;\n    return dummy.next;\n}\n\nstruct ListNode* sortList(struct ListNode* head) {\n    if (head == NULL || head->next == NULL) return head;\n    struct ListNode *slow = head, *fast = head->next;\n    while (fast != NULL && fast->next != NULL) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    struct ListNode* mid = slow->next;\n    slow->next = NULL;\n    struct ListNode* left = sortList(head);\n    struct ListNode* right = sortList(mid);\n    return merge(left, right);\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    struct ListNode dummy;\n    dummy.next = NULL;\n    struct ListNode* cur = &dummy;\n    for (int i = 0; i < n; i++) {\n        int x;\n        scanf(\"%d\", &x);\n        struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));\n        node->val = x;\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n    }\n    struct ListNode* sorted = sortList(dummy.next);\n    while (sorted != NULL) {\n        printf(\"%d->\", sorted->val);\n        sorted = sorted->next;\n    }\n    printf(\"NULL\\n\");\n    return 0;\n}',NULL,1,'2026-09-27 13:09:13','2026-09-28 15:16:03'),(491,131,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction reorderList(head) {\n    if (head === null || head.next === null) return;\n    let slow = head, fast = head;\n    while (fast.next !== null && fast.next.next !== null) {\n        slow = slow.next;\n        fast = fast.next.next;\n    }\n    let second = slow.next;\n    slow.next = null;\n    second = reverse(second);\n    let first = head;\n    while (second !== null) {\n        let tmp1 = first.next;\n        let tmp2 = second.next;\n        first.next = second;\n        second.next = tmp1;\n        first = tmp1;\n        second = tmp2;\n    }\n}\n\nfunction reverse(head) {\n    let prev = null;\n    while (head !== null) {\n        let next = head.next;\n        head.next = prev;\n        prev = head;\n        head = next;\n    }\n    return prev;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.endsWith(\'->NULL\')) {\n        line = line.substring(0, line.length - 6);\n    }\n    if (line === \'\') {\n        console.log(\'NULL\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (const p of parts) {\n        cur.next = new ListNode(parseInt(p.trim(), 10));\n        cur = cur.next;\n    }\n    const head = dummy.next;\n    reorderList(head);\n    let sb = \'\';\n    cur = head;\n    while (cur !== null) {\n        sb += cur.val + \'->\';\n        cur = cur.next;\n    }\n    sb += \'NULL\';\n    console.log(sb);\n    rl.close();\n});',NULL,1,'2026-09-27 13:09:14','2026-09-28 15:16:03'),(492,134,'PYTHON','import sys\n\nclass ListNode:\n    __slots__ = (\'val\', \'next\')\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef sortList(head):\n    if head is None or head.next is None:\n        return head\n    slow = head\n    fast = head.next\n    while fast is not None and fast.next is not None:\n        slow = slow.next\n        fast = fast.next.next\n    mid = slow.next\n    slow.next = None\n    left = sortList(head)\n    right = sortList(mid)\n    return merge(left, right)\n\ndef merge(l1, l2):\n    dummy = ListNode(0)\n    cur = dummy\n    while l1 is not None and l2 is not None:\n        if l1.val <= l2.val:\n            cur.next = l1\n            l1 = l1.next\n        else:\n            cur.next = l2\n            l2 = l2.next\n        cur = cur.next\n    cur.next = l1 if l1 is not None else l2\n    return dummy.next\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    n = int(data[0])\n    dummy = ListNode(0)\n    cur = dummy\n    for i in range(n):\n        cur.next = ListNode(int(data[i + 1]))\n        cur = cur.next\n    sorted_head = sortList(dummy.next)\n    parts = []\n    while sorted_head is not None:\n        parts.append(str(sorted_head.val))\n        sorted_head = sorted_head.next\n    parts.append(\"NULL\")\n    sys.stdout.write(\"->\".join(parts))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:09:15','2026-09-28 15:16:03'),(493,135,'JAVA','import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int x) { val = x; }\n    }\n\n    static int maxSum = Integer.MIN_VALUE;\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) line = line.substring(1);\n        if (line.endsWith(\"]\")) line = line.substring(0, line.length() - 1);\n\n        if (line.trim().isEmpty()) {\n            System.out.println(0);\n            return;\n        }\n\n        String[] parts = line.split(\",\");\n        TreeNode root = buildTree(parts);\n        maxPathSum(root);\n        System.out.println(maxSum);\n    }\n\n    static TreeNode buildTree(String[] parts) {\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode node = queue.poll();\n            if (i < parts.length && !parts[i].trim().equals(\"null\")) {\n                node.left = new TreeNode(Integer.parseInt(parts[i].trim()));\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < parts.length && !parts[i].trim().equals(\"null\")) {\n                node.right = new TreeNode(Integer.parseInt(parts[i].trim()));\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    static int maxPathSum(TreeNode root) {\n        maxSum = Integer.MIN_VALUE;\n        dfs(root);\n        return maxSum;\n    }\n\n    static int dfs(TreeNode node) {\n        if (node == null) return 0;\n        int left = Math.max(0, dfs(node.left));\n        int right = Math.max(0, dfs(node.right));\n        maxSum = Math.max(maxSum, node.val + left + right);\n        return node.val + Math.max(left, right);\n    }\n}',NULL,1,'2026-09-27 13:09:17','2026-09-28 15:16:03'),(494,134,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction sortList(head) {\n    if (head === null || head.next === null) return head;\n    let slow = head, fast = head.next;\n    while (fast !== null && fast.next !== null) {\n        slow = slow.next;\n        fast = fast.next.next;\n    }\n    let mid = slow.next;\n    slow.next = null;\n    let left = sortList(head);\n    let right = sortList(mid);\n    return merge(left, right);\n}\n\nfunction merge(l1, l2) {\n    let dummy = new ListNode(0);\n    let cur = dummy;\n    while (l1 !== null && l2 !== null) {\n        if (l1.val <= l2.val) {\n            cur.next = l1;\n            l1 = l1.next;\n        } else {\n            cur.next = l2;\n            l2 = l2.next;\n        }\n        cur = cur.next;\n    }\n    cur.next = (l1 !== null) ? l1 : l2;\n    return dummy.next;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        rl.close();\n        const n = parseInt(lines[0]);\n        const values = lines[1].split(\' \').map(Number);\n        let dummy = new ListNode(0);\n        let cur = dummy;\n        for (let i = 0; i < n; i++) {\n            cur.next = new ListNode(values[i]);\n            cur = cur.next;\n        }\n        let sorted = sortList(dummy.next);\n        let sb = \'\';\n        while (sorted !== null) {\n            sb += sorted.val + \'->\';\n            sorted = sorted.next;\n        }\n        sb += \'NULL\';\n        console.log(sb);\n    }\n});',NULL,1,'2026-09-27 13:09:18','2026-09-28 15:16:03'),(495,133,'CPP','#include <bits/stdc++.h>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode *next;\n    ListNode(int x) : val(x), next(nullptr) {}\n};\n\nListNode* parseList(const string& s) {\n    if (s.empty() || s == \"NULL\") return nullptr;\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    size_t start = 0;\n    while (start < s.size()) {\n        size_t pos = s.find(\"->\", start);\n        string part;\n        if (pos == string::npos) {\n            part = s.substr(start);\n            start = s.size();\n        } else {\n            part = s.substr(start, pos - start);\n            start = pos + 2;\n        }\n        if (part == \"NULL\") break;\n        cur->next = new ListNode(stoi(part));\n        cur = cur->next;\n    }\n    return dummy.next;\n}\n\nstring formatList(ListNode* head) {\n    string res;\n    ListNode* cur = head;\n    while (cur) {\n        res += to_string(cur->val);\n        res += \"->\";\n        cur = cur->next;\n    }\n    res += \"NULL\";\n    return res;\n}\n\nstruct Compare {\n    bool operator()(ListNode* a, ListNode* b) {\n        return a->val > b->val;\n    }\n};\n\nListNode* mergeKLists(vector<ListNode*>& lists) {\n    priority_queue<ListNode*, vector<ListNode*>, Compare> pq;\n    for (ListNode* node : lists) {\n        if (node) pq.push(node);\n    }\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    while (!pq.empty()) {\n        ListNode* node = pq.top();\n        pq.pop();\n        cur->next = node;\n        cur = cur->next;\n        if (node->next) pq.push(node->next);\n    }\n    return dummy.next;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int k;\n    cin >> k;\n    cin.ignore();\n\n    vector<ListNode*> lists;\n    lists.reserve(k);\n\n    for (int i = 0; i < k; ++i) {\n        string line;\n        getline(cin, line);\n        lists.push_back(parseList(line));\n    }\n\n    ListNode* merged = mergeKLists(lists);\n    cout << formatList(merged) << \'\\n\';\n\n    return 0;\n}',NULL,1,'2026-09-27 13:09:19','2026-09-28 15:16:03'),(496,135,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n#include <climits>\n#include <algorithm>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nint maxSum = INT_MIN;\n\nTreeNode* buildTree(const vector<string>& parts) {\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size() && parts[i] != \"null\") {\n            node->left = new TreeNode(stoi(parts[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < (int)parts.size() && parts[i] != \"null\") {\n            node->right = new TreeNode(stoi(parts[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nint dfs(TreeNode* node) {\n    if (node == nullptr) return 0;\n    int left = max(0, dfs(node->left));\n    int right = max(0, dfs(node->right));\n    maxSum = max(maxSum, node->val + left + right);\n    return node->val + max(left, right);\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    if (!line.empty() && line.front() == \'[\') line.erase(0, 1);\n    if (!line.empty() && line.back() == \']\') line.pop_back();\n\n    if (line.find_first_not_of(\" \\t\\r\\n\") == string::npos) {\n        cout << 0 << endl;\n        return 0;\n    }\n\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\\r\\n\");\n        size_t end = token.find_last_not_of(\" \\t\\r\\n\");\n        if (start == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(token.substr(start, end - start + 1));\n        }\n    }\n\n    TreeNode* root = buildTree(parts);\n    maxSum = INT_MIN;\n    dfs(root);\n    cout << maxSum << endl;\n\n    return 0;\n}',NULL,1,'2026-09-27 13:09:20','2026-09-28 15:16:03'),(497,136,'JAVA','import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int x) { val = x; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) line = line.substring(1);\n        if (line.endsWith(\"]\")) line = line.substring(0, line.length() - 1);\n        if (line.isEmpty()) {\n            System.out.println(\"[]\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        TreeNode root = buildTree(parts);\n        List<List<Integer>> result = zigzagLevelOrder(root);\n        System.out.println(format(result));\n    }\n\n    private static TreeNode buildTree(String[] parts) {\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode node = queue.poll();\n            if (i < parts.length) {\n                String leftVal = parts[i++].trim();\n                if (!leftVal.equals(\"null\")) {\n                    node.left = new TreeNode(Integer.parseInt(leftVal));\n                    queue.offer(node.left);\n                }\n            }\n            if (i < parts.length) {\n                String rightVal = parts[i++].trim();\n                if (!rightVal.equals(\"null\")) {\n                    node.right = new TreeNode(Integer.parseInt(rightVal));\n                    queue.offer(node.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    private static List<List<Integer>> zigzagLevelOrder(TreeNode root) {\n        List<List<Integer>> result = new ArrayList<>();\n        if (root == null) return result;\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        boolean leftToRight = true;\n        while (!queue.isEmpty()) {\n            int size = queue.size();\n            LinkedList<Integer> level = new LinkedList<>();\n            for (int i = 0; i < size; i++) {\n                TreeNode node = queue.poll();\n                if (leftToRight) {\n                    level.addLast(node.val);\n                } else {\n                    level.addFirst(node.val);\n                }\n                if (node.left != null) queue.offer(node.left);\n                if (node.right != null) queue.offer(node.right);\n            }\n            result.add(level);\n            leftToRight = !leftToRight;\n        }\n        return result;\n    }\n\n    private static String format(List<List<Integer>> result) {\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            sb.append(\"[\");\n            List<Integer> level = result.get(i);\n            for (int j = 0; j < level.size(); j++) {\n                sb.append(level.get(j));\n                if (j < level.size() - 1) sb.append(\",\");\n            }\n            sb.append(\"]\");\n            if (i < result.size() - 1) sb.append(\",\");\n        }\n        sb.append(\"]\");\n        return sb.toString();\n    }\n}',NULL,1,'2026-09-27 13:09:21','2026-09-28 15:16:03'),(498,135,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <limits.h>\n\nstruct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n};\n\nstatic int maxSum;\n\nstruct TreeNode* newNode(int val) {\n    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nstruct TreeNode* buildTree(char** parts, int n) {\n    if (n == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n    struct TreeNode* root = newNode(atoi(parts[0]));\n    struct TreeNode** queue = (struct TreeNode**)malloc(sizeof(struct TreeNode*) * n);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < n) {\n        struct TreeNode* node = queue[front++];\n        if (i < n && strcmp(parts[i], \"null\") != 0) {\n            node->left = newNode(atoi(parts[i]));\n            queue[rear++] = node->left;\n        }\n        i++;\n        if (i < n && strcmp(parts[i], \"null\") != 0) {\n            node->right = newNode(atoi(parts[i]));\n            queue[rear++] = node->right;\n        }\n        i++;\n    }\n    free(queue);\n    return root;\n}\n\nint dfs(struct TreeNode* node) {\n    if (node == NULL) return 0;\n    int left = dfs(node->left);\n    if (left < 0) left = 0;\n    int right = dfs(node->right);\n    if (right < 0) right = 0;\n    int cur = node->val + left + right;\n    if (cur > maxSum) maxSum = cur;\n    int ret = node->val + (left > right ? left : right);\n    return ret;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    char* s = line;\n    while (*s == \' \' || *s == \'\\t\') s++;\n    if (*s == \'[\') s++;\n    int end = strlen(s) - 1;\n    while (end >= 0 && (s[end] == \' \' || s[end] == \'\\t\')) end--;\n    if (end >= 0 && s[end] == \']\') s[end] = \'\\0\';\n\n    int isEmpty = 1;\n    for (int i = 0; s[i]; i++) {\n        if (s[i] != \' \' && s[i] != \'\\t\') { isEmpty = 0; break; }\n    }\n    if (isEmpty) {\n        printf(\"0\\n\");\n        return 0;\n    }\n\n    char* parts[100000];\n    int n = 0;\n    char* token = strtok(s, \",\");\n    while (token != NULL) {\n        while (*token == \' \' || *token == \'\\t\') token++;\n        int tl = strlen(token);\n        while (tl > 0 && (token[tl-1] == \' \' || token[tl-1] == \'\\t\')) token[--tl] = \'\\0\';\n        parts[n++] = token;\n        token = strtok(NULL, \",\");\n    }\n\n    struct TreeNode* root = buildTree(parts, n);\n    maxSum = INT_MIN;\n    dfs(root);\n    printf(\"%d\\n\", maxSum);\n    return 0;\n}',NULL,1,'2026-09-27 13:09:23','2026-09-28 15:16:03'),(499,133,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\ntypedef struct {\n    ListNode **data;\n    int size;\n    int capacity;\n} PriorityQueue;\n\nstatic void pq_init(PriorityQueue *pq, int capacity) {\n    pq->data = (ListNode **)malloc(sizeof(ListNode *) * capacity);\n    pq->size = 0;\n    pq->capacity = capacity;\n}\n\nstatic void pq_free(PriorityQueue *pq) {\n    free(pq->data);\n}\n\nstatic void pq_swap(ListNode **a, ListNode **b) {\n    ListNode *t = *a;\n    *a = *b;\n    *b = t;\n}\n\nstatic void pq_push(PriorityQueue *pq, ListNode *node) {\n    int i = pq->size++;\n    pq->data[i] = node;\n    while (i > 0) {\n        int p = (i - 1) / 2;\n        if (pq->data[p]->val <= pq->data[i]->val) break;\n        pq_swap(&pq->data[p], &pq->data[i]);\n        i = p;\n    }\n}\n\nstatic ListNode *pq_pop(PriorityQueue *pq) {\n    ListNode *res = pq->data[0];\n    pq->data[0] = pq->data[--pq->size];\n    int i = 0;\n    while (1) {\n        int l = i * 2 + 1;\n        int r = i * 2 + 2;\n        int smallest = i;\n        if (l < pq->size && pq->data[l]->val < pq->data[smallest]->val) smallest = l;\n        if (r < pq->size && pq->data[r]->val < pq->data[smallest]->val) smallest = r;\n        if (smallest == i) break;\n        pq_swap(&pq->data[i], &pq->data[smallest]);\n        i = smallest;\n    }\n    return res;\n}\n\nstatic ListNode *parseList(const char *s) {\n    if (s == NULL || s[0] == \'\\0\' || strcmp(s, \"NULL\") == 0) return NULL;\n    char *buf = (char *)malloc(strlen(s) + 1);\n    strcpy(buf, s);\n    ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    ListNode *cur = &dummy;\n    char *token = strtok(buf, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) break;\n        ListNode *node = (ListNode *)malloc(sizeof(ListNode));\n        node->val = atoi(token);\n        node->next = NULL;\n        cur->next = node;\n        cur = node;\n        token = strtok(NULL, \"->\");\n    }\n    free(buf);\n    return dummy.next;\n}\n\nstatic char *formatList(ListNode *head) {\n    size_t cap = 1024;\n    size_t len = 0;\n    char *res = (char *)malloc(cap);\n    res[0] = \'\\0\';\n    ListNode *cur = head;\n    while (cur != NULL) {\n        char tmp[32];\n        int n = snprintf(tmp, sizeof(tmp), \"%d->\", cur->val);\n        if (len + (size_t)n + 6 > cap) {\n            cap *= 2;\n            res = (char *)realloc(res, cap);\n        }\n        strcpy(res + len, tmp);\n        len += (size_t)n;\n        cur = cur->next;\n    }\n    if (len + 5 > cap) {\n        cap = len + 5;\n        res = (char *)realloc(res, cap);\n    }\n    strcpy(res + len, \"NULL\");\n    return res;\n}\n\nstatic ListNode *mergeKLists(ListNode **lists, int k) {\n    PriorityQueue pq;\n    pq_init(&pq, k > 0 ? k : 1);\n    for (int i = 0; i < k; i++) {\n        if (lists[i] != NULL) pq_push(&pq, lists[i]);\n    }\n    ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    ListNode *cur = &dummy;\n    while (pq.size > 0) {\n        ListNode *node = pq_pop(&pq);\n        cur->next = node;\n        cur = cur->next;\n        if (node->next != NULL) pq_push(&pq, node->next);\n    }\n    pq_free(&pq);\n    return dummy.next;\n}\n\nint main(void) {\n    int k;\n    if (scanf(\"%d\", &k) != 1) return 0;\n    int c;\n    while ((c = getchar()) != \'\\n\' && c != EOF) {}\n\n    ListNode **lists = (ListNode **)malloc(sizeof(ListNode *) * (k > 0 ? k : 1));\n    for (int i = 0; i < k; i++) {\n        size_t cap = 1024;\n        size_t len = 0;\n        char *line = (char *)malloc(cap);\n        line[0] = \'\\0\';\n        while ((c = getchar()) != \'\\n\' && c != EOF) {\n            if (len + 2 > cap) {\n                cap *= 2;\n                line = (char *)realloc(line, cap);\n            }\n            line[len++] = (char)c;\n            line[len] = \'\\0\';\n        }\n        lists[i] = parseList(line);\n        free(line);\n    }\n\n    ListNode *merged = mergeKLists(lists, k);\n    char *out = formatList(merged);\n    printf(\"%s\\n\", out);\n\n    free(out);\n    free(lists);\n    return 0;\n}',NULL,1,'2026-09-27 13:09:24','2026-09-28 15:16:03'),(500,135,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(parts):\n    if not parts or parts[0].strip() == \"null\":\n        return None\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts) and parts[i].strip() != \"null\":\n            node.left = TreeNode(int(parts[i].strip()))\n            queue.append(node.left)\n        i += 1\n        if i < len(parts) and parts[i].strip() != \"null\":\n            node.right = TreeNode(int(parts[i].strip()))\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:]\n    if line.endswith(\"]\"):\n        line = line[:-1]\n    if line.strip() == \"\":\n        print(0)\n        return\n    parts = line.split(\",\")\n    root = build_tree(parts)\n    max_sum = float(\"-inf\")\n    def dfs(node):\n        nonlocal max_sum\n        if node is None:\n            return 0\n        left = max(0, dfs(node.left))\n        right = max(0, dfs(node.right))\n        max_sum = max(max_sum, node.val + left + right)\n        return node.val + max(left, right)\n    dfs(root)\n    print(max_sum)\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:09:25','2026-09-28 15:16:03'),(501,133,'PYTHON','import sys\nimport heapq\n\nclass ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef parse_list(s):\n    if s is None or s == \"\" or s == \"NULL\":\n        return None\n    parts = s.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for p in parts:\n        if p == \"NULL\":\n            break\n        cur.next = ListNode(int(p.strip()))\n        cur = cur.next\n    return dummy.next\n\ndef format_list(head):\n    sb = []\n    cur = head\n    while cur is not None:\n        sb.append(str(cur.val))\n        sb.append(\"->\")\n        cur = cur.next\n    sb.append(\"NULL\")\n    return \"\".join(sb)\n\ndef merge_k_lists(lists):\n    heap = []\n    for node in lists:\n        if node is not None:\n            heapq.heappush(heap, (node.val, id(node), node))\n    dummy = ListNode(0)\n    cur = dummy\n    while heap:\n        val, _, node = heapq.heappop(heap)\n        cur.next = node\n        cur = cur.next\n        if node.next is not None:\n            heapq.heappush(heap, (node.next.val, id(node.next), node.next))\n    return dummy.next\n\ndef main():\n    data = sys.stdin.read().splitlines()\n    if not data:\n        return\n    k = int(data[0].strip())\n    lists = []\n    for i in range(1, k + 1):\n        line = data[i].strip() if i < len(data) else \"\"\n        lists.append(parse_list(line))\n    merged = merge_k_lists(lists)\n    print(format_list(merged))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:09:25','2026-09-28 15:16:03'),(502,136,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n#include <algorithm>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const vector<string>& parts) {\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i++];\n            if (leftVal != \"null\") {\n                node->left = new TreeNode(stoi(leftVal));\n                q.push(node->left);\n            }\n        }\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i++];\n            if (rightVal != \"null\") {\n                node->right = new TreeNode(stoi(rightVal));\n                q.push(node->right);\n            }\n        }\n    }\n    return root;\n}\n\nvector<vector<int>> zigzagLevelOrder(TreeNode* root) {\n    vector<vector<int>> result;\n    if (!root) return result;\n    queue<TreeNode*> q;\n    q.push(root);\n    bool leftToRight = true;\n    while (!q.empty()) {\n        int size = q.size();\n        vector<int> level(size);\n        for (int i = 0; i < size; i++) {\n            TreeNode* node = q.front();\n            q.pop();\n            int index = leftToRight ? i : (size - 1 - i);\n            level[index] = node->val;\n            if (node->left) q.push(node->left);\n            if (node->right) q.push(node->right);\n        }\n        result.push_back(level);\n        leftToRight = !leftToRight;\n    }\n    return result;\n}\n\nstring format(const vector<vector<int>>& result) {\n    string sb = \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        sb += \"[\";\n        const vector<int>& level = result[i];\n        for (int j = 0; j < (int)level.size(); j++) {\n            sb += to_string(level[j]);\n            if (j < (int)level.size() - 1) sb += \",\";\n        }\n        sb += \"]\";\n        if (i < (int)result.size() - 1) sb += \",\";\n    }\n    sb += \"]\";\n    return sb;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\' || line.back() == \' \')) {\n        line.pop_back();\n    }\n    size_t start = line.find_first_not_of(\" \\t\");\n    if (start != string::npos) line = line.substr(start);\n    if (!line.empty() && line.front() == \'[\') line = line.substr(1);\n    if (!line.empty() && line.back() == \']\') line.pop_back();\n    if (line.empty()) {\n        cout << \"[]\" << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t s = token.find_first_not_of(\" \\t\");\n        size_t e = token.find_last_not_of(\" \\t\");\n        if (s == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(token.substr(s, e - s + 1));\n        }\n    }\n    TreeNode* root = buildTree(parts);\n    vector<vector<int>> result = zigzagLevelOrder(root);\n    cout << format(result) << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:09:26','2026-09-28 15:16:03'),(503,135,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nlet maxSum = -Infinity;\n\nfunction buildTree(parts) {\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n    const root = new TreeNode(parseInt(parts[0].trim()));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length && parts[i].trim() !== \'null\') {\n            node.left = new TreeNode(parseInt(parts[i].trim()));\n            queue.push(node.left);\n        }\n        i++;\n        if (i < parts.length && parts[i].trim() !== \'null\') {\n            node.right = new TreeNode(parseInt(parts[i].trim()));\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction dfs(node) {\n    if (node === null) return 0;\n    const left = Math.max(0, dfs(node.left));\n    const right = Math.max(0, dfs(node.right));\n    maxSum = Math.max(maxSum, node.val + left + right);\n    return node.val + Math.max(left, right);\n}\n\nfunction maxPathSum(root) {\n    maxSum = -Infinity;\n    dfs(root);\n    return maxSum;\n}\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1);\n    if (line.endsWith(\']\')) line = line.substring(0, line.length - 1);\n\n    if (line.trim() === \'\') {\n        console.log(0);\n        rl.close();\n        return;\n    }\n\n    const parts = line.split(\',\');\n    const root = buildTree(parts);\n    maxPathSum(root);\n    console.log(maxSum);\n    rl.close();\n});',NULL,1,'2026-09-27 13:09:27','2026-09-28 15:16:03'),(504,133,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction parseList(s) {\n    if (!s || s === \'NULL\') return null;\n    const parts = s.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (const p of parts) {\n        if (p === \'NULL\') break;\n        cur.next = new ListNode(parseInt(p.trim(), 10));\n        cur = cur.next;\n    }\n    return dummy.next;\n}\n\nfunction formatList(head) {\n    let sb = \'\';\n    let cur = head;\n    while (cur !== null) {\n        sb += cur.val + \'->\';\n        cur = cur.next;\n    }\n    sb += \'NULL\';\n    return sb;\n}\n\nfunction mergeKLists(lists) {\n    const pq = [];\n    const push = (node) => {\n        pq.push(node);\n        let i = pq.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (pq[p].val <= pq[i].val) break;\n            [pq[p], pq[i]] = [pq[i], pq[p]];\n            i = p;\n        }\n    };\n    const pop = () => {\n        const top = pq[0];\n        const last = pq.pop();\n        if (pq.length > 0) {\n            pq[0] = last;\n            let i = 0;\n            while (true) {\n                let l = i * 2 + 1;\n                let r = i * 2 + 2;\n                let smallest = i;\n                if (l < pq.length && pq[l].val < pq[smallest].val) smallest = l;\n                if (r < pq.length && pq[r].val < pq[smallest].val) smallest = r;\n                if (smallest === i) break;\n                [pq[i], pq[smallest]] = [pq[smallest], pq[i]];\n                i = smallest;\n            }\n        }\n        return top;\n    };\n\n    for (const node of lists) {\n        if (node !== null) push(node);\n    }\n\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    while (pq.length > 0) {\n        const node = pop();\n        cur.next = node;\n        cur = cur.next;\n        if (node.next !== null) push(node.next);\n    }\n    return dummy.next;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const k = parseInt(lines[0].trim(), 10);\n    const lists = [];\n    for (let i = 0; i < k; i++) {\n        lists.push(parseList(lines[i + 1].trim()));\n    }\n    const merged = mergeKLists(lists);\n    console.log(formatList(merged));\n});',NULL,1,'2026-09-27 13:09:28','2026-09-28 15:16:03'),(505,137,'JAVA','import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        int k = Integer.parseInt(sc.nextLine().trim());\n\n        TreeNode root = buildTree(line);\n        System.out.println(kthSmallest(root, k));\n    }\n\n    private static TreeNode buildTree(String line) {\n        if (line == null || line.length() == 0) return null;\n        line = line.trim();\n        if (line.startsWith(\"[\")) line = line.substring(1);\n        if (line.endsWith(\"]\")) line = line.substring(0, line.length() - 1);\n        if (line.trim().isEmpty()) return null;\n\n        String[] parts = line.split(\",\");\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode cur = queue.poll();\n\n            if (i < parts.length) {\n                String leftVal = parts[i].trim();\n                i++;\n                if (!leftVal.equals(\"null\")) {\n                    cur.left = new TreeNode(Integer.parseInt(leftVal));\n                    queue.offer(cur.left);\n                }\n            }\n\n            if (i < parts.length) {\n                String rightVal = parts[i].trim();\n                i++;\n                if (!rightVal.equals(\"null\")) {\n                    cur.right = new TreeNode(Integer.parseInt(rightVal));\n                    queue.offer(cur.right);\n                }\n            }\n        }\n\n        return root;\n    }\n\n    private static int kthSmallest(TreeNode root, int k) {\n        Deque<TreeNode> stack = new ArrayDeque<>();\n        TreeNode cur = root;\n\n        while (cur != null || !stack.isEmpty()) {\n            while (cur != null) {\n                stack.push(cur);\n                cur = cur.left;\n            }\n            cur = stack.pop();\n            k--;\n            if (k == 0) return cur.val;\n            cur = cur.right;\n        }\n\n        return -1;\n    }\n}',NULL,1,'2026-09-27 13:09:30','2026-09-28 15:16:03'),(506,138,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int k = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        Deque<Integer> deque = new ArrayDeque<>();\n        int[] result = new int[n - k + 1];\n        int idx = 0;\n\n        for (int i = 0; i < n; i++) {\n            while (!deque.isEmpty() && deque.peekFirst() < i - k + 1) {\n                deque.pollFirst();\n            }\n            while (!deque.isEmpty() && nums[deque.peekLast()] < nums[i]) {\n                deque.pollLast();\n            }\n            deque.offerLast(i);\n            if (i >= k - 1) {\n                result[idx++] = nums[deque.peekFirst()];\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.length; i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(result[i]);\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1,'2026-09-27 13:09:30','2026-09-28 15:16:03'),(507,136,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\ntypedef struct {\n    TreeNode **data;\n    int front;\n    int rear;\n    int size;\n    int capacity;\n} Queue;\n\nQueue* createQueue(int capacity) {\n    Queue *q = (Queue*)malloc(sizeof(Queue));\n    q->data = (TreeNode**)malloc(sizeof(TreeNode*) * capacity);\n    q->front = 0;\n    q->rear = 0;\n    q->size = 0;\n    q->capacity = capacity;\n    return q;\n}\n\nvoid enqueue(Queue *q, TreeNode *node) {\n    if (q->size == q->capacity) {\n        q->capacity *= 2;\n        q->data = (TreeNode**)realloc(q->data, sizeof(TreeNode*) * q->capacity);\n    }\n    q->data[q->rear] = node;\n    q->rear = (q->rear + 1) % q->capacity;\n    q->size++;\n}\n\nTreeNode* dequeue(Queue *q) {\n    if (q->size == 0) return NULL;\n    TreeNode *node = q->data[q->front];\n    q->front = (q->front + 1) % q->capacity;\n    q->size--;\n    return node;\n}\n\nint isEmpty(Queue *q) {\n    return q->size == 0;\n}\n\nvoid freeQueue(Queue *q) {\n    free(q->data);\n    free(q);\n}\n\nTreeNode* buildTree(char **parts, int partsSize) {\n    if (partsSize == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n    TreeNode *root = (TreeNode*)malloc(sizeof(TreeNode));\n    root->val = atoi(parts[0]);\n    root->left = NULL;\n    root->right = NULL;\n    \n    Queue *q = createQueue(partsSize);\n    enqueue(q, root);\n    int i = 1;\n    while (!isEmpty(q) && i < partsSize) {\n        TreeNode *node = dequeue(q);\n        if (i < partsSize) {\n            char *leftVal = parts[i++];\n            if (strcmp(leftVal, \"null\") != 0) {\n                node->left = (TreeNode*)malloc(sizeof(TreeNode));\n                node->left->val = atoi(leftVal);\n                node->left->left = NULL;\n                node->left->right = NULL;\n                enqueue(q, node->left);\n            }\n        }\n        if (i < partsSize) {\n            char *rightVal = parts[i++];\n            if (strcmp(rightVal, \"null\") != 0) {\n                node->right = (TreeNode*)malloc(sizeof(TreeNode));\n                node->right->val = atoi(rightVal);\n                node->right->left = NULL;\n                node->right->right = NULL;\n                enqueue(q, node->right);\n            }\n        }\n    }\n    freeQueue(q);\n    return root;\n}\n\nint** zigzagLevelOrder(TreeNode *root, int *returnSize, int **returnColumnSizes) {\n    if (root == NULL) {\n        *returnSize = 0;\n        return NULL;\n    }\n    \n    int capacity = 100;\n    int **result = (int**)malloc(sizeof(int*) * capacity);\n    *returnColumnSizes = (int*)malloc(sizeof(int) * capacity);\n    *returnSize = 0;\n    \n    Queue *q = createQueue(1000);\n    enqueue(q, root);\n    int leftToRight = 1;\n    \n    while (!isEmpty(q)) {\n        int size = q->size;\n        int *level = (int*)malloc(sizeof(int) * size);\n        int idx = 0;\n        \n        for (int i = 0; i < size; i++) {\n            TreeNode *node = dequeue(q);\n            if (leftToRight) {\n                level[idx++] = node->val;\n            } else {\n                level[size - 1 - idx++] = node->val;\n            }\n            if (node->left) enqueue(q, node->left);\n            if (node->right) enqueue(q, node->right);\n        }\n        \n        if (*returnSize >= capacity) {\n            capacity *= 2;\n            result = (int**)realloc(result, sizeof(int*) * capacity);\n            *returnColumnSizes = (int*)realloc(*returnColumnSizes, sizeof(int) * capacity);\n        }\n        result[*returnSize] = level;\n        (*returnColumnSizes)[*returnSize] = size;\n        (*returnSize)++;\n        leftToRight = !leftToRight;\n    }\n    \n    freeQueue(q);\n    return result;\n}\n\nvoid freeTree(TreeNode *root) {\n    if (root == NULL) return;\n    freeTree(root->left);\n    freeTree(root->right);\n    free(root);\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    \n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    \n    char *start = line;\n    while (*start && isspace(*start)) start++;\n    char *end = start + strlen(start) - 1;\n    while (end > start && isspace(*end)) end--;\n    *(end + 1) = \'\\0\';\n    \n    if (*start == \'[\') start++;\n    end = start + strlen(start) - 1;\n    if (*end == \']\') *end = \'\\0\';\n    \n    if (strlen(start) == 0) {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    \n    char *parts[10000];\n    int partsSize = 0;\n    char *token = strtok(start, \",\");\n    while (token != NULL) {\n        while (*token && isspace(*token)) token++;\n        char *tend = token + strlen(token) - 1;\n        while (tend > token && isspace(*tend)) *tend-- = \'\\0\';\n        parts[partsSize++] = token;\n        token = strtok(NULL, \",\");\n    }\n    \n    TreeNode *root = buildTree(parts, partsSize);\n    \n    int returnSize;\n    int *returnColumnSizes;\n    int **result = zigzagLevelOrder(root, &returnSize, &returnColumnSizes);\n    \n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        printf(\"[\");\n        for (int j = 0; j < returnColumnSizes[i]; j++) {\n            printf(\"%d\", result[i][j]);\n            if (j < returnColumnSizes[i] - 1) printf(\",\");\n        }\n        printf(\"]\");\n        if (i < returnSize - 1) printf(\",\");\n    }\n    printf(\"]\\n\");\n    \n    for (int i = 0; i < returnSize; i++) {\n        free(result[i]);\n    }\n    free(result);\n    free(returnColumnSizes);\n    freeTree(root);\n    \n    return 0;\n}',NULL,1,'2026-09-27 13:09:31','2026-09-28 15:16:03'),(508,138,'CPP','#include <iostream>\n#include <vector>\n#include <deque>\nusing namespace std;\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    deque<int> dq;\n    vector<int> result(n - k + 1);\n    int idx = 0;\n\n    for (int i = 0; i < n; i++) {\n        while (!dq.empty() && dq.front() < i - k + 1) {\n            dq.pop_front();\n        }\n        while (!dq.empty() && nums[dq.back()] < nums[i]) {\n            dq.pop_back();\n        }\n        dq.push_back(i);\n        if (i >= k - 1) {\n            result[idx++] = nums[dq.front()];\n        }\n    }\n\n    cout << \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << result[i];\n    }\n    cout << \"]\" << endl;\n\n    return 0;\n}',NULL,1,'2026-09-27 13:09:33','2026-09-28 15:16:03'),(509,137,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\n#include <vector>\n#include <queue>\n#include <stack>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const string& line) {\n    if (line.empty()) return nullptr;\n    string s = line;\n    size_t start = s.find_first_not_of(\" \\t\");\n    size_t end = s.find_last_not_of(\" \\t\");\n    if (start == string::npos) return nullptr;\n    s = s.substr(start, end - start + 1);\n    if (s.front() == \'[\') s = s.substr(1);\n    if (s.back() == \']\') s.pop_back();\n    if (s.empty()) return nullptr;\n\n    vector<string> parts;\n    stringstream ss(s);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t l = token.find_first_not_of(\" \\t\");\n        size_t r = token.find_last_not_of(\" \\t\");\n        if (l == string::npos) parts.push_back(\"\");\n        else parts.push_back(token.substr(l, r - l + 1));\n    }\n\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* cur = q.front();\n        q.pop();\n\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i++];\n            if (leftVal != \"null\") {\n                cur->left = new TreeNode(stoi(leftVal));\n                q.push(cur->left);\n            }\n        }\n\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i++];\n            if (rightVal != \"null\") {\n                cur->right = new TreeNode(stoi(rightVal));\n                q.push(cur->right);\n            }\n        }\n    }\n\n    return root;\n}\n\nint kthSmallest(TreeNode* root, int k) {\n    stack<TreeNode*> st;\n    TreeNode* cur = root;\n\n    while (cur != nullptr || !st.empty()) {\n        while (cur != nullptr) {\n            st.push(cur);\n            cur = cur->left;\n        }\n        cur = st.top();\n        st.pop();\n        k--;\n        if (k == 0) return cur->val;\n        cur = cur->right;\n    }\n\n    return -1;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    int k;\n    cin >> k;\n\n    TreeNode* root = buildTree(line);\n    cout << kthSmallest(root, k) << endl;\n\n    return 0;\n}',NULL,1,'2026-09-27 13:09:34','2026-09-28 15:16:03'),(510,136,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, x):\n        self.val = x\n        self.left = None\n        self.right = None\n\ndef build_tree(parts):\n    if not parts or parts[0].strip() == \"null\":\n        return None\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts):\n            left_val = parts[i].strip()\n            i += 1\n            if left_val != \"null\":\n                node.left = TreeNode(int(left_val))\n                queue.append(node.left)\n        if i < len(parts):\n            right_val = parts[i].strip()\n            i += 1\n            if right_val != \"null\":\n                node.right = TreeNode(int(right_val))\n                queue.append(node.right)\n    return root\n\ndef zigzag_level_order(root):\n    result = []\n    if root is None:\n        return result\n    queue = deque([root])\n    left_to_right = True\n    while queue:\n        size = len(queue)\n        level = deque()\n        for _ in range(size):\n            node = queue.popleft()\n            if left_to_right:\n                level.append(node.val)\n            else:\n                level.appendleft(node.val)\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n        result.append(list(level))\n        left_to_right = not left_to_right\n    return result\n\ndef format_result(result):\n    sb = []\n    sb.append(\"[\")\n    for i, level in enumerate(result):\n        sb.append(\"[\")\n        for j, val in enumerate(level):\n            sb.append(str(val))\n            if j < len(level) - 1:\n                sb.append(\",\")\n        sb.append(\"]\")\n        if i < len(result) - 1:\n            sb.append(\",\")\n    sb.append(\"]\")\n    return \"\".join(sb)\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:]\n    if line.endswith(\"]\"):\n        line = line[:-1]\n    if not line:\n        print(\"[]\")\n        return\n    parts = line.split(\",\")\n    root = build_tree(parts)\n    result = zigzag_level_order(root)\n    print(format_result(result))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:09:34','2026-09-28 15:16:03'),(511,132,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* buildList(const string& s) {\n    if (s.empty() || s == \"NULL\") return nullptr;\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    size_t start = 0;\n    while (start < s.size()) {\n        size_t pos = s.find(\"->\", start);\n        string part;\n        if (pos == string::npos) {\n            part = s.substr(start);\n            start = s.size();\n        } else {\n            part = s.substr(start, pos - start);\n            start = pos + 2;\n        }\n        if (part == \"NULL\") break;\n        cur->next = new ListNode(stoi(part));\n        cur = cur->next;\n    }\n    return dummy.next;\n}\n\nstring printList(ListNode* head) {\n    string res;\n    ListNode* cur = head;\n    while (cur) {\n        res += to_string(cur->val);\n        res += \"->\";\n        cur = cur->next;\n    }\n    res += \"NULL\";\n    return res;\n}\n\nListNode* rotateRight(ListNode* head, int k) {\n    if (!head || !head->next || k == 0) return head;\n\n    int len = 1;\n    ListNode* tail = head;\n    while (tail->next) {\n        tail = tail->next;\n        len++;\n    }\n\n    k %= len;\n    if (k == 0) return head;\n\n    tail->next = head;\n    ListNode* newTail = head;\n    for (int i = 0; i < len - k - 1; i++) {\n        newTail = newTail->next;\n    }\n\n    ListNode* newHead = newTail->next;\n    newTail->next = nullptr;\n    return newHead;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    string line;\n    getline(cin, line);\n    int k;\n    cin >> k;\n\n    ListNode* head = buildList(line);\n    head = rotateRight(head, k);\n    cout << printList(head) << \'\\n\';\n\n    return 0;\n}',NULL,1,'2026-09-27 13:09:34','2026-09-28 15:16:03'),(512,138,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n, k;\n    scanf(\"%d %d\", &n, &k);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int *deque = (int *)malloc(n * sizeof(int));\n    int head = 0, tail = 0;\n    int *result = (int *)malloc((n - k + 1) * sizeof(int));\n    int idx = 0;\n\n    for (int i = 0; i < n; i++) {\n        while (head < tail && deque[head] < i - k + 1) {\n            head++;\n        }\n        while (head < tail && nums[deque[tail - 1]] < nums[i]) {\n            tail--;\n        }\n        deque[tail++] = i;\n        if (i >= k - 1) {\n            result[idx++] = nums[deque[head]];\n        }\n    }\n\n    printf(\"[\");\n    for (int i = 0; i < idx; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", result[i]);\n    }\n    printf(\"]\\n\");\n\n    free(nums);\n    free(deque);\n    free(result);\n    return 0;\n}',NULL,1,'2026-09-27 13:09:35','2026-09-28 15:16:03'),(513,136,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(parts) {\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n    const root = new TreeNode(parseInt(parts[0].trim()));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length) {\n            const leftVal = parts[i++].trim();\n            if (leftVal !== \'null\') {\n                node.left = new TreeNode(parseInt(leftVal));\n                queue.push(node.left);\n            }\n        }\n        if (i < parts.length) {\n            const rightVal = parts[i++].trim();\n            if (rightVal !== \'null\') {\n                node.right = new TreeNode(parseInt(rightVal));\n                queue.push(node.right);\n            }\n        }\n    }\n    return root;\n}\n\nfunction zigzagLevelOrder(root) {\n    const result = [];\n    if (root === null) return result;\n    const queue = [root];\n    let leftToRight = true;\n    while (queue.length > 0) {\n        const size = queue.length;\n        const level = [];\n        for (let i = 0; i < size; i++) {\n            const node = queue.shift();\n            if (leftToRight) {\n                level.push(node.val);\n            } else {\n                level.unshift(node.val);\n            }\n            if (node.left !== null) queue.push(node.left);\n            if (node.right !== null) queue.push(node.right);\n        }\n        result.push(level);\n        leftToRight = !leftToRight;\n    }\n    return result;\n}\n\nfunction format(result) {\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < result.length; i++) {\n        sb += \'[\';\n        const level = result[i];\n        for (let j = 0; j < level.length; j++) {\n            sb += level[j];\n            if (j < level.length - 1) sb += \',\';\n        }\n        sb += \']\';\n        if (i < result.length - 1) sb += \',\';\n    }\n    sb += \']\';\n    return sb;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1);\n    if (line.endsWith(\']\')) line = line.substring(0, line.length - 1);\n    if (line.length === 0) {\n        console.log(\'[]\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const root = buildTree(parts);\n    const result = zigzagLevelOrder(root);\n    console.log(format(result));\n    rl.close();\n});',NULL,1,'2026-09-27 13:09:36','2026-09-28 15:16:03'),(514,138,'PYTHON','import sys\nfrom collections import deque\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    k = int(data[1])\n    nums = list(map(int, data[2:2 + n]))\n\n    dq = deque()\n    result = []\n\n    for i in range(n):\n        while dq and dq[0] < i - k + 1:\n            dq.popleft()\n        while dq and nums[dq[-1]] < nums[i]:\n            dq.pop()\n        dq.append(i)\n        if i >= k - 1:\n            result.append(nums[dq[0]])\n\n    print(\"[\" + \",\".join(map(str, result)) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:09:36','2026-09-28 15:16:03'),(515,137,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nstatic TreeNode* newTreeNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nstatic char* trim(char* s) {\n    while (*s && isspace((unsigned char)*s)) s++;\n    if (*s == \'\\0\') return s;\n    char* end = s + strlen(s) - 1;\n    while (end > s && isspace((unsigned char)*end)) {\n        *end = \'\\0\';\n        end--;\n    }\n    return s;\n}\n\nstatic TreeNode* buildTree(char* line) {\n    if (line == NULL) return NULL;\n    line = trim(line);\n    if (*line == \'\\0\') return NULL;\n\n    if (line[0] == \'[\') line++;\n    size_t len = strlen(line);\n    if (len > 0 && line[len - 1] == \']\') line[len - 1] = \'\\0\';\n    line = trim(line);\n    if (*line == \'\\0\') return NULL;\n\n    char* parts[10000];\n    int count = 0;\n    char* token = strtok(line, \",\");\n    while (token != NULL && count < 10000) {\n        parts[count++] = trim(token);\n        token = strtok(NULL, \",\");\n    }\n\n    if (count == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n\n    TreeNode* root = newTreeNode(atoi(parts[0]));\n    TreeNode* queue[10000];\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n\n    while (front < rear && i < count) {\n        TreeNode* cur = queue[front++];\n\n        if (i < count) {\n            char* leftVal = parts[i++];\n            if (strcmp(leftVal, \"null\") != 0) {\n                cur->left = newTreeNode(atoi(leftVal));\n                queue[rear++] = cur->left;\n            }\n        }\n\n        if (i < count) {\n            char* rightVal = parts[i++];\n            if (strcmp(rightVal, \"null\") != 0) {\n                cur->right = newTreeNode(atoi(rightVal));\n                queue[rear++] = cur->right;\n            }\n        }\n    }\n\n    return root;\n}\n\nstatic int kthSmallest(TreeNode* root, int k) {\n    TreeNode* stack[10000];\n    int top = 0;\n    TreeNode* cur = root;\n\n    while (cur != NULL || top > 0) {\n        while (cur != NULL) {\n            stack[top++] = cur;\n            cur = cur->left;\n        }\n        cur = stack[--top];\n        k--;\n        if (k == 0) return cur->val;\n        cur = cur->right;\n    }\n\n    return -1;\n}\n\nint main(void) {\n    char line[100000];\n    int k;\n\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    line[strcspn(line, \"\\r\\n\")] = \'\\0\';\n\n    if (scanf(\"%d\", &k) != 1) return 0;\n\n    TreeNode* root = buildTree(line);\n    printf(\"%d\\n\", kthSmallest(root, k));\n\n    return 0;\n}',NULL,1,'2026-09-27 13:09:37','2026-09-28 15:16:03'),(516,132,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstruct ListNode {\n    int val;\n    struct ListNode *next;\n};\n\nstruct ListNode* buildList(char *s) {\n    if (s == NULL || s[0] == \'\\0\' || strcmp(s, \"NULL\") == 0) {\n        return NULL;\n    }\n    struct ListNode dummy;\n    dummy.next = NULL;\n    struct ListNode *cur = &dummy;\n    char *token = strtok(s, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) {\n            break;\n        }\n        struct ListNode *node = (struct ListNode*)malloc(sizeof(struct ListNode));\n        node->val = atoi(token);\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n        token = strtok(NULL, \"->\");\n    }\n    return dummy.next;\n}\n\nchar* printList(struct ListNode *head) {\n    char *buf = (char*)malloc(1000000);\n    buf[0] = \'\\0\';\n    struct ListNode *cur = head;\n    while (cur != NULL) {\n        char tmp[32];\n        sprintf(tmp, \"%d->\", cur->val);\n        strcat(buf, tmp);\n        cur = cur->next;\n    }\n    strcat(buf, \"NULL\");\n    return buf;\n}\n\nstruct ListNode* rotateRight(struct ListNode *head, int k) {\n    if (head == NULL || head->next == NULL || k == 0) {\n        return head;\n    }\n\n    int len = 1;\n    struct ListNode *tail = head;\n    while (tail->next != NULL) {\n        tail = tail->next;\n        len++;\n    }\n\n    k = k % len;\n    if (k == 0) {\n        return head;\n    }\n\n    tail->next = head;\n    struct ListNode *newTail = head;\n    for (int i = 0; i < len - k - 1; i++) {\n        newTail = newTail->next;\n    }\n\n    struct ListNode *newHead = newTail->next;\n    newTail->next = NULL;\n    return newHead;\n}\n\nint main() {\n    char line[1000000];\n    int k;\n\n    if (fgets(line, sizeof(line), stdin) == NULL) {\n        return 0;\n    }\n    line[strcspn(line, \"\\r\\n\")] = \'\\0\';\n\n    if (scanf(\"%d\", &k) != 1) {\n        return 0;\n    }\n\n    struct ListNode *head = buildList(line);\n    head = rotateRight(head, k);\n    char *result = printList(head);\n    printf(\"%s\\n\", result);\n\n    free(result);\n    return 0;\n}',NULL,1,'2026-09-27 13:09:37','2026-09-28 15:16:03'),(517,138,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const [n, k] = lines[0].split(\' \').map(Number);\n    const nums = lines[1].split(\' \').map(Number);\n\n    const deque = [];\n    const result = [];\n\n    for (let i = 0; i < n; i++) {\n        while (deque.length > 0 && deque[0] < i - k + 1) {\n            deque.shift();\n        }\n        while (deque.length > 0 && nums[deque[deque.length - 1]] < nums[i]) {\n            deque.pop();\n        }\n        deque.push(i);\n        if (i >= k - 1) {\n            result.push(nums[deque[0]]);\n        }\n    }\n\n    console.log(\'[\' + result.join(\',\') + \']\');\n});',NULL,1,'2026-09-27 13:09:38','2026-09-28 15:16:03'),(518,139,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int numCourses = sc.nextInt();\n        int m = sc.nextInt();\n\n        List<List<Integer>> graph = new ArrayList<>();\n        for (int i = 0; i < numCourses; i++) {\n            graph.add(new ArrayList<>());\n        }\n\n        int[] indegree = new int[numCourses];\n\n        for (int i = 0; i < m; i++) {\n            int ai = sc.nextInt();\n            int bi = sc.nextInt();\n            graph.get(bi).add(ai);\n            indegree[ai]++;\n        }\n\n        PriorityQueue<Integer> pq = new PriorityQueue<>();\n        for (int i = 0; i < numCourses; i++) {\n            if (indegree[i] == 0) {\n                pq.offer(i);\n            }\n        }\n\n        List<Integer> order = new ArrayList<>();\n        while (!pq.isEmpty()) {\n            int cur = pq.poll();\n            order.add(cur);\n            for (int next : graph.get(cur)) {\n                indegree[next]--;\n                if (indegree[next] == 0) {\n                    pq.offer(next);\n                }\n            }\n        }\n\n        if (order.size() != numCourses) {\n            System.out.println(\"[]\");\n        } else {\n            StringBuilder sb = new StringBuilder();\n            for (int i = 0; i < order.size(); i++) {\n                if (i > 0) sb.append(\' \');\n                sb.append(order.get(i));\n            }\n            System.out.println(sb.toString());\n        }\n    }\n}',NULL,1,'2026-09-27 13:09:39','2026-09-28 15:16:03'),(519,137,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(line):\n    if line is None or len(line) == 0:\n        return None\n    line = line.strip()\n    if line.startswith(\"[\"):\n        line = line[1:]\n    if line.endswith(\"]\"):\n        line = line[:-1]\n    if line.strip() == \"\":\n        return None\n\n    parts = line.split(\",\")\n    if len(parts) == 0 or parts[0].strip() == \"null\":\n        return None\n\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n\n    while queue and i < len(parts):\n        cur = queue.popleft()\n\n        if i < len(parts):\n            left_val = parts[i].strip()\n            i += 1\n            if left_val != \"null\":\n                cur.left = TreeNode(int(left_val))\n                queue.append(cur.left)\n\n        if i < len(parts):\n            right_val = parts[i].strip()\n            i += 1\n            if right_val != \"null\":\n                cur.right = TreeNode(int(right_val))\n                queue.append(cur.right)\n\n    return root\n\ndef kth_smallest(root, k):\n    stack = []\n    cur = root\n\n    while cur is not None or stack:\n        while cur is not None:\n            stack.append(cur)\n            cur = cur.left\n        cur = stack.pop()\n        k -= 1\n        if k == 0:\n            return cur.val\n        cur = cur.right\n\n    return -1\n\ndef main():\n    line = sys.stdin.readline().strip()\n    k = int(sys.stdin.readline().strip())\n    root = build_tree(line)\n    print(kth_smallest(root, k))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:09:39','2026-09-28 15:16:03'),(520,132,'PYTHON','import sys\n\nclass ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef build_list(s):\n    if s is None or s == \"\" or s == \"NULL\":\n        return None\n    parts = s.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for part in parts:\n        if part == \"NULL\":\n            break\n        cur.next = ListNode(int(part))\n        cur = cur.next\n    return dummy.next\n\ndef print_list(head):\n    sb = []\n    cur = head\n    while cur is not None:\n        sb.append(str(cur.val))\n        sb.append(\"->\")\n        cur = cur.next\n    sb.append(\"NULL\")\n    return \"\".join(sb)\n\ndef rotate_right(head, k):\n    if head is None or head.next is None or k == 0:\n        return head\n\n    length = 1\n    tail = head\n    while tail.next is not None:\n        tail = tail.next\n        length += 1\n\n    k = k % length\n    if k == 0:\n        return head\n\n    tail.next = head\n    new_tail = head\n    for _ in range(length - k - 1):\n        new_tail = new_tail.next\n\n    new_head = new_tail.next\n    new_tail.next = None\n    return new_head\n\ndef main():\n    lines = sys.stdin.read().splitlines()\n    if not lines:\n        return\n    line = lines[0].strip()\n    k = int(lines[1].strip())\n\n    head = build_list(line)\n    head = rotate_right(head, k)\n    print(print_list(head))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:09:39','2026-09-28 15:16:03'),(521,140,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine();\n        int n = s.length();\n        int[] dp = new int[n];\n        int max = 0;\n        for (int i = 1; i < n; i++) {\n            if (s.charAt(i) == \')\') {\n                if (s.charAt(i - 1) == \'(\') {\n                    dp[i] = (i >= 2 ? dp[i - 2] : 0) + 2;\n                } else if (i - dp[i - 1] > 0 && s.charAt(i - dp[i - 1] - 1) == \'(\') {\n                    dp[i] = dp[i - 1] + ((i - dp[i - 1] >= 2) ? dp[i - dp[i - 1] - 2] : 0) + 2;\n                }\n                max = Math.max(max, dp[i]);\n            }\n        }\n        System.out.println(max);\n    }\n}',NULL,1,'2026-09-27 13:09:40','2026-09-28 15:16:03'),(522,139,'CPP','#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int numCourses, m;\n    cin >> numCourses >> m;\n\n    vector<vector<int>> graph(numCourses);\n    vector<int> indegree(numCourses, 0);\n\n    for (int i = 0; i < m; i++) {\n        int ai, bi;\n        cin >> ai >> bi;\n        graph[bi].push_back(ai);\n        indegree[ai]++;\n    }\n\n    priority_queue<int, vector<int>, greater<int>> pq;\n    for (int i = 0; i < numCourses; i++) {\n        if (indegree[i] == 0) {\n            pq.push(i);\n        }\n    }\n\n    vector<int> order;\n    while (!pq.empty()) {\n        int cur = pq.top();\n        pq.pop();\n        order.push_back(cur);\n        for (int next : graph[cur]) {\n            indegree[next]--;\n            if (indegree[next] == 0) {\n                pq.push(next);\n            }\n        }\n    }\n\n    if ((int)order.size() != numCourses) {\n        cout << \"[]\" << endl;\n    } else {\n        for (int i = 0; i < (int)order.size(); i++) {\n            if (i > 0) cout << \' \';\n            cout << order[i];\n        }\n        cout << endl;\n    }\n\n    return 0;\n}',NULL,1,'2026-09-27 13:09:42','2026-09-28 15:16:03'),(523,137,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(line) {\n    if (line === null || line.length === 0) return null;\n    line = line.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1);\n    if (line.endsWith(\']\')) line = line.substring(0, line.length - 1);\n    if (line.trim().length === 0) return null;\n\n    const parts = line.split(\',\');\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n\n    const root = new TreeNode(parseInt(parts[0].trim()));\n    const queue = [root];\n    let i = 1;\n\n    while (queue.length > 0 && i < parts.length) {\n        const cur = queue.shift();\n\n        if (i < parts.length) {\n            const leftVal = parts[i].trim();\n            i++;\n            if (leftVal !== \'null\') {\n                cur.left = new TreeNode(parseInt(leftVal));\n                queue.push(cur.left);\n            }\n        }\n\n        if (i < parts.length) {\n            const rightVal = parts[i].trim();\n            i++;\n            if (rightVal !== \'null\') {\n                cur.right = new TreeNode(parseInt(rightVal));\n                queue.push(cur.right);\n            }\n        }\n    }\n\n    return root;\n}\n\nfunction kthSmallest(root, k) {\n    const stack = [];\n    let cur = root;\n\n    while (cur !== null || stack.length > 0) {\n        while (cur !== null) {\n            stack.push(cur);\n            cur = cur.left;\n        }\n        cur = stack.pop();\n        k--;\n        if (k === 0) return cur.val;\n        cur = cur.right;\n    }\n\n    return -1;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 2) {\n        const treeLine = lines[0].trim();\n        const k = parseInt(lines[1].trim());\n        const root = buildTree(treeLine);\n        console.log(kthSmallest(root, k));\n        rl.close();\n    }\n});',NULL,1,'2026-09-27 13:09:42','2026-09-28 15:16:03'),(524,132,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction buildList(s) {\n    if (s === null || s === \'\' || s === \'NULL\') {\n        return null;\n    }\n    const parts = s.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (const part of parts) {\n        if (part === \'NULL\') {\n            break;\n        }\n        cur.next = new ListNode(parseInt(part));\n        cur = cur.next;\n    }\n    return dummy.next;\n}\n\nfunction printList(head) {\n    let sb = \'\';\n    let cur = head;\n    while (cur !== null) {\n        sb += cur.val + \'->\';\n        cur = cur.next;\n    }\n    sb += \'NULL\';\n    return sb;\n}\n\nfunction rotateRight(head, k) {\n    if (head === null || head.next === null || k === 0) {\n        return head;\n    }\n\n    let len = 1;\n    let tail = head;\n    while (tail.next !== null) {\n        tail = tail.next;\n        len++;\n    }\n\n    k = k % len;\n    if (k === 0) {\n        return head;\n    }\n\n    tail.next = head;\n    let newTail = head;\n    for (let i = 0; i < len - k - 1; i++) {\n        newTail = newTail.next;\n    }\n\n    const newHead = newTail.next;\n    newTail.next = null;\n    return newHead;\n}\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const listLine = lines[0];\n        const k = parseInt(lines[1]);\n\n        let head = buildList(listLine);\n        head = rotateRight(head, k);\n        console.log(printList(head));\n        rl.close();\n    }\n});',NULL,1,'2026-09-27 13:09:42','2026-09-28 15:16:03'),(525,140,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n    int n = s.length();\n    vector<int> dp(n, 0);\n    int maxLen = 0;\n    for (int i = 1; i < n; i++) {\n        if (s[i] == \')\') {\n            if (s[i - 1] == \'(\') {\n                dp[i] = (i >= 2 ? dp[i - 2] : 0) + 2;\n            } else if (i - dp[i - 1] > 0 && s[i - dp[i - 1] - 1] == \'(\') {\n                dp[i] = dp[i - 1] + ((i - dp[i - 1] >= 2) ? dp[i - dp[i - 1] - 2] : 0) + 2;\n            }\n            maxLen = max(maxLen, dp[i]);\n        }\n    }\n    cout << maxLen << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:09:42','2026-09-28 15:16:03'),(526,140,'C','#include <stdio.h>\n#include <string.h>\n\nint main() {\n    char s[100005];\n    if (scanf(\"%s\", s) != 1) return 0;\n    int n = strlen(s);\n    int dp[100005] = {0};\n    int max = 0;\n    for (int i = 1; i < n; i++) {\n        if (s[i] == \')\') {\n            if (s[i - 1] == \'(\') {\n                dp[i] = (i >= 2 ? dp[i - 2] : 0) + 2;\n            } else if (i - dp[i - 1] > 0 && s[i - dp[i - 1] - 1] == \'(\') {\n                dp[i] = dp[i - 1] + ((i - dp[i - 1] >= 2) ? dp[i - dp[i - 1] - 2] : 0) + 2;\n            }\n            if (dp[i] > max) max = dp[i];\n        }\n    }\n    printf(\"%d\\n\", max);\n    return 0;\n}',NULL,1,'2026-09-27 13:09:44','2026-09-28 15:16:03'),(527,142,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n        char[][] matrix = new char[m][n];\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine().trim();\n            matrix[i] = line.toCharArray();\n        }\n\n        int[][] dp = new int[m + 1][n + 1];\n        int maxSide = 0;\n\n        for (int i = 1; i <= m; i++) {\n            for (int j = 1; j <= n; j++) {\n                if (matrix[i - 1][j - 1] == \'1\') {\n                    dp[i][j] = Math.min(Math.min(dp[i - 1][j], dp[i][j - 1]), dp[i - 1][j - 1]) + 1;\n                    maxSide = Math.max(maxSide, dp[i][j]);\n                }\n            }\n        }\n\n        System.out.println(maxSide * maxSide);\n    }\n}',NULL,1,'2026-09-27 13:09:44','2026-09-28 15:16:03'),(528,141,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static int count = 0;\n    static int n;\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        n = sc.nextInt();\n        boolean[] col = new boolean[n];\n        boolean[] diag1 = new boolean[2 * n];\n        boolean[] diag2 = new boolean[2 * n];\n        dfs(0, col, diag1, diag2);\n        System.out.println(count);\n    }\n\n    static void dfs(int row, boolean[] col, boolean[] diag1, boolean[] diag2) {\n        if (row == n) {\n            count++;\n            return;\n        }\n        for (int c = 0; c < n; c++) {\n            int d1 = row + c;\n            int d2 = row - c + n;\n            if (!col[c] && !diag1[d1] && !diag2[d2]) {\n                col[c] = true;\n                diag1[d1] = true;\n                diag2[d2] = true;\n                dfs(row + 1, col, diag1, diag2);\n                col[c] = false;\n                diag1[d1] = false;\n                diag2[d2] = false;\n            }\n        }\n    }\n}',NULL,1,'2026-09-27 13:09:44','2026-09-28 15:16:03'),(529,139,'C','#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int *data;\n    int size;\n    int capacity;\n} Heap;\n\nvoid heapInit(Heap *h, int capacity) {\n    h->data = (int *)malloc(sizeof(int) * capacity);\n    h->size = 0;\n    h->capacity = capacity;\n}\n\nvoid heapPush(Heap *h, int value) {\n    int i = h->size++;\n    h->data[i] = value;\n    while (i > 0) {\n        int parent = (i - 1) / 2;\n        if (h->data[parent] <= h->data[i]) break;\n        int tmp = h->data[parent];\n        h->data[parent] = h->data[i];\n        h->data[i] = tmp;\n        i = parent;\n    }\n}\n\nint heapPop(Heap *h) {\n    int result = h->data[0];\n    h->data[0] = h->data[--h->size];\n    int i = 0;\n    while (1) {\n        int left = i * 2 + 1;\n        int right = i * 2 + 2;\n        int smallest = i;\n        if (left < h->size && h->data[left] < h->data[smallest]) smallest = left;\n        if (right < h->size && h->data[right] < h->data[smallest]) smallest = right;\n        if (smallest == i) break;\n        int tmp = h->data[i];\n        h->data[i] = h->data[smallest];\n        h->data[smallest] = tmp;\n        i = smallest;\n    }\n    return result;\n}\n\nint main() {\n    int numCourses, m;\n    scanf(\"%d\", &numCourses);\n    scanf(\"%d\", &m);\n\n    int **graph = (int **)malloc(sizeof(int *) * numCourses);\n    int *graphSize = (int *)calloc(numCourses, sizeof(int));\n    int *graphCap = (int *)calloc(numCourses, sizeof(int));\n    for (int i = 0; i < numCourses; i++) {\n        graphCap[i] = 4;\n        graph[i] = (int *)malloc(sizeof(int) * graphCap[i]);\n    }\n\n    int *indegree = (int *)calloc(numCourses, sizeof(int));\n\n    for (int i = 0; i < m; i++) {\n        int ai, bi;\n        scanf(\"%d %d\", &ai, &bi);\n        if (graphSize[bi] == graphCap[bi]) {\n            graphCap[bi] *= 2;\n            graph[bi] = (int *)realloc(graph[bi], sizeof(int) * graphCap[bi]);\n        }\n        graph[bi][graphSize[bi]++] = ai;\n        indegree[ai]++;\n    }\n\n    Heap pq;\n    heapInit(&pq, numCourses);\n    for (int i = 0; i < numCourses; i++) {\n        if (indegree[i] == 0) {\n            heapPush(&pq, i);\n        }\n    }\n\n    int *order = (int *)malloc(sizeof(int) * numCourses);\n    int orderSize = 0;\n\n    while (pq.size > 0) {\n        int cur = heapPop(&pq);\n        order[orderSize++] = cur;\n        for (int i = 0; i < graphSize[cur]; i++) {\n            int next = graph[cur][i];\n            indegree[next]--;\n            if (indegree[next] == 0) {\n                heapPush(&pq, next);\n            }\n        }\n    }\n\n    if (orderSize != numCourses) {\n        printf(\"[]\\n\");\n    } else {\n        for (int i = 0; i < orderSize; i++) {\n            if (i > 0) printf(\" \");\n            printf(\"%d\", order[i]);\n        }\n        printf(\"\\n\");\n    }\n\n    for (int i = 0; i < numCourses; i++) {\n        free(graph[i]);\n    }\n    free(graph);\n    free(graphSize);\n    free(graphCap);\n    free(indegree);\n    free(order);\n    free(pq.data);\n\n    return 0;\n}',NULL,1,'2026-09-27 13:09:45','2026-09-28 15:16:03'),(530,140,'PYTHON','s = input()\nn = len(s)\ndp = [0] * n\nmax_len = 0\nfor i in range(1, n):\n    if s[i] == \')\':\n        if s[i - 1] == \'(\':\n            dp[i] = (dp[i - 2] if i >= 2 else 0) + 2\n        elif i - dp[i - 1] > 0 and s[i - dp[i - 1] - 1] == \'(\':\n            dp[i] = dp[i - 1] + (dp[i - dp[i - 1] - 2] if i - dp[i - 1] >= 2 else 0) + 2\n        max_len = max(max_len, dp[i])\nprint(max_len)',NULL,1,'2026-09-27 13:09:45','2026-09-28 15:16:03'),(531,142,'CPP','#include <iostream>\n#include <vector>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    cin.ignore();\n    vector<string> matrix(m);\n    for (int i = 0; i < m; i++) {\n        getline(cin, matrix[i]);\n    }\n\n    vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));\n    int maxSide = 0;\n\n    for (int i = 1; i <= m; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (matrix[i - 1][j - 1] == \'1\') {\n                dp[i][j] = min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]}) + 1;\n                maxSide = max(maxSide, dp[i][j]);\n            }\n        }\n    }\n\n    cout << maxSide * maxSide << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:09:46','2026-09-28 15:16:03'),(532,141,'CPP','#include <iostream>\nusing namespace std;\n\nint count = 0;\nint n;\nbool col[20];\nbool diag1[40];\nbool diag2[40];\n\nvoid dfs(int row) {\n    if (row == n) {\n        count++;\n        return;\n    }\n    for (int c = 0; c < n; c++) {\n        int d1 = row + c;\n        int d2 = row - c + n;\n        if (!col[c] && !diag1[d1] && !diag2[d2]) {\n            col[c] = true;\n            diag1[d1] = true;\n            diag2[d2] = true;\n            dfs(row + 1);\n            col[c] = false;\n            diag1[d1] = false;\n            diag2[d2] = false;\n        }\n    }\n}\n\nint main() {\n    cin >> n;\n    dfs(0);\n    cout << count << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:09:46','2026-09-28 15:16:03'),(533,140,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    const n = s.length;\n    const dp = new Array(n).fill(0);\n    let max = 0;\n    for (let i = 1; i < n; i++) {\n        if (s[i] === \')\') {\n            if (s[i - 1] === \'(\') {\n                dp[i] = (i >= 2 ? dp[i - 2] : 0) + 2;\n            } else if (i - dp[i - 1] > 0 && s[i - dp[i - 1] - 1] === \'(\') {\n                dp[i] = dp[i - 1] + ((i - dp[i - 1] >= 2) ? dp[i - dp[i - 1] - 2] : 0) + 2;\n            }\n            max = Math.max(max, dp[i]);\n        }\n    }\n    console.log(max);\n    rl.close();\n});',NULL,1,'2026-09-27 13:09:47','2026-09-28 15:16:03'),(534,139,'PYTHON','import sys\nimport heapq\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    it = iter(data)\n    numCourses = int(next(it))\n    m = int(next(it))\n\n    graph = [[] for _ in range(numCourses)]\n    indegree = [0] * numCourses\n\n    for _ in range(m):\n        ai = int(next(it))\n        bi = int(next(it))\n        graph[bi].append(ai)\n        indegree[ai] += 1\n\n    pq = []\n    for i in range(numCourses):\n        if indegree[i] == 0:\n            heapq.heappush(pq, i)\n\n    order = []\n    while pq:\n        cur = heapq.heappop(pq)\n        order.append(cur)\n        for nxt in graph[cur]:\n            indegree[nxt] -= 1\n            if indegree[nxt] == 0:\n                heapq.heappush(pq, nxt)\n\n    if len(order) != numCourses:\n        print(\"[]\")\n    else:\n        print(\" \".join(map(str, order)))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:09:47','2026-09-28 15:16:03'),(535,141,'C','#include <stdio.h>\n#include <stdbool.h>\n\nint count = 0;\nint n;\n\nvoid dfs(int row, bool col[], bool diag1[], bool diag2[]) {\n    if (row == n) {\n        count++;\n        return;\n    }\n    for (int c = 0; c < n; c++) {\n        int d1 = row + c;\n        int d2 = row - c + n;\n        if (!col[c] && !diag1[d1] && !diag2[d2]) {\n            col[c] = true;\n            diag1[d1] = true;\n            diag2[d2] = true;\n            dfs(row + 1, col, diag1, diag2);\n            col[c] = false;\n            diag1[d1] = false;\n            diag2[d2] = false;\n        }\n    }\n}\n\nint main() {\n    scanf(\"%d\", &n);\n    bool col[n];\n    bool diag1[2 * n];\n    bool diag2[2 * n];\n    for (int i = 0; i < n; i++) col[i] = false;\n    for (int i = 0; i < 2 * n; i++) {\n        diag1[i] = false;\n        diag2[i] = false;\n    }\n    dfs(0, col, diag1, diag2);\n    printf(\"%d\\n\", count);\n    return 0;\n}',NULL,1,'2026-09-27 13:09:48','2026-09-28 15:16:03'),(536,143,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] height = new int[n];\n        for (int i = 0; i < n; i++) {\n            height[i] = sc.nextInt();\n        }\n\n        int left = 0, right = n - 1;\n        int leftMax = 0, rightMax = 0;\n        int ans = 0;\n\n        while (left < right) {\n            if (height[left] < height[right]) {\n                if (height[left] >= leftMax) {\n                    leftMax = height[left];\n                } else {\n                    ans += leftMax - height[left];\n                }\n                left++;\n            } else {\n                if (height[right] >= rightMax) {\n                    rightMax = height[right];\n                } else {\n                    ans += rightMax - height[right];\n                }\n                right--;\n            }\n        }\n\n        System.out.println(ans);\n    }\n}',NULL,1,'2026-09-27 13:09:49','2026-09-28 15:16:03'),(537,142,'C','#include <stdio.h>\n#include <string.h>\n\nint main() {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n    getchar();\n\n    char matrix[m][n + 1];\n    for (int i = 0; i < m; i++) {\n        fgets(matrix[i], n + 2, stdin);\n        matrix[i][strcspn(matrix[i], \"\\r\\n\")] = \'\\0\';\n    }\n\n    int dp[m + 1][n + 1];\n    memset(dp, 0, sizeof(dp));\n    int maxSide = 0;\n\n    for (int i = 1; i <= m; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (matrix[i - 1][j - 1] == \'1\') {\n                int min = dp[i - 1][j];\n                if (dp[i][j - 1] < min) min = dp[i][j - 1];\n                if (dp[i - 1][j - 1] < min) min = dp[i - 1][j - 1];\n                dp[i][j] = min + 1;\n                if (dp[i][j] > maxSide) maxSide = dp[i][j];\n            }\n        }\n    }\n\n    printf(\"%d\\n\", maxSide * maxSide);\n    return 0;\n}',NULL,1,'2026-09-27 13:09:49','2026-09-28 15:16:03'),(538,139,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const numCourses = parseInt(lines[idx++]);\n    const m = parseInt(lines[idx++]);\n\n    const graph = Array.from({ length: numCourses }, () => []);\n    const indegree = new Array(numCourses).fill(0);\n\n    for (let i = 0; i < m; i++) {\n        const parts = lines[idx++].split(/\\s+/).map(Number);\n        const ai = parts[0];\n        const bi = parts[1];\n        graph[bi].push(ai);\n        indegree[ai]++;\n    }\n\n    const pq = [];\n    const push = (x) => {\n        pq.push(x);\n        let i = pq.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (pq[p] <= pq[i]) break;\n            [pq[p], pq[i]] = [pq[i], pq[p]];\n            i = p;\n        }\n    };\n    const pop = () => {\n        const top = pq[0];\n        const last = pq.pop();\n        if (pq.length > 0) {\n            pq[0] = last;\n            let i = 0;\n            const n = pq.length;\n            while (true) {\n                let smallest = i;\n                const l = 2 * i + 1;\n                const r = 2 * i + 2;\n                if (l < n && pq[l] < pq[smallest]) smallest = l;\n                if (r < n && pq[r] < pq[smallest]) smallest = r;\n                if (smallest === i) break;\n                [pq[i], pq[smallest]] = [pq[smallest], pq[i]];\n                i = smallest;\n            }\n        }\n        return top;\n    };\n\n    for (let i = 0; i < numCourses; i++) {\n        if (indegree[i] === 0) {\n            push(i);\n        }\n    }\n\n    const order = [];\n    while (pq.length > 0) {\n        const cur = pop();\n        order.push(cur);\n        for (const next of graph[cur]) {\n            indegree[next]--;\n            if (indegree[next] === 0) {\n                push(next);\n            }\n        }\n    }\n\n    if (order.length !== numCourses) {\n        console.log(\"[]\");\n    } else {\n        console.log(order.join(\' \'));\n    }\n});',NULL,1,'2026-09-27 13:09:49','2026-09-28 15:16:03'),(539,141,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    count = 0\n    col = [False] * n\n    diag1 = [False] * (2 * n)\n    diag2 = [False] * (2 * n)\n\n    def dfs(row):\n        nonlocal count\n        if row == n:\n            count += 1\n            return\n        for c in range(n):\n            d1 = row + c\n            d2 = row - c + n\n            if not col[c] and not diag1[d1] and not diag2[d2]:\n                col[c] = True\n                diag1[d1] = True\n                diag2[d2] = True\n                dfs(row + 1)\n                col[c] = False\n                diag1[d1] = False\n                diag2[d2] = False\n\n    dfs(0)\n    print(count)\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:09:50','2026-09-28 15:16:03'),(540,142,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    m = int(data[0])\n    n = int(data[1])\n    matrix = data[2:2 + m]\n\n    dp = [[0] * (n + 1) for _ in range(m + 1)]\n    max_side = 0\n\n    for i in range(1, m + 1):\n        row = matrix[i - 1]\n        for j in range(1, n + 1):\n            if row[j - 1] == \'1\':\n                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1\n                if dp[i][j] > max_side:\n                    max_side = dp[i][j]\n\n    print(max_side * max_side)\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:09:50','2026-09-28 15:16:03'),(541,143,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> height(n);\n    for (int i = 0; i < n; i++) {\n        cin >> height[i];\n    }\n\n    int left = 0, right = n - 1;\n    int leftMax = 0, rightMax = 0;\n    int ans = 0;\n\n    while (left < right) {\n        if (height[left] < height[right]) {\n            if (height[left] >= leftMax) {\n                leftMax = height[left];\n            } else {\n                ans += leftMax - height[left];\n            }\n            left++;\n        } else {\n            if (height[right] >= rightMax) {\n                rightMax = height[right];\n            } else {\n                ans += rightMax - height[right];\n            }\n            right--;\n        }\n    }\n\n    cout << ans << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:09:51','2026-09-28 15:16:03'),(542,144,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String digits = sc.nextLine().trim();\n        List<String> result = new ArrayList<>();\n        if (digits == null || digits.length() == 0) {\n            System.out.println(\"[]\");\n            return;\n        }\n        String[] map = {\n            \"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"\n        };\n        backtrack(result, new StringBuilder(), digits, 0, map);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"\\\"\").append(result.get(i)).append(\"\\\"\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    private static void backtrack(List<String> result, StringBuilder path, String digits, int index, String[] map) {\n        if (index == digits.length()) {\n            result.add(path.toString());\n            return;\n        }\n        char c = digits.charAt(index);\n        String letters = map[c - \'0\'];\n        for (int i = 0; i < letters.length(); i++) {\n            path.append(letters.charAt(i));\n            backtrack(result, path, digits, index + 1, map);\n            path.deleteCharAt(path.length() - 1);\n        }\n    }\n}',NULL,1,'2026-09-27 13:09:52','2026-09-28 15:16:03'),(543,141,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet n;\nlet count = 0;\n\nrl.on(\'line\', (line) => {\n    n = parseInt(line.trim());\n    const col = new Array(n).fill(false);\n    const diag1 = new Array(2 * n).fill(false);\n    const diag2 = new Array(2 * n).fill(false);\n    dfs(0, col, diag1, diag2);\n    console.log(count);\n    rl.close();\n});\n\nfunction dfs(row, col, diag1, diag2) {\n    if (row === n) {\n        count++;\n        return;\n    }\n    for (let c = 0; c < n; c++) {\n        const d1 = row + c;\n        const d2 = row - c + n;\n        if (!col[c] && !diag1[d1] && !diag2[d2]) {\n            col[c] = true;\n            diag1[d1] = true;\n            diag2[d2] = true;\n            dfs(row + 1, col, diag1, diag2);\n            col[c] = false;\n            diag1[d1] = false;\n            diag2[d2] = false;\n        }\n    }\n}',NULL,1,'2026-09-27 13:09:52','2026-09-28 15:16:03'),(544,142,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const [m, n] = lines[0].trim().split(/\\s+/).map(Number);\n    const matrix = [];\n    for (let i = 0; i < m; i++) {\n        matrix.push(lines[i + 1].trim().split(\'\'));\n    }\n\n    const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));\n    let maxSide = 0;\n\n    for (let i = 1; i <= m; i++) {\n        for (let j = 1; j <= n; j++) {\n            if (matrix[i - 1][j - 1] === \'1\') {\n                dp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1;\n                maxSide = Math.max(maxSide, dp[i][j]);\n            }\n        }\n    }\n\n    console.log(maxSide * maxSide);\n});',NULL,1,'2026-09-27 13:09:52','2026-09-28 15:16:03'),(545,143,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int height[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &height[i]);\n    }\n\n    int left = 0, right = n - 1;\n    int leftMax = 0, rightMax = 0;\n    int ans = 0;\n\n    while (left < right) {\n        if (height[left] < height[right]) {\n            if (height[left] >= leftMax) {\n                leftMax = height[left];\n            } else {\n                ans += leftMax - height[left];\n            }\n            left++;\n        } else {\n            if (height[right] >= rightMax) {\n                rightMax = height[right];\n            } else {\n                ans += rightMax - height[right];\n            }\n            right--;\n        }\n    }\n\n    printf(\"%d\\n\", ans);\n    return 0;\n}',NULL,1,'2026-09-27 13:09:53','2026-09-28 15:16:03'),(546,145,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        String haystack = scanner.nextLine();\n        String needle = scanner.nextLine();\n        System.out.println(strStr(haystack, needle));\n    }\n\n    public static int strStr(String haystack, String needle) {\n        if (needle.isEmpty()) {\n            return 0;\n        }\n        int n = haystack.length();\n        int m = needle.length();\n        for (int i = 0; i <= n - m; i++) {\n            if (haystack.substring(i, i + m).equals(needle)) {\n                return i;\n            }\n        }\n        return -1;\n    }\n}',NULL,1,'2026-09-27 13:09:54','2026-09-28 15:16:03'),(547,143,'PYTHON','n = int(input())\nheight = list(map(int, input().split()))\n\nleft, right = 0, n - 1\nleftMax, rightMax = 0, 0\nans = 0\n\nwhile left < right:\n    if height[left] < height[right]:\n        if height[left] >= leftMax:\n            leftMax = height[left]\n        else:\n            ans += leftMax - height[left]\n        left += 1\n    else:\n        if height[right] >= rightMax:\n            rightMax = height[right]\n        else:\n            ans += rightMax - height[right]\n        right -= 1\n\nprint(ans)',NULL,1,'2026-09-27 13:09:54','2026-09-28 15:16:03'),(548,146,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        int[][] matrix = new int[m][n];\n        for (int i = 0; i < m; i++) {\n            for (int j = 0; j < n; j++) {\n                matrix[i][j] = sc.nextInt();\n            }\n        }\n        int target = sc.nextInt();\n        int left = 0, right = m * n - 1;\n        boolean found = false;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            int val = matrix[mid / n][mid % n];\n            if (val == target) {\n                found = true;\n                break;\n            } else if (val < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        System.out.println(found);\n    }\n}',NULL,1,'2026-09-27 13:09:54','2026-09-28 15:16:03'),(549,144,'CPP','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvoid backtrack(vector<string>& result, string& path, const string& digits, int index, const string map[]) {\n    if (index == (int)digits.length()) {\n        result.push_back(path);\n        return;\n    }\n    char c = digits[index];\n    string letters = map[c - \'0\'];\n    for (int i = 0; i < (int)letters.length(); i++) {\n        path.push_back(letters[i]);\n        backtrack(result, path, digits, index + 1, map);\n        path.pop_back();\n    }\n}\n\nint main() {\n    string digits;\n    getline(cin, digits);\n    while (!digits.empty() && (digits.back() == \'\\r\' || digits.back() == \'\\n\' || digits.back() == \' \' || digits.back() == \'\\t\')) {\n        digits.pop_back();\n    }\n    size_t start = 0;\n    while (start < digits.size() && (digits[start] == \' \' || digits[start] == \'\\t\')) {\n        start++;\n    }\n    if (start > 0) digits = digits.substr(start);\n\n    vector<string> result;\n    if (digits.empty()) {\n        cout << \"[]\" << endl;\n        return 0;\n    }\n    string map[10] = {\n        \"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"\n    };\n    string path;\n    backtrack(result, path, digits, 0, map);\n    cout << \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << \"\\\"\" << result[i] << \"\\\"\";\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:09:55','2026-09-28 15:16:03'),(550,145,'CPP','#include <iostream>\n#include <string>\nusing namespace std;\n\nint strStr(const string& haystack, const string& needle) {\n    if (needle.empty()) {\n        return 0;\n    }\n    int n = haystack.length();\n    int m = needle.length();\n    for (int i = 0; i <= n - m; i++) {\n        if (haystack.substr(i, m) == needle) {\n            return i;\n        }\n    }\n    return -1;\n}\n\nint main() {\n    string haystack, needle;\n    getline(cin, haystack);\n    getline(cin, needle);\n    cout << strStr(haystack, needle) << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:09:56','2026-09-28 15:16:03'),(551,146,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    vector<vector<int>> matrix(m, vector<int>(n));\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            cin >> matrix[i][j];\n        }\n    }\n    int target;\n    cin >> target;\n    int left = 0, right = m * n - 1;\n    bool found = false;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        int val = matrix[mid / n][mid % n];\n        if (val == target) {\n            found = true;\n            break;\n        } else if (val < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    cout << (found ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:09:57','2026-09-28 15:16:03'),(552,143,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const height = lines[1].split(\' \').map(Number);\n\n    let left = 0, right = n - 1;\n    let leftMax = 0, rightMax = 0;\n    let ans = 0;\n\n    while (left < right) {\n        if (height[left] < height[right]) {\n            if (height[left] >= leftMax) {\n                leftMax = height[left];\n            } else {\n                ans += leftMax - height[left];\n            }\n            left++;\n        } else {\n            if (height[right] >= rightMax) {\n                rightMax = height[right];\n            } else {\n                ans += rightMax - height[right];\n            }\n            right--;\n        }\n    }\n\n    console.log(ans);\n});',NULL,1,'2026-09-27 13:09:57','2026-09-28 15:16:03'),(553,144,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nchar *map[] = {\"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"};\n\nvoid backtrack(char **result, int *count, char *path, int index, char *digits) {\n    if (index == (int)strlen(digits)) {\n        path[index] = \'\\0\';\n        result[*count] = (char *)malloc((strlen(path) + 1) * sizeof(char));\n        strcpy(result[*count], path);\n        (*count)++;\n        return;\n    }\n    char c = digits[index];\n    char *letters = map[c - \'0\'];\n    for (int i = 0; i < (int)strlen(letters); i++) {\n        path[index] = letters[i];\n        backtrack(result, count, path, index + 1, digits);\n    }\n}\n\nint main() {\n    char digits[100];\n    if (scanf(\"%s\", digits) != 1) {\n        return 0;\n    }\n    int len = strlen(digits);\n    if (len == 0) {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    int maxCount = 1;\n    for (int i = 0; i < len; i++) {\n        maxCount *= strlen(map[digits[i] - \'0\']);\n    }\n    char **result = (char **)malloc(maxCount * sizeof(char *));\n    char *path = (char *)malloc((len + 1) * sizeof(char));\n    int count = 0;\n    backtrack(result, &count, path, 0, digits);\n    printf(\"[\");\n    for (int i = 0; i < count; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"\\\"%s\\\"\", result[i]);\n    }\n    printf(\"]\\n\");\n    for (int i = 0; i < count; i++) {\n        free(result[i]);\n    }\n    free(result);\n    free(path);\n    return 0;\n}',NULL,1,'2026-09-27 13:09:58','2026-09-28 15:16:03'),(554,145,'C','#include <stdio.h>\n#include <string.h>\n\nint strStr(const char *haystack, const char *needle) {\n    if (needle[0] == \'\\0\') {\n        return 0;\n    }\n    int n = (int)strlen(haystack);\n    int m = (int)strlen(needle);\n    for (int i = 0; i <= n - m; i++) {\n        if (strncmp(haystack + i, needle, m) == 0) {\n            return i;\n        }\n    }\n    return -1;\n}\n\nint main(void) {\n    char haystack[100005];\n    char needle[100005];\n\n    if (fgets(haystack, sizeof(haystack), stdin) == NULL) {\n        return 0;\n    }\n    if (fgets(needle, sizeof(needle), stdin) == NULL) {\n        return 0;\n    }\n\n    size_t len1 = strlen(haystack);\n    if (len1 > 0 && haystack[len1 - 1] == \'\\n\') {\n        haystack[len1 - 1] = \'\\0\';\n    }\n\n    size_t len2 = strlen(needle);\n    if (len2 > 0 && needle[len2 - 1] == \'\\n\') {\n        needle[len2 - 1] = \'\\0\';\n    }\n\n    printf(\"%d\\n\", strStr(haystack, needle));\n    return 0;\n}',NULL,1,'2026-09-27 13:09:58','2026-09-28 15:16:03'),(555,146,'C','#include <stdio.h>\n\nint main() {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n    int matrix[m][n];\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            scanf(\"%d\", &matrix[i][j]);\n        }\n    }\n    int target;\n    scanf(\"%d\", &target);\n    int left = 0, right = m * n - 1;\n    int found = 0;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        int val = matrix[mid / n][mid % n];\n        if (val == target) {\n            found = 1;\n            break;\n        } else if (val < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    if (found) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:09:58','2026-09-28 15:16:03'),(556,147,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        int low = 0, mid = 0, high = n - 1;\n        while (mid <= high) {\n            if (nums[mid] == 0) {\n                int temp = nums[low];\n                nums[low] = nums[mid];\n                nums[mid] = temp;\n                low++;\n                mid++;\n            } else if (nums[mid] == 1) {\n                mid++;\n            } else {\n                int temp = nums[mid];\n                nums[mid] = nums[high];\n                nums[high] = temp;\n                high--;\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(nums[i]);\n        }\n        System.out.println(sb.toString());\n    }\n}',NULL,1,'2026-09-27 13:09:59','2026-09-28 15:16:03'),(557,145,'PYTHON','haystack = input()\nneedle = input()\n\nif needle == \"\":\n    print(0)\nelse:\n    n = len(haystack)\n    m = len(needle)\n    result = -1\n    for i in range(n - m + 1):\n        if haystack[i:i + m] == needle:\n            result = i\n            break\n    print(result)',NULL,1,'2026-09-27 13:09:59','2026-09-28 15:16:03'),(558,144,'PYTHON','import sys\n\ndef main():\n    digits = sys.stdin.readline().strip()\n    if not digits:\n        print(\"[]\")\n        return\n    mapping = [\"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"]\n    result = []\n    def backtrack(index, path):\n        if index == len(digits):\n            result.append(path)\n            return\n        letters = mapping[int(digits[index])]\n        for ch in letters:\n            backtrack(index + 1, path + ch)\n    backtrack(0, \"\")\n    print(\"[\" + \",\".join(f\'\"{s}\"\' for s in result) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:09:59','2026-09-28 15:16:03'),(559,146,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    m = int(data[0])\n    n = int(data[1])\n    idx = 2\n    matrix = []\n    for i in range(m):\n        row = []\n        for j in range(n):\n            row.append(int(data[idx]))\n            idx += 1\n        matrix.append(row)\n    target = int(data[idx])\n    \n    left, right = 0, m * n - 1\n    found = False\n    while left <= right:\n        mid = left + (right - left) // 2\n        val = matrix[mid // n][mid % n]\n        if val == target:\n            found = True\n            break\n        elif val < target:\n            left = mid + 1\n        else:\n            right = mid - 1\n    print(\"true\" if found else \"false\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:10:00','2026-09-28 15:16:03'),(560,147,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    int low = 0, mid = 0, high = n - 1;\n    while (mid <= high) {\n        if (nums[mid] == 0) {\n            swap(nums[low], nums[mid]);\n            low++;\n            mid++;\n        } else if (nums[mid] == 1) {\n            mid++;\n        } else {\n            swap(nums[mid], nums[high]);\n            high--;\n        }\n    }\n\n    for (int i = 0; i < n; i++) {\n        if (i > 0) cout << \' \';\n        cout << nums[i];\n    }\n    cout << endl;\n\n    return 0;\n}',NULL,1,'2026-09-27 13:10:01','2026-09-28 15:16:03'),(561,145,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 2) {\n        const haystack = lines[0];\n        const needle = lines[1];\n        console.log(strStr(haystack, needle));\n        rl.close();\n    }\n});\n\nfunction strStr(haystack, needle) {\n    if (needle.length === 0) {\n        return 0;\n    }\n    const n = haystack.length;\n    const m = needle.length;\n    for (let i = 0; i <= n - m; i++) {\n        if (haystack.substring(i, i + m) === needle) {\n            return i;\n        }\n    }\n    return -1;\n}',NULL,1,'2026-09-27 13:10:01','2026-09-28 15:16:03'),(562,144,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const digits = line.trim();\n    const result = [];\n    if (!digits || digits.length === 0) {\n        console.log(\"[]\");\n        rl.close();\n        return;\n    }\n    const map = [\"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"];\n    backtrack(result, \"\", digits, 0, map);\n    let sb = \"[\";\n    for (let i = 0; i < result.length; i++) {\n        if (i > 0) sb += \",\";\n        sb += \"\\\"\" + result[i] + \"\\\"\";\n    }\n    sb += \"]\";\n    console.log(sb);\n    rl.close();\n});\n\nfunction backtrack(result, path, digits, index, map) {\n    if (index === digits.length) {\n        result.push(path);\n        return;\n    }\n    const c = digits.charAt(index);\n    const letters = map[c.charCodeAt(0) - \'0\'.charCodeAt(0)];\n    for (let i = 0; i < letters.length; i++) {\n        backtrack(result, path + letters.charAt(i), digits, index + 1, map);\n    }\n}',NULL,1,'2026-09-27 13:10:01','2026-09-28 15:16:03'),(563,146,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const [m, n] = lines[idx++].split(\' \').map(Number);\n    const matrix = [];\n    for (let i = 0; i < m; i++) {\n        matrix.push(lines[idx++].split(\' \').map(Number));\n    }\n    const target = Number(lines[idx++]);\n\n    let left = 0, right = m * n - 1;\n    let found = false;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        const val = matrix[Math.floor(mid / n)][mid % n];\n        if (val === target) {\n            found = true;\n            break;\n        } else if (val < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    console.log(found);\n});',NULL,1,'2026-09-27 13:10:02','2026-09-28 15:16:03'),(564,149,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine().trim();\n        int n = s.length();\n        if (n == 0) {\n            System.out.println(0);\n            return;\n        }\n        int[] dp = new int[n + 1];\n        dp[0] = 1;\n        dp[1] = s.charAt(0) == \'0\' ? 0 : 1;\n        for (int i = 2; i <= n; i++) {\n            int one = s.charAt(i - 1) - \'0\';\n            int two = Integer.parseInt(s.substring(i - 2, i));\n            if (one >= 1 && one <= 9) {\n                dp[i] += dp[i - 1];\n            }\n            if (two >= 10 && two <= 26) {\n                dp[i] += dp[i - 2];\n            }\n        }\n        System.out.println(dp[n]);\n    }\n}',NULL,1,'2026-09-27 13:10:03','2026-09-28 15:16:03'),(565,148,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        Arrays.sort(nums);\n        List<List<Integer>> res = new ArrayList<>();\n        backtrack(nums, 0, new ArrayList<>(), res);\n        System.out.println(format(res));\n    }\n\n    private static void backtrack(int[] nums, int start, List<Integer> path, List<List<Integer>> res) {\n        res.add(new ArrayList<>(path));\n        for (int i = start; i < nums.length; i++) {\n            if (i > start && nums[i] == nums[i - 1]) continue;\n            path.add(nums[i]);\n            backtrack(nums, i + 1, path, res);\n            path.remove(path.size() - 1);\n        }\n    }\n\n    private static String format(List<List<Integer>> res) {\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"[\");\n            List<Integer> list = res.get(i);\n            for (int j = 0; j < list.size(); j++) {\n                if (j > 0) sb.append(\",\");\n                sb.append(list.get(j));\n            }\n            sb.append(\"]\");\n        }\n        sb.append(\"]\");\n        return sb.toString();\n    }\n}',NULL,1,'2026-09-27 13:10:03','2026-09-28 15:16:03'),(566,147,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int low = 0, mid = 0, high = n - 1;\n    while (mid <= high) {\n        if (nums[mid] == 0) {\n            int temp = nums[low];\n            nums[low] = nums[mid];\n            nums[mid] = temp;\n            low++;\n            mid++;\n        } else if (nums[mid] == 1) {\n            mid++;\n        } else {\n            int temp = nums[mid];\n            nums[mid] = nums[high];\n            nums[high] = temp;\n            high--;\n        }\n    }\n\n    for (int i = 0; i < n; i++) {\n        if (i > 0) printf(\" \");\n        printf(\"%d\", nums[i]);\n    }\n    printf(\"\\n\");\n\n    free(nums);\n    return 0;\n}',NULL,1,'2026-09-27 13:10:04','2026-09-28 15:16:03'),(567,150,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            for (int j = 1; j <= i; j++) {\n                dp[i] += dp[j - 1] * dp[i - j];\n            }\n        }\n        System.out.println(dp[n]);\n    }\n}',NULL,1,'2026-09-27 13:10:04','2026-09-28 15:16:03'),(568,147,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\n\nlow, mid, high = 0, 0, n - 1\nwhile mid <= high:\n    if nums[mid] == 0:\n        nums[low], nums[mid] = nums[mid], nums[low]\n        low += 1\n        mid += 1\n    elif nums[mid] == 1:\n        mid += 1\n    else:\n        nums[mid], nums[high] = nums[high], nums[mid]\n        high -= 1\n\nprint(\' \'.join(map(str, nums)))',NULL,1,'2026-09-27 13:10:05','2026-09-28 15:16:03'),(569,149,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n\nint main() {\n    std::string s;\n    std::getline(std::cin, s);\n    while (!s.empty() && (s.back() == \'\\n\' || s.back() == \'\\r\' || s.back() == \' \' || s.back() == \'\\t\')) {\n        s.pop_back();\n    }\n    size_t start = 0;\n    while (start < s.size() && (s[start] == \' \' || s[start] == \'\\t\')) {\n        ++start;\n    }\n    s = s.substr(start);\n\n    int n = static_cast<int>(s.size());\n    if (n == 0) {\n        std::cout << 0 << std::endl;\n        return 0;\n    }\n\n    std::vector<int> dp(n + 1, 0);\n    dp[0] = 1;\n    dp[1] = (s[0] == \'0\') ? 0 : 1;\n\n    for (int i = 2; i <= n; ++i) {\n        int one = s[i - 1] - \'0\';\n        int two = (s[i - 2] - \'0\') * 10 + (s[i - 1] - \'0\');\n\n        if (one >= 1 && one <= 9) {\n            dp[i] += dp[i - 1];\n        }\n        if (two >= 10 && two <= 26) {\n            dp[i] += dp[i - 2];\n        }\n    }\n\n    std::cout << dp[n] << std::endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:10:05','2026-09-28 15:16:03'),(570,148,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nvoid backtrack(vector<int>& nums, int start, vector<int>& path, vector<vector<int>>& res) {\n    res.push_back(path);\n    for (int i = start; i < (int)nums.size(); i++) {\n        if (i > start && nums[i] == nums[i - 1]) continue;\n        path.push_back(nums[i]);\n        backtrack(nums, i + 1, path, res);\n        path.pop_back();\n    }\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    sort(nums.begin(), nums.end());\n    vector<vector<int>> res;\n    vector<int> path;\n    backtrack(nums, 0, path, res);\n\n    cout << \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << \"[\";\n        for (int j = 0; j < (int)res[i].size(); j++) {\n            if (j > 0) cout << \",\";\n            cout << res[i][j];\n        }\n        cout << \"]\";\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:10:06','2026-09-28 15:16:03'),(571,147,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n\n    let low = 0, mid = 0, high = n - 1;\n    while (mid <= high) {\n        if (nums[mid] === 0) {\n            let temp = nums[low];\n            nums[low] = nums[mid];\n            nums[mid] = temp;\n            low++;\n            mid++;\n        } else if (nums[mid] === 1) {\n            mid++;\n        } else {\n            let temp = nums[mid];\n            nums[mid] = nums[high];\n            nums[high] = temp;\n            high--;\n        }\n    }\n\n    console.log(nums.join(\' \'));\n});',NULL,1,'2026-09-27 13:10:07','2026-09-28 15:16:03'),(572,150,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; i++) {\n        for (int j = 1; j <= i; j++) {\n            dp[i] += dp[j - 1] * dp[i - j];\n        }\n    }\n    cout << dp[n] << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:10:07','2026-09-28 15:16:03'),(573,149,'C','#include <stdio.h>\n#include <string.h>\n\nint main() {\n    char s[100005];\n    if (scanf(\"%s\", s) != 1) return 0;\n    int n = strlen(s);\n    if (n == 0) {\n        printf(\"0\\n\");\n        return 0;\n    }\n    int dp[100005];\n    dp[0] = 1;\n    dp[1] = (s[0] == \'0\') ? 0 : 1;\n    for (int i = 2; i <= n; i++) {\n        dp[i] = 0;\n        int one = s[i - 1] - \'0\';\n        int two = (s[i - 2] - \'0\') * 10 + (s[i - 1] - \'0\');\n        if (one >= 1 && one <= 9) {\n            dp[i] += dp[i - 1];\n        }\n        if (two >= 10 && two <= 26) {\n            dp[i] += dp[i - 2];\n        }\n    }\n    printf(\"%d\\n\", dp[n]);\n    return 0;\n}',NULL,1,'2026-09-27 13:10:07','2026-09-28 15:16:03'),(574,148,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nvoid backtrack(int *nums, int n, int start, int *path, int pathSize, int **res, int *returnSize, int **returnColumnSizes) {\n    res[*returnSize] = (int *)malloc(sizeof(int) * pathSize);\n    for (int i = 0; i < pathSize; i++) {\n        res[*returnSize][i] = path[i];\n    }\n    (*returnColumnSizes)[*returnSize] = pathSize;\n    (*returnSize)++;\n\n    for (int i = start; i < n; i++) {\n        if (i > start && nums[i] == nums[i - 1]) continue;\n        path[pathSize] = nums[i];\n        backtrack(nums, n, i + 1, path, pathSize + 1, res, returnSize, returnColumnSizes);\n    }\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(sizeof(int) * n);\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    qsort(nums, n, sizeof(int), cmp);\n\n    int maxRes = 1 << n;\n    int **res = (int **)malloc(sizeof(int *) * maxRes);\n    int *returnColumnSizes = (int *)malloc(sizeof(int) * maxRes);\n    int returnSize = 0;\n    int *path = (int *)malloc(sizeof(int) * n);\n\n    backtrack(nums, n, 0, path, 0, res, &returnSize, &returnColumnSizes);\n\n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"[\");\n        for (int j = 0; j < returnColumnSizes[i]; j++) {\n            if (j > 0) printf(\",\");\n            printf(\"%d\", res[i][j]);\n        }\n        printf(\"]\");\n    }\n    printf(\"]\\n\");\n\n    for (int i = 0; i < returnSize; i++) {\n        free(res[i]);\n    }\n    free(res);\n    free(returnColumnSizes);\n    free(path);\n    free(nums);\n\n    return 0;\n}',NULL,1,'2026-09-27 13:10:08','2026-09-28 15:16:03'),(575,149,'PYTHON','s = input().strip()\nn = len(s)\nif n == 0:\n    print(0)\nelse:\n    dp = [0] * (n + 1)\n    dp[0] = 1\n    dp[1] = 0 if s[0] == \'0\' else 1\n    for i in range(2, n + 1):\n        one = int(s[i - 1])\n        two = int(s[i - 2:i])\n        if 1 <= one <= 9:\n            dp[i] += dp[i - 1]\n        if 10 <= two <= 26:\n            dp[i] += dp[i - 2]\n    print(dp[n])',NULL,1,'2026-09-27 13:10:09','2026-09-28 15:16:03'),(576,150,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    long long dp[n + 1];\n    dp[0] = 1;\n    for (int i = 1; i <= n; i++) {\n        dp[i] = 0;\n        for (int j = 1; j <= i; j++) {\n            dp[i] += dp[j - 1] * dp[i - j];\n        }\n    }\n    printf(\"%lld\\n\", dp[n]);\n    return 0;\n}',NULL,1,'2026-09-27 13:10:09','2026-09-28 15:16:03'),(577,151,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] triangle = new int[n][n];\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j <= i; j++) {\n                triangle[i][j] = sc.nextInt();\n            }\n        }\n        int[] dp = new int[n];\n        for (int j = 0; j < n; j++) {\n            dp[j] = triangle[n - 1][j];\n        }\n        for (int i = n - 2; i >= 0; i--) {\n            for (int j = 0; j <= i; j++) {\n                dp[j] = triangle[i][j] + Math.min(dp[j], dp[j + 1]);\n            }\n        }\n        System.out.println(dp[0]);\n    }\n}',NULL,1,'2026-09-27 13:10:09','2026-09-28 15:16:03'),(578,148,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1+n]))\n    nums.sort()\n    res = []\n    \n    def backtrack(start, path):\n        res.append(path[:])\n        for i in range(start, len(nums)):\n            if i > start and nums[i] == nums[i-1]:\n                continue\n            path.append(nums[i])\n            backtrack(i + 1, path)\n            path.pop()\n    \n    backtrack(0, [])\n    \n    parts = []\n    for subset in res:\n        parts.append(\"[\" + \",\".join(map(str, subset)) + \"]\")\n    print(\"[\" + \",\".join(parts) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:10:10','2026-09-28 15:16:03'),(579,150,'PYTHON','n = int(input())\ndp = [0] * (n + 1)\ndp[0] = 1\nfor i in range(1, n + 1):\n    for j in range(1, i + 1):\n        dp[i] += dp[j - 1] * dp[i - j]\nprint(dp[n])',NULL,1,'2026-09-27 13:10:10','2026-09-28 15:16:03'),(580,149,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const s = line.trim();\n    const n = s.length;\n    if (n === 0) {\n        console.log(0);\n        rl.close();\n        return;\n    }\n    const dp = new Array(n + 1).fill(0);\n    dp[0] = 1;\n    dp[1] = s.charAt(0) === \'0\' ? 0 : 1;\n    for (let i = 2; i <= n; i++) {\n        const one = s.charCodeAt(i - 1) - \'0\'.charCodeAt(0);\n        const two = parseInt(s.substring(i - 2, i), 10);\n        if (one >= 1 && one <= 9) {\n            dp[i] += dp[i - 1];\n        }\n        if (two >= 10 && two <= 26) {\n            dp[i] += dp[i - 2];\n        }\n    }\n    console.log(dp[n]);\n    rl.close();\n});',NULL,1,'2026-09-27 13:10:10','2026-09-28 15:16:03'),(581,148,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    nums.sort((a, b) => a - b);\n    const res = [];\n    backtrack(nums, 0, [], res);\n    console.log(format(res));\n});\n\nfunction backtrack(nums, start, path, res) {\n    res.push([...path]);\n    for (let i = start; i < nums.length; i++) {\n        if (i > start && nums[i] === nums[i - 1]) continue;\n        path.push(nums[i]);\n        backtrack(nums, i + 1, path, res);\n        path.pop();\n    }\n}\n\nfunction format(res) {\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < res.length; i++) {\n        if (i > 0) sb += \',\';\n        sb += \'[\';\n        const list = res[i];\n        for (let j = 0; j < list.length; j++) {\n            if (j > 0) sb += \',\';\n            sb += list[j];\n        }\n        sb += \']\';\n    }\n    sb += \']\';\n    return sb;\n}',NULL,1,'2026-09-27 13:10:12','2026-09-28 15:16:03'),(582,150,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim(), 10);\n    const dp = new Array(n + 1).fill(0);\n    dp[0] = 1;\n    for (let i = 1; i <= n; i++) {\n        for (let j = 1; j <= i; j++) {\n            dp[i] += dp[j - 1] * dp[i - j];\n        }\n    }\n    console.log(dp[n]);\n    rl.close();\n});',NULL,1,'2026-09-27 13:10:12','2026-09-28 15:16:03'),(583,151,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> triangle(n, vector<int>(n));\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j <= i; j++) {\n            cin >> triangle[i][j];\n        }\n    }\n    vector<int> dp(n);\n    for (int j = 0; j < n; j++) {\n        dp[j] = triangle[n - 1][j];\n    }\n    for (int i = n - 2; i >= 0; i--) {\n        for (int j = 0; j <= i; j++) {\n            dp[j] = triangle[i][j] + min(dp[j], dp[j + 1]);\n        }\n    }\n    cout << dp[0] << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:10:12','2026-09-28 15:16:03'),(584,152,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine();\n        int n = Integer.parseInt(sc.nextLine().trim());\n        Set<String> wordDict = new HashSet<>();\n        for (int i = 0; i < n; i++) {\n            wordDict.add(sc.nextLine().trim());\n        }\n\n        int len = s.length();\n        boolean[] dp = new boolean[len + 1];\n        dp[0] = true;\n\n        for (int i = 1; i <= len; i++) {\n            for (int j = 0; j < i; j++) {\n                if (dp[j] && wordDict.contains(s.substring(j, i))) {\n                    dp[i] = true;\n                    break;\n                }\n            }\n        }\n\n        System.out.println(dp[len]);\n    }\n}',NULL,1,'2026-09-27 13:10:12','2026-09-28 15:16:03'),(585,154,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (sc.hasNextLine()) {\n            String s = sc.nextLine();\n            System.out.println(decodeString(s));\n        }\n    }\n\n    public static String decodeString(String s) {\n        Deque<Integer> countStack = new ArrayDeque<>();\n        Deque<StringBuilder> stringStack = new ArrayDeque<>();\n        StringBuilder current = new StringBuilder();\n        int k = 0;\n\n        for (char c : s.toCharArray()) {\n            if (Character.isDigit(c)) {\n                k = k * 10 + (c - \'0\');\n            } else if (c == \'[\') {\n                countStack.push(k);\n                stringStack.push(current);\n                current = new StringBuilder();\n                k = 0;\n            } else if (c == \']\') {\n                int repeat = countStack.pop();\n                StringBuilder prev = stringStack.pop();\n                for (int i = 0; i < repeat; i++) {\n                    prev.append(current);\n                }\n                current = prev;\n            } else {\n                current.append(c);\n            }\n        }\n\n        return current.toString();\n    }\n}',NULL,1,'2026-09-27 13:10:14','2026-09-28 15:16:03'),(586,153,'JAVA','import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        String[] first = br.readLine().trim().split(\"\\\\s+\");\n        int n = Integer.parseInt(first[0]);\n        int k = Integer.parseInt(first[1]);\n        int[] nums = new int[n];\n        String[] second = br.readLine().trim().split(\"\\\\s+\");\n        for (int i = 0; i < n; i++) {\n            nums[i] = Integer.parseInt(second[i]);\n        }\n\n        Map<Integer, Integer> freq = new HashMap<>();\n        for (int num : nums) {\n            freq.put(num, freq.getOrDefault(num, 0) + 1);\n        }\n\n        List<Integer> list = new ArrayList<>(freq.keySet());\n        list.sort((a, b) -> {\n            int fa = freq.get(a);\n            int fb = freq.get(b);\n            if (fa != fb) {\n                return fb - fa;\n            }\n            return a - b;\n        });\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < k; i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(list.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1,'2026-09-27 13:10:14','2026-09-28 15:16:03'),(587,151,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int **triangle = (int **)malloc(n * sizeof(int *));\n    for (int i = 0; i < n; i++) {\n        triangle[i] = (int *)malloc(n * sizeof(int));\n        for (int j = 0; j <= i; j++) {\n            scanf(\"%d\", &triangle[i][j]);\n        }\n    }\n    int *dp = (int *)malloc(n * sizeof(int));\n    for (int j = 0; j < n; j++) {\n        dp[j] = triangle[n - 1][j];\n    }\n    for (int i = n - 2; i >= 0; i--) {\n        for (int j = 0; j <= i; j++) {\n            int min = dp[j] < dp[j + 1] ? dp[j] : dp[j + 1];\n            dp[j] = triangle[i][j] + min;\n        }\n    }\n    printf(\"%d\\n\", dp[0]);\n    for (int i = 0; i < n; i++) {\n        free(triangle[i]);\n    }\n    free(triangle);\n    free(dp);\n    return 0;\n}',NULL,1,'2026-09-27 13:10:14','2026-09-28 15:16:03'),(588,152,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <unordered_set>\n\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n\n    string nLine;\n    getline(cin, nLine);\n    int n = stoi(nLine);\n\n    unordered_set<string> wordDict;\n    for (int i = 0; i < n; ++i) {\n        string word;\n        getline(cin, word);\n        wordDict.insert(word);\n    }\n\n    int len = s.length();\n    vector<bool> dp(len + 1, false);\n    dp[0] = true;\n\n    for (int i = 1; i <= len; ++i) {\n        for (int j = 0; j < i; ++j) {\n            if (dp[j] && wordDict.count(s.substr(j, i - j))) {\n                dp[i] = true;\n                break;\n            }\n        }\n    }\n\n    cout << (dp[len] ? \"true\" : \"false\") << endl;\n\n    return 0;\n}',NULL,1,'2026-09-27 13:10:15','2026-09-28 15:16:03'),(589,151,'PYTHON','n = int(input())\ntriangle = []\nfor i in range(n):\n    row = list(map(int, input().split()))\n    triangle.append(row)\n\ndp = triangle[-1][:]\n\nfor i in range(n - 2, -1, -1):\n    for j in range(i + 1):\n        dp[j] = triangle[i][j] + min(dp[j], dp[j + 1])\n\nprint(dp[0])',NULL,1,'2026-09-27 13:10:16','2026-09-28 15:16:03'),(590,154,'CPP','#include <iostream>\n#include <string>\n#include <stack>\nusing namespace std;\n\nstring decodeString(const string& s) {\n    stack<int> countStack;\n    stack<string> stringStack;\n    string current;\n    int k = 0;\n\n    for (char c : s) {\n        if (isdigit(c)) {\n            k = k * 10 + (c - \'0\');\n        } else if (c == \'[\') {\n            countStack.push(k);\n            stringStack.push(current);\n            current.clear();\n            k = 0;\n        } else if (c == \']\') {\n            int repeat = countStack.top();\n            countStack.pop();\n            string prev = stringStack.top();\n            stringStack.pop();\n            for (int i = 0; i < repeat; i++) {\n                prev += current;\n            }\n            current = prev;\n        } else {\n            current += c;\n        }\n    }\n\n    return current;\n}\n\nint main() {\n    string s;\n    if (getline(cin, s)) {\n        cout << decodeString(s) << endl;\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:10:16','2026-09-28 15:16:03'),(591,153,'CPP','#include <iostream>\n#include <vector>\n#include <unordered_map>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    vector<int> nums(n);\n    for (int i = 0; i < n; ++i) {\n        cin >> nums[i];\n    }\n\n    unordered_map<int, int> freq;\n    for (int num : nums) {\n        freq[num]++;\n    }\n\n    vector<int> list;\n    for (auto &p : freq) {\n        list.push_back(p.first);\n    }\n\n    sort(list.begin(), list.end(), [&](int a, int b) {\n        int fa = freq[a];\n        int fb = freq[b];\n        if (fa != fb) return fa > fb;\n        return a < b;\n    });\n\n    cout << \"[\";\n    for (int i = 0; i < k; ++i) {\n        if (i > 0) cout << \",\";\n        cout << list[i];\n    }\n    cout << \"]\" << endl;\n\n    return 0;\n}',NULL,1,'2026-09-27 13:10:17','2026-09-28 15:16:03'),(592,152,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdbool.h>\n\nint main() {\n    char s[10005];\n    if (fgets(s, sizeof(s), stdin) == NULL) return 0;\n    s[strcspn(s, \"\\r\\n\")] = \'\\0\';\n\n    char line[10005];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    int n = atoi(line);\n\n    char **wordDict = (char **)malloc(n * sizeof(char *));\n    for (int i = 0; i < n; i++) {\n        wordDict[i] = (char *)malloc(10005 * sizeof(char));\n        if (fgets(wordDict[i], 10005, stdin) == NULL) {\n            wordDict[i][0] = \'\\0\';\n        }\n        wordDict[i][strcspn(wordDict[i], \"\\r\\n\")] = \'\\0\';\n    }\n\n    int len = strlen(s);\n    bool *dp = (bool *)calloc(len + 1, sizeof(bool));\n    dp[0] = true;\n\n    for (int i = 1; i <= len; i++) {\n        for (int j = 0; j < i; j++) {\n            if (dp[j]) {\n                int subLen = i - j;\n                char *sub = (char *)malloc((subLen + 1) * sizeof(char));\n                strncpy(sub, s + j, subLen);\n                sub[subLen] = \'\\0\';\n\n                bool found = false;\n                for (int k = 0; k < n; k++) {\n                    if (strcmp(sub, wordDict[k]) == 0) {\n                        found = true;\n                        break;\n                    }\n                }\n                free(sub);\n\n                if (found) {\n                    dp[i] = true;\n                    break;\n                }\n            }\n        }\n    }\n\n    if (dp[len]) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n\n    for (int i = 0; i < n; i++) {\n        free(wordDict[i]);\n    }\n    free(wordDict);\n    free(dp);\n\n    return 0;\n}',NULL,1,'2026-09-27 13:10:17','2026-09-28 15:16:03'),(593,151,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const n = parseInt(lines[idx++]);\n    const triangle = [];\n    for (let i = 0; i < n; i++) {\n        const row = lines[idx++].split(\' \').map(Number);\n        triangle.push(row);\n    }\n    const dp = new Array(n);\n    for (let j = 0; j < n; j++) {\n        dp[j] = triangle[n - 1][j];\n    }\n    for (let i = n - 2; i >= 0; i--) {\n        for (let j = 0; j <= i; j++) {\n            dp[j] = triangle[i][j] + Math.min(dp[j], dp[j + 1]);\n        }\n    }\n    console.log(dp[0]);\n});',NULL,1,'2026-09-27 13:10:18','2026-09-28 15:16:03'),(594,153,'C','#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int num;\n    int freq;\n} Pair;\n\nint cmp(const void *a, const void *b) {\n    Pair *p1 = (Pair *)a;\n    Pair *p2 = (Pair *)b;\n    if (p1->freq != p2->freq) {\n        return p2->freq - p1->freq;\n    }\n    return p1->num - p2->num;\n}\n\nint main() {\n    int n, k;\n    scanf(\"%d %d\", &n, &k);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    Pair *pairs = (Pair *)malloc(n * sizeof(Pair));\n    int size = 0;\n    for (int i = 0; i < n; i++) {\n        int found = 0;\n        for (int j = 0; j < size; j++) {\n            if (pairs[j].num == nums[i]) {\n                pairs[j].freq++;\n                found = 1;\n                break;\n            }\n        }\n        if (!found) {\n            pairs[size].num = nums[i];\n            pairs[size].freq = 1;\n            size++;\n        }\n    }\n\n    qsort(pairs, size, sizeof(Pair), cmp);\n\n    printf(\"[\");\n    for (int i = 0; i < k; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", pairs[i].num);\n    }\n    printf(\"]\\n\");\n\n    free(nums);\n    free(pairs);\n    return 0;\n}',NULL,1,'2026-09-27 13:10:19','2026-09-28 15:16:03'),(595,152,'PYTHON','s = input()\nn = int(input().strip())\nwordDict = set()\nfor _ in range(n):\n    wordDict.add(input().strip())\n\nlength = len(s)\ndp = [False] * (length + 1)\ndp[0] = True\n\nfor i in range(1, length + 1):\n    for j in range(i):\n        if dp[j] and s[j:i] in wordDict:\n            dp[i] = True\n            break\n\nprint(str(dp[length]).lower())',NULL,1,'2026-09-27 13:10:19','2026-09-28 15:16:03'),(596,154,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n\n#define MAXN 100000\n\ntypedef struct {\n    int count;\n    char *str;\n} StackItem;\n\nchar *decodeString(const char *s) {\n    int len = strlen(s);\n    StackItem countStack[MAXN];\n    int top = 0;\n    char *current = (char *)malloc(MAXN * sizeof(char));\n    int curLen = 0;\n    current[0] = \'\\0\';\n    int k = 0;\n\n    for (int i = 0; i < len; i++) {\n        char c = s[i];\n        if (isdigit(c)) {\n            k = k * 10 + (c - \'0\');\n        } else if (c == \'[\') {\n            countStack[top].count = k;\n            countStack[top].str = (char *)malloc((curLen + 1) * sizeof(char));\n            strcpy(countStack[top].str, current);\n            top++;\n            curLen = 0;\n            current[0] = \'\\0\';\n            k = 0;\n        } else if (c == \']\') {\n            top--;\n            int repeat = countStack[top].count;\n            char *prev = countStack[top].str;\n            int prevLen = strlen(prev);\n            int newLen = prevLen + curLen * repeat;\n            char *newStr = (char *)malloc((newLen + 1) * sizeof(char));\n            strcpy(newStr, prev);\n            for (int j = 0; j < repeat; j++) {\n                strcat(newStr, current);\n            }\n            free(prev);\n            free(current);\n            current = newStr;\n            curLen = newLen;\n        } else {\n            current[curLen++] = c;\n            current[curLen] = \'\\0\';\n        }\n    }\n\n    return current;\n}\n\nint main() {\n    char s[MAXN];\n    if (fgets(s, sizeof(s), stdin)) {\n        size_t len = strlen(s);\n        if (len > 0 && s[len - 1] == \'\\n\') {\n            s[len - 1] = \'\\0\';\n        }\n        char *result = decodeString(s);\n        printf(\"%s\\n\", result);\n        free(result);\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:10:19','2026-09-28 15:16:03'),(597,155,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        int sum = 0;\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n            sum += nums[i];\n        }\n        if (sum % 2 != 0) {\n            System.out.println(false);\n            return;\n        }\n        int target = sum / 2;\n        boolean[] dp = new boolean[target + 1];\n        dp[0] = true;\n        for (int num : nums) {\n            for (int j = target; j >= num; j--) {\n                dp[j] = dp[j] || dp[j - num];\n            }\n        }\n        System.out.println(dp[target]);\n    }\n}',NULL,1,'2026-09-27 13:10:20','2026-09-28 15:16:03'),(598,153,'PYTHON','import sys\nfrom collections import Counter\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    k = int(data[1])\n    nums = list(map(int, data[2:2+n]))\n    \n    freq = Counter(nums)\n    items = sorted(freq.keys(), key=lambda x: (-freq[x], x))\n    \n    result = items[:k]\n    print(\"[\" + \",\".join(map(str, result)) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:10:20','2026-09-28 15:16:03'),(599,152,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const s = lines[0];\n    const n = parseInt(lines[1].trim());\n    const wordDict = new Set();\n    for (let i = 0; i < n; i++) {\n        wordDict.add(lines[2 + i].trim());\n    }\n\n    const len = s.length;\n    const dp = new Array(len + 1).fill(false);\n    dp[0] = true;\n\n    for (let i = 1; i <= len; i++) {\n        for (let j = 0; j < i; j++) {\n            if (dp[j] && wordDict.has(s.substring(j, i))) {\n                dp[i] = true;\n                break;\n            }\n        }\n    }\n\n    console.log(dp[len]);\n});',NULL,1,'2026-09-27 13:10:20','2026-09-28 15:16:03'),(600,154,'PYTHON','import sys\n\ndef decodeString(s: str) -> str:\n    count_stack = []\n    string_stack = []\n    current = []\n    k = 0\n\n    for c in s:\n        if c.isdigit():\n            k = k * 10 + int(c)\n        elif c == \'[\':\n            count_stack.append(k)\n            string_stack.append(current)\n            current = []\n            k = 0\n        elif c == \']\':\n            repeat = count_stack.pop()\n            prev = string_stack.pop()\n            for _ in range(repeat):\n                prev.extend(current)\n            current = prev\n        else:\n            current.append(c)\n\n    return \'\'.join(current)\n\nif __name__ == \"__main__\":\n    line = sys.stdin.readline()\n    if line:\n        s = line.rstrip(\'\\n\')\n        print(decodeString(s))',NULL,1,'2026-09-27 13:10:21','2026-09-28 15:16:03'),(601,153,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const [n, k] = lines[0].split(/\\s+/).map(Number);\n        const nums = lines[1].split(/\\s+/).map(Number);\n\n        const freq = new Map();\n        for (const num of nums) {\n            freq.set(num, (freq.get(num) || 0) + 1);\n        }\n\n        const list = Array.from(freq.keys());\n        list.sort((a, b) => {\n            const fa = freq.get(a);\n            const fb = freq.get(b);\n            if (fa !== fb) {\n                return fb - fa;\n            }\n            return a - b;\n        });\n\n        const result = list.slice(0, k);\n        console.log(\'[\' + result.join(\',\') + \']\');\n        rl.close();\n    }\n});',NULL,1,'2026-09-27 13:10:21','2026-09-28 15:16:03'),(602,155,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    int sum = 0;\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n        sum += nums[i];\n    }\n    if (sum % 2 != 0) {\n        cout << \"false\" << endl;\n        return 0;\n    }\n    int target = sum / 2;\n    vector<bool> dp(target + 1, false);\n    dp[0] = true;\n    for (int num : nums) {\n        for (int j = target; j >= num; j--) {\n            dp[j] = dp[j] || dp[j - num];\n        }\n    }\n    cout << (dp[target] ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:10:22','2026-09-28 15:16:03'),(603,156,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n + 1];\n        for (int i = 0; i <= n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int slow = nums[0];\n        int fast = nums[0];\n        do {\n            slow = nums[slow];\n            fast = nums[nums[fast]];\n        } while (slow != fast);\n        slow = nums[0];\n        while (slow != fast) {\n            slow = nums[slow];\n            fast = nums[fast];\n        }\n        System.out.println(slow);\n    }\n}',NULL,1,'2026-09-27 13:10:22','2026-09-28 15:16:03'),(604,154,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    console.log(decodeString(line));\n    rl.close();\n});\n\nfunction decodeString(s) {\n    const countStack = [];\n    const stringStack = [];\n    let current = \'\';\n    let k = 0;\n\n    for (const c of s) {\n        if (c >= \'0\' && c <= \'9\') {\n            k = k * 10 + (c.charCodeAt(0) - \'0\'.charCodeAt(0));\n        } else if (c === \'[\') {\n            countStack.push(k);\n            stringStack.push(current);\n            current = \'\';\n            k = 0;\n        } else if (c === \']\') {\n            const repeat = countStack.pop();\n            const prev = stringStack.pop();\n            current = prev + current.repeat(repeat);\n        } else {\n            current += c;\n        }\n    }\n\n    return current;\n}',NULL,1,'2026-09-27 13:10:22','2026-09-28 15:16:03'),(605,157,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] dp = new int[n + 1];\n        for (int i = 1; i <= n; i++) {\n            dp[i] = Integer.MAX_VALUE;\n            for (int j = 1; j * j <= i; j++) {\n                dp[i] = Math.min(dp[i], dp[i - j * j] + 1);\n            }\n        }\n        System.out.println(dp[n]);\n    }\n}',NULL,1,'2026-09-27 13:10:23','2026-09-28 15:16:03'),(606,155,'C','#include <stdio.h>\n#include <stdbool.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    int sum = 0;\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n        sum += nums[i];\n    }\n    if (sum % 2 != 0) {\n        printf(\"false\\n\");\n        return 0;\n    }\n    int target = sum / 2;\n    bool dp[target + 1];\n    for (int i = 0; i <= target; i++) {\n        dp[i] = false;\n    }\n    dp[0] = true;\n    for (int i = 0; i < n; i++) {\n        int num = nums[i];\n        for (int j = target; j >= num; j--) {\n            dp[j] = dp[j] || dp[j - num];\n        }\n    }\n    if (dp[target]) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:10:24','2026-09-28 15:16:03'),(607,156,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n + 1);\n    for (int i = 0; i <= n; i++) {\n        cin >> nums[i];\n    }\n    int slow = nums[0];\n    int fast = nums[0];\n    do {\n        slow = nums[slow];\n        fast = nums[nums[fast]];\n    } while (slow != fast);\n    slow = nums[0];\n    while (slow != fast) {\n        slow = nums[slow];\n        fast = nums[fast];\n    }\n    cout << slow << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:10:24','2026-09-28 15:16:03'),(608,158,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine();\n        int n = s.length();\n        int[][] dp = new int[n][n];\n        for (int i = 0; i < n; i++) {\n            dp[i][i] = 1;\n        }\n        for (int len = 2; len <= n; len++) {\n            for (int i = 0; i + len - 1 < n; i++) {\n                int j = i + len - 1;\n                if (s.charAt(i) == s.charAt(j)) {\n                    dp[i][j] = dp[i + 1][j - 1] + 2;\n                } else {\n                    dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n        System.out.println(dp[0][n - 1]);\n    }\n}',NULL,1,'2026-09-27 13:10:24','2026-09-28 15:16:03'),(609,155,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\ntotal = sum(nums)\nif total % 2 != 0:\n    print(\"false\")\nelse:\n    target = total // 2\n    dp = [False] * (target + 1)\n    dp[0] = True\n    for num in nums:\n        for j in range(target, num - 1, -1):\n            dp[j] = dp[j] or dp[j - num]\n    print(\"true\" if dp[target] else \"false\")',NULL,1,'2026-09-27 13:10:25','2026-09-28 15:16:03'),(610,157,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <climits>\n\nint main() {\n    int n;\n    std::cin >> n;\n    std::vector<int> dp(n + 1);\n    for (int i = 1; i <= n; i++) {\n        dp[i] = INT_MAX;\n        for (int j = 1; j * j <= i; j++) {\n            dp[i] = std::min(dp[i], dp[i - j * j] + 1);\n        }\n    }\n    std::cout << dp[n] << std::endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:10:26','2026-09-28 15:16:03'),(611,156,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc((n + 1) * sizeof(int));\n    for (int i = 0; i <= n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int slow = nums[0];\n    int fast = nums[0];\n    do {\n        slow = nums[slow];\n        fast = nums[nums[fast]];\n    } while (slow != fast);\n    slow = nums[0];\n    while (slow != fast) {\n        slow = nums[slow];\n        fast = nums[fast];\n    }\n    printf(\"%d\\n\", slow);\n    free(nums);\n    return 0;\n}',NULL,1,'2026-09-27 13:10:26','2026-09-28 15:16:03'),(612,158,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n    int n = s.length();\n    vector<vector<int>> dp(n, vector<int>(n, 0));\n    for (int i = 0; i < n; i++) {\n        dp[i][i] = 1;\n    }\n    for (int len = 2; len <= n; len++) {\n        for (int i = 0; i + len - 1 < n; i++) {\n            int j = i + len - 1;\n            if (s[i] == s[j]) {\n                dp[i][j] = dp[i + 1][j - 1] + 2;\n            } else {\n                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1]);\n            }\n        }\n    }\n    cout << dp[0][n - 1] << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:10:27','2026-09-28 15:16:03'),(613,155,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    let sum = 0;\n    for (let i = 0; i < n; i++) {\n        sum += nums[i];\n    }\n    if (sum % 2 !== 0) {\n        console.log(false);\n        return;\n    }\n    const target = sum / 2;\n    const dp = new Array(target + 1).fill(false);\n    dp[0] = true;\n    for (const num of nums) {\n        for (let j = target; j >= num; j--) {\n            dp[j] = dp[j] || dp[j - num];\n        }\n    }\n    console.log(dp[target]);\n});',NULL,1,'2026-09-27 13:10:27','2026-09-28 15:16:03'),(614,156,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\nslow = nums[0]\nfast = nums[0]\nwhile True:\n    slow = nums[slow]\n    fast = nums[nums[fast]]\n    if slow == fast:\n        break\nslow = nums[0]\nwhile slow != fast:\n    slow = nums[slow]\n    fast = nums[fast]\nprint(slow)',NULL,1,'2026-09-27 13:10:27','2026-09-28 15:16:03'),(615,157,'C','#include <stdio.h>\n#include <limits.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int dp[n + 1];\n    dp[0] = 0;\n    for (int i = 1; i <= n; i++) {\n        dp[i] = INT_MAX;\n        for (int j = 1; j * j <= i; j++) {\n            if (dp[i - j * j] + 1 < dp[i]) {\n                dp[i] = dp[i - j * j] + 1;\n            }\n        }\n    }\n    printf(\"%d\\n\", dp[n]);\n    return 0;\n}',NULL,1,'2026-09-27 13:10:28','2026-09-28 15:16:03'),(616,156,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n\n    let slow = nums[0];\n    let fast = nums[0];\n\n    do {\n        slow = nums[slow];\n        fast = nums[nums[fast]];\n    } while (slow !== fast);\n\n    slow = nums[0];\n    while (slow !== fast) {\n        slow = nums[slow];\n        fast = nums[fast];\n    }\n\n    console.log(slow);\n});',NULL,1,'2026-09-27 13:10:29','2026-09-28 15:16:03'),(617,159,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n1 = sc.nextInt();\n        int[] nums1 = new int[n1];\n        for (int i = 0; i < n1; i++) {\n            nums1[i] = sc.nextInt();\n        }\n        int n2 = sc.nextInt();\n        int[] nums2 = new int[n2];\n        for (int i = 0; i < n2; i++) {\n            nums2[i] = sc.nextInt();\n        }\n\n        Map<Integer, Integer> map = new HashMap<>();\n        for (int num : nums1) {\n            map.put(num, map.getOrDefault(num, 0) + 1);\n        }\n\n        List<Integer> res = new ArrayList<>();\n        for (int num : nums2) {\n            if (map.getOrDefault(num, 0) > 0) {\n                res.add(num);\n                map.put(num, map.get(num) - 1);\n            }\n        }\n\n        Collections.sort(res);\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            sb.append(res.get(i));\n            if (i != res.size() - 1) {\n                sb.append(\",\");\n            }\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1,'2026-09-27 13:10:29','2026-09-28 15:16:03'),(618,157,'PYTHON','n = int(input())\ndp = [0] * (n + 1)\nfor i in range(1, n + 1):\n    dp[i] = float(\'inf\')\n    j = 1\n    while j * j <= i:\n        dp[i] = min(dp[i], dp[i - j * j] + 1)\n        j += 1\nprint(dp[n])',NULL,1,'2026-09-27 13:10:29','2026-09-28 15:16:03'),(619,157,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim(), 10);\n    const dp = new Array(n + 1).fill(0);\n    for (let i = 1; i <= n; i++) {\n        dp[i] = Number.MAX_SAFE_INTEGER;\n        for (let j = 1; j * j <= i; j++) {\n            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);\n        }\n    }\n    console.log(dp[n]);\n    rl.close();\n});',NULL,1,'2026-09-27 13:10:30','2026-09-28 15:16:03'),(620,160,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line1 = sc.nextLine().trim();\n        String line2 = sc.nextLine().trim();\n\n        ListNode l1 = parseList(line1);\n        ListNode l2 = parseList(line2);\n\n        ListNode result = addTwoNumbers(l1, l2);\n        System.out.println(formatList(result));\n    }\n\n    private static ListNode parseList(String s) {\n        if (s == null || s.isEmpty() || s.equals(\"NULL\")) {\n            return null;\n        }\n        String[] parts = s.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String part : parts) {\n            if (part.equals(\"NULL\")) {\n                break;\n            }\n            cur.next = new ListNode(Integer.parseInt(part.trim()));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    private static String formatList(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = head;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    private static ListNode addTwoNumbers(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        int carry = 0;\n        while (l1 != null || l2 != null || carry != 0) {\n            int x = (l1 != null) ? l1.val : 0;\n            int y = (l2 != null) ? l2.val : 0;\n            int sum = x + y + carry;\n            carry = sum / 10;\n            cur.next = new ListNode(sum % 10);\n            cur = cur.next;\n            if (l1 != null) l1 = l1.next;\n            if (l2 != null) l2 = l2.next;\n        }\n        return dummy.next;\n    }\n}',NULL,1,'2026-09-27 13:10:31','2026-09-28 15:16:03'),(621,159,'CPP','#include <iostream>\n#include <vector>\n#include <unordered_map>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n1;\n    cin >> n1;\n    vector<int> nums1(n1);\n    for (int i = 0; i < n1; i++) {\n        cin >> nums1[i];\n    }\n\n    int n2;\n    cin >> n2;\n    vector<int> nums2(n2);\n    for (int i = 0; i < n2; i++) {\n        cin >> nums2[i];\n    }\n\n    unordered_map<int, int> map;\n    for (int num : nums1) {\n        map[num]++;\n    }\n\n    vector<int> res;\n    for (int num : nums2) {\n        if (map[num] > 0) {\n            res.push_back(num);\n            map[num]--;\n        }\n    }\n\n    sort(res.begin(), res.end());\n\n    cout << \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        cout << res[i];\n        if (i != (int)res.size() - 1) {\n            cout << \",\";\n        }\n    }\n    cout << \"]\" << endl;\n\n    return 0;\n}',NULL,1,'2026-09-27 13:10:31','2026-09-28 15:16:03'),(622,161,'JAVA','import java.util.HashSet;\nimport java.util.Scanner;\nimport java.util.Set;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = scanner.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = scanner.nextInt();\n        }\n        scanner.close();\n\n        Set<Integer> set = new HashSet<>();\n        for (int num : nums) {\n            set.add(num);\n        }\n\n        int maxLength = 0;\n        for (int num : set) {\n            if (!set.contains(num - 1)) {\n                int currentNum = num;\n                int currentLength = 1;\n                while (set.contains(currentNum + 1)) {\n                    currentNum++;\n                    currentLength++;\n                }\n                maxLength = Math.max(maxLength, currentLength);\n            }\n        }\n\n        System.out.println(maxLength);\n    }\n}',NULL,1,'2026-09-27 13:10:32','2026-09-28 15:16:03'),(623,159,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nint main() {\n    int n1, n2;\n    scanf(\"%d\", &n1);\n    int *nums1 = (int *)malloc(n1 * sizeof(int));\n    for (int i = 0; i < n1; i++) {\n        scanf(\"%d\", &nums1[i]);\n    }\n    scanf(\"%d\", &n2);\n    int *nums2 = (int *)malloc(n2 * sizeof(int));\n    for (int i = 0; i < n2; i++) {\n        scanf(\"%d\", &nums2[i]);\n    }\n\n    qsort(nums1, n1, sizeof(int), cmp);\n    qsort(nums2, n2, sizeof(int), cmp);\n\n    int *res = (int *)malloc((n1 < n2 ? n1 : n2) * sizeof(int));\n    int i = 0, j = 0, k = 0;\n    while (i < n1 && j < n2) {\n        if (nums1[i] < nums2[j]) {\n            i++;\n        } else if (nums1[i] > nums2[j]) {\n            j++;\n        } else {\n            res[k++] = nums1[i];\n            i++;\n            j++;\n        }\n    }\n\n    printf(\"[\");\n    for (int t = 0; t < k; t++) {\n        printf(\"%d\", res[t]);\n        if (t != k - 1) {\n            printf(\",\");\n        }\n    }\n    printf(\"]\\n\");\n\n    free(nums1);\n    free(nums2);\n    free(res);\n    return 0;\n}',NULL,1,'2026-09-27 13:10:34','2026-09-28 15:16:03'),(624,160,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int x) : val(x), next(nullptr) {}\n};\n\nListNode* parseList(const string& s) {\n    if (s.empty() || s == \"NULL\") return nullptr;\n    string str = s;\n    string token;\n    stringstream ss(str);\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    while (getline(ss, token, \'-\')) {\n        if (token.empty() || token == \">\") continue;\n        if (token == \">NULL\" || token == \"NULL\") break;\n        if (token[0] == \'>\') token = token.substr(1);\n        if (token == \"NULL\") break;\n        cur->next = new ListNode(stoi(token));\n        cur = cur->next;\n    }\n    return dummy.next;\n}\n\nstring formatList(ListNode* head) {\n    string res;\n    ListNode* cur = head;\n    while (cur) {\n        res += to_string(cur->val) + \"->\";\n        cur = cur->next;\n    }\n    res += \"NULL\";\n    return res;\n}\n\nListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    int carry = 0;\n    while (l1 || l2 || carry) {\n        int x = l1 ? l1->val : 0;\n        int y = l2 ? l2->val : 0;\n        int sum = x + y + carry;\n        carry = sum / 10;\n        cur->next = new ListNode(sum % 10);\n        cur = cur->next;\n        if (l1) l1 = l1->next;\n        if (l2) l2 = l2->next;\n    }\n    return dummy.next;\n}\n\nint main() {\n    string line1, line2;\n    getline(cin, line1);\n    getline(cin, line2);\n\n    ListNode* l1 = parseList(line1);\n    ListNode* l2 = parseList(line2);\n\n    ListNode* result = addTwoNumbers(l1, l2);\n    cout << formatList(result) << endl;\n\n    return 0;\n}',NULL,1,'2026-09-27 13:10:35','2026-09-28 15:16:03'),(625,161,'CPP','#include <iostream>\n#include <vector>\n#include <unordered_set>\n#include <algorithm>\n\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    unordered_set<int> set(nums.begin(), nums.end());\n\n    int maxLength = 0;\n    for (int num : set) {\n        if (set.find(num - 1) == set.end()) {\n            int currentNum = num;\n            int currentLength = 1;\n            while (set.find(currentNum + 1) != set.end()) {\n                currentNum++;\n                currentLength++;\n            }\n            maxLength = max(maxLength, currentLength);\n        }\n    }\n\n    cout << maxLength << endl;\n\n    return 0;\n}',NULL,1,'2026-09-27 13:10:35','2026-09-28 15:16:03'),(626,159,'PYTHON','import sys\nfrom collections import Counter\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    idx = 0\n    n1 = int(data[idx]); idx += 1\n    nums1 = list(map(int, data[idx:idx+n1])); idx += n1\n    n2 = int(data[idx]); idx += 1\n    nums2 = list(map(int, data[idx:idx+n2])); idx += n2\n\n    count = Counter(nums1)\n    res = []\n    for num in nums2:\n        if count.get(num, 0) > 0:\n            res.append(num)\n            count[num] -= 1\n\n    res.sort()\n    print(\"[\" + \",\".join(map(str, res)) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:10:35','2026-09-28 15:16:03'),(627,158,'C','#include <stdio.h>\n#include <string.h>\n\nint main() {\n    char s[1005];\n    if (scanf(\"%s\", s) != 1) return 0;\n    int n = (int)strlen(s);\n    if (n == 0) {\n        printf(\"0\\n\");\n        return 0;\n    }\n\n    static int dp[1005][1005];\n    for (int i = 0; i < n; i++) {\n        dp[i][i] = 1;\n    }\n\n    for (int len = 2; len <= n; len++) {\n        for (int i = 0; i + len - 1 < n; i++) {\n            int j = i + len - 1;\n            if (s[i] == s[j]) {\n                if (len == 2) dp[i][j] = 2;\n                else dp[i][j] = dp[i + 1][j - 1] + 2;\n            } else {\n                int a = dp[i + 1][j];\n                int b = dp[i][j - 1];\n                dp[i][j] = a > b ? a : b;\n            }\n        }\n    }\n\n    printf(\"%d\\n\", dp[0][n - 1]);\n    return 0;\n}',NULL,1,'2026-09-27 13:10:36','2026-09-28 15:16:03'),(628,159,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n1 = parseInt(lines[0]);\n    const nums1 = lines[1].split(\' \').map(Number);\n    const n2 = parseInt(lines[2]);\n    const nums2 = lines[3].split(\' \').map(Number);\n\n    const map = new Map();\n    for (const num of nums1) {\n        map.set(num, (map.get(num) || 0) + 1);\n    }\n\n    const res = [];\n    for (const num of nums2) {\n        if ((map.get(num) || 0) > 0) {\n            res.push(num);\n            map.set(num, map.get(num) - 1);\n        }\n    }\n\n    res.sort((a, b) => a - b);\n\n    let sb = \'[\';\n    for (let i = 0; i < res.length; i++) {\n        sb += res[i];\n        if (i !== res.length - 1) {\n            sb += \',\';\n        }\n    }\n    sb += \']\';\n    console.log(sb);\n});',NULL,1,'2026-09-27 13:10:37','2026-09-28 15:16:03'),(629,158,'PYTHON','s = input().strip()\nn = len(s)\ndp = [[0] * n for _ in range(n)]\nfor i in range(n):\n    dp[i][i] = 1\nfor length in range(2, n + 1):\n    for i in range(n - length + 1):\n        j = i + length - 1\n        if s[i] == s[j]:\n            dp[i][j] = dp[i + 1][j - 1] + 2\n        else:\n            dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])\nprint(dp[0][n - 1])',NULL,1,'2026-09-27 13:10:37','2026-09-28 15:16:03'),(630,161,'C','#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int *data;\n    int size;\n    int capacity;\n} HashSet;\n\nunsigned int hash(int x) {\n    return (unsigned int)x * 2654435761u;\n}\n\nHashSet* createHashSet(int capacity) {\n    HashSet *set = (HashSet*)malloc(sizeof(HashSet));\n    set->capacity = capacity;\n    set->size = 0;\n    set->data = (int*)calloc(capacity, sizeof(int));\n    for (int i = 0; i < capacity; i++) {\n        set->data[i] = 0;\n    }\n    return set;\n}\n\nvoid freeHashSet(HashSet *set) {\n    free(set->data);\n    free(set);\n}\n\nint contains(HashSet *set, int x) {\n    unsigned int h = hash(x) % set->capacity;\n    while (set->data[h] != 0) {\n        if (set->data[h] == x) return 1;\n        h = (h + 1) % set->capacity;\n    }\n    return 0;\n}\n\nvoid add(HashSet *set, int x) {\n    if (contains(set, x)) return;\n    unsigned int h = hash(x) % set->capacity;\n    while (set->data[h] != 0) {\n        h = (h + 1) % set->capacity;\n    }\n    set->data[h] = x;\n    set->size++;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int*)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    HashSet *set = createHashSet(n * 2 + 1);\n    for (int i = 0; i < n; i++) {\n        add(set, nums[i]);\n    }\n\n    int maxLength = 0;\n    for (int i = 0; i < n; i++) {\n        int num = nums[i];\n        if (!contains(set, num - 1)) {\n            int currentNum = num;\n            int currentLength = 1;\n            while (contains(set, currentNum + 1)) {\n                currentNum++;\n                currentLength++;\n            }\n            if (currentLength > maxLength) {\n                maxLength = currentLength;\n            }\n        }\n    }\n\n    printf(\"%d\\n\", maxLength);\n\n    freeHashSet(set);\n    free(nums);\n    return 0;\n}',NULL,1,'2026-09-27 13:10:38','2026-09-28 15:16:03'),(631,160,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\nListNode* parseList(const char *s) {\n    if (s == NULL || s[0] == \'\\0\' || strcmp(s, \"NULL\") == 0) {\n        return NULL;\n    }\n    char *copy = strdup(s);\n    ListNode dummy = {0, NULL};\n    ListNode *cur = &dummy;\n    char *token = strtok(copy, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) {\n            break;\n        }\n        ListNode *node = (ListNode*)malloc(sizeof(ListNode));\n        node->val = atoi(token);\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n        token = strtok(NULL, \"->\");\n    }\n    free(copy);\n    return dummy.next;\n}\n\nchar* formatList(ListNode *head) {\n    char *buf = (char*)malloc(100000);\n    buf[0] = \'\\0\';\n    ListNode *cur = head;\n    char temp[32];\n    while (cur != NULL) {\n        sprintf(temp, \"%d->\", cur->val);\n        strcat(buf, temp);\n        cur = cur->next;\n    }\n    strcat(buf, \"NULL\");\n    return buf;\n}\n\nListNode* addTwoNumbers(ListNode *l1, ListNode *l2) {\n    ListNode dummy = {0, NULL};\n    ListNode *cur = &dummy;\n    int carry = 0;\n    while (l1 != NULL || l2 != NULL || carry != 0) {\n        int x = (l1 != NULL) ? l1->val : 0;\n        int y = (l2 != NULL) ? l2->val : 0;\n        int sum = x + y + carry;\n        carry = sum / 10;\n        ListNode *node = (ListNode*)malloc(sizeof(ListNode));\n        node->val = sum % 10;\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n        if (l1 != NULL) l1 = l1->next;\n        if (l2 != NULL) l2 = l2->next;\n    }\n    return dummy.next;\n}\n\nint main() {\n    char line1[100000];\n    char line2[100000];\n    if (fgets(line1, sizeof(line1), stdin) == NULL) return 0;\n    if (fgets(line2, sizeof(line2), stdin) == NULL) return 0;\n    line1[strcspn(line1, \"\\r\\n\")] = \'\\0\';\n    line2[strcspn(line2, \"\\r\\n\")] = \'\\0\';\n\n    ListNode *l1 = parseList(line1);\n    ListNode *l2 = parseList(line2);\n\n    ListNode *result = addTwoNumbers(l1, l2);\n    char *out = formatList(result);\n    printf(\"%s\\n\", out);\n\n    free(out);\n    return 0;\n}',NULL,1,'2026-09-27 13:10:38','2026-09-28 15:16:03'),(632,161,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\n\nnum_set = set(nums)\nmax_length = 0\n\nfor num in num_set:\n    if num - 1 not in num_set:\n        current_num = num\n        current_length = 1\n        while current_num + 1 in num_set:\n            current_num += 1\n            current_length += 1\n        max_length = max(max_length, current_length)\n\nprint(max_length)',NULL,1,'2026-09-27 13:10:39','2026-09-28 15:16:03'),(633,158,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    const n = s.length;\n    const dp = Array.from({ length: n }, () => new Array(n).fill(0));\n    for (let i = 0; i < n; i++) {\n        dp[i][i] = 1;\n    }\n    for (let len = 2; len <= n; len++) {\n        for (let i = 0; i + len - 1 < n; i++) {\n            const j = i + len - 1;\n            if (s[i] === s[j]) {\n                dp[i][j] = dp[i + 1][j - 1] + 2;\n            } else {\n                dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);\n            }\n        }\n    }\n    console.log(dp[0][n - 1]);\n    rl.close();\n});',NULL,1,'2026-09-27 13:10:39','2026-09-28 15:16:03'),(634,162,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        int[] nums1 = new int[m + n];\n        int[] nums2 = new int[n];\n        for (int i = 0; i < m; i++) {\n            nums1[i] = sc.nextInt();\n        }\n        for (int i = 0; i < n; i++) {\n            nums2[i] = sc.nextInt();\n        }\n        int i = m - 1, j = n - 1, k = m + n - 1;\n        while (i >= 0 && j >= 0) {\n            if (nums1[i] > nums2[j]) {\n                nums1[k--] = nums1[i--];\n            } else {\n                nums1[k--] = nums2[j--];\n            }\n        }\n        while (j >= 0) {\n            nums1[k--] = nums2[j--];\n        }\n        StringBuilder sb = new StringBuilder();\n        for (int x = 0; x < m + n; x++) {\n            if (x > 0) sb.append(\' \');\n            sb.append(nums1[x]);\n        }\n        System.out.println(sb.toString());\n    }\n}',NULL,1,'2026-09-27 13:10:39','2026-09-28 15:16:03'),(635,160,'PYTHON','import sys\n\nclass ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef parse_list(s):\n    if s is None or s == \"\" or s == \"NULL\":\n        return None\n    parts = s.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for part in parts:\n        if part == \"NULL\":\n            break\n        cur.next = ListNode(int(part.strip()))\n        cur = cur.next\n    return dummy.next\n\ndef format_list(head):\n    sb = []\n    cur = head\n    while cur is not None:\n        sb.append(str(cur.val))\n        sb.append(\"->\")\n        cur = cur.next\n    sb.append(\"NULL\")\n    return \"\".join(sb)\n\ndef add_two_numbers(l1, l2):\n    dummy = ListNode(0)\n    cur = dummy\n    carry = 0\n    while l1 is not None or l2 is not None or carry != 0:\n        x = l1.val if l1 is not None else 0\n        y = l2.val if l2 is not None else 0\n        total = x + y + carry\n        carry = total // 10\n        cur.next = ListNode(total % 10)\n        cur = cur.next\n        if l1 is not None:\n            l1 = l1.next\n        if l2 is not None:\n            l2 = l2.next\n    return dummy.next\n\ndef main():\n    lines = sys.stdin.read().strip().splitlines()\n    line1 = lines[0].strip()\n    line2 = lines[1].strip()\n\n    l1 = parse_list(line1)\n    l2 = parse_list(line2)\n\n    result = add_two_numbers(l1, l2)\n    print(format_list(result))\n\nif __name__ == \"__main__\":\n    main()',NULL,1,'2026-09-27 13:10:40','2026-09-28 15:16:03'),(636,161,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n\n    const set = new Set(nums);\n\n    let maxLength = 0;\n    for (const num of set) {\n        if (!set.has(num - 1)) {\n            let currentNum = num;\n            let currentLength = 1;\n            while (set.has(currentNum + 1)) {\n                currentNum++;\n                currentLength++;\n            }\n            maxLength = Math.max(maxLength, currentLength);\n        }\n    }\n\n    console.log(maxLength);\n});',NULL,1,'2026-09-27 13:10:40','2026-09-28 15:16:03'),(637,163,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] matrix = new int[n][n];\n        int top = 0, bottom = n - 1, left = 0, right = n - 1;\n        int num = 1;\n        while (num <= n * n) {\n            for (int i = left; i <= right; i++) {\n                matrix[top][i] = num++;\n            }\n            top++;\n            for (int i = top; i <= bottom; i++) {\n                matrix[i][right] = num++;\n            }\n            right--;\n            for (int i = right; i >= left; i--) {\n                matrix[bottom][i] = num++;\n            }\n            bottom--;\n            for (int i = bottom; i >= top; i--) {\n                matrix[i][left] = num++;\n            }\n            left++;\n        }\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                sb.append(matrix[i][j]);\n                if (j < n - 1) {\n                    sb.append(\' \');\n                }\n            }\n            sb.append(\'\\n\');\n        }\n        System.out.print(sb);\n    }\n}',NULL,1,'2026-09-27 13:10:41','2026-09-28 15:16:03'),(638,162,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    vector<int> nums1(m + n);\n    vector<int> nums2(n);\n    for (int i = 0; i < m; i++) {\n        cin >> nums1[i];\n    }\n    for (int i = 0; i < n; i++) {\n        cin >> nums2[i];\n    }\n    int i = m - 1, j = n - 1, k = m + n - 1;\n    while (i >= 0 && j >= 0) {\n        if (nums1[i] > nums2[j]) {\n            nums1[k--] = nums1[i--];\n        } else {\n            nums1[k--] = nums2[j--];\n        }\n    }\n    while (j >= 0) {\n        nums1[k--] = nums2[j--];\n    }\n    for (int x = 0; x < m + n; x++) {\n        if (x > 0) cout << \' \';\n        cout << nums1[x];\n    }\n    cout << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:10:41','2026-09-28 15:16:03'),(639,160,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction parseList(s) {\n    if (!s || s === \'NULL\') return null;\n    const parts = s.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (const part of parts) {\n        if (part === \'NULL\') break;\n        cur.next = new ListNode(parseInt(part.trim(), 10));\n        cur = cur.next;\n    }\n    return dummy.next;\n}\n\nfunction formatList(head) {\n    let sb = \'\';\n    let cur = head;\n    while (cur !== null) {\n        sb += cur.val + \'->\';\n        cur = cur.next;\n    }\n    sb += \'NULL\';\n    return sb;\n}\n\nfunction addTwoNumbers(l1, l2) {\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    let carry = 0;\n    while (l1 !== null || l2 !== null || carry !== 0) {\n        const x = l1 !== null ? l1.val : 0;\n        const y = l2 !== null ? l2.val : 0;\n        const sum = x + y + carry;\n        carry = Math.floor(sum / 10);\n        cur.next = new ListNode(sum % 10);\n        cur = cur.next;\n        if (l1 !== null) l1 = l1.next;\n        if (l2 !== null) l2 = l2.next;\n    }\n    return dummy.next;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nconst lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const l1 = parseList(lines[0]);\n        const l2 = parseList(lines[1]);\n        const result = addTwoNumbers(l1, l2);\n        console.log(formatList(result));\n        rl.close();\n    }\n});',NULL,1,'2026-09-27 13:10:42','2026-09-28 15:16:03'),(640,164,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int jumps = 0;\n        int currentEnd = 0;\n        int farthest = 0;\n        for (int i = 0; i < n - 1; i++) {\n            farthest = Math.max(farthest, i + nums[i]);\n            if (i == currentEnd) {\n                jumps++;\n                currentEnd = farthest;\n            }\n        }\n        System.out.println(jumps);\n    }\n}',NULL,1,'2026-09-27 13:10:42','2026-09-28 15:16:03'),(641,162,'C','#include <stdio.h>\n\nint main() {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n    int nums1[m + n];\n    int nums2[n];\n    for (int i = 0; i < m; i++) {\n        scanf(\"%d\", &nums1[i]);\n    }\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums2[i]);\n    }\n    int i = m - 1, j = n - 1, k = m + n - 1;\n    while (i >= 0 && j >= 0) {\n        if (nums1[i] > nums2[j]) {\n            nums1[k--] = nums1[i--];\n        } else {\n            nums1[k--] = nums2[j--];\n        }\n    }\n    while (j >= 0) {\n        nums1[k--] = nums2[j--];\n    }\n    for (int x = 0; x < m + n; x++) {\n        if (x > 0) printf(\" \");\n        printf(\"%d\", nums1[x]);\n    }\n    printf(\"\\n\");\n    return 0;\n}',NULL,1,'2026-09-27 13:10:43','2026-09-28 15:16:03'),(642,163,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> matrix(n, vector<int>(n));\n    int top = 0, bottom = n - 1, left = 0, right = n - 1;\n    int num = 1;\n    while (num <= n * n) {\n        for (int i = left; i <= right; i++) {\n            matrix[top][i] = num++;\n        }\n        top++;\n        for (int i = top; i <= bottom; i++) {\n            matrix[i][right] = num++;\n        }\n        right--;\n        for (int i = right; i >= left; i--) {\n            matrix[bottom][i] = num++;\n        }\n        bottom--;\n        for (int i = bottom; i >= top; i--) {\n            matrix[i][left] = num++;\n        }\n        left++;\n    }\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            cout << matrix[i][j];\n            if (j < n - 1) {\n                cout << \' \';\n            }\n        }\n        cout << \'\\n\';\n    }\n    return 0;\n}',NULL,1,'2026-09-27 13:10:44','2026-09-28 15:16:03'),(643,164,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int jumps = 0;\n    int currentEnd = 0;\n    int farthest = 0;\n    for (int i = 0; i < n - 1; i++) {\n        farthest = max(farthest, i + nums[i]);\n        if (i == currentEnd) {\n            jumps++;\n            currentEnd = farthest;\n        }\n    }\n    cout << jumps << endl;\n    return 0;\n}',NULL,1,'2026-09-27 13:10:45','2026-09-28 15:16:03'),(644,165,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = 