\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    int cand1 = 0, cand2 = 0;\n    int count1 = 0, count2 = 0;\n\n    for (int num : nums) {\n        if (num == cand1) {\n            count1++;\n        } else if (num == cand2) {\n            count2++;\n        } else if (count1 == 0) {\n            cand1 = num;\n            count1 = 1;\n        } else if (count2 == 0) {\n            cand2 = num;\n            count2 = 1;\n        } else {\n            count1--;\n            count2--;\n        }\n    }\n\n    count1 = 0;\n    count2 = 0;\n    for (int num : nums) {\n        if (num == cand1) count1++;\n        else if (num == cand2) count2++;\n    }\n\n    vector<int> result;\n    if (count1 > n / 3) result.push_back(cand1);\n    if (count2 > n / 3) result.push_back(cand2);\n\n    sort(result.begin(), result.end());\n\n    cout << \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << result[i];\n    }\n    cout << \"]\" << endl;\n\n    return 0;\n}',NULL,1,'2026-09-27 13:10:47','2026-09-28 15:16:03'),(651,164,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\njumps = 0\ncurrent_end = 0\nfarthest = 0\nfor i in range(n - 1):\n    farthest = max(farthest, i + nums[i])\n    if i == current_end:\n        jumps += 1\n        current_end = farthest\nprint(jumps)',NULL,1,'2026-09-27 13:10:47','2026-09-28 15:16:03'),(652,164,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    let jumps = 0;\n    let currentEnd = 0;\n    let farthest = 0;\n    for (let i = 0; i < n - 1; i++) {\n        farthest = Math.max(farthest, i + nums[i]);\