--
-- Table structure for table `submit_record`
--

DROP TABLE IF EXISTS `submit_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `submit_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '鎻愪氦ID',
  `user_id` bigint NOT NULL COMMENT '鐢ㄦ埛ID',
  `problem_id` bigint NOT NULL COMMENT '棰樼洰ID',
  `code` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鎻愪氦鐨勪唬鐮',
  `language` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'JAVA' COMMENT '缂栫▼璇?█',
  `status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鐘舵?',
  `time_used` int DEFAULT NULL COMMENT '杩愯?鏃堕棿锛堟?绉掞級',
  `memory_used` int DEFAULT NULL COMMENT '鍐呭瓨浣跨敤锛圞B锛',
  `error_message` text COLLATE utf8mb4_unicode_ci COMMENT '閿欒?淇℃伅',
  `output` text COLLATE utf8mb4_unicode_ci COMMENT '杩愯?杈撳嚭',
  `expected_output` text COLLATE utf8mb4_unicode_ci COMMENT '棰勬湡杈撳嚭',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鎻愪氦鏃堕棿',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_problem_id` (`problem_id`),
  KEY `idx_status` (`status`),
  KEY `idx_create_time` (`create_time`),
  CONSTRAINT `fk_submit_problem` FOREIGN KEY (`problem_id`) REFERENCES `problem` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_submit_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=189 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='鎻愪氦璁板綍琛';
/*!40101 SET character_set_client = @saved_cs_client */;

