n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] vals = new int[n];\n        for (int i = 0; i < n; i++) vals[i] = sc.nextInt();\n        int pos = sc.nextInt();\n\n        // 按数组建成链表，再把尾节点接到下标 pos 处形成环\n        ListNode[] nodes = new ListNode[n];\n        for (int i = 0; i < n; i++) nodes[i] = new ListNode(vals[i]);\n        for (int i = 0; i < n - 1; i++) nodes[i].next = nodes[i + 1];\n        if (pos >= 0 && pos < n) nodes[n - 1].next = nodes[pos];\n\n        // 快慢指针：有环的话两者一定会在环内相遇\n        ListNode slow = n > 0 ? nodes[0] : null;\n        ListNode fast = slow;\n        boolean hasCycle = false;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) { hasCycle = true; break; }\n        }\n        System.out.println(hasCycle);\n    }\n}\n','JAVA','ACCEPTED',299,8132,'通过','true\n\n','true\n','2026-09-27 12:22:48'),(119,1,105,'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int k = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n\n        // 维护一个容量为 k 的小顶堆，堆顶就是第 k 大\n        PriorityQueue<Integer> heap = new PriorityQueue<>();\n        for (int v : nums) {\n            heap.offer(v);\n            if (heap.size() > k) heap.poll();\n        }\n        System.out.println(heap.peek());\n    }\n}\n','JAVA','ACCEPTED',300,8260,'通过','5\n\n','5\n','2026-09-27 12:22:49'),(120,1,106,'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();\n\n        // 二分：比较中点与右邻居，往「上坡」的方向收缩，一定能走到某个峰值\n        int lo = 0, hi