d) return;\n        inorder(node.left);\n        if (prev != null && prev.val >= node.val) valid = false;\n        prev = node;\n        inorder(node.right);\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        TreeNode root = build(sc.nextLine());\n        inorder(root);\n        System.out.println(valid);\n    }\n}\n','JAVA','ACCEPTED',300,8176,'通过','true\n\n','true\n','2026-09-27 12:23:33'),(132,1,118,'import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left, right;\n        TreeNode(int v) { val = v; }\n    }\n\n    static TreeNode build(String line) {\n        line = line.trim();\n        if (line.startsWith(\"[\")) line = line.substring(1, line.length() - 1);\n        if (line.isEmpty()) return null;\n        String[] parts = line.split(\",\");\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();\n        q.offer(root);\n        int i = 1;\n        while (!q.isEmpty() && i < parts.length) {\n            TreeNode cur = q.poll();\n            String l = parts[i++].trim();\n            if (!\"null\".equals(l)) {\n                cur.left = new TreeNode(Integer.parseInt(l));\n                q.offer(cur.left);\n            }\n            if (i < parts.length) {\n                String r = parts[i++].trim();\n                if (!\"null\".equals(r)) {\n                    cur.right = new TreeNode(Integer.parseInt(r));\n                    q.offer(cur.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    static String serialize(TreeNode root) {\n        if (root == null) return \"[]\";\n        java.util.List<String> out = new java.util.ArrayList<>();\n        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();\n        q.offer(root);\n        while (!q.isEmpty()) {\n            TreeNode cur = q.poll();\n            if (cur == null) { out.add(\"null\"); continue; }\n            out.add(String.valueOf(cur.val));\n            q.offer(cur.left);\n            q.offer(cur.right);\n        }\n        while (!out.isEmpty() && \"null\".equals(out.get(out.size() - 1))) out.remove(out.size() - 1);\n        return \"[\" + String.join(\",\", out) + \"]\";\n    }\n\n    static TreeNode invert(TreeNode node) {\n        if (node == null) return null;\n        TreeNode t = node.left;\n        node.left = invert(node.right);\n        node.right = invert(t);\n        return node;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        TreeNode root = build(sc.nextLine());\n        System.out.println(serialize(invert(root)));\n    }\n}\n','JAVA','ACCEPTED',357,38992,'通过','[4,7,2,9,6,3,1]\n\n','[4,7,2,9,6,3,1]\n','2026-09-27 12:23:34'),(133,1,119,'import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left, right;\n        TreeNode(int v) { val = v; }\n    }\n\n    static TreeNode build(String line) {\n        line = line.trim();\n        if (line.startsWith(\"[\")) line = line.substring(1, line.length() - 1);\n        if (line.isEmpty()) return null;\n        String[] parts = line.split(\",\");\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        java.util.Queue<TreeNode> q = new java.util.LinkedList<>();\n        q.offer(root);\n        int i = 1;\n        while (!q.isEmpty() && i < parts.length) {\n            TreeNode cur = q.poll();\n            String l = parts[i++].trim();\n            if (!\"null\".equals(l)) {\n                cur.left = new TreeNode(Integer.parseInt(l));\n                q.offer(cur.left);\n            }\n            if (i < parts.length) {\n                String r = parts[i++].trim();\n                if (!\"null\".equals(r)) {\n                    cur.right = new TreeNode(Integer.parseInt(r));\n                    q.offer(cur.right);\n      